fn humble_budoka() -> CardIndex {
    card_index("9508efe6-0528-4a13-9961-c2a1b05085a6")
}

/// Humble Budoka — {1}{G} 2/2 Human Monk with shroud.
///
/// Shroud carries no "your opponents control" (CR 702.18a), so the spell that
/// proves it is one of the controller's *own*: a Giant Growth aimed at the
/// board has to offer the Llanowar Elves beside it and must not offer the
/// Budoka. Both readings together are the card — a filter that only declined
/// opponents' spells, or one that declined nothing, would show up as the
/// Budoka sitting in the target list, and a shroud that had cost the printed
/// body would still pass the targeting half. The pump is then allowed to
/// resolve on the Elf, so the pair of projected bodies says the two creatures
/// really are different permanents to the engine.
#[test]
fn humble_budoka_is_shrouded_even_from_its_controllers_own_spell() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), llanowar_elves()])
        .hand(0, &[humble_budoka(), giant_growth()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Three Forests, and the Elf kept standing: it is the control the offer
    // below is read against, so it must be an untapped 1/1 when the question
    // is asked. `tap_all_mana_but` names it as the printing to leave alone.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Forests, and the Elf paid nothing"
    );

    // {1}{G} out of the open pool, leaving the {G} the Growth needs beside it
    // — CR 500.5 keeps a pool until the step ends and the whole scenario lives
    // in this one main phase.
    cast_with_floating(&mut engine, p0, humble_budoka());
    pass_until(&mut engine, stack_is_empty);
    let budoka = on_battlefield(&engine, p0, humble_budoka()).expect("the Budoka resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is still out");
    assert_eq!(pt(&engine, budoka), (2, 2), "the printed body");
    assert!(
        keywords(&engine, budoka).contains(KeywordSet::SHROUD),
        "shroud is the card's whole rules text"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "two of the three green paid the {{1}}{{G}} and one is left floating"
    );

    cast_with_floating(&mut engine, p0, giant_growth());
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "Giant Growth targets a creature, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that cast it aims it");
    assert!(
        options.contains(&elves),
        "a creature without shroud is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&budoka),
        "CR 702.18a: shroud declines its own controller's spell too, so the \
         Budoka is not a legal target for Giant Growth: {options:?}"
    );
    assert_eq!(
        options.len(),
        1,
        "and the Elf is the whole of the menu on this board: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .expect("the Elf was one of the options it enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, elves),
        (4, 4),
        "the +3/+3 landed on the creature that was named"
    );
    assert_eq!(
        pt(&engine, budoka),
        (2, 2),
        "and the shrouded one is untouched, because it was never a target"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the Growth's {{G}} came out of the pool"
    );
}

fn icatian_lieutenant() -> CardIndex {
    card_index("51e9af95-745b-45b9-b870-7f768578fa4f")
}

/// Icatian Lieutenant is `{W}{W}` for a 1/2 Human **Soldier** with
/// `{1}{W}: Target Soldier creature gets +1/+0 until end of turn`. The word
/// "Soldier" is the line's only filter, so next to the Lieutenant stands
/// a Llanowar Elves (Elf Druid, not a Soldier), whom the offer must not name,
/// and across the table a second Lieutenant, who — unlike with
/// "you control" — very much is one. The +1/+0 lands on the Soldier
/// that was named: the 1/2 becomes a 2/2, and the second Soldier and the
/// Elf remain what they were.
#[test]
fn icatian_lieutenant_pumps_the_soldier_it_names_and_no_other_creature() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[plains(), plains(), plains(), plains(), llanowar_elves()],
        )
        .hand(0, &[icatian_lieutenant()])
        .battlefield(1, &[icatian_lieutenant()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {W}{W} from two of the four Plains; the ability then still wants
    // {1}{W}, and the mana stays in the pool until end of step (CR 500.5),
    // because this scenario never leaves the main phase.
    cast_from_hand(&mut engine, p0, icatian_lieutenant());
    pass_until(&mut engine, stack_is_empty);
    let lieutenant = on_battlefield(&engine, p0, icatian_lieutenant()).expect("der Leutnant liegt");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("der Elf steht");
    let theirs = on_battlefield(&engine, p1, icatian_lieutenant()).expect("ihr Leutnant steht");
    assert_eq!(pt(&engine, lieutenant), (1, 2), "der gedruckte 1/2");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "vier Plains und der Elf sind fünf Mana, zwei davon für {{W}}{{W}}"
    );

    activate(&mut engine, p0, icatian_lieutenant(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target Soldier creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "der aktivierende Sitz wählt");
    assert_eq!((min, max), (1, 1), "exactly one target");
    assert!(
        options.contains(&lieutenant),
        "der Leutnant ist selbst ein Soldier: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"Soldier\" ist der ganze Filter und kein \"you control\": {options:?}"
    );
    assert!(
        !options.contains(&elf),
        "der Llanowar Elves ist ein Elf Druid und kein Soldat: {options:?}"
    );
    assert_eq!(options.len(), 2, "und die beiden sind das ganze Menü");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "CR 601.2h pays last: while the question is pending, no mana is spent"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![lieutenant],
            },
        )
        .expect("der Leutnant war eine der Optionen");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "{{1}}{{W}} are paid from the pool"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, lieutenant),
        (2, 2),
        "der genannte Soldat bekommt +1/+0"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 2),
        "the Soldier across the table was not named and does not grow"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "a non-Soldier cannot be named at all"
    );
}

fn ironshell_beetle() -> CardIndex {
    card_index("693ca077-2b91-4de1-8136-8fe45f8ea5a7")
}

/// Ironshell Beetle prints one sentence — "When this creature enters, put a
/// +1/+1 counter on target creature" — and the word carrying it is "target":
/// the offer has to reach across the table, not just the Beetle's own board.
/// So an Elf stands on each side, and the counter is read off the creature the
/// trigger *named* (a 2/2 against the untouched printed 1/1), because a trigger
/// that resolved against nothing would leave both bodies exactly as printed.
#[test]
fn ironshell_beetle_puts_its_counter_on_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[ironshell_beetle()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(
        pt(&engine, mine),
        (1, 1),
        "a printed 1/1 before the trigger"
    );

    // {1}{G} off the board. The helper spends both Elves for mana on the way,
    // which costs this scenario nothing: a tapped creature is still on the
    // battlefield and still a legal thing to name.
    cast_from_hand(&mut engine, p0, ironshell_beetle());

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until only stops on a target choice")
    };
    assert_eq!(player, p0, "the Beetle's controller chooses");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" reaches either side of the table: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Elf across the table was one of the options");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, theirs),
        (2, 2),
        "the +1/+1 counter landed on the creature the trigger named"
    );
    assert_eq!(
        pt(&engine, mine),
        (1, 1),
        "and on nothing else: the Elf nobody named is the 1/1 it was printed as"
    );
    assert!(
        on_battlefield(&engine, p0, ironshell_beetle()).is_some(),
        "the Beetle itself resolved and stayed, its trigger already spent"
    );
}

fn kami_of_ancient_law() -> CardIndex {
    card_index("e937e0f5-ca35-4dce-9f05-8f2075731628")
}

/// Kami of Ancient Law is a 2/2 whose whole printed text is one line:
/// "Sacrifice this creature: Destroy target enchantment." Both halves want
/// their own board. The price is the source itself, so the Kami is still
/// standing while the target question is open (CR 601.2c) and in its owner's
/// graveyard the instant that question is answered (CR 601.2h) — a rider that
/// resolved later would look exactly the same once the stack had emptied.
/// And the menu is what reads `Filter::ENCHANTMENT`: the opponent's
/// enchantment is the only legal target, while the creature on each side of
/// the table is a permanent that any "target permanent" reading would have
/// offered and this one must not.
#[test]
fn kami_of_ancient_law_eats_itself_to_destroy_an_enchantment_across_the_table() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[kami_of_ancient_law(), llanowar_elves()])
        .battlefield(1, &[their_enchantment(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let kami = on_battlefield(&engine, p0, kami_of_ancient_law()).expect("the Kami is out");
    let my_elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    let enchantment =
        on_battlefield(&engine, p1, their_enchantment()).expect("their enchantment is out");
    assert_eq!(pt(&engine, kami), (2, 2), "the printed 2/2 body");

    // The whole price is the source itself — no mana and no tap — so the line
    // is offered off a board with an empty pool and nothing floating for it.
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat that holds the Kami holds priority");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the cost is a sacrifice and no mana, so nothing has to be paid into a pool first"
    );
    assert!(
        legal.abilities.contains(&(kami, 0)),
        "the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, kami_of_ancient_law(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target enchantment\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that chooses");
    assert_eq!(
        options,
        vec![enchantment],
        "the one enchantment on the table and nothing else: the Kami and both \
         Elves are creatures, which is exactly what a bare `Filter::Any` would \
         have put on this menu"
    );
    assert!(
        !options.contains(&my_elf) && !options.contains(&their_elf),
        "a creature is not an enchantment, on either side of the table: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p0, kami_of_ancient_law()).is_some(),
        "CR 601.2c before CR 601.2h: the target is named while the Kami is \
         still standing, so the sacrifice has not been paid yet"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![enchantment],
            },
        )
        .expect("the enchantment the question offered was one of its answers");

    assert!(
        in_graveyard(&engine, p0, kami_of_ancient_law()).is_some(),
        "the sacrifice is the last step of the activation, so it is paid the \
         moment the target question is settled — and a sacrificed creature \
         goes to its owner's graveyard"
    );
    assert!(
        !stack_is_empty(&engine),
        "and the ability that price paid for is what is waiting on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p1, their_enchantment()).is_none(),
        "the targeted enchantment was destroyed"
    );
    assert!(
        in_graveyard(&engine, p1, their_enchantment()).is_some(),
        "and it rests in the graveyard of the seat that owned it, not the \
         seat that aimed the ability"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "the creature the ability did not name never moved"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "and neither did the creature on this side of the table"
    );
}

fn king_suleiman() -> CardIndex {
    card_index("97f548b1-6398-4dc7-b5eb-da5a3f24ddb7")
}

/// King Suleiman — {1}{W} 1/1 Human Noble: "{T}: Destroy target Djinn or
/// Efreet."
///
/// No card in the pool is printed with either type as a *card*, so the Djinn is
/// made and not found: a Mutavault animated by its own `{1}` is "a 2/2 creature
/// with all creature types", which is a Djinn and an Efreet at once, and the
/// Llanowar Elves standing beside it is the control that says the filter is not
/// "target creature". The turn between the cast and the `{T}` is load-bearing
/// too: a creature's `{T}` ability is not offered the turn it arrives
/// (CR 302.6), so the Noble has to untap before either claim holds.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn king_suleiman_destroys_the_animated_mutavault_that_is_every_creature_type() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[plains(), plains(), plains(), mutavault(), llanowar_elves()],
        )
        .hand(0, &[king_suleiman()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{W} off the three Plains and the two mana permanents beside them: the
    // card has to arrive in a game before anything is claimed about its text.
    cast_from_hand(&mut engine, p0, king_suleiman());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let suleiman = on_battlefield(&engine, p0, king_suleiman()).expect("the Noble resolved");

    // A whole turn cycle. `reach_their_main_phase` crosses the combat steps
    // and does not answer "you are already there" from the main phase this
    // started in, which is what a `{T}` ability on a summoning-sick creature
    // needs.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, suleiman),
        "the untap step stood the Noble back up, which is what its {{T}} needs"
    );
    let vault = on_battlefield(&engine, p0, mutavault()).expect("the Mutavault is still out");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("and so are the Elves");

    // Mana before the claim: the animation's {1} is read off the pool and not
    // off the untapped lands, so everything taps first — the Mutavault with
    // them, since its whole price is its own {T} (#159). Its animation costs
    // {1} and no tap, so it is still activatable while tapped.
    tap_all_mana(&mut engine, p0);
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    let (source, animation) = legal
        .abilities
        .iter()
        .copied()
        .find(|(src, _)| *src == vault)
        .expect("with {{1}} floating, the animation is the one line left on it");
    engine
        .apply(
            p0,
            PlayerAction::ActivateAbility {
                source,
                ability_index: animation,
            },
        )
        .expect("the animation costs {{1}} and nothing else");
    pass_until(&mut engine, stack_is_empty);
    assert!(
        types(&engine, vault).contains(TypeSet::CREATURE),
        "\"Mutavault becomes a 2/2 creature ... It's still a land\""
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(suleiman, 0)),
        "an untapped Noble with a Djinn on the table is offered the only line \
         it prints: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, king_suleiman(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target Djinn or Efreet\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&vault),
        "the animated Mutavault has every creature type and is therefore a Djinn \
         and an Efreet: {options:?}"
    );
    assert!(
        !options.contains(&elves),
        "the Llanowar Elves beside it is neither, so this is a filter and not \
         \"target creature\": {options:?}"
    );
    assert_eq!(
        options.len(),
        1,
        "and those two readings are the whole menu: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![vault],
            },
        )
        .expect("the animated land was one of the options it enumerated");
    // CR 601.2c names the target and CR 601.2h pays, so the {T} is read after
    // the answer and not while the question was still open.
    assert!(is_tapped(&engine, suleiman), "{{T}} was the cost");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, mutavault()).is_none(),
        "the Djinn left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p0, mutavault()).is_some(),
        "destroyed, so the card is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the creature the filter never named is untouched"
    );
    assert!(
        on_battlefield(&engine, p0, king_suleiman()).is_some(),
        "and the Noble is still standing, its ability having aimed elsewhere"
    );
}

fn kobold_drill_sergeant() -> CardIndex {
    card_index("a6409aa6-035c-4859-8135-90d34d67f72c")
}

/// Kobold Drill Sergeant — {1}{R}, a 1/2 Kobold Soldier whose whole text is
/// one static: "Other Kobold creatures you control get +0/+1 and have
/// trample."
///
/// The board carries a Sergeant on each side of the table, an Elf under the
/// seat that will cast a second one, and that second one in hand, because
/// every word of the filter needs its own witness: the lone Sergeant reads
/// the printed (1, 2) with no trample, which is the word "Another" being read
/// rather than skipped; the Elf stays a (1, 1), which is "Kobold"; and the
/// Sergeant across the table stays (1, 2), which is "you control".
///
/// Casting the second one is the whole card in one move — it arrives as an
/// *other* Kobold to the one beside it, so the pair reads (1, 3) with trample
/// where a moment earlier nothing on either side moved.
#[test]
fn kobold_drill_sergeant_arms_only_the_other_kobolds_its_controller_has() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                llanowar_elves(),
                kobold_drill_sergeant(),
            ],
        )
        .battlefield(1, &[kobold_drill_sergeant()])
        .hand(0, &[kobold_drill_sergeant()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let sergeant =
        on_battlefield(&engine, p0, kobold_drill_sergeant()).expect("a Sergeant is on the table");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");
    let theirs =
        on_battlefield(&engine, p1, kobold_drill_sergeant()).expect("their Sergeant is out");

    assert_eq!(
        pt(&engine, sergeant),
        (1, 2),
        "the only Kobold under this seat is not an *other* Kobold to itself"
    );
    assert!(
        !keywords(&engine, sergeant).contains(KeywordSet::TRAMPLE),
        "and the static does not grant its own source the keyword it prints"
    );
    assert_eq!(pt(&engine, elves), (1, 1), "an Elf is no Kobold");
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::TRAMPLE),
        "so the Elf keeps its printed body and gains nothing"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 2),
        "and a Kobold the other seat controls is not one *you* control"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::TRAMPLE),
        "so the Sergeant across the table never moves"
    );

    // The second one arrives the way a card arrives: {1}{R} off the two
    // Mountains (and the Elf, whose only ability is its own {T}).
    cast_from_hand(&mut engine, p0, kobold_drill_sergeant());
    pass_until(&mut engine, stack_is_empty);

    let pair = all_on_battlefield(&engine, p0, kobold_drill_sergeant());
    assert_eq!(
        pair.len(),
        2,
        "the cast Sergeant resolved beside the seated one"
    );
    for id in pair {
        assert_eq!(
            pt(&engine, id),
            (1, 3),
            "+0/+1 from the other Kobold beside it, and one point of toughness \
             per Sergeant — not two from a static that read itself"
        );
        assert!(
            keywords(&engine, id).contains(KeywordSet::TRAMPLE),
            "and trample off the same static"
        );
    }
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "\"Kobold\" is read and not skipped: the Elf beside them never grew"
    );
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::TRAMPLE),
        "nor did it gain trample"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 2),
        "\"you control\" is read too: their Sergeant counts its own side and \
         not mine"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::TRAMPLE),
        "and it stays the printed 1/2 it entered as"
    );
}

fn kobold_overlord() -> CardIndex {
    card_index("5839bc83-868e-402a-9233-ad3d2871ac6d")
}

/// Kobold Overlord — {1}{R} — is a 1/2 Kobold printing `first strike` and
/// "Other Kobold creatures you control have first strike." The static is a
/// four-part filter and this board strikes two of its limbs: a Llanowar Elf
/// under the same seat is a creature you control and no Kobold, and a
/// Llanowar Elf across the table is a creature somebody else controls and no
/// Kobold — a filter that had lost `HasSubtype(KOBOLD)` arms the first, one
/// that had lost `ControlledByYou` arms the second, and the Sol Ring beside
/// them catches a filter that had lost `CREATURE`.
///
/// The Overlord's own first strike is the keyword it prints, so the positive
/// half of the static — another Kobold, which has none of its own — is the
/// one thing this scenario cannot reach: no handle in this crate names a
/// second Kobold, and nothing else on the board is one.
#[test]
fn kobold_overlord_arms_itself_and_no_creature_that_is_not_a_kobold() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[mountain(), mountain(), llanowar_elves(), quiet_artifact()],
        )
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[kobold_overlord()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{R} off the two Mountains; every card on the board that is not a
    // Mountain makes mana too, so the cast is paid out of the pool the
    // helper filled rather than out of a claim about untapped lands.
    cast_from_hand(&mut engine, p0, kobold_overlord());
    pass_until(&mut engine, stack_is_empty);

    let overlord = on_battlefield(&engine, p0, kobold_overlord()).expect("the Overlord resolved");
    assert_eq!(pt(&engine, overlord), (1, 2), "the body the card prints");
    assert!(
        keywords(&engine, overlord).contains(KeywordSet::FIRST_STRIKE),
        "the Overlord's own first strike reaches it as the keyword it prints"
    );

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let rock = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring is out");
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::FIRST_STRIKE),
        "\"other **Kobold** creatures you control\": a Llanowar Elf is a \
         creature you control and no Kobold"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::FIRST_STRIKE),
        "\"**you control**\" is not the whole table: the Elf across it stays a \
         keywordless 1/1"
    );
    assert!(
        !keywords(&engine, rock).contains(KeywordSet::FIRST_STRIKE),
        "and the Sol Ring under the same seat is no creature at all"
    );
}

fn kobold_taskmaster() -> CardIndex {
    card_index("372f2534-25dc-4ff3-9891-31ee42b33345")
}

/// Kobold Taskmaster — {1}{R}, a 1/2 Kobold — prints exactly one sentence:
/// "Other Kobold creatures you control get +1/+0." Four words carry it and
/// each needs its own witness on the board: "Other" (a lone Taskmaster is a
/// Kobold its controller controls and has to stay 1/2), "Kobold" (the Elf
/// beside it is a creature you control and gains nothing), "you control" (a
/// third Taskmaster across the table has to stay 1/2) and the pump itself,
/// which only a second Kobold under the same seat can show — two Taskmasters
/// under one seat pump each other to 2/2 without either pumping itself.
#[test]
fn kobold_taskmaster_pumps_only_the_other_kobolds_its_controller_has() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                llanowar_elves(),
            ],
        )
        .battlefield(1, &[kobold_taskmaster()])
        .hand(0, &[kobold_taskmaster(), kobold_taskmaster()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");
    let theirs = on_battlefield(&engine, p1, kobold_taskmaster()).expect("their Kobold is out");
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "a printed 1/1 with nothing cast yet"
    );
    assert_eq!(pt(&engine, theirs), (1, 2), "and their printed 1/2");

    // Four Mountains pay for both Taskmasters — {1}{R} each — inside this one
    // main phase (CR 500.5), and the Elf is named as the source kept back so
    // that "four" is a count of four lands and not of a mana creature that
    // `tap_all_mana_but` would have drunk along with them.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Mountains, and the Elf holds its {{G}}"
    );

    // The first copy alone: a Kobold its own controller controls, and the word
    // "Other" is what keeps the static off it.
    cast_with_floating(&mut engine, p0, kobold_taskmaster());
    pass_until(&mut engine, stack_is_empty);
    let lone = all_on_battlefield(&engine, p0, kobold_taskmaster());
    assert_eq!(lone.len(), 1, "one Taskmaster resolved");
    assert_eq!(
        pt(&engine, lone[0]),
        (1, 2),
        "\"Other\": the Taskmaster is a Kobold its controller controls, so it \
         does not pump itself"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "\"Kobold\": a creature you control of some other type gains nothing"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 2),
        "\"you control\": their Taskmaster is a Kobold and it is other, and it \
         still takes nothing"
    );

    // The second copy is the pump's only witness: no other card on this board
    // grants +1/+0 to anything.
    cast_with_floating(&mut engine, p0, kobold_taskmaster());
    pass_until(&mut engine, stack_is_empty);
    let pair = all_on_battlefield(&engine, p0, kobold_taskmaster());
    assert_eq!(pair.len(), 2, "the second copy resolved beside the first");
    assert_eq!(
        pt(&engine, pair[0]),
        (2, 2),
        "another Kobold you control: 1/2 plus the printed +1/+0"
    );
    assert_eq!(
        pt(&engine, pair[1]),
        (2, 2),
        "and the same read from the other side of the pair"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "two {{1}}{{R}} casts came out of the four Mountains"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the Elf is still a printed 1/1: the subtype filter is read and not \
         skipped"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 2),
        "and their Kobold gains nothing from a static it is not under"
    );
}

fn leonin_skyhunter() -> CardIndex {
    card_index("517c7295-8ba2-47a6-a1c6-aee722f8ca88")
}

/// Leonin Skyhunter is `{W}{W}` for a 2/2 Cat Knight and one word of text:
/// flying. That word is only worth playing when somebody tries to block, and
/// the block offer here is a *pairing* — `BlockOption` lists which blocker may
/// be assigned to which attacker — so the same declared attacker is looked up
/// twice on one board: a ground Elf may not be paired with it and a Baleful
/// Strix may. The Skyhunter is cast with the two Plains and then waits a full
/// turn cycle, because CR 302.6 keeps a creature cast this turn out of the
/// attack declaration entirely, and an unoffered attacker proves nothing about
/// flying.
#[test]
fn leonin_skyhunter_flies_over_the_ground_and_is_blockable_only_by_a_flier() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(401, plains())
        .battlefield(0, &[plains(), plains()])
        .hand(0, &[leonin_skyhunter()])
        .battlefield(1, &[llanowar_elves(), baleful_strix()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, leonin_skyhunter());
    pass_until(&mut engine, stack_is_empty);
    let hunter = on_battlefield(&engine, p0, leonin_skyhunter()).expect("the Skyhunter resolved");
    assert_eq!(pt(&engine, hunter), (2, 2), "the body the card prints");
    assert!(
        types(&engine, hunter).contains(TypeSet::CREATURE),
        "and it arrived as the creature it is"
    );
    assert!(
        keywords(&engine, hunter).contains(KeywordSet::FLYING),
        "the whole of its printed text is the keyword"
    );

    let elves = on_battlefield(&engine, p1, llanowar_elves()).expect("a ground blocker");
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("a flying blocker");
    assert!(
        !is_tapped(&engine, elves) && !is_tapped(&engine, strix),
        "both are untapped and so both are available to block"
    );

    // A creature cast this turn may not attack (CR 302.6), so the scenario
    // walks the opponent's turn and back rather than reading the keyword off
    // a permanent the combat step would never offer.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, hunter),
        "the untap step stood the Skyhunter back up"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stopped on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&hunter),
        "the flier is offered as an attacker in its controller's turn: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(hunter, Defender::Player(p1))],
            },
        )
        .unwrap();

    // Walk to the defending seat's declaration without answering it: `pass_until`
    // declares no blockers, which would resolve the combat before the pairing
    // could be read.
    for _ in 0..30 {
        if matches!(engine.pending(), Pending::ChooseBlockers { .. }) {
            break;
        }
        let Pending::Priority { player, .. } = engine.pending().clone() else {
            panic!(
                "expected priority on the way to the block declaration, got {:?}",
                engine.pending()
            );
        };
        engine.apply(player, PlayerAction::PassPriority).unwrap();
    }
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        panic!(
            "the defending seat is asked how it blocks: {:?}",
            engine.pending()
        );
    };
    assert_eq!(player, p1, "and it is the seat being attacked");

    assert!(
        blockers
            .iter()
            .find(|o| o.blocker == elves)
            .is_none_or(|o| !o.attackers.contains(&hunter)),
        "CR 702.9b: a creature without flying cannot be paired with a flier: {blockers:?}"
    );
    let winged = blockers
        .iter()
        .find(|o| o.blocker == strix)
        .expect("a creature with flying is offered as a blocker at all");
    assert!(
        winged.attackers.contains(&hunter),
        "and flying is symmetric — the Strix is paired with the Skyhunter: {blockers:?}"
    );
}

fn llanowar_dead() -> CardIndex {
    card_index("3a48541a-240b-4406-945c-1d0d032eca25")
}

/// Llanowar Dead — `{B}{G}` Creature — Zombie Elf, 2/2, whose entire printed
/// text is one line: "`{T}`: Add `{B}`."
///
/// Both halves are played, because neither shows the other. The cast proves the
/// two-colour cost is really paid off a Swamp and a Forest — the pool is empty
/// and the Swamp is tapped afterwards — and the mana ability proves the creature
/// adds *black* rather than the green it costs, as an ordinary `(source, index)`
/// entry in `LegalActions::abilities` and with nothing on the stack (CR 605.1,
/// 605.3b). It is activated in p0's **next** own turn, so that whether this
/// engine reads a creature's summoning sickness as reaching its mana ability is
/// not what the test decides; the 2/2 body is read off the board in between.
#[test]
fn llanowar_dead_costs_black_and_green_and_taps_for_black() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[swamp(), forest()])
        .hand(0, &[llanowar_dead()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // One Swamp and one Forest is exactly {B}{G}, so the cast is paid by the
    // two lands the test named and by nothing else.
    cast_from_hand(&mut engine, p0, llanowar_dead());
    pass_until(&mut engine, stack_is_empty);

    let dead = on_battlefield(&engine, p0, llanowar_dead()).expect("the {B}{G} spell resolved");
    assert_eq!(pt(&engine, dead), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{B}}{{G}} was paid, so nothing is left floating"
    );
    let land = on_battlefield(&engine, p0, swamp()).expect("the Swamp is still out");
    assert!(
        is_tapped(&engine, land),
        "the {{B}} half of the cost came off the Swamp"
    );

    // A turn cycle, so the {T} below is unambiguously payable.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 takes another turn and holds priority in its own main phase"
    );

    let dead = on_battlefield(&engine, p0, llanowar_dead()).expect("still on the battlefield");
    assert!(!is_tapped(&engine, dead), "nothing has tapped it yet");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "a main phase begins with an empty pool"
    );

    // Ability 0 is the printed "{T}: Add {B}." Its whole price is its own tap,
    // so nothing is tapped or floated first.
    activate(&mut engine, p0, llanowar_dead(), 0);

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Black), 1, "{{T}}: Add {{B}}");
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "the Zombie Elf adds black, not the green it costs to cast"
    );
    assert_eq!(pool.total(), 1, "one mana, off one tap");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, dead), "the creature paid its own {{T}}");
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "and the seat holds priority again, got {:?}",
        engine.pending()
    );
}

fn longbow_archer() -> CardIndex {
    card_index("51531db1-ba59-4ccc-9a91-54de2887fc8b")
}

/// Longbow Archer is `{W}{W}` for a 2/2 with reach and first strike, and a
/// keyword is worth nothing as a word in a card file: it is projected from the
/// card def only once the layers have run, so a test reading the def would pass
/// while the permanent on the table carried neither. So the Archer is cast for
/// its printed cost onto a board with a bare Elf beside it, and the pair is read
/// off the objects the layers project — the Archer with both keywords, the Elf
/// with neither. Reach is then exercised where it is a rule rather than a word:
/// the flying Baleful Strix across the table attacks, and the defender's own
/// block declaration is the only place "can block creatures with flying" lives —
/// the Archer is offered against the Strix and the untapped Elf beside it is not.
#[test]
fn longbow_archer_lands_with_reach_and_first_strike_and_blocks_a_flier() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .hand(0, &[longbow_archer()])
        .battlefield(1, &[baleful_strix()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // `{W}{W}` out of the two Plains, with the Elf named as the printing kept
    // back: it is the control in the block declaration below, and a creature
    // tapped for its own mana may not block for the rest of the turn.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        2,
        "two Plains, two white, and the Elf tapped for nothing"
    );
    cast_with_floating(&mut engine, p0, longbow_archer());
    pass_until(&mut engine, stack_is_empty);

    let archer = on_battlefield(&engine, p0, longbow_archer()).expect("the Archer resolved");
    assert_eq!(pt(&engine, archer), (2, 2), "the body the card prints");
    let kw = keywords(&engine, archer);
    assert!(kw.contains(KeywordSet::REACH), "reach");
    assert!(kw.contains(KeywordSet::FIRST_STRIKE), "first strike");

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    let elf_keywords = keywords(&engine, elf);
    assert!(
        !elf_keywords.contains(KeywordSet::REACH)
            && !elf_keywords.contains(KeywordSet::FIRST_STRIKE),
        "the Elf beside it has neither of the Archer's keywords"
    );

    // Reach decides something only in a block declaration, so the flying Strix
    // attacks and p0's own offer is read: that list is the whole rule, and a
    // keyword that never reached it would leave the Archer unblockable.
    reach_their_main_phase(&mut engine, p1);
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("the Strix is out");
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(strix, Defender::Player(p0))],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until only stops on the block declaration")
    };
    assert_eq!(player, p0, "the defending seat answers");
    let against_the_strix = blockers
        .iter()
        .find(|option| option.blocker == archer)
        .expect("reach lets the Archer block a creature with flying");
    assert!(
        against_the_strix.attackers.contains(&strix),
        "the Archer may block the Strix: {against_the_strix:?}"
    );
    assert!(
        blockers
            .iter()
            .all(|option| option.blocker != elf || !option.attackers.contains(&strix)),
        "an untapped Elf with neither reach nor flying may not: {blockers:?}"
    );
}

fn lotus_cobra() -> CardIndex {
    card_index("8ad91f64-ccab-4edc-bd54-b2ee9267d614")
}

/// Lotus Cobra prints one line: Landfall — "Whenever a land you control
/// enters, add one mana of any color." This scenario plays it from the
/// beginning: the 2/1 Snake enters for {1}{G}, the pool is empty afterward,
/// and when its controller plays a land, the color question covers all five
/// colors — so the black mana in the pool can only come from the trigger, and
/// the land that triggered it stayed untapped. The second clause "you
/// control" is checked with a land that enters under the opponent's control:
/// there no one asks for a color.
#[test]
fn lotus_cobra_adds_a_mana_of_any_color_for_your_land_and_none_for_theirs() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(31, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[lotus_cobra(), forest()])
        .hand(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} from the two Forests, and after that the pool is empty again —
    // this is what makes the mana reading further down an exact statement.
    cast_from_hand(&mut engine, p0, lotus_cobra());
    pass_until(&mut engine, stack_is_empty);
    let cobra = on_battlefield(&engine, p0, lotus_cobra()).expect("the Cobra resolved");
    assert_eq!(pt(&engine, cobra), (2, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{1}}{{G}} is all that the two Forests gave"
    );

    // The land drop that the card is about.
    let land = play_land(&mut engine, p0, forest());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseColor { .. })
    });
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        unreachable!("pass_until hält auf nichts als der Farbfrage an");
    };
    assert_eq!(player, p0, "the controller of the Cobra names the color");
    assert_eq!(
        options.len(),
        5,
        "\"any color\" is the game's five colors (CR 105.4): {options:?}"
    );
    for color in [
        ManaColor::White,
        ManaColor::Blue,
        ManaColor::Black,
        ManaColor::Red,
        ManaColor::Green,
    ] {
        assert!(
            options.contains(&color),
            "`any color` schließt {color:?} ein"
        );
    }

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Black))
        .expect("black was one of the offered colors");
    pass_until(&mut engine, stack_is_empty);

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        1,
        "the named color, and no default value"
    );
    assert_eq!(
        pool.total(),
        1,
        "ein Mana, aus einem Land, und sonst nichts"
    );
    assert!(
        !is_tapped(&engine, land),
        "der Wald, der den Auslöser ausgelöst hat, hat selbst nichts bezahlt: \
         das Mana kam von der Cobra"
    );

    // Die andere Hälfte von „you control": dasselbe Ereignis auf der anderen
    // Seite des Tisches.
    reach_their_main_phase(&mut engine, p1);
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("p1 holds a main phase priority: {:?}", engine.pending())
    };
    assert_eq!(player, p1, "and it is the opponent who holds it");
    let theirs = *legal.lands.first().expect("p1 has a land in hand");
    engine
        .apply(p1, PlayerAction::PlayLand { card: theirs })
        .expect("a land drop in one's own main phase");

    // Ein Landfall-Auslöser würde die Farbfrage auf den Stapel legen, und sie
    // wäre beantwortet, bevor diese Phase enden kann; nichts anderes im Spiel
    // stellt hier eine.
    let mut asked = false;
    for _ in 0..8 {
        match engine.pending().clone() {
            Pending::ChooseColor { .. } => {
                asked = true;
                break;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            _ => break,
        }
    }
    assert!(
        !asked,
        "a land under the opponent's control is not a land *you control*, so \
         the Cobra offers no mana"
    );
}

fn lurking_nightstalker() -> CardIndex {
    card_index("8c17f48b-467e-4953-85d0-221cef5b3bff")
}

/// Lurking Nightstalker prints a single line: "Whenever this creature
/// attacks, it gets +2/+0 until end of turn." The filter is `Filter::This`,
/// so a second Nightstalker stands idle next to it and must not pump itself
/// — only this way can the two readings "the attacker" and "each
/// Nightstalker" be told apart. That p1 takes three instead of one combat
/// damage shows that the +2/+0 applied when attacking and were not merely
/// projected, and the controller's own main phase in the next turn reads the
/// second half of the sentence: "until end of turn" is not a lasting type.
#[test]
fn lurking_nightstalker_pumps_itself_when_it_attacks_and_not_its_idle_twin() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(1837, swamp())
        .battlefield(0, &[lurking_nightstalker(), lurking_nightstalker()])
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let stalkers = all_on_battlefield(&engine, p0, lurking_nightstalker());
    assert_eq!(
        stalkers.len(),
        2,
        "two Nightstalkers, one of them stays home"
    );
    let (attacker, bystander) = (stalkers[0], stalkers[1]);
    assert_eq!(pt(&engine, attacker), (1, 1), "die gedruckte 1/1");
    assert_eq!(pt(&engine, bystander), (1, 1), "die gedruckte 1/1");

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until hält nur an der Angriffserklärung")
    };
    assert!(
        attackers.contains(&attacker),
        "an untapped 1/1 may attack, even though its text prints nothing but \
         a trigger: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(attacker, Defender::Player(p1))],
            },
        )
        .unwrap();

    // Der Angriffs-Trigger geht mit der Erklärung auf den Stapel (CR 603.2)
    // und löst auf, lange bevor irgendwer Schaden nimmt.
    pass_until(&mut engine, |e| {
        stack_is_empty(e) && matches!(e.pending(), Pending::Priority { .. })
    });
    assert_eq!(
        pt(&engine, attacker),
        (3, 1),
        "+2/+0 für den, der angegriffen hat"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "`Filter::This` pumps the attacker and not every Nightstalker in the game"
    );

    // Three combat damage instead of one: the +2/+0 applied when it
    // struck and was not a mere projection.
    pass_until(&mut engine, |e| e.state().players[1].life < 20);
    assert_eq!(
        engine.state().players[1].life,
        17,
        "drei Kampfschaden von der gepumpten 1/1"
    );

    // "until end of turn" is the second half of the line: next turn
    // the pump is gone, without anyone having to remove it.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, attacker),
        (1, 1),
        "the pump ends with the turn and not with the attack"
    );
}

fn master_decoy() -> CardIndex {
    card_index("94a16609-8529-4301-8a3d-47ced194f7cd")
}

/// Master Decoy is a `{1}{W}` 1/2 whose whole card is one line: "`{W}`,
/// `{T}`: Tap target creature." The two halves of that price leave their
/// marks in two different places — the `{W}` in the mana pool and the `{T}`
/// on the creature itself — so the line has to be absent over an empty pool,
/// offered the moment white is floating, and paid for exactly when the
/// target is answered (CR 601.2c before CR 601.2h). Two Elves stand across
/// the table and only the one that was named may change state, which is what
/// tells "target creature" from "creatures"; the Decoy itself stays on the
/// menu as the other side of the same filter and as the permanent the tap
/// symbol spends.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn master_decoy_taps_the_creature_it_names_for_a_white_and_its_own_tap() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(6174, forest())
        .battlefield(0, &[plains(), master_decoy()])
        .battlefield(1, &[llanowar_elves(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let decoy = on_battlefield(&engine, p0, master_decoy()).expect("the Decoy is on the table");
    let elves = all_on_battlefield(&engine, p1, llanowar_elves());
    assert_eq!(elves.len(), 2, "two Elves across the table");
    let (victim, bystander) = (elves[0], elves[1]);
    assert_eq!(pt(&engine, decoy), (1, 2), "the printed 1/2 body");
    assert!(!is_tapped(&engine, decoy), "and it starts untapped");
    assert!(
        !is_tapped(&engine, victim) && !is_tapped(&engine, bystander),
        "as do both creatures it may aim at"
    );

    // `can_afford` reads the pool and not the untapped land, so with nothing
    // floating the line is not offered at all.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(decoy, 0)),
        "an empty pool pays no {{W}}, so the ability is absent rather than \
         refused: {:?}",
        legal.abilities
    );

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one Plains, and the Decoy prints no mana ability of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(decoy, 0)),
        "with {{W}} floating the whole price is payable: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, master_decoy(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"tap target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert!(
        options.contains(&victim) && options.contains(&bystander),
        "\"target creature\" reaches across the table: {options:?}"
    );
    assert!(
        options.contains(&decoy),
        "and the filter names no controller, so the Decoy is a legal target \
         for its own ability: {options:?}"
    );
    assert_eq!(
        options.len(),
        3,
        "the two Elves and the Decoy, and the Plains is no creature: {options:?}"
    );
    // CR 601.2c before CR 601.2h: while this question stands, neither half of
    // the price has been paid.
    assert!(
        !is_tapped(&engine, decoy),
        "the {{T}} has not been spent yet"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "and the {{W}} is still in the pool"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![victim],
            },
        )
        .expect("the Elf was one of the options it enumerated");

    assert!(
        is_tapped(&engine, decoy),
        "{{T}} is the source's half of the price, paid as the activation ends"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{W}} came out of the pool"
    );
    assert!(
        !is_tapped(&engine, victim),
        "tapping is an effect and not a cost, so nothing has happened yet"
    );
    assert!(
        !stack_is_empty(&engine),
        "and tapping a creature is no mana ability, so the ability waits on \
         the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        is_tapped(&engine, victim),
        "\"tap target creature\" — the one the ability was aimed at"
    );
    assert!(
        !is_tapped(&engine, bystander),
        "and only that one: the Elf nobody named never moved"
    );
    assert!(
        on_battlefield(&engine, p0, master_decoy()).is_some(),
        "the Decoy paid its own tap and is otherwise untouched"
    );
}

// oracle_id = "10736ea3-6253-44c3-8a1e-3b9a7f38f3cf"
fn misshapen_fiend() -> CardIndex {
    card_index("10736ea3-6253-44c3-8a1e-3b9a7f38f3cf")
}

/// Misshapen Fiend is `{1}{B}` for a 1/1 Horror Mercenary whose whole printed
/// text is "Flying", so the only thing a game can hold it to is the combat
/// step: two Swamps pay for it, it arrives as a 1/1 with the keyword on its
/// *projected* characteristics, and a turn later it attacks across a table
/// holding both a grounded Llanowar Elves and a flying Baleful Strix — the
/// one creature that may block it and the one that may not.
///
/// The pairing the engine publishes for the block declaration is the card:
/// the Strix is offered against the Fiend and the Elf is not (CR 702.9b),
/// which is a reading nothing but flying produces — the Elf is untapped,
/// alive, and perfectly able to kill a 1/1, and still may not stand in front
/// of it. p1 falling to 19 is the same claim from the other end, and p0's
/// untouched 20 says the damage is the Fiend's and not a counterattack.
#[allow(clippy::too_many_lines)] // one cast, one full turn cycle, one attack
#[test]
fn misshapen_fiend_flies_over_the_ground_and_only_a_flier_may_block_it() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp()])
        .hand(0, &[misshapen_fiend()])
        // The control: one creature that may block a flier and one that may
        // not, both untapped and both able to kill a 1/1 in a fight.
        .battlefield(1, &[baleful_strix(), llanowar_elves()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // `{1}{B}` off the two Swamps — nothing else on this board makes mana, so
    // an emptied pool afterwards is the whole printed cost and nothing more.
    cast_from_hand(&mut engine, p0, misshapen_fiend());
    pass_until(&mut engine, stack_is_empty);
    let fiend = on_battlefield(&engine, p0, misshapen_fiend()).expect("the Fiend resolved");
    assert_eq!(pt(&engine, fiend), (1, 1), "the body the card prints");
    assert!(
        keywords(&engine, fiend).contains(KeywordSet::FLYING),
        "and the one keyword it prints, seen through the layers: {:?}",
        keywords(&engine, fiend)
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "two black paid the {{1}}{{B}}, with nothing left over"
    );

    // A creature cast this turn is summoning sick (CR 302.6), so the attack
    // waits out a whole turn cycle: through p1's turn and back into p0's.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player, attackers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing else")
    };
    assert_eq!(player, p0, "the active seat declares its attackers");
    assert!(
        attackers.contains(&fiend),
        "untapped and past summoning sickness, it may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(fiend, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The block declaration, read rather than merely answered: this is the
    // engine's own statement about which creatures flying excludes.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing else")
    };
    assert_eq!(player, p1, "the defending seat declares blockers");
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("the Strix is out");
    let elves = on_battlefield(&engine, p1, llanowar_elves()).expect("the Elf is out");
    assert!(
        blockers
            .iter()
            .any(|b| b.blocker == strix && b.attackers.contains(&fiend)),
        "a flier may block a flier: {blockers:?}"
    );
    assert!(
        !blockers
            .iter()
            .any(|b| b.blocker == elves && b.attackers.contains(&fiend)),
        "an untapped 1/1 that could kill the Fiend still may not block it \
         without flying (CR 702.9b): {blockers:?}"
    );
    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .expect("declining to block is always legal");

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "the Fiend's one point of combat damage went through (CR 510.2)"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing came back: the damage is the Fiend's, not a trade"
    );
    assert!(
        on_battlefield(&engine, p0, misshapen_fiend()).is_some(),
        "nobody blocked it, so the Fiend is still on the battlefield"
    );
}

fn monk_realist() -> CardIndex {
    card_index("8df64d89-64ee-4388-826d-dd091db4510a")
}

/// Monk Realist is `{1}{W}` for a 1/1 whose whole text is "When this creature
/// enters, destroy target enchantment." The scenario puts the enchantment
/// across the table and an Elf and a Forest beside it, so a
/// `Filter::ENCHANTMENT` that had widened to "any permanent" would show up in
/// the offer — and the target question is read *after* the body has landed,
/// which is what makes this an enters-trigger rather than the cast itself.
#[test]
fn monk_realist_enters_and_destroys_an_enchantment_across_the_table() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains()])
        .hand(0, &[monk_realist()])
        .battlefield(1, &[luminarch_ascension(), llanowar_elves(), forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let ascension = on_battlefield(&engine, p1, luminarch_ascension())
        .expect("the enchantment is across the table");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf is across the table");
    let land = on_battlefield(&engine, p1, forest()).expect("a Forest is across the table");

    // {1}{W} off the two Plains, mana into the pool first: the offer reads the
    // pool and not the untapped lands.
    cast_from_hand(&mut engine, p0, monk_realist());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });

    assert!(
        on_battlefield(&engine, p0, monk_realist()).is_some(),
        "the body landed before its enters-trigger asked anything"
    );

    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the target choice")
    };
    assert_eq!(player, p0, "the creature's controller aims its own trigger");
    assert!(
        options.contains(&ascension),
        "\"target enchantment\" reaches across the table: {options:?}"
    );
    assert!(
        !options.contains(&elf) && !options.contains(&land),
        "an Elf and a Forest are permanents and no enchantments: {options:?}"
    );
    assert_eq!(options.len(), 1, "one enchantment, one option: {options:?}");

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![ascension],
            },
        )
        .expect("the enchantment the question offered was chosen");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, luminarch_ascension()).is_none(),
        "the targeted enchantment left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p1, luminarch_ascension()).is_some(),
        "and it is in its owner's graveyard, which is where a destroyed \
         permanent goes"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some()
            && on_battlefield(&engine, p1, forest()).is_some(),
        "the permanents the ability did not name never moved"
    );
    let realist = on_battlefield(&engine, p0, monk_realist()).expect("still on the battlefield");
    assert_eq!(
        pt(&engine, realist),
        (1, 1),
        "a printed 1/1 that traded nothing of itself for the enchantment"
    );
}

fn moon_sprite() -> CardIndex {
    card_index("1e41136b-afa7-45ee-8d04-d0c7514b5387")
}

/// Moon Sprite prints exactly two things: `{1}{G}` for a 1/1 Faerie and
/// "Flying". Both together are only worth something if the two mana really
/// disappear from the pool *and* flying changes the combat-step offer — so
/// across the table stands a ground creature that may not block the flyer,
/// and a second Moon Sprite as the one blocker that could. Without the
/// second, a missing offer could not be distinguished from a blocking step
/// that was never even made. The attack waits one turn cycle, because a
/// creature cast this turn has summoning sickness (CR 302.6).
#[test]
fn moon_sprite_flies_over_a_ground_blocker() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[moon_sprite()])
        // The Elf is the control for "Flying", the second Sprite the reason
        // that the block question is even asked.
        .battlefield(1, &[llanowar_elves(), moon_sprite()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Two Forests and nothing else on this side: no mana creature that
    // `tap_all_mana` would include (rule 11), so the two mana the spell
    // costs are readable from the pool.
    cast_from_hand(&mut engine, p0, moon_sprite());
    pass_until(&mut engine, stack_is_empty);
    let sprite = on_battlefield(&engine, p0, moon_sprite()).expect("the Sprite resolved");
    assert_eq!(
        pt(&engine, sprite),
        (1, 1),
        "{{1}}{{G}} buys the printed 1/1 body"
    );
    assert!(
        keywords(&engine, sprite).contains(KeywordSet::FLYING),
        "and the printed flying line reaches the permanent through the layers"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the two Forests paid for it"
    );

    // CR 302.6: cast this turn, so it can only attack after its own turn
    // has begun.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(sprite, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the blocker declaration")
    };
    let ground = on_battlefield(&engine, p1, llanowar_elves()).expect("the Elf is out");
    let flier = on_battlefield(&engine, p1, moon_sprite()).expect("their Sprite is out");
    assert!(
        blockers
            .iter()
            .all(|option| option.blocker != ground || !option.attackers.contains(&sprite)),
        "a ground creature may not block a flyer: {blockers:?}"
    );
    assert!(
        blockers
            .iter()
            .any(|option| option.blocker == flier && option.attackers.contains(&sprite)),
        "the only flyer there is offered exactly this pairing: {blockers:?}"
    );

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "ein 1/1-Flieger, den niemand blocken konnte, trifft für eins"
    );
}

fn nantuko_shade() -> CardIndex {
    card_index("40d02b8c-fb0e-4607-855f-49fbcec2e209")
}

/// Nantuko Shade is a {B}{B} 2/1 with one printed line: "{B}: This creature
/// gets +1/+1 until end of turn." Three activations out of three Swamps are
/// what separate a repeatable pump from a one-shot — 2/1, then 3/2, 4/3, 5/4
/// — while the Llanowar Elves beside it stay a printed 1/1, which is
/// `Filter::This` being read and not "creatures you control".
///
/// The empty pool before the first activation is the other half, because
/// `can_afford` reads the pool rather than the untapped Swamps: with nothing
/// floating the card offers nothing at all. And the pump has to *lapse* —
/// `Duration::UntilEndOfTurn` ends it in the next cleanup (CR 514.2) — or the
/// Shade would be a 5/4 for the rest of the game.
#[test]
fn nantuko_shade_pumps_itself_one_black_at_a_time_and_lets_the_pump_lapse() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(4211, swamp())
        .battlefield(
            0,
            &[swamp(), swamp(), swamp(), llanowar_elves(), nantuko_shade()],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let shade = on_battlefield(&engine, p0, nantuko_shade()).expect("the Shade is on the table");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is on the table");
    assert_eq!(pt(&engine, shade), (2, 1), "the printed 2/1");

    let offered = |engine: &Engine<RegistryLookup>| -> bool {
        matches!(
            engine.pending(),
            Pending::Priority { legal, .. }
                if legal.abilities.iter().any(|(src, _)| *src == shade)
        )
    };
    assert!(
        !offered(&engine),
        "`can_afford` reads the pool and not the untapped Swamps, so with \
         nothing floating the one line the card prints is absent from the offer"
    );

    // Three Swamps, and the Elf kept back: a mana creature tapped for mana is
    // a creature whose status changed for a reason of its own, and this is
    // the creature the static beside it has to leave alone.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        3,
        "three Swamps, three black, and nothing off the Elf"
    );
    assert!(
        offered(&engine),
        "with {{B}} floating the ability is on offer"
    );

    activate(&mut engine, p0, nantuko_shade(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, shade), (3, 2), "one {{B}} is +1/+1, and stacks");
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        2,
        "one black out of the three was the price"
    );

    activate(&mut engine, p0, nantuko_shade(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, shade),
        (4, 3),
        "a second activation on the same creature: +2/+2, not a fresh pump"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        1,
        "a second black out of the pool"
    );
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "`Filter::This`: the creature beside the Shade never moves"
    );

    activate(&mut engine, p0, nantuko_shade(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, shade), (5, 4), "and a third");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three activations spent the whole pool"
    );
    assert!(
        !offered(&engine),
        "and an empty pool is no offer again, so a fourth activation cannot \
         be had for free"
    );

    // `Duration::UntilEndOfTurn`: the next cleanup ends it (CR 514.2).
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        pt(&engine, shade),
        (2, 1),
        "past the end of the turn the Shade is the printed 2/1 again"
    );
}

fn nomadic_elf() -> CardIndex {
    card_index("025bbfc8-bccd-4062-b758-7f9e1f8ad420")
}

/// Nomadic Elf prints a *mana* ability — "{1}{G}: Add one mana of any color"
/// — on a {1}{G} 2/2 body, and the price is the whole card: read as a
/// tap-only line it would make mana out of nothing, and read as a fixed
/// color it would never ask. Two Forests pay exactly {1}{G}, so the pool
/// afterwards holds one mana of the named color and nothing else; and the
/// Elf is still standing afterwards, because the cost is mana and not the
/// tap symbol some other mana creatures print. The question itself is five
/// colors wide with no colorless on it, which is "any color" (CR 105.4).
#[test]
fn nomadic_elf_spends_two_mana_for_one_of_any_color_and_keeps_its_tap() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[nomadic_elf(), forest(), forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let elf = on_battlefield(&engine, p0, nomadic_elf()).expect("the Elf is on the table");
    assert_eq!(pt(&engine, elf), (2, 2), "the body the card prints");

    // `can_afford` reads the pool and not the untapped lands, so the mana is
    // floated first and the offer read afterwards. `tap_all_mana` presses only
    // abilities whose whole price is their own `{T}` (#159), and this one's
    // price is `{1}{G}`, so the Elf is not one of the routes it takes.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Forests, two green"
    );
    assert!(
        !is_tapped(&engine, elf),
        "the price is mana; nothing has tapped the Elf"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(elf, 0)),
        "with {{1}}{{G}} floating the line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, nomadic_elf(), 0);
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!("`any color` is a question, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat is the one that names it");
    assert_eq!(
        options.len(),
        5,
        "the five colors of the game, and colorless is no color at all \
         (CR 105.4): {options:?}"
    );
    for color in [
        ManaColor::White,
        ManaColor::Blue,
        ManaColor::Black,
        ManaColor::Red,
        ManaColor::Green,
    ] {
        assert!(
            options.contains(&color),
            "\"any color\" includes {color:?}: {options:?}"
        );
    }

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Black))
        .expect("black was one of the colors it offered");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        1,
        "the color that was named, and not a default"
    );
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "both Forests paid the {{1}}{{G}}, so no green is left beside it"
    );
    assert_eq!(
        pool.total(),
        1,
        "one mana off a two-mana price — a free activation would leave three"
    );
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        !is_tapped(&engine, elf),
        "and the price was mana alone: the Elf is untapped and still a 2/2"
    );
    assert_eq!(pt(&engine, elf), (2, 2), "which the ability never touched");
}

fn oboro_breezecaller() -> CardIndex {
    card_index("257ee9a0-5ee0-49c4-8619-e75e1134d7ac")
}

/// Oboro Breezecaller — {1}{U}, a 1/1 Moonfolk Wizard with flying — prints
/// "{2}, Return a land you control to its owner's hand: Untap target land."
/// One activation reads every part of that off a different place: the {2}
/// leaves a pool only the three Forests paid into, the returned land is the
/// *cost* and is in its owner's hand before the ability resolves, and the
/// untap is the effect — so the land that was named is still tapped while the
/// price is being settled (CR 601.2c before CR 601.2h). A third Forest that
/// is neither aimed at nor given up stays tapped, which is what says "untap
/// target land" is one land and not a board untap, and the Forest across the
/// table is offered as a target and never moves.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn oboro_breezecaller_returns_a_land_to_untap_the_land_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), oboro_breezecaller()])
        // A land on the other side of the table: "target land" is any land,
        // and a filter narrowed to your own would still offer three.
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let caller =
        on_battlefield(&engine, p0, oboro_breezecaller()).expect("the Breezecaller is out");
    assert!(
        keywords(&engine, caller).contains(KeywordSet::FLYING),
        "the printed flying line reaches the creature"
    );
    let forests = all_on_battlefield(&engine, p0, forest());
    assert_eq!(
        forests.len(),
        3,
        "three Forests: two to pay the {{2}} with and one to give up"
    );
    let (aimed, given_up, bystander) = (forests[0], forests[1], forests[2]);
    let theirs = on_battlefield(&engine, p1, forest()).expect("a Forest across the table");

    // The pool is what `can_afford` reads and not the untapped lands, so the
    // Forests are tapped before anything is claimed about the offer. The
    // Breezecaller prints no mana ability, so it is none of the routes taken.
    assert_eq!(
        tap_all_mana(&mut engine, p0),
        3,
        "the three Forests, and nothing else on the board makes mana"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three green floating"
    );
    assert!(
        forests.iter().all(|id| is_tapped(&engine, *id)),
        "and every Forest is down"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(caller, 0)),
        "with {{2}} floating and a land to give up, the one line the card \
         prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, oboro_breezecaller(), 0);

    // Two questions, answered in the order they arrive: the target
    // (CR 601.2c) and then the land the cost gives up (CR 601.2h).
    let mut asked_target = false;
    let mut asked_cost = false;
    for _ in 0..12 {
        if asked_target && asked_cost {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player,
                options,
                min,
                max,
                ..
            } => {
                assert_eq!(player, p0, "the activating seat aims it");
                assert_eq!((min, max), (1, 1), "one land, no more and no fewer");
                assert!(
                    options.contains(&aimed),
                    "a land this seat controls is on the menu: {options:?}"
                );
                assert!(
                    options.contains(&theirs),
                    "\"target land\" is any land, on either side of the table: {options:?}"
                );
                assert!(
                    !options.contains(&caller),
                    "a Wizard is no land: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![aimed],
                        },
                    )
                    .expect("the land the question offered is a legal target");
                asked_target = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(player, p0, "the activating seat pays its own cost");
                assert_eq!(
                    prompt,
                    ChoicePrompt::CostReturn,
                    "a cost and not a search, and the variant is what tells a \
                     client the land is coming back rather than being given up"
                );
                assert_eq!((min, max), (1, 1), "one land, no more and no fewer");
                assert!(
                    options.contains(&given_up),
                    "a land this seat controls may pay: {options:?}"
                );
                assert!(
                    !options.contains(&theirs),
                    "an opponent's land is not yours to return, whatever the \
                     filter says: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![given_up],
                        },
                    )
                    .expect("the land the cost offered pays for it");
                asked_cost = true;
            }
            other => {
                panic!("unexpected while the Breezecaller's activation resolves: {other:?}")
            }
        }
    }
    assert!(
        asked_target && asked_cost,
        "both the target and the cost are asked before the ability resolves"
    );

    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{2}} came out of the three green the Forests filled"
    );
    assert_eq!(
        engine.state().object(given_up).map(|o| o.zone),
        Some(Zone::Hand),
        "\"return a land you control to its owner's hand\": the very land the \
         cost offered, and not a copy of the same printing"
    );
    assert_eq!(
        all_on_battlefield(&engine, p0, forest()).len(),
        2,
        "and only the land that was named — the other two Forests are still out"
    );
    assert!(
        is_tapped(&engine, aimed),
        "the untap is the effect, so the target is still tapped while the cost \
         is being settled (CR 601.2h)"
    );
    assert!(
        !stack_is_empty(&engine),
        "and the ability is what is waiting"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        !is_tapped(&engine, aimed),
        "\"untap target land\" — the land the ability was aimed at stands back up"
    );
    assert!(
        is_tapped(&engine, bystander),
        "and the Forest it was not aimed at stays down, so the effect is one \
         land and not a board untap"
    );
    assert!(
        on_battlefield(&engine, p1, forest()).is_some() && !is_tapped(&engine, theirs),
        "the Forest across the table was offered as a target and was never the \
         one that was chosen"
    );
}

fn ornithopter() -> CardIndex {
    card_index("a3a98bc9-caa0-49b7-951c-fe4e4f54e4ba")
}

/// Ornithopter prints a `{0}` cost, an Artifact Creature body of 0/2 and one
/// word of rules text: flying. The scenario reads all three off one game — the
/// cast happens out of an **empty** pool with the board's only Forest still
/// standing, so `{0}` is the card's doing and not a land's — and the keyword is
/// read where the rules actually use it: the attack declaration offers the
/// Thopter, and the block pairing across the table offers p1's own flying
/// creature while leaving out p1's ground Elf, both untapped and under the same
/// seat. Those two differ in nothing the engine may act on but the keyword, so
/// a pairing holding both or neither is exactly what a missing flying check
/// would look like — the second Ornithopter is across the table on purpose,
/// because its flying is the one this test has already read.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn ornithopter_lands_for_free_and_only_a_flier_may_block_it() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest()])
        .hand(0, &[ornithopter()])
        .battlefield(1, &[ornithopter(), llanowar_elves()])
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let card = in_hand(&engine, p0, ornithopter()).expect("the Thopter is in hand");
    let land = on_battlefield(&engine, p0, forest()).expect("the Forest is on the table");
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats and nothing has been tapped, which is the pool a {{0}} \
         spell has to be castable out of"
    );
    assert!(
        legal.castable.contains(&card),
        "the printed {{0}} is affordable on an empty pool: {:?}",
        legal.castable
    );
    engine
        .apply(p0, PlayerAction::CastSpell { card })
        .expect("the printed {{0}} is the whole cost");
    pass_until(&mut engine, |e| at_rest(e, p0));

    let thopter = on_battlefield(&engine, p0, ornithopter()).expect("the Thopter resolved");
    assert!(
        !is_tapped(&engine, land),
        "a {{0}} spell spends no mana, so the only land on the board never moved"
    );
    let kinds = types(&engine, thopter);
    assert!(
        kinds.contains(TypeSet::ARTIFACT) && kinds.contains(TypeSet::CREATURE),
        "\"Artifact Creature\" is the type line it arrives with: {kinds:?}"
    );
    assert_eq!(pt(&engine, thopter), (0, 2), "and the body the card prints");
    assert!(
        keywords(&engine, thopter).contains(KeywordSet::FLYING),
        "flying is its whole rules text"
    );

    // CR 302.6: a creature that entered this turn cannot attack, so the
    // scenario waits for a turn of p0's to have begun — which is also what
    // untaps the two creatures across the table.
    reach_their_main_phase(&mut engine, p1);
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player, attackers, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the turn belongs to the Thopter's controller");
    assert!(
        attackers.contains(&thopter),
        "an untapped 0/2 does not stop being a creature because it is an \
         artifact, nor because its power is nothing: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(thopter, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p1, "the seat being attacked answers the pairing");
    let wings = on_battlefield(&engine, p1, ornithopter()).expect("their Thopter is out");
    let grounder = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let can_block = |blocker: ObjectId| {
        blockers
            .iter()
            .any(|o| o.blocker == blocker && o.attackers.contains(&thopter))
    };
    assert!(
        can_block(wings),
        "a creature with flying may block a flier: {blockers:?}"
    );
    assert!(
        !can_block(grounder),
        "and one without may not, though it stands untapped beside the first \
         and under the same seat: {blockers:?}"
    );

    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        20,
        "nobody blocked it, so the 0/2 connected — and took nothing with it, \
         which is the printed power and not a size a keyword added"
    );
}

fn orochi_sustainer() -> CardIndex {
    card_index("d3039b42-25d5-4fe2-955a-0d910d7395bd")
}

/// Orochi Sustainer is a `{1}{G}` 1/2 Snake Shaman whose entire printed
/// is a single mana ability: "{T}: Add {G}". The card is thus truly played —
/// the body is read from the battlefield, and the tap happens a turn later so
/// that the creature is unambiguously no longer summoning-sick (CR 302.6) and
/// both Forests are standing again. Precisely these two standing Forests are
/// the control: “exactly one green and nothing else” is only a statement
/// about the Sustainer if no source next to it has moved — and no
/// `ChooseColor` question is asked, because the card names its color where
/// “Add one mana of any color” would have to choose (CR 605.3b: no stack).
#[test]
fn orochi_sustainer_taps_for_one_green_and_nothing_else_moves() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(1731, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[orochi_sustainer()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} from exactly the two Forests: two green tapped and two paid,
    // so the pool is empty when the creature lands — the green below cannot
    // therefore be a leftover from the calculation.
    cast_from_hand(&mut engine, p0, orochi_sustainer());
    pass_until(&mut engine, stack_is_empty);
    let snake = on_battlefield(&engine, p0, orochi_sustainer()).expect("the Sustainer resolved");
    assert_eq!(pt(&engine, snake), (1, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the two Forests pay exactly the {{1}}{{G}} and leave nothing floating"
    );

    // A turn change, so that the {T} is unambiguously payable (CR 302.6) and
    // both Forests stand up again — they are the control against which the
    // green is read, and they must stand for that.
    reach_their_main_phase(&mut engine, p1);
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");
    let lands = all_on_battlefield(&engine, p0, forest());
    assert_eq!(lands.len(), 2, "both Forests are still on the table");
    assert!(
        lands.iter().all(|id| !is_tapped(&engine, *id)),
        "and both are untapped, so neither has paid into the pool below"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats on the new turn, so the tap is the only source there is"
    );

    // Ability 0 is the printed "{T}: Add {G}" — a mana ability that a card
    // prints, thus an ordinary entry in `abilities` with an index, and its
    // entire cost is its own tap symbol.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(snake, 0)),
        "an untapped Sustainer with nothing floating is a payable {{T}}: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, orochi_sustainer(), 0);
    assert!(
        !matches!(engine.pending(), Pending::ChooseColor { .. }),
        "the card names its colour, so there is nothing to choose: {:?}",
        engine.pending()
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Green), 1, "{{T}}: Add {{G}}");
    assert_eq!(
        pool.total(),
        1,
        "one mana, off one tap, and nothing beside it"
    );
    assert!(
        is_tapped(&engine, snake),
        "the Sustainer paid its own {{T}}"
    );
    assert!(
        lands.iter().all(|id| !is_tapped(&engine, *id)),
        "and no Forest moved: the green came off the creature and not off a land"
    );
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
}

fn patrol_hound() -> CardIndex {
    card_index("115dabbd-1a09-4641-a428-92fcbfd82ae9")
}

/// Patrol Hound is a `{1}{W}` 2/2 whose entire rules text is a cost with
/// a question in it: "Discard a card: This creature gains first strike
/// until end of turn." Both halves are played — the Hound is cast so that
/// the permanent is a real one, the card for the cost comes from the hand
/// that the engine itself enumerated, and the keyword is only read after
/// resolution through the layers. The Llanowar Elf under the same control is
/// the control: the pump is `Filter::This`, so no second creature may take
/// the keyword along. That the card is already in the graveyard while the
/// ability is still waiting on the stack is CR 601.2h — payment happens
/// before resolution, and the Hound never taps in the process.
#[test]
fn patrol_hound_discards_a_card_to_gain_first_strike() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .hand(0, &[patrol_hound(), forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, patrol_hound());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let hound = on_battlefield(&engine, p0, patrol_hound()).expect("the Hound resolved");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert_eq!(pt(&engine, hound), (2, 2), "a printed 2/2");
    assert!(
        !keywords(&engine, hound).contains(KeywordSet::FIRST_STRIKE),
        "nothing has been discarded yet"
    );

    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Hound holds priority");
    assert!(
        legal.abilities.contains(&(hound, 0)),
        "the price is a card and no mana, so the one line the card prints is \
         offered as long as the hand is not empty: {:?}",
        legal.abilities
    );

    let fodder = in_hand(&engine, p0, forest()).expect("a Forest is in hand");
    activate(&mut engine, p0, patrol_hound(), 0);

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the discard is a cost and asks which card, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostDiscard,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert!(
        options.contains(&fodder),
        "a card in hand is the whole of the answer: {options:?}"
    );
    assert!(
        in_hand(&engine, p0, forest()).is_some(),
        "CR 601.2h: costs are paid after the question, so nothing has left the hand yet"
    );

    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the card the question offered pays the cost");

    assert!(
        in_graveyard(&engine, p0, forest()).is_some(),
        "the discarded card left the hand for its owner's graveyard"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before - 1,
        "exactly one card was given up"
    );
    assert!(
        !stack_is_empty(&engine),
        "gaining a keyword is no mana ability, so the ability is on the stack"
    );
    assert!(
        !is_tapped(&engine, hound),
        "its whole price is the card: the Hound never taps"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        keywords(&engine, hound).contains(KeywordSet::FIRST_STRIKE),
        "\"This creature gains first strike\""
    );
    assert_eq!(
        pt(&engine, hound),
        (2, 2),
        "the pump is +0/+0 and the keyword: the body does not move"
    );
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FIRST_STRIKE),
        "`Filter::This` reaches the Hound and no other creature"
    );
}

fn phyrexian_denouncer() -> CardIndex {
    card_index("b331c5fa-cd97-4fd8-b1df-d2c9e6a5a854")
}

/// Phyrexian Denouncer is a `{1}{B}` 1/1 whose entire text is one line:
/// "{T}, Sacrifice this creature: Target creature gets -1/-1 until end of
/// turn." It is *cast* here rather than seated, because the `{T}` in the cost
/// is what summoning sickness (CR 302.6) makes unpayable in the turn the
/// creature arrives — the offer is read twice, once on each side of that
/// rule, and the second read is a whole round of turns later. The `-1/-1` is
/// aimed at a body large enough to survive it, so the numbers read a *pump*
/// and not a death, and an Elf across the table is the control that
/// separates "target creature" from "creatures you control". The target
/// question is answered before the price is paid (CR 601.2c, then
/// CR 601.2h), so the still-standing creature on the battlefield is the state
/// that proves the ordering — and the last turn cycle is the printed "until
/// end of turn".
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn phyrexian_denouncer_taps_and_sacrifices_itself_for_a_minus_one_minus_one() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), rootbreaker_wurm()])
        .hand(0, &[phyrexian_denouncer()])
        // A creature across the table: "target creature" names no controller,
        // and an offer that only ever held this seat's own board would
        // satisfy every number below.
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches its own first main"
    );

    // {1}{B} off the two Swamps, and then the offer is read in the turn it
    // arrived: the tap symbol is a price a creature this new may not pay.
    cast_from_hand(&mut engine, p0, phyrexian_denouncer());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, phyrexian_denouncer()).is_some()
    });
    let denouncer =
        on_battlefield(&engine, p0, phyrexian_denouncer()).expect("the Denouncer resolved");
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == denouncer),
        "CR 302.6: a {{T}} in the cost of a creature that arrived this turn is \
         unpayable, so the one line the card prints is not offered: {:?}",
        legal.abilities
    );

    // A whole round of turns, which is what CR 302.6 asks for.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "and back to the Denouncer's controller"
    );

    let wurm = on_battlefield(&engine, p0, rootbreaker_wurm()).expect("the Wurm is out");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let (power, toughness) = pt(&engine, wurm);
    let elf_body = pt(&engine, elf);
    assert!(
        power > 1 && toughness > 1,
        "a body the -1/-1 cannot kill, so the numbers below read a pump and \
         not a death"
    );
    assert!(
        !is_tapped(&engine, denouncer),
        "nothing has tapped it: the price is still unpaid"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the whole price is the tap symbol and the creature, and neither is mana"
    );

    activate(&mut engine, p0, phyrexian_denouncer(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        options.contains(&wurm) && options.contains(&elf),
        "\"target creature\" reaches both sides of the table: {options:?}"
    );
    // CR 601.2c before CR 601.2h: while the question stands the price is
    // unpaid, so the Denouncer is still on the battlefield and still standing.
    assert!(
        on_battlefield(&engine, p0, phyrexian_denouncer()).is_some(),
        "the sacrifice is a cost, and costs are paid after the target"
    );
    assert!(
        !is_tapped(&engine, denouncer),
        "and it is still standing for the same reason"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![wurm],
            },
        )
        .expect("the body the question offered was chosen");

    assert!(
        on_battlefield(&engine, p0, phyrexian_denouncer()).is_none(),
        "\"Sacrifice this creature\" takes the whole card"
    );
    assert!(
        in_graveyard(&engine, p0, phyrexian_denouncer()).is_some(),
        "and a sacrificed creature goes to its owner's graveyard"
    );
    assert!(
        !stack_is_empty(&engine),
        "shrinking a creature is no mana ability, so it waits on the stack"
    );
    assert_eq!(
        pt(&engine, wurm),
        (power, toughness),
        "and the -1/-1 is the resolving effect, so it has not landed yet"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, wurm),
        (power - 1, toughness - 1),
        "-1/-1 on the creature the ability was aimed at"
    );
    assert_eq!(
        pt(&engine, elf),
        elf_body,
        "and nothing at all for the creature it was not aimed at"
    );

    // "until end of turn": a whole round later the body is the one it was
    // printed as, so what landed was a pump and not a counter.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "its controller takes another turn"
    );
    assert_eq!(
        pt(&engine, wurm),
        (power, toughness),
        "the pump expired with the turn it was made in"
    );
}

fn plague_witch() -> CardIndex {
    card_index("532ab335-4873-405b-84b3-c447207172b5")
}

/// Plague Witch — {1}{B}, 1/1 Elf Spellshaper: "{B}, {T}, Discard a card:
/// Target creature gets -1/-1 until end of turn."
///
/// Three parts of one price are each read somewhere different: the {B} comes
/// out of a pool only the Swamp filled, the {T} leaves the Witch tapped, and
/// the discarded card leaves the hand for the graveyard — read *before* the
/// target is named (CR 601.2c, then 601.2h), because while the target question
/// stands the Witch is still untapped and the card is still in hand. The
/// control is the Elf across the table: "target creature" offers it, so the
/// -1/-1 is proven to land on the creature that was named and not on a board
/// sweep. The second Sol Ring in hand is the discard, and the Witch's own
/// p/t is read after resolution to show the pump is aimed outward.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn plague_witch_discards_a_card_and_a_swamp_to_shrink_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[swamp(), plague_witch()])
        .hand(0, &[quiet_artifact()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let witch = on_battlefield(&engine, p0, plague_witch()).expect("the Witch is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    let fodder = in_hand(&engine, p0, quiet_artifact()).expect("the Sol Ring is in hand");
    assert_eq!(pt(&engine, witch), (1, 1), "a printed 1/1");
    assert_eq!(pt(&engine, theirs), (1, 1), "and a 1/1 to shrink");

    // The one Swamp is the whole pool, and the offer is read off it.
    tap_mana_except(&mut engine, p0, witch);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        1,
        "one Swamp tapped for the {{B}} the ability charges"
    );
    assert!(
        !is_tapped(&engine, witch),
        "and the Witch is still standing"
    );

    activate(&mut engine, p0, plague_witch(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&theirs),
        "the Elf across the table is a creature and so a legal target: {options:?}"
    );

    // CR 601.2c before CR 601.2h: nothing is paid while the question stands.
    assert!(
        !is_tapped(&engine, witch),
        "the {{T}} is the last step of the activation, so the Witch is still untapped"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "and the {{B}} is still in the pool"
    );
    assert!(
        in_hand(&engine, p0, quiet_artifact()).is_some(),
        "and the discard has not happened either"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Elf was one of the options it enumerated");

    // Now the costs: {B}, {T}, and a card. The discard asks its own question
    // before the ability resolves.
    if let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    {
        assert_eq!(player, p0, "the activating seat gives up its own card");
        assert_eq!(
            prompt,
            crate::choice::ChoicePrompt::CostDiscard,
            "a cost and not a search, which is all a client has to tell them apart"
        );
        assert_eq!((min, max), (1, 1), "one card, and the cost asks once");
        assert_eq!(
            options,
            vec![fodder],
            "the Sol Ring is the only card in hand, so it is the whole menu"
        );
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![fodder],
                },
            )
            .expect("the card the question offered pays the cost");
    } else {
        panic!(
            "`Discard a card` is a cost and is asked, got {:?}",
            engine.pending()
        );
    }

    assert!(
        is_tapped(&engine, witch),
        "{{T}} is paid with the rest of the cost"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{B}} came out of the pool"
    );
    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "the discarded card is in its owner's graveyard"
    );
    assert!(!stack_is_empty(&engine), "shrinking is no mana ability");
    pass_until(&mut engine, stack_is_empty);

    // Not a 0/0 on the battlefield: CR 704.5a puts a creature with toughness
    // zero into its owner's graveyard before anybody gets priority back, and
    // a card in a graveyard projects its printed self again — so reading
    // `pt` here would read the 1/1 the printing has and call the ability a
    // failure. Where it went is the assertion.
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "-1/-1 on a printed 1/1 leaves nothing behind"
    );
    assert!(
        !engine
            .state()
            .zones
            .list(ZoneLocation::Battlefield)
            .contains(&theirs),
        "and the battlefield is where it is not"
    );
    assert_eq!(
        pt(&engine, witch),
        (1, 1),
        "and the Witch's own body is untouched: the pump is aimed outward"
    );
}

fn plant_elemental() -> CardIndex {
    card_index("e822bf3d-3a29-4a02-9ae8-e2830ce70f15")
}

/// Plant Elemental is `{1}{G}` for a 3/4 whose whole text is one enters
/// trigger: "sacrifice it unless you sacrifice a Forest". Two boards play the
/// two branches of that "unless". With three Forests and an Elf standing, the
/// trigger asks which Forest is given up, the Elemental stays, and the menu it
/// offered can be read for what it leaves off — so the filter is a Forest and
/// not merely "a permanent you control". With no Forest anywhere — two
/// Llanowar Elves pay the `{1}{G}` — there is nothing to give up and the
/// trigger takes the Elemental itself, which is what says the fallback is a
/// real sacrifice rather than a clause that never fires.
#[test]
#[allow(clippy::too_many_lines)] // two boards, one printed sentence, one branch of it each
fn plant_elemental_is_sacrificed_unless_a_forest_is_given_up_for_it() {
    /// Answers whatever the enters-trigger asks: `pay` sacrifices the first
    /// thing the cost offers and declines everything otherwise. Returns the
    /// last menu the cost published, which is the only place the filter that
    /// drew it is legible.
    fn settle(engine: &mut Engine<RegistryLookup>, pay: bool) -> Vec<ObjectId> {
        let mut menu = Vec::new();
        for _ in 0..30 {
            match engine.pending().clone() {
                Pending::Priority { .. } if stack_is_empty(engine) => return menu,
                Pending::Priority { player, .. } => {
                    engine.apply(player, PlayerAction::PassPriority).unwrap();
                }
                Pending::YesNo { player, .. } => {
                    engine.apply(player, PlayerAction::YesNo(pay)).unwrap();
                }
                Pending::ChooseCards {
                    player,
                    options,
                    min,
                    ..
                } => {
                    if pay {
                        let first = options
                            .first()
                            .copied()
                            .expect("the cost names which Forest is given up");
                        menu = options;
                        engine
                            .apply(
                                player,
                                PlayerAction::ChooseObjects {
                                    objects: vec![first],
                                },
                            )
                            .unwrap();
                    } else {
                        assert_eq!(min, 0, "a may-cost is declined by choosing nothing");
                        engine
                            .apply(player, PlayerAction::ChooseObjects { objects: vec![] })
                            .unwrap();
                    }
                }
                other => panic!("unexpected while the enters-trigger resolves: {other:?}"),
            }
        }
        panic!("the enters-trigger never settled");
    }

    let p0 = PlayerId::new(0);

    // Feeding it a Forest. The Elf is the counter-half of the cost's filter:
    // a creature this seat controls, on the menu only if "a Forest" went
    // unread.
    let mut fed = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), llanowar_elves()])
        .hand(0, &[plant_elemental()])
        .start();
    keep_mulligans(&mut fed);
    assert!(walk_to_own_main(&mut fed, p0), "p0 reaches its own main");
    let elf = on_battlefield(&fed, p0, llanowar_elves()).expect("the Elf is out");
    cast_from_hand(&mut fed, p0, plant_elemental());
    let menu = settle(&mut fed, true);

    assert_eq!(
        all_on_battlefield(&fed, p0, forest()).len(),
        2,
        "one Forest paid for the Elemental's life"
    );
    assert!(
        in_graveyard(&fed, p0, forest()).is_some(),
        "and a sacrificed land goes to its owner's graveyard"
    );
    assert!(
        !menu.contains(&elf),
        "\"a Forest\" is the whole of the cost — the Elf beside them is a \
         permanent this seat controls and no part of the menu: {menu:?}"
    );
    let elemental = on_battlefield(&fed, p0, plant_elemental())
        .expect("the Elemental is still standing, which is what it paid for");
    assert_eq!(pt(&fed, elemental), (3, 4), "the body the card prints");
    assert!(
        on_battlefield(&fed, p0, llanowar_elves()).is_some(),
        "and nothing else on the board moved"
    );

    // Nothing to give up, and the two Elves are the mana: the `{1}{G}` is
    // paid in full while not one Forest is anywhere on the table.
    let mut starved = Duel::new(SEED, forest())
        .battlefield(0, &[llanowar_elves(), llanowar_elves()])
        .hand(0, &[plant_elemental()])
        .start();
    keep_mulligans(&mut starved);
    assert!(
        walk_to_own_main(&mut starved, p0),
        "p0 reaches its own main"
    );
    cast_from_hand(&mut starved, p0, plant_elemental());
    settle(&mut starved, false);

    assert!(
        on_battlefield(&starved, p0, plant_elemental()).is_none(),
        "\"sacrifice it unless you sacrifice a Forest\" — with no Forest to \
         give, the Elemental is the only permanent the clause can take"
    );
    assert!(
        in_graveyard(&starved, p0, plant_elemental()).is_some(),
        "and the sacrifice is a real one, so the card is in its owner's graveyard"
    );
    assert_eq!(
        all_on_battlefield(&starved, p0, llanowar_elves()).len(),
        2,
        "the Elves were never part of the price, so neither of them paid it"
    );
}

fn priest_of_titania() -> CardIndex {
    card_index("3a198a16-17b9-481e-b516-5bc945c7e247")
}

/// Priest of Titania — {1}{G}, 1/1 Elf Druid: "{T}: Add {G} for each Elf on
/// the battlefield."
///
/// The count is the whole card, and the word that needs a witness is "on the
/// battlefield": the Priest is an Elf itself, two Llanowar Elves stand beside
/// it and a fourth stands across the table, with no "you control" anywhere in
/// the sentence to keep that one out. Only the two Elves of mine are tapped
/// for mana — the Priest is named as the thing kept back, because its own
/// `{T}` is exactly what this test presses — so the four green that arrive are
/// one per Elf in play and can be read as neither two nor three.
/// The two Shadows stand on the same side of the table as the light: the
/// `{T}` is the whole price of the ability and nothing is asked on the way
/// (CR 605.3b), so the mana is in the pool the moment it is activated.
#[test]
fn priest_of_titania_taps_for_one_green_per_elf_on_the_battlefield() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[priest_of_titania(), llanowar_elves(), llanowar_elves()],
        )
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let priest = on_battlefield(&engine, p0, priest_of_titania()).expect("the Priest is out");
    assert_eq!(pt(&engine, priest), (1, 1), "a printed 1/1");
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "an Elf across the table, which \"on the battlefield\" counts"
    );

    // Two Elves and only those: the Priest prints the very `{T}` this test
    // presses, so `tap_all_mana` would have spent it (#159).
    tap_all_mana_but(&mut engine, p0, Some(priest_of_titania()));
    let before = engine.state().players[0]
        .mana_pool
        .available(ManaColor::Green);
    assert_eq!(before, 2, "two Elves tapped, two green floating");

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(priest, 0)),
        "the whole price is an untapped Priest's own {{T}}, so its one line is \
         offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, priest_of_titania(), 0);

    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so the green is already here"
    );
    assert!(is_tapped(&engine, priest), "the Priest paid its own {{T}}");
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        6,
        "the two green the Elves made plus one for each of the four Elves on \
         the battlefield: the Priest itself, my two, and the one across the \
         table"
    );
    assert_eq!(
        pool.total(),
        6,
        "and nothing else came with it — no other colour, no other source"
    );
}

fn pygmy_razorback() -> CardIndex {
    card_index("2bdd82e7-cbbf-4f12-bcb7-b276df021351")
}

/// Pygmy Razorback prints `{1}{G}` for a 2/1 creature of type Boar with
/// Trample and nothing else. Trample is the only line that does something on
/// the battlefield, and the only kind of proof that a keyword cannot read
/// out of the card text is combat: the Razorback attacks, is blocked by a
/// 1/1, and the excess of 1 goes to the defender, while the blocker's life
/// points die. A test that only read `CHARACTERISTICS` would be green for a
/// card without the ability.
#[test]
fn pygmy_razorback_tramples_one_damage_over_the_blocker_into_the_defender() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[pygmy_razorback()])
        .battlefield(1, &[llanowar_elves()])
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} from two Forests; the Elves are not on the battlefield, so
    // the Razorback is the only creature under p0 and can attack alone.
    cast_from_hand(&mut engine, p0, pygmy_razorback());
    pass_until(&mut engine, stack_is_empty);
    let boar = on_battlefield(&engine, p0, pygmy_razorback()).expect("the Boar resolved");
    assert_eq!(pt(&engine, boar), (2, 1), "ein 2/1, wie gedruckt");
    assert!(
        keywords(&engine, boar).contains(KeywordSet::TRAMPLE),
        "the card prints Trample"
    );

    // Its own next turn: the Boar arrived this turn and may not yet attack
    // (CR 302.6) — the first attack window is its own and empty, and the
    // question at issue here is only asked in the next one.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::ChooseAttackers { attackers, .. } if attackers.contains(&boar)
        )
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(boar, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The Elf on the table blocks, and that is the only way to make Trample
    // visible: without the ability all damage would be stuck on the
    // blocker and p1 would lose nothing.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their blocker is out");
    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(their_elf, boar)],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "1 Schaden an einem 1/1 ist tödlich (CR 704.5f)"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "the attacker takes no damage"
    );
    assert_eq!(
        engine.state().players[1].life,
        19,
        "Trample: der Überschuss von 1 geht auf den Verteidiger (CR 702.19b)"
    );
}

fn scryb_sprites() -> CardIndex {
    card_index("a1f20695-6f08-4d5c-9fba-b0018bee298e")
}

/// Scryb Sprites is a {G} 1/1 Faerie and "Flying" is the whole of its printed
/// text, so a test that only read the keyword off the permanent would prove
/// nothing about what the card does. The scenario therefore plays the keyword
/// in combat: a turn later the Sprites attacks beside a ground 1/1, and the
/// opponent's own untapped Elf — the control that nothing on this board grants
/// flying to anything else — is offered as a blocker for the ground attacker
/// and refused for the flier. Exactly one point of damage gets through, and it
/// is the flier's.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn scryb_sprites_flies_over_the_ground_and_lands_its_point_of_damage() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), llanowar_elves()])
        .hand(0, &[scryb_sprites()])
        .battlefield(1, &[llanowar_elves()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let flier_card = scryb_sprites();
    let my_elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert!(
        !keywords(&engine, their_elf).contains(KeywordSet::FLYING),
        "the Elf across the table is the control: nothing here grants flying \
         to anything but the card under test"
    );

    // {G} off the one Forest, with the Elf named as the source kept back: it is
    // an attacker in the combat below, and a creature tapped for mana is one
    // the attack step will no longer offer.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one Forest tapped, and the Elf did not pay for the spell"
    );
    cast_with_floating(&mut engine, p0, flier_card);
    pass_until(&mut engine, stack_is_empty);
    let sprites = on_battlefield(&engine, p0, flier_card).expect("the Sprites resolved");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{G}} came out of the pool the Forest filled"
    );
    assert_eq!(pt(&engine, sprites), (1, 1), "the body the card prints");
    assert!(
        types(&engine, sprites).contains(TypeSet::CREATURE),
        "and it arrived as a creature"
    );
    assert!(
        keywords(&engine, sprites).contains(KeywordSet::FLYING),
        "with the one keyword the card prints"
    );

    // A turn around, because a creature that entered this turn may not attack
    // (CR 302.6): a flier the combat step never offered would say nothing at
    // all about the keyword.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, sprites) && !is_tapped(&engine, my_elf),
        "both of my creatures untapped with me"
    );
    assert!(
        !is_tapped(&engine, their_elf),
        "and the ground Elf across the table is untapped too, so the block it \
         is refused is refused for flying and not for its own tap"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&sprites) && attackers.contains(&my_elf),
        "both are legal attackers now that neither is sick: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (sprites, Defender::Player(p1)),
                    (my_elf, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the block declaration")
    };
    let ground = blockers
        .iter()
        .find(|option| option.blocker == their_elf)
        .expect("the Elf can block the ground attacker, so it is on the list");
    assert!(
        ground.attackers.contains(&my_elf),
        "and the ground attacker is exactly what it may block, so the refusal \
         below is a refusal and not an empty list: {blockers:?}"
    );
    assert!(
        !ground.attackers.contains(&sprites),
        "the same Elf may not block the flier — flying is the whole of what \
         the card prints and this is the only place it shows: {blockers:?}"
    );

    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(their_elf, my_elf)],
            },
        )
        .expect("the pairing the offer named is a legal answer");
    // Not `stack_is_empty`: the stack is empty the moment blockers are
    // declared, so that predicate would stop before the combat damage step.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert_eq!(
        engine.state().players[1].life,
        19,
        "the ground attacker was answered and the flier was not: one point of \
         damage, and it is the flying creature's"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some()
            && in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "the two ground 1/1s killed each other, which is what says the declared \
         block really happened"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing came back at me"
    );
}

fn quirion_elves() -> CardIndex {
    card_index("e2975a88-5a5a-462a-90b9-d8c00150b6d3")
}

/// Quirion Elves — {1}{G}, 1/1 Elf Druid — prints three sentences: "As this
/// creature enters, choose a color", "{T}: Add {G}", and "{T}: Add one mana of
/// the chosen color". Two mana lines on one body that differ only in the color
/// they hand back, so both are played: the {G} on the turn the Elf can finally
/// pay its own {T} (CR 302.6 keeps a fresh 1/1 from tapping the turn it
/// arrives), and the chosen color on the next one — and the second tap asks
/// nothing, because the color was settled once as the creature entered. Each
/// activation is read against an empty pool, so "exactly one green" and "exactly
/// one blue" are claims about the Elf rather than about the Forests it was cast
/// with. The color is checked through the pool and not through a field, because
/// the pool is what the card is for.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn quirion_elves_taps_for_green_and_for_the_color_it_chose_as_it_entered() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[quirion_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{G} off the two Forests, which spends both: the pool is empty again
    // by the time the Elf asks its question.
    cast_from_hand(&mut engine, p0, quirion_elves());
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{1}}{{G}} took the two Forests and no source is left floating"
    );

    for _ in 0..20 {
        if matches!(engine.pending(), Pending::ChooseColor { .. }) {
            break;
        }
        let Pending::Priority { player, .. } = engine.pending().clone() else {
            panic!(
                "expected priority while the Elves resolves, got {:?}",
                engine.pending()
            );
        };
        engine.apply(player, PlayerAction::PassPriority).unwrap();
    }
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!(
            "\"as this creature enters, choose a color\" is a question, got {:?}",
            engine.pending()
        );
    };
    assert_eq!(
        player, p0,
        "the controller of the entering creature chooses"
    );
    assert_eq!(
        options.len(),
        5,
        "a color is one of the five, and colorless is no color at all \
         (CR 105.4): {options:?}"
    );
    assert!(
        options.contains(&ManaColor::Blue),
        "blue is one of the colors it offered: {options:?}"
    );
    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Blue))
        .expect("blue was one of the colors it offered");

    let elves = on_battlefield(&engine, p0, quirion_elves()).expect("the Elves resolved");
    assert!(
        stack_is_empty(&engine),
        "the question was the spell's last step, so nothing is waiting behind it"
    );
    assert_eq!(pt(&engine, elves), (1, 1), "the printed body");

    // A creature pays a {T} only from the turn after it arrived (CR 302.6),
    // so the first tap is on p0's next turn and not in the main phase it was
    // cast in. Nothing has been tapped and nothing floats.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, elves),
        "the untap step stood it back up"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and no mana is left over from the cast"
    );

    // Ability 0 is the printed "{T}: Add {G}".
    activate(&mut engine, p0, quirion_elves(), 0);
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Green), 1, "{{T}}: Add {{G}}");
    assert_eq!(pool.total(), 1, "one mana, off one tap");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so the mana is here already"
    );
    assert!(is_tapped(&engine, elves), "the Elf paid its own {{T}}");

    // A whole turn later, for the same reason: one creature has one {T}.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the pool emptied when the step that held the green ended (CR 500.5)"
    );
    assert!(!is_tapped(&engine, elves), "and the Elf untapped again");

    // Ability 1 is the printed "{T}: Add one mana of the chosen color", and
    // the color was chosen as the creature entered: nothing is asked here.
    activate(&mut engine, p0, quirion_elves(), 1);
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "the color was settled once, on entry, so the tap asks nothing: {:?}",
        engine.pending()
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Blue),
        1,
        "\"one mana of the chosen color\", and blue is what was chosen"
    );
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "the second line names no color of its own, so it adds none of the first's"
    );
    assert_eq!(
        pool.total(),
        1,
        "one mana, off one tap, and nothing beside it"
    );
    assert!(
        is_tapped(&engine, elves),
        "the Elf paid its own {{T}} again"
    );
}

fn quiron_sentinel() -> CardIndex {
    card_index("70bb2690-653b-4787-bdd1-d1739a8ae545")
}

/// Quirion Sentinel is `{1}{G}` for a 2/1 Elf Druid and prints exactly
/// one line: "When this creature enters, add one mana of any color." The
/// card is the only place in the scenario where mana can be produced — two
/// Forests pay for the spell completely (GG against `{1}{G}`), so the pool
/// is empty when the trigger resolves, and exactly one floating mana of the
/// chosen color is a statement about the card and not about a land.
/// The trigger goes on the stack as a normal triggered ability (CR 603.3),
/// so it is only asked for after priority passes — hence `pass_until`
/// until the `ChooseColor` question, and five colors to choose from, because
/// "any color" means the five colors of the game (CR 105.4) and not
/// colorless.
#[test]
fn quiron_sentinel_adds_one_mana_of_any_color_when_it_enters() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[quiron_sentinel()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{G} from two Forests: afterwards the pool is empty, and nothing on
    // the board can make mana anymore — the Sentinel itself is not a mana
    // source.
    cast_from_hand(&mut engine, p0, quiron_sentinel());
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the Forests are tapped and the spell is paid"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseColor { .. })
    });
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        unreachable!("die Bedingung hat gerade gematcht")
    };
    assert_eq!(
        player, p0,
        "the controller of the Sentinel chooses the color"
    );
    for color in [
        ManaColor::White,
        ManaColor::Blue,
        ManaColor::Black,
        ManaColor::Red,
        ManaColor::Green,
    ] {
        assert!(
            options.contains(&color),
            "\"any color\" schließt {color:?} ein: {options:?}"
        );
    }
    assert_eq!(
        options.len(),
        5,
        "the five colors of the game, and colorless is not a color (CR 105.4): {options:?}"
    );

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Black))
        .expect("black was one of the offered colors");
    pass_until(&mut engine, |e| at_rest(e, p0));

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        1,
        "one mana of the chosen color, from the trigger and not from a land"
    );
    assert_eq!(
        pool.total(),
        1,
        "exactly one: the board has no other mana that could float next to it"
    );

    let sentinel =
        on_battlefield(&engine, p0, quiron_sentinel()).expect("der Sentinel ist angekommen");
    assert_eq!(
        pt(&engine, sentinel),
        (2, 1),
        "und was angekommen ist, ist der gedruckte 2/1-Körper"
    );
}

fn rats_of_rath() -> CardIndex {
    card_index("75458175-eeb1-4a6b-93d9-c744c93b3759")
}

/// Rats of Rath prints one line — "{B}: Destroy target artifact, creature, or
/// land you control" — and the two things worth playing are the three-type
/// `Or` and the "you control" that closes it. The menu is read *before* it is
/// answered, because CR 601.2c names the target while the {B} is still
/// floating and the Sol Ring is still standing, so a board holding all three
/// types under this seat and both of them across the table says the filter is
/// read rather than assumed. The offer is read twice — absent on an empty pool
/// and present once the mana is floating — because `legal.abilities` is
/// filtered through `can_afford`, which reads the pool and not the untapped
/// lands.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn rats_of_rath_destroys_a_permanent_you_control_and_no_other() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                swamp(),
                forest(),
                quiet_artifact(),
                llanowar_elves(),
                rats_of_rath(),
            ],
        )
        .battlefield(1, &[forest(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let rats = on_battlefield(&engine, p0, rats_of_rath()).expect("the Rats are on the table");
    let rock = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring is out");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let my_land = on_battlefield(&engine, p0, forest()).expect("my Forest is out");
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    let their_land = on_battlefield(&engine, p1, forest()).expect("their Forest is out");
    assert_eq!(pt(&engine, rats), (2, 1), "and it is the body it prints");

    // An empty pool pays no {B}, so the line is absent rather than refused.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        !legal.abilities.contains(&(rats, 0)),
        "nothing floats, so the {{B}} is unpayable and nothing is offered: {:?}",
        legal.abilities
    );

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        1,
        "the Swamp's {{B}}; the Forest, the Elves and the Sol Ring paid in \
         beside it, which is why only the colour is asserted"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(rats, 0)),
        "with {{B}} in the pool the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, rats_of_rath(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target artifact, creature, or land\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert_eq!((min, max), (1, 1), "exactly one permanent");
    assert!(
        options.contains(&rock) && options.contains(&mine) && options.contains(&my_land),
        "all three printed types are on the menu — the artifact, the creature \
         and the land: {options:?}"
    );
    assert!(
        !options.contains(&their_elf) && !options.contains(&their_land),
        "\"you control\" is not \"a permanent\": neither of the opponent's is \
         a legal target: {options:?}"
    );
    assert_eq!(
        options.len(),
        5,
        "every permanent this seat has — Swamp and Forest as lands, Elves and \
         Rats as creatures, Sol Ring as an artifact — and nothing across the \
         table: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_some(),
        "CR 601.2c names the target and CR 601.2h pays afterwards, so nothing \
         has died while the question still stands"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![rock],
            },
        )
        .expect("the Sol Ring was one of the options it enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "the artifact the ability named is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_none(),
        "and it left the battlefield to get there"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some()
            && on_battlefield(&engine, p0, rats_of_rath()).is_some(),
        "one target, one permanent: the creature and the Rats beside it were \
         not named and never moved"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some()
            && on_battlefield(&engine, p1, forest()).is_some(),
        "and the opponent's board is exactly where it was"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        0,
        "the {{B}} is the price and it came out of the pool"
    );
}

fn razorfin_hunter() -> CardIndex {
    card_index("45baa5d1-79aa-4583-b938-0d5feaa5aa0c")
}

/// Razorfin Hunter — {U}{R}, 1/1 Merfolk Goblin: "{T}: This creature deals 1
/// damage to any target."
///
/// Cast for exactly the {U}{R} an Island and a Mountain make, then played on
/// the turn after: a creature that entered this turn has not been under its
/// controller's control since the beginning of one and could not pay its own
/// {T} (CR 302.6). The whole price of the ability is that tap and no mana, so
/// the empty pool leaves the life total as the only thing that can move —
/// aimed at the player across the table it is one damage and one damage only,
/// while the 1/1 Elf sitting on the same menu as an object option never moves.
#[test]
fn razorfin_hunter_taps_for_one_damage_to_the_target_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[island(), mountain()])
        .hand(0, &[razorfin_hunter()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, razorfin_hunter());
    pass_until(&mut engine, |e| {
        stack_is_empty(e) && on_battlefield(e, p0, razorfin_hunter()).is_some()
    });
    let hunter = on_battlefield(&engine, p0, razorfin_hunter()).expect("the Hunter resolved");
    assert_eq!(pt(&engine, hunter), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "an Island and a Mountain pay {{U}}{{R}} exactly"
    );

    // A turn cycle, so the Hunter is no longer summoning sick and its {T} may
    // be paid at all. The opponent's Elf untaps and does nothing.
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    assert!(
        !is_tapped(&engine, hunter),
        "the untap step stood it back up"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing is floating: the whole price of the ability is its own {{T}}"
    );
    let (mine_before, theirs_before) = (
        engine.state().players[0].life,
        engine.state().players[1].life,
    );

    activate(&mut engine, p0, razorfin_hunter(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that activated aims it");
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "CR 115.4: \"any target\" counts players in the same choice: {player_options:?}"
    );
    assert!(
        options.contains(&theirs),
        "and the creature across the table is one of the object options: {options:?}"
    );
    assert!(
        !is_tapped(&engine, hunter),
        "CR 601.2c comes before CR 601.2h: the tap is the last step, so the \
         Hunter is still standing while the question is open"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![],
                players: vec![p1],
            },
        )
        .expect("a player is a legal target for `any target`");
    assert!(
        is_tapped(&engine, hunter),
        "answering the target finished the activation, and the price was {{T}}"
    );
    assert!(
        !stack_is_empty(&engine),
        "dealing damage is no mana ability"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        engine.state().players[1].life,
        theirs_before - 1,
        "\"deals 1 damage\" — one, on a board where a two would have read as two"
    );
    assert_eq!(
        engine.state().players[0].life,
        mine_before,
        "the damage belongs to the target that was named and not to both seats"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the object the ability did not name never moved"
    );
}

fn rofellos_llanowar_emissary() -> CardIndex {
    card_index("3015882b-4897-4d2c-8e33-6731c85a0d03")
}

/// Rofellos, Llanowar Emissary is a `{G}{G}` legend whose entire text
/// is `{T}: Add {G} for each Forest you control`. On the battlefield stand
/// three Forests under his control and one across the table, so exactly
/// three green is the only answer that reads both: two would mean the
/// opponent's Forest was counted, four that `ControlledByYou` has fallen,
/// and a single green that the amount was read as a fixed one. Before that,
/// **nothing** is tapped, so that “three and nothing else” is an exact
/// statement about Rofellos and not about three floating Forest mana.
#[test]
fn rofellos_adds_one_green_for_each_forest_you_control_and_no_other() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(31, forest())
        .battlefield(
            0,
            &[rofellos_llanowar_emissary(), forest(), forest(), forest()],
        )
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let rofellos = on_battlefield(&engine, p0, rofellos_llanowar_emissary())
        .expect("Rofellos is on the battlefield");
    let mine = all_on_battlefield(&engine, p0, forest());
    assert_eq!(mine.len(), 3, "three Forests on this side of the table");
    assert!(
        on_battlefield(&engine, p1, forest()).is_some(),
        "and one across it, which is nobody's Forest here"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats and nothing is tapped, so every drop below is his"
    );

    // A printed mana ability has an index to name it, so it stands as an
    // ordinary entry in `legal.abilities` — offered at an empty pool, because
    // its entire cost is its own {T} (CR 605.1).
    activate(&mut engine, p0, rofellos_llanowar_emissary(), 0);

    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "`Add {{G}}` names its color, so nothing is asked (CR 605.1): {:?}",
        engine.pending()
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        3,
        "{{G}} for each of the three Forests that *you* control"
    );
    assert_eq!(pool.total(), 3, "drei, und kein anderes Mana daneben");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability doesn't use the stack"
    );
    assert!(is_tapped(&engine, rofellos), "the {{T}} was the price");
    assert!(
        mine.iter().all(|id| !is_tapped(&engine, *id)),
        "and no Forest has moved, so the green mana came from Rofellos"
    );
}

fn royal_falcon() -> CardIndex {
    card_index("a247a7e7-83bb-46f8-9a31-85b0d8ede919")
}

/// Royal Falcon is `{1}{W}` for a 1/1 Bird whose whole printed text is
/// "Flying". A keyword on a vanilla body can only be read off the board it
/// stands on, so the card is cast for real and then sent into combat: a
/// grounded Elf beside it is offered as a blocker of the ground attacker in
/// the very same declaration and refused as a blocker of the Bird. `(1, 1)`
/// plus flying, and the {1}{W} actually paid out of the pool, is the entire
/// card — both halves are asserted rather than one.
#[test]
fn royal_falcon_lands_as_a_one_one_flier_a_grounded_elf_cannot_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .hand(0, &[royal_falcon()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The Elf beside the Bird is kept untapped: it is this test's *ground*
    // attacker, and a creature tapped for its own mana is no longer one. The
    // two Plains are exactly the printed `{1}{W}` and nothing else.
    let my_elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Plains, and not the Elf beside them"
    );
    cast_with_floating(&mut engine, p0, royal_falcon());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let falcon = on_battlefield(&engine, p0, royal_falcon()).expect("the Falcon resolved");
    assert_eq!(pt(&engine, falcon), (1, 1), "a printed 1/1 Bird");
    assert!(
        types(&engine, falcon).contains(TypeSet::CREATURE),
        "and a creature"
    );
    assert!(
        keywords(&engine, falcon).contains(KeywordSet::FLYING),
        "the one word the card prints reaches the permanent"
    );
    assert!(
        !keywords(&engine, my_elf).contains(KeywordSet::FLYING),
        "the Elf beside it is grounded, which is the other half of that reading"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{W}} came out of the pool"
    );

    // A turn cycle: the Bird was cast this turn and has summoning sickness
    // (CR 302.6), so the combat its keyword is read in is the next one.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&falcon) && attackers.contains(&my_elf),
        "both untapped creatures under p0 may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (falcon, Defender::Player(p1)),
                    (my_elf, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    // The blocking question is read and not merely tolerated: the ground
    // Elf is the control that keeps the second assertion from being an empty
    // board's.
    // CR 508.2 hands priority round once the attack is declared, so the
    // blocker menu is not the next thing the engine says.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        panic!(
            "a legal block exists, so the defending seat is asked: {:?}",
            engine.pending()
        )
    };
    let paired = |blocker: ObjectId, attacker: ObjectId| {
        blockers
            .iter()
            .any(|o| o.blocker == blocker && o.attackers.contains(&attacker))
    };
    assert!(
        paired(their_elf, my_elf),
        "two grounded 1/1s: the Elf across the table may block the one I \
         attacked with: {blockers:?}"
    );
    assert!(
        !paired(their_elf, falcon),
        "\"Flying\" — a creature with no flying may not block it: {blockers:?}"
    );
    engine
        .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();

    // Nothing blocked, so the flier's point of damage lands on the same board
    // as the Elf's: one combat step, two life.
    pass_until(&mut engine, |e| e.state().players[1].life < 20);
    assert_eq!(
        engine.state().players[1].life,
        18,
        "the Bird connected for 1 and the ground attacker for 1"
    );
}

fn sage_of_lat_nam() -> CardIndex {
    card_index("f34be3cc-ff47-4415-a6a8-ed142891dc0c")
}

/// Sage of Lat-Nam — {1}{U}, a 1/2 Human Artificer printing exactly one line:
/// "{T}, Sacrifice an artifact: Draw a card."
///
/// The sacrifice names no artifact of its own, so the engine has to ask which
/// one, and the menu is half the card: the Sol Ring beside it is on it, the two
/// creatures are not (the Sage is no artifact either, so the missing "another"
/// costs it nothing) and neither is the Sol Ring across the table, which
/// CR 701.21a keeps off it. The price is a tap symbol and a permanent, so no
/// mana is floating anywhere — the offer turns on nothing the pool could have
/// supplied, which is what makes the missing entry a statement about the filter.
/// The draw is read as a *move*, and only after the ability resolves: a library
/// one shorter *and* a hand one longer, because a card that merely left the top
/// of the library would satisfy the first count on its own.
#[allow(clippy::too_many_lines)] // one activation, every gate it passes asserted
#[test]
fn sage_of_lat_nam_eats_an_artifact_of_yours_to_draw_a_card() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, forest())
        .battlefield(0, &[sage_of_lat_nam(), quiet_artifact(), llanowar_elves()])
        .battlefield(1, &[quiet_artifact()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let sage = on_battlefield(&engine, p0, sage_of_lat_nam()).expect("the Sage is on the table");
    let ring = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring is beside it");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("and an Elf is too");
    let theirs = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");

    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the whole price is the tap symbol and an artifact, so nothing is \
         floating to pay with"
    );
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Sage holds it");
    assert!(
        legal.abilities.contains(&(sage, 0)),
        "an artifact to eat is on the board, so the one line the Sage prints is \
         offered: {:?}",
        legal.abilities
    );

    let library_before = library_size(&engine, p0);
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    activate(&mut engine, p0, sage_of_lat_nam(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which artifact, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
    assert_eq!(
        options,
        vec![ring],
        "the Sol Ring is the only artifact this seat controls, and nothing else \
         on the table belongs on the menu"
    );
    assert!(
        !options.contains(&sage),
        "the Sage is a creature: it cannot eat itself"
    );
    assert!(
        !options.contains(&elves),
        "and neither is an Elf an artifact"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: an opponent's artifact is not yours to sacrifice"
    );
    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![ring],
            },
        )
        .expect("the artifact the question offered pays the cost");

    // CR 601.2h: the price is the last step of the activation, so by the time
    // the draw is waiting the Sol Ring is already buried and the Sage already
    // tapped — and the card is still on the library, because drawing is the
    // *effect* and it has not resolved.
    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "a sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        is_tapped(&engine, sage),
        "{{T}} is the other half of the price"
    );
    assert!(
        !stack_is_empty(&engine),
        "drawing a card is no mana ability, so the Sage's ability is waiting"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before,
        "and nothing has been drawn yet"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"Draw a card\": one card left the top of the library"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before + 1,
        "and it reached the hand — a library that emptied would satisfy the \
         count above without drawing anything"
    );
    assert!(
        on_battlefield(&engine, p0, sage_of_lat_nam()).is_some(),
        "the Sage ate the Sol Ring and not itself"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the artifact the ability did not name never moved"
    );
}

fn sakura_tribe_elder() -> CardIndex {
    card_index("e3afc704-220f-498f-9eaa-0821b17dc24c")
}

/// Sakura-Tribe Elder — `{1}{G}` Snake Shaman 1/1: "Sacrifice this creature:
/// Search your library for a basic land card, put that card onto the
/// battlefield tapped, then shuffle."
///
/// Both halves of the price are the engine's answer, so both are read on the
/// state: the creature has to be in its owner's graveyard the moment the
/// ability is announced (CR 601.2h — the whole cost is the sacrifice and no
/// mana at all, which the empty pool beside it says out loud), and the card
/// the search offers has to *arrive* — on the battlefield, tapped, and one
/// shorter a library for it. Asserting the land merely exists would pass for
/// a tutor that never moved anything; the battlefield Forest count is what
/// tells one fetched land from two.
#[test]
fn sakura_tribe_elder_sacrifices_itself_for_a_basic_land_that_arrives_tapped() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(4197, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[sakura_tribe_elder()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} off the two Forests, and nothing is left floating afterwards:
    // the ability about to be pressed costs no mana, so the empty pool is
    // what makes the graveyard below the only thing the price produced.
    cast_from_hand(&mut engine, p0, sakura_tribe_elder());
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the two Forests paid for the creature and nothing is left over"
    );
    let elder = on_battlefield(&engine, p0, sakura_tribe_elder()).expect("the Elder resolved");
    assert_eq!(pt(&engine, elder), (1, 1), "a printed 1/1");
    assert_eq!(
        all_on_battlefield(&engine, p0, forest()).len(),
        2,
        "two Forests on the board before anything is fetched"
    );

    let library_before = library_size(&engine, p0);

    // Ability 0 is the only line the card prints, and its price is the
    // permanent itself.
    activate(&mut engine, p0, sakura_tribe_elder(), 0);
    assert!(
        in_graveyard(&engine, p0, sakura_tribe_elder()).is_some(),
        "`Sacrifice this creature:` is paid as the ability is announced \
         (CR 601.2h), so the Elder is in its owner's graveyard already"
    );
    assert!(
        on_battlefield(&engine, p0, sakura_tribe_elder()).is_none(),
        "and it is no longer on the battlefield"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseCards { .. })
    });
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the seat that sacrificed the Elder searches");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::SearchLibrary,
        "a tutor and not a scry or a discard"
    );
    assert_eq!((min, max), (1, 1), "the search is not optional");
    assert!(!options.is_empty(), "the library holds basic lands to find");
    let in_library = engine.state().zones.list(ZoneLocation::Library(p0)).clone();
    for id in &options {
        assert!(
            in_library.contains(id),
            "\"search your library\": {id:?} is no card in it"
        );
    }
    let chosen = options[0];
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![chosen],
            },
        )
        .expect("a card the search offered is a legal answer");

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine
            .state()
            .object(chosen)
            .expect("the found land is an object")
            .zone,
        Zone::Battlefield,
        "\"put that card onto the battlefield\""
    );
    assert!(
        is_tapped(&engine, chosen),
        "\"…onto the battlefield tapped\" — the land arrives turned over"
    );
    assert_eq!(
        all_on_battlefield(&engine, p0, forest()).len(),
        3,
        "exactly one land was fetched: the two Forests that paid for the Elder \
         plus the one the search put down"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"then shuffle\" — the found card left the library, and shuffling \
         reorders what is left without changing how much of it there is"
    );
}

fn sea_eagle() -> CardIndex {
    card_index("acb57162-7093-4a3c-9818-d3b61ce757c6")
}

/// Sea Eagle is a {1}{U} 1/1 Bird whose whole printed text is flying, so the
/// test has to play it twice: once as a spell, where the cost, the body and
/// the keyword can be read off the permanent it becomes, and once in combat,
/// because flying is an evasion rule and a keyword assertion on its own would
/// pass on a board where nothing ever tried to block. The two Islands pay
/// {1}{U} while the Llanowar Elves beside them is kept back, so the Elf can
/// attack a turn later and the defending Elf's block menu carries the ground
/// attacker and not the Bird — which is the difference between a projected
/// keyword and a keyword the game was asked to use.
#[test]
fn sea_eagle_arrives_as_a_one_one_flier_a_ground_elf_cannot_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), llanowar_elves()])
        .hand(0, &[sea_eagle()])
        .battlefield(1, &[forest(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The Elf beside the Bird is not mana for it: it is the ground attacker
    // whose block menu makes the flying mean something below, so it is the one
    // source kept standing while the two Islands fill the pool.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands, and the {{1}}{{U}} the Bird prints is payable"
    );
    cast_with_floating(&mut engine, p0, sea_eagle());
    pass_until(&mut engine, stack_is_empty);

    let eagle = on_battlefield(&engine, p0, sea_eagle()).expect("the Eagle resolved");
    assert_eq!(pt(&engine, eagle), (1, 1), "the body the card prints");
    assert!(
        types(&engine, eagle).contains(TypeSet::CREATURE),
        "it is the creature it prints: {:?}",
        types(&engine, eagle)
    );
    assert!(
        keywords(&engine, eagle).contains(KeywordSet::FLYING),
        "the one line of text the card has"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{1}}{{U}} came out of the pool the Islands filled"
    );

    // A turn each way: a creature cast on a turn may not attack until its
    // controller's next one (CR 302.6), and the block question below belongs
    // to the turn after that.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let blocker = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(eagle, Defender::Player(p1)), (elf, Defender::Player(p1))],
            },
        )
        .expect("an untapped flier and an untapped Elf may both attack");

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p1, "the defending seat declares blockers");
    let may_block = |attacker: ObjectId| {
        blockers
            .iter()
            .filter(|option| option.blocker == blocker)
            .any(|option| option.attackers.contains(&attacker))
    };
    assert!(
        may_block(elf),
        "the ground Elf is offered against the ground attacker, so the empty \
         half below is flying and not a blocker that never had a chance: {blockers:?}"
    );
    assert!(
        !may_block(eagle),
        "and it is never offered against the Bird, which is `CR 702.9b` and \
         the whole of what the card prints: {blockers:?}"
    );

    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();
    pass_until(&mut engine, |e| e.state().players[1].life < 20);
    assert_eq!(
        engine.state().players[1].life,
        18,
        "an unblocked 1/1 flier and an unblocked 1/1 Elf: two damage"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing came back, so the damage read above belongs to the \
         attackers this turn and not to an earlier one"
    );
}

fn sea_scryer() -> CardIndex {
    card_index("f17954dd-c8e0-4983-b81e-5440cca41afc")
}

/// Sea Scryer prints two mana abilities: "{T}: Add {C}" and "{1}, {T}:
/// Add {U}". The first has its own tap symbol as its entire cost, the second
/// additionally demands a mana — and because `can_afford` reads the *pool*,
/// the second is not even offered at an empty pool. Precisely for that reason
/// the test goes through a full turn cycle: the Scryer taps for {C}, untaps,
/// and a single Forest pays the {1}, whereupon green disappears from the pool
/// and the printed blue comes back.
#[test]
fn sea_scryer_taps_for_colorless_then_pays_a_mana_for_blue() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), forest()])
        .hand(0, &[sea_scryer()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 erreicht seine eigene Hauptphase"
    );

    // The two Islands pay {1}{U} and nothing else: the Forest stays untapped,
    // so that “empty pool” is an exact statement after the spell.
    tap_all_mana_but(&mut engine, p0, Some(forest()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands, two blue"
    );
    cast_with_floating(&mut engine, p0, sea_scryer());
    pass_until(&mut engine, stack_is_empty);
    let scryer = on_battlefield(&engine, p0, sea_scryer()).expect("der Scryer ist gelandet");
    assert_eq!(pt(&engine, scryer), (1, 1), "ein gedruckter 1/1");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{1}}{{U}} came from the pool and nothing remained"
    );

    // Its own next turn: `{T}` in a cost is not payable for a creature
    // that arrived this turn (CR 302.6). To expect the line during the
    // turn of casting would mean explaining away the summoning sickness.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got: {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(scryer, 0)),
        "{{T}}: Add {{C}} charges its own tap symbol and nothing else: {:?}",
        legal.abilities
    );
    assert!(
        !legal.abilities.contains(&(scryer, 1)),
        "{{1}}, {{T}} is not payable from an empty pool and therefore \
         not even in the offer: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, sea_scryer(), 0);
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Colorless),
        1,
        "ein farbloses Mana"
    );
    assert_eq!(pool.total(), 1, "und sonst nichts");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability does not use the stack"
    );
    assert!(is_tapped(&engine, scryer), "the Scryer paid its {{T}}");

    // A turn cycle so that the creature really untaps: tapped, it offers
    // neither the one nor the other line.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, scryer),
        "der Enttappschritt hat den Scryer wieder aufgestellt"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the pool empties at the end of a step (CR 500.5)"
    );

    // Only the Forest is tapped: one green mana, which pays exactly the {1}
    // of the second line, while the Scryer stays untapped for its {T}.
    let grove = on_battlefield(&engine, p0, forest()).expect("the Forest is still there");
    tap_mana_where(&mut engine, p0, |id| id == grove);
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got: {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(scryer, 1)),
        "mit einem schwebenden Mana ist {{1}}, {{T}}: Add {{U}} bezahlbar: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, sea_scryer(), 1);
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "das grüne Mana war das {{1}} der Kosten"
    );
    assert_eq!(
        pool.available(ManaColor::Blue),
        1,
        "and the ability gives back exactly the blue that it prints"
    );
    assert_eq!(pool.total(), 1, "ein Mana hinein, ein Mana hinaus");
    assert!(
        stack_is_empty(&engine),
        "this mana ability doesn't use the stack either"
    );
    assert!(is_tapped(&engine, scryer), "paid with its own {{T}}");
}

fn seeker_of_skybreak() -> CardIndex {
    card_index("704723f3-0490-4d96-930a-aacc6d19ba8d")
}

/// Seeker of Skybreak is a {1}{G} 2/1 Elf printing "{T}: Untap target
/// creature." — the whole price is the tap symbol, so the ability is read off
/// a *tapped* creature: the Llanowar Elves paid for the Seeker's own `{1}{G}`
/// through `tap_all_mana` (#159), which leaves it face down and makes the
/// untap a change of state rather than a no-op. The Elf across the table is
/// the control for the target line — the card says "target creature" and not
/// "you control" — so it has to be offered and has to be the one that does
/// not move, which is what says the ability hit the creature that was named.
#[test]
fn seeker_of_skybreak_taps_to_untap_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, forest())
        // Seated and not cast: the printed cost is `{T}`, which a creature
        // that arrived this turn cannot pay (CR 302.6), and what this test is
        // about is the untap rather than the casting.
        .battlefield(
            0,
            &[forest(), forest(), llanowar_elves(), seeker_of_skybreak()],
        )
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");

    // The Elf and nothing else: it is a mana route, so tapping it for its own
    // green makes it exactly the tapped permanent the printed ability is
    // about, while the two Forests stay standing and out of the way.
    let seeker = on_battlefield(&engine, p0, seeker_of_skybreak()).expect("the Seeker is seated");
    assert_eq!(pt(&engine, seeker), (2, 1), "the body the card prints");
    tap_mana_where(&mut engine, p0, |id| id == elves);
    assert!(
        is_tapped(&engine, elves),
        "the Elf made its green and is lying down"
    );
    assert!(
        !is_tapped(&engine, seeker),
        "and the Seeker stands up for it, so its {{T}} is still there"
    );

    // A printed `{T}` and nothing else: the ability is offered with an empty
    // pool and presses by index, which is the only index the card has.
    activate(&mut engine, p0, seeker_of_skybreak(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that chooses");
    assert!(
        options.contains(&elves),
        "the tapped creature is a legal target: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"target creature\" is not \"creature you control\", so the Elf \
         across the table is on the same menu: {options:?}"
    );
    // CR 601.2c names the target and CR 601.2h pays afterwards, so the Seeker
    // is still upright while the question stands.
    assert!(
        !is_tapped(&engine, seeker),
        "the cost is the last step of the activation, not the first"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .expect("the creature the question offered was chosen");
    assert!(is_tapped(&engine, seeker), "{{T}} was the whole price");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        !is_tapped(&engine, elves),
        "\"Untap target creature\": the creature that was down is standing again"
    );
    assert!(
        !is_tapped(&engine, theirs),
        "and the creature the ability did not name never moved"
    );
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "untapping is all it does: no counter, no pump, the printed 1/1"
    );
    assert!(
        on_battlefield(&engine, p0, seeker_of_skybreak()).is_some(),
        "an activated ability costs the Seeker nothing but its tap"
    );
}

fn selesnya_evangel() -> CardIndex {
    card_index("4a2fea39-99d6-4766-9f2c-0a63925349cb")
}

/// Selesnya Evangel prints “`{1}`, `{T}`, Tap an untapped creature you
/// control: Create a 1/1 green Saproling creature token.” The cost has
/// three parts and each is visible in a different place: the `{1}` in the
/// pool (`can_afford` reads the pool, so the line is missing entirely
/// without floating mana instead of being rejected), its own tap symbol on
/// the Evangel, and the second tap on an *other* creature that must belong
/// to you — the Elf across the table is the control that “you control” is
/// read and not just “a creature”. Only the one Forest is tapped for mana:
/// its own Elf stays untapped, because it is about to be the second tap,
/// and an Elf tapped for mana would no longer be an untapped creature.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn selesnya_evangel_taps_two_creatures_for_one_green_saproling() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), selesnya_evangel(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let evangel = on_battlefield(&engine, p0, selesnya_evangel()).expect("the Evangel is out");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    let land = on_battlefield(&engine, p0, forest()).expect("the Forest is out");

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(evangel, 0)),
        "without {{1}} in the pool the price is unpayable and the line is \
         missing from the offer: {:?}",
        legal.abilities
    );

    // Only the Forest: the Elf is the creature that should tap the second
    // part of the price in a moment.
    let taken = tap_mana_where(&mut engine, p0, |id| id == land);
    assert_eq!(taken, 1, "a Forest and nothing else");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "ein grüner, und grün zahlt die {{1}}"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(evangel, 0)),
        "with {{1}} in the pool the whole price is payable: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, selesnya_evangel(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the price asks for the second creature, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(
        player, p0,
        "der aktivierende Sitz antwortet seine eigene Kostenfrage"
    );
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostTap,
        "a cost and not a search: a tapped permanent is not destroyed"
    );
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        options.contains(&elves),
        "my own Elf is untapped and may pay too: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "\"a creature *you* control\": the Elf across the table is not mine: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .expect("the creature that offered the question pays the price");

    assert!(
        is_tapped(&engine, evangel),
        "{{T}} ist der eigene Teil des Preises"
    );
    assert!(is_tapped(&engine, elves), "and the second tip hits the Elf");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}} came from the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "creating a creature is not a mana ability, so it is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    let tokens = tokens_of(&engine, p0);
    assert_eq!(tokens.len(), 1, "eine Aktivierung, ein Saproling");
    let saproling = tokens[0];
    let kinds = types(&engine, saproling);
    assert!(
        kinds.contains(TypeSet::CREATURE),
        "a Saproling is a creature: {kinds:?}"
    );
    let printed = engine
        .state()
        .object(saproling)
        .expect("the Saproling is on the battlefield")
        .token
        .expect("es weiß, welches Token es ist");
    assert_eq!(printed.name, "Saproling");
    assert_eq!(
        (printed.power, printed.toughness),
        (Some(1), Some(1)),
        "ein 1/1, wie gedruckt"
    );
    assert!(
        printed.colors.contains(baylee_core::color::Color::Green),
        "und ein *grünes* Saproling"
    );
    assert!(
        on_battlefield(&engine, p0, selesnya_evangel()).is_some(),
        "the Evangel remains on the battlefield — the ability sacrifices nothing"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the Elf on the table has never done anything"
    );
}

fn shimmering_barrier() -> CardIndex {
    card_index("94674840-c73c-4659-80b9-11140d1deaa3")
}

/// Shimmering Barrier is a {1}{W} 1/3 Wall printing three lines: Defender,
/// first strike, and cycling {2}. This scenario plays all three in one main
/// phase — the first copy is cast onto the table, where its body and both
/// keywords are read off the projected characteristics and Defender is
/// checked where it actually bites, in the attack declaration against an
/// untapped Elf that the same offer does name; the second copy is cycled
/// *out of the hand*, which is the zone the ability lives in, for {2} out of
/// a pool the four Plains actually filled. The Elf is kept back from the
/// mana so that "may not attack" is a claim about Defender and not about a
/// creature that tapped for its own cast.
#[test]
fn shimmering_barrier_stands_with_defender_and_cycles_itself_away_for_a_card() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[plains(), plains(), plains(), plains(), quiet_creature()],
        )
        .hand(0, &[shimmering_barrier(), shimmering_barrier()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Four Plains and the Elf left standing: it is the control in the attack
    // declaration below, and a creature tapped for mana may not attack.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Plains, and the Elf contributed nothing"
    );

    // {1}{W} for the first copy.
    cast_with_floating(&mut engine, p0, shimmering_barrier());
    pass_until(&mut engine, stack_is_empty);
    let wall = on_battlefield(&engine, p0, shimmering_barrier()).expect("the Wall resolved");
    assert_eq!(pt(&engine, wall), (1, 3), "the body the card prints");
    let projected = keywords(&engine, wall);
    assert!(
        projected.contains(KeywordSet::DEFENDER),
        "Defender reaches the permanent"
    );
    assert!(
        projected.contains(KeywordSet::FIRST_STRIKE),
        "and so does first strike"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the {{1}}{{W}} came out of the pool and the {{2}} for the cycling is left"
    );

    // Cycling {2}: the ability lives in the hand, so it is the *other* copy
    // that is activated, and its price is the mana plus the card itself.
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();
    let library_before = library_size(&engine, p0);
    activate(&mut engine, p0, shimmering_barrier(), 0);
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, shimmering_barrier()).is_some(),
        "\"Discard this card\" is part of the cost, so the card is in its owner's graveyard"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"Draw a card\" — one card off the top of the library"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before,
        "one card discarded and one drawn: a cycled card is replaced, not lost"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{2}} came out of the pool"
    );

    // Defender where it bites, against the Elf that the same offer names.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    let elves = on_battlefield(&engine, p0, quiet_creature()).expect("the Elf is out");
    assert!(
        attackers.contains(&elves),
        "an untapped 1/1 with no text of its own may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&wall),
        "\"This creature can't attack\" — the Wall is on the table with a \
         body and no summoning sickness and is still not offered: {attackers:?}"
    );
}

fn silverglade_pathfinder() -> CardIndex {
    card_index("ac00d3db-d9e4-4fc3-a4ea-dd1187f406bb")
}

/// Silverglade Pathfinder prints one line — "{1}{G}, {T}, Discard a card:
/// Search your library for a basic land card, put that card onto the
/// battlefield tapped, then shuffle." — and each part of that price is read
/// off a different place in one activation: the mana leaves the pool, the
/// Pathfinder taps, and the discarded card lies in its owner's graveyard. The
/// discard is a *cost*, so the engine asks which card over the hand before
/// anything reaches the stack (CR 601.2h), while the search is the effect and
/// can only ask behind that answer. The found land is read as a move and not
/// as a question: it is on the battlefield, it is **tapped** there, and the
/// library is one shorter for it.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn silverglade_pathfinder_discards_for_a_basic_land_that_arrives_tapped() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[silverglade_pathfinder(), forest(), forest()])
        .hand(0, &[dark_ritual()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches a main phase of its own"
    );

    let pathfinder =
        on_battlefield(&engine, p0, silverglade_pathfinder()).expect("the Pathfinder is out");
    let fodder = in_hand(&engine, p0, dark_ritual()).expect("a card to discard is in hand");

    // `legal.abilities` is filtered through the pool, so the {1}{G} is tapped
    // first — two Forests, and nothing else on this board makes mana.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Forests, two green for {{1}}{{G}}"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(pathfinder, 0)),
        "the one line the card prints is offered: {:?}",
        legal.abilities
    );

    let library_before = library_size(&engine, p0);
    activate(&mut engine, p0, silverglade_pathfinder(), 0);

    // "Discard a card" is part of the cost and is asked before the ability is
    // on the stack — over the hand, which is the only place a discard can
    // come from (CR 701.9a).
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the discard is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostDiscard,
        "a cost and not a search, which is all a client has to tell them apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert!(
        options.contains(&fodder),
        "the card named in hand is the whole of the answer: {options:?}"
    );
    assert!(
        !options.contains(&pathfinder),
        "the Pathfinder is a permanent on the battlefield and no card in hand: {options:?}"
    );
    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![pathfinder],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the card the question offered pays the cost");

    // Now the effect, which is the card's other question and a different one:
    // the search's own prompt, asked once the ability has resolved.
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::ChooseCards {
                prompt: ChoicePrompt::SearchLibrary,
                ..
            }
        )
    });
    let Pending::ChooseCards {
        player,
        options,
        prompt,
        ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the seat that activated does the searching");
    assert_eq!(
        prompt,
        ChoicePrompt::SearchLibrary,
        "the tutor's own question, and not the discard's"
    );
    assert!(!options.is_empty(), "the library holds basic lands to find");
    let in_library = engine.state().zones.list(ZoneLocation::Library(p0)).clone();
    for id in &options {
        assert!(
            in_library.contains(id),
            "\"search your library\": {id:?} is no card in it"
        );
    }
    let chosen = options[0];
    let kinds = engine
        .state()
        .object(chosen)
        .expect("the offered card is an object")
        .characteristics()
        .types;
    assert!(
        kinds.contains(TypeSet::LAND),
        "\"a basic land card\" — the filter names a land, and this is one: {kinds:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![chosen],
            },
        )
        .expect("a card the search offered is a legal answer");

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine
            .state()
            .object(chosen)
            .expect("the found land is still an object")
            .zone,
        Zone::Battlefield,
        "\"put that card onto the battlefield\""
    );
    assert!(
        is_tapped(&engine, chosen),
        "\"…onto the battlefield **tapped**\" — and not merely onto the table"
    );
    assert_eq!(
        lands_of(&engine, p0).len(),
        3,
        "the two Forests that were dealt and the one the search found"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"then shuffle\": the found card left the library, and shuffling \
         reorders what is left without changing how much of it there is"
    );
    assert!(
        is_tapped(&engine, pathfinder),
        "{{T}} was half the price the card prints"
    );
    assert!(
        in_graveyard(&engine, p0, dark_ritual()).is_some(),
        "and the discarded card is in its owner's graveyard, not merely gone"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{G}} came out of the pool"
    );
}

fn skittering_skirge() -> CardIndex {
    card_index("fae1d5d9-a50e-423e-8692-3e41f39df081")
}

/// Skittering Skirge is a `{B}{B}` 3/2 Phyrexian Imp with flying and exactly
/// one additional line: "When you cast a creature spell, sacrifice this
/// creature." Three spells read the sentence from both sides. A Dark Ritual
/// is a spell and not a creature, and the Skirge stays — so it is about
/// creature spells and not about spells. An opponent's Festering Goblin is
/// a creature spell and still not one that **you** cast, and the Skirge
/// stays again. Only the creature spell of its own controller puts the
/// ability on the stack above this spell, and the Skirge is then in the
/// graveyard, while the spell underneath is still being resolved.
#[test]
fn skittering_skirge_sacrifices_itself_only_for_its_own_controllers_creature_spell() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp(), swamp()])
        .hand(0, &[skittering_skirge(), dark_ritual(), festering_goblin()])
        .battlefield(1, &[swamp(), swamp()])
        .hand(1, &[festering_goblin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Five Swamps into the pool: {B}{B} for the Skirge and one {B} each for
    // Ritual and the Goblin all come from this one main phase
    // (CR 500.5). No creature on the board produces mana, so it's five.
    assert_eq!(
        tap_all_mana(&mut engine, p0),
        5,
        "five Swamps, and nothing else on the board makes mana"
    );

    cast_with_floating(&mut engine, p0, skittering_skirge());
    pass_until(&mut engine, stack_is_empty);
    let skirge = on_battlefield(&engine, p0, skittering_skirge()).expect("der Skirge ist gelandet");
    assert_eq!(pt(&engine, skirge), (3, 2), "the body the card prints");
    assert!(
        keywords(&engine, skirge).contains(KeywordSet::FLYING),
        "and the flying that it prints"
    );

    // A spell and not a creature: the printed line says nothing about it,
    // and otherwise the Skirge has no reason to leave.
    cast_with_floating(&mut engine, p0, dark_ritual());
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, skittering_skirge()).is_some(),
        "\"When you cast a creature spell\" — ein Dark Ritual ist keiner"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "das Ritual hat das eine {{B}} ausgegeben und drei zurückgelegt"
    );

    // The other half of "you": a creature spell on the table is a
    // creature spell and yet not one that this controller casts.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(tap_all_mana(&mut engine, p1), 2, "zwei Sümpfe des Gegners");
    cast_with_floating(&mut engine, p1, festering_goblin());
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p1, festering_goblin()).is_some(),
        "the opponent's Goblin landed"
    );
    assert!(
        on_battlefield(&engine, p0, skittering_skirge()).is_some(),
        "and the Skirge is untouched: the ability reads *your* creature spells"
    );

    // Back to your own turn. The Swamps have untapped again in the untap
    // step, which the return value records here — without it, an offer that
    // costs nothing would not be distinguishable from an empty pool.
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        tap_all_mana(&mut engine, p0),
        5,
        "fünf Sümpfe, wieder alle untapped"
    );

    cast_with_floating(&mut engine, p0, festering_goblin());
    assert!(
        on_stack(&engine, festering_goblin()).is_some(),
        "the spell is on the stack"
    );
    assert!(
        on_battlefield(&engine, p0, skittering_skirge()).is_some(),
        "and the ability it triggered has not yet resolved — \
         the Skirge still stands, because only its trigger will fetch it"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, skittering_skirge()).is_none(),
        "\"sacrifice this creature\" — die Auslösung hat den Skirgen geholt"
    );
    assert!(
        in_graveyard(&engine, p0, skittering_skirge()).is_some(),
        "and a sacrificed permanent is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, festering_goblin()).is_some(),
        "the spell it triggered on is nevertheless resolved \
         beneath it"
    );
}

fn skyshroud_elf() -> CardIndex {
    card_index("84a666a0-e453-4b34-815c-48dbfc9b4f4b")
}

/// Skyshroud Elf is `{1}{G}` for a 1/1 with **two** printed mana abilities —
/// "{T}: Add {G}" and "{1}: Add {R} or {W}" — and the whole scenario turns on
/// the difference between their costs. The second names no tap symbol, so the
/// Elf may use it the turn it lands (CR 302.6 reaches only the tap and untap
/// symbols) and does so off the mana its own cast left floating, where the
/// first has to wait for an untap step. Both halves are read against a board
/// that could not have produced either colour otherwise: three Forests make
/// nothing but green, so the colour that was named can only have come off the
/// second ability, and the single green the Elf's own tap makes a turn later
/// arrives in an empty pool with every Forest still standing.
#[test]
fn skyshroud_elf_lands_for_a_mana_and_then_taps_for_green() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(3771, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[skyshroud_elf()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} off the three Forests, which leaves one green in the pool — the
    // exact mana the second ability charges, already floating when the claim
    // below is made (`can_afford` reads the pool, not the untapped lands).
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Forests, and the Elf is still in hand"
    );
    cast_with_floating(&mut engine, p0, skyshroud_elf());
    pass_until(&mut engine, stack_is_empty);

    let elf = on_battlefield(&engine, p0, skyshroud_elf()).expect("the Elf resolved");
    assert_eq!(pt(&engine, elf), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{1}}{{G}} is spent and one green is left floating"
    );

    // Ability 1, "{1}: Add {R} or {W}". Its cost is a mana and no tap symbol,
    // so a creature that has been under its controller's control for no time
    // at all may still use it.
    activate(&mut engine, p0, skyshroud_elf(), 1);
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!(
            "\"Add {{R}} or {{W}}\" is a question, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that names it");
    assert_eq!(
        options,
        vec![ManaColor::Red, ManaColor::White],
        "the two colours the card prints, and green is not one of them"
    );
    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Red))
        .expect("red was one of the two it offered");

    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so the red is already here"
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Red),
        1,
        "the colour that was named, and not a default"
    );
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "the green the cast left was the {{1}} that paid for it"
    );
    assert_eq!(pool.total(), 1, "one mana, off one activation");
    assert!(
        !is_tapped(&engine, elf),
        "the second ability is a mana and not the tap symbol, so the Elf is \
         still standing"
    );

    // Now the printed tap, which needs an untap step first. A turn passes,
    // the pool empties at the end of the step the red was made in (CR 500.5),
    // and the reading below is about one tap of one creature and nothing left
    // over.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the red from last turn's main phase is gone"
    );
    assert!(
        !is_tapped(&engine, elf),
        "and the untap step stood the Elf back up"
    );

    // Ability 0 is "{T}: Add {G}", whose whole price is its own tap — exactly
    // the route `tap_all_mana` presses (#159). Asking for the object keeps
    // the three Forests out of the count, so "one green and nothing else" is
    // an exact claim about the Elf.
    let taken = tap_mana_where(&mut engine, p0, |id| id == elf);
    assert_eq!(taken, 1, "one route: the Elf's own {{T}}");
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Green), 1, "{{T}}: Add {{G}}");
    assert_eq!(pool.total(), 1, "one mana, and nothing else came with it");
    assert!(is_tapped(&engine, elf), "the Elf paid its own {{T}}");
    assert!(
        all_on_battlefield(&engine, p0, forest())
            .iter()
            .all(|id| !is_tapped(&engine, *id)),
        "and the three Forests are untouched, so the green came off the Elf"
    );
}

fn skyshroud_falcon() -> CardIndex {
    card_index("877ab494-da90-4c26-a184-c6ba64ec30b5")
}

/// Skyshroud Falcon is a {1}{W} 1/1 Bird whose whole printed text is two
/// keywords, and each one is only legible in a different half of one combat
/// step. The vigilance half is read off the attacker itself: the Falcon is
/// still standing untapped after it was declared, where the Llanowar Elves
/// that attacked beside it is not. The flying half is read off the *block*
/// offer, where the same untapped Elf across the table may block the ground
/// attacker and may not block the Falcon at all.
#[test]
fn skyshroud_falcon_attacks_without_tapping_and_a_ground_creature_cannot_block_it() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[skyshroud_falcon()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{W} off the two Plains, with the Elf named as the printing kept
    // back: it is the creature that attacks beside the Falcon below, and a
    // creature tapped for mana may not be declared as an attacker.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Plains tapped, and the Elf that has to attack later did not pay"
    );
    cast_with_floating(&mut engine, p0, skyshroud_falcon());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let falcon = on_battlefield(&engine, p0, skyshroud_falcon()).expect("the Falcon resolved");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    assert_eq!(pt(&engine, falcon), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the two mana are what paid for it"
    );

    // Cast this turn, so it is summoning sick (CR 302.6) and the attack
    // declaration it is read in belongs to the *next* turn of p0's.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::ChooseAttackers { player, .. } if *player == p0),
    );
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&falcon) && attackers.contains(&elf),
        "both untapped creatures may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(falcon, Defender::Player(p1)), (elf, Defender::Player(p1))],
            },
        )
        .unwrap();

    assert!(
        !is_tapped(&engine, falcon),
        "\"vigilance\": attacking does not tap the Falcon"
    );
    assert!(
        is_tapped(&engine, elf),
        "and the Elf beside it, which has no vigilance, is tapped by the same declaration"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("the predicate just matched")
    };
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let option = blockers
        .iter()
        .find(|b| b.blocker == their_elf)
        .expect("an untapped creature across the table may block");
    assert!(
        option.attackers.contains(&elf),
        "the ground attacker is reachable by the ground blocker: {:?}",
        option.attackers
    );
    assert!(
        !option.attackers.contains(&falcon),
        "\"flying\": the same untapped Elf cannot be assigned to it at all: {:?}",
        option.attackers
    );

    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();
    // Not `stack_is_empty`: the stack is already empty the moment attackers
    // are declared, so that predicate would stop the walk *before* combat
    // damage and the life total would read 20. The end step is past it
    // (CR 510.2).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert_eq!(
        engine.state().players[1].life,
        18,
        "two 1/1s went unblocked: one from the Falcon that flew over and one from the Elf"
    );
    assert!(
        !is_tapped(&engine, falcon),
        "and the Falcon is still standing after the combat it attacked through"
    );
}

/// Slobad, Goblin Tinkerer — {1}{R} legendary 1/2 Goblin Artificer:
/// "Sacrifice an artifact: Target artifact gains indestructible until end of
/// turn."
///
/// The one printed line carries two different artifact readings, and the two
/// menus the engine publishes separate them: the *target* is any artifact on
/// either side of the table, while the *sacrifice* is one this seat controls
/// (CR 701.21a). The grant is then put to work instead of read off the layers —
/// a Vindicate aimed at the artifact is a destruction effect, and indestructible
/// is the one thing it cannot do (CR 702.12b) — so the permanent still standing
/// with a spent Vindicate in the graveyard is what says the keyword was really
/// there, and not merely that a projection said so.
fn slobad_goblin_tinkerer() -> CardIndex {
    card_index("1f2d6cf4-b8f4-440f-ac08-ca47ada868ac")
}

#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn slobad_sacrifices_an_artifact_to_make_another_indestructible() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                plains(),
                plains(),
                swamp(),
                swamp(),
                time_sieve(),
                thopter_foundry(),
            ],
        )
        .hand(0, &[slobad_goblin_tinkerer(), vindicate()])
        // An artifact across the table, so "target artifact" is read as the
        // whole battlefield and not quietly narrowed to this seat's board.
        .battlefield(1, &[chromatic_lantern()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{R} out of the six lands, tapped in one pass so the {1}{W}{B} of the
    // Vindicate below comes out of the same open pool (CR 500.5).
    tap_all_mana(&mut engine, p0);
    cast_with_floating(&mut engine, p0, slobad_goblin_tinkerer());
    pass_until(&mut engine, stack_is_empty);
    let slobad = on_battlefield(&engine, p0, slobad_goblin_tinkerer()).expect("Slobad resolved");
    let fodder = on_battlefield(&engine, p0, time_sieve()).expect("an artifact to give up");
    let target = on_battlefield(&engine, p0, thopter_foundry()).expect("an artifact to protect");
    let theirs =
        on_battlefield(&engine, p1, chromatic_lantern()).expect("an artifact across the table");
    assert!(
        !keywords(&engine, target).contains(KeywordSet::INDESTRUCTIBLE),
        "nothing has granted anything yet"
    );

    activate(&mut engine, p0, slobad_goblin_tinkerer(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "`target artifact` is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat chooses");
    assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
    assert!(player_options.is_empty(), "no player is an artifact");
    assert!(
        options.contains(&fodder) && options.contains(&target),
        "both artifacts this seat controls may be named: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "`target artifact` is any artifact, on either side of the table: {options:?}"
    );
    assert!(
        !options.contains(&slobad),
        "Slobad is a creature and no artifact: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![target],
            },
        )
        .expect("the artifact the question offered was chosen");

    // CR 601.2c before CR 601.2h: the target is named while the price is still
    // unpaid, so the fodder is where it was when the question was asked.
    assert!(
        on_battlefield(&engine, p0, time_sieve()).is_some(),
        "the sacrifice is the last step of the activation, not the first"
    );
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which artifact, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell them apart"
    );
    assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "the two artifacts this seat controls and nothing else: {options:?}"
    );
    assert!(
        options.contains(&fodder) && options.contains(&target),
        "both are artifacts you control, the one just named included: {options:?}"
    );
    assert!(
        !options.contains(&slobad),
        "Slobad is a creature: `an artifact` is read, not skipped: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "CR 701.21a: an opponent's artifact is not yours to sacrifice: {options:?}"
    );

    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, chromatic_lantern()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the artifact the question offered pays the cost");
    assert!(
        in_graveyard(&engine, p0, time_sieve()).is_some(),
        "a sacrificed artifact goes to its owner's graveyard"
    );
    assert!(
        !stack_is_empty(&engine),
        "granting a keyword is no mana ability, so the ability is on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, thopter_foundry()).is_some(),
        "the artifact that was named never moved"
    );
    assert!(
        keywords(&engine, target).contains(KeywordSet::INDESTRUCTIBLE),
        "`target artifact gains indestructible until end of turn`"
    );

    // The keyword read off the layers is a projection; the destroy is what
    // makes it a rule. Vindicate's `destroy` cannot take an indestructible
    // permanent (CR 702.12b), and it is spent either way.
    cast_with_floating(&mut engine, p0, vindicate());
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!("Vindicate targets a permanent, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "same seat, same main phase — the grant lasts");
    assert!(
        options.contains(&target),
        "the artifact is still a legal target for a destroy effect: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![target],
            },
        )
        .expect("the permanent the question offered was chosen");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, thopter_foundry()).is_some(),
        "CR 702.12b: a permanent with indestructible can't be destroyed, so it \
         is still standing"
    );
    assert!(
        in_graveyard(&engine, p0, thopter_foundry()).is_none(),
        "and it was not put into the graveyard"
    );
    assert!(
        in_graveyard(&engine, p0, vindicate()).is_some(),
        "the spell resolved and went to the graveyard, so a destroy really \
         happened and was refused"
    );
}

fn spiteful_bully() -> CardIndex {
    card_index("410acdbc-3a00-49db-a712-ad970d24b363")
}

/// Spiteful Bully — {1}{B} 3/3 — "At the beginning of your upkeep, this
/// creature deals 3 damage to target creature you control."
///
/// The trigger is the whole card, so the Bully is cast and a full turn cycle
/// is walked to its controller's next upkeep, where the three damage has to
/// land on the creature the question offered. "You control" is read on both
/// sides of the table — the Elf across it is a creature and must stay off the
/// menu — and "creature you control" is not "another creature", so the Bully
/// itself is on that menu too. The Elf under the same seat dying while the
/// Bully stands is the repeat the card is played for (CR 704.5f).
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn spiteful_bully_shoots_a_creature_you_control_at_your_upkeep() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), swamp(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[spiteful_bully()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{B} off the Forest and the Swamp. The Elf is named as the printing
    // kept back because it is the creature the upkeep trigger will aim at,
    // and it is a mana creature `tap_all_mana` would otherwise have spent.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the Forest and the Swamp, and the Elf left standing"
    );
    cast_with_floating(&mut engine, p0, spiteful_bully());
    pass_until(&mut engine, stack_is_empty);

    let bully = on_battlefield(&engine, p0, spiteful_bully()).expect("the Bully resolved");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    assert_eq!(pt(&engine, bully), (3, 3), "the body the card prints");

    // The trigger belongs to its controller's own upkeep, so a whole turn
    // cycle has to pass — and the combat declarations are answered on the way,
    // because the question arrives before any priority round of that turn.
    let mut offered: Vec<ObjectId> = Vec::new();
    for _ in 0..400 {
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player, options, ..
            } => {
                assert_eq!(player, p0, "the Bully's controller is asked");
                offered = options;
                break;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::DiscardChoice { player, count } => {
                let hand = engine
                    .state()
                    .zones
                    .list(ZoneLocation::Hand(player))
                    .clone();
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: hand.into_iter().take(usize::from(count)).collect(),
                        },
                    )
                    .unwrap();
            }
            other => panic!("unexpected on the way to the next upkeep: {other:?}"),
        }
    }

    assert!(
        offered.contains(&mine),
        "the Elf under my own control is on the menu: {offered:?}"
    );
    assert!(
        offered.contains(&bully),
        "\"target creature you control\" is not \"another creature\": the \
         Bully's own body is a legal target for its trigger: {offered:?}"
    );
    assert!(
        !offered.contains(&theirs),
        "the Elf across the table is a creature and still no legal target, \
         which is the whole of `Filter::YOUR_CREATURE`: {offered:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the Elf was one of the options it enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "three damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_none(),
        "and the creature the trigger named left the battlefield"
    );
    assert!(
        on_battlefield(&engine, p0, spiteful_bully()).is_some(),
        "the Bully outlives its own upkeep, which is what makes the damage a \
         repeated price and not a one-shot"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the creature the trigger did not name never moved"
    );
}

fn starlight_invoker() -> CardIndex {
    card_index("4d27a90b-dae4-48a0-9eb2-e199ff548867")
}

/// Starlight Invoker — {1}{W}, a 1/3 Human Cleric Mutant — prints exactly one
/// line: "{7}{W}: You gain 5 life."
///
/// Ten lands go into the pool before anything is claimed, because
/// `can_afford` reads the mana pool and not the untapped lands: the cast's
/// {1}{W} comes out of that pool and leaves exactly the eight the ability
/// charges, which is the only moment the {7}{W} is legible at all — on an
/// empty pool the activation would be missing for want of mana rather than for
/// anything about the card. The five life is read on the seat that paid it,
/// and the pool is empty afterwards, so the life cannot have been bought with
/// mana that was never spent. Both left over — the {1}{W} of the cast and the
/// {7}{W} of the ability — are real payments out of a pool ten lands filled.
#[test]
fn starlight_invoker_charges_eight_mana_for_five_life() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                plains(),
                plains(),
                plains(),
                forest(),
                forest(),
                forest(),
                forest(),
                forest(),
                forest(),
                forest(),
            ],
        )
        .hand(0, &[starlight_invoker()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    tap_all_mana(&mut engine, p0);
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.total(), 10, "three Plains and seven Forests");
    assert_eq!(pool.available(ManaColor::White), 3, "the Plains");
    assert_eq!(pool.available(ManaColor::Green), 7, "the Forests");

    cast_with_floating(&mut engine, p0, starlight_invoker());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let invoker = on_battlefield(&engine, p0, starlight_invoker()).expect("the Invoker resolved");
    assert_eq!(pt(&engine, invoker), (1, 3), "the body it prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        8,
        "{{1}}{{W}} out of the pool leaves exactly the eight the ability charges"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(invoker, 0)),
        "{{7}}{{W}} is eight, and the pool holds exactly eight: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, starlight_invoker(), 0);
    assert!(!stack_is_empty(&engine), "gaining life is no mana ability");
    assert_eq!(
        engine.state().players[0].life,
        20,
        "nothing has resolved yet — the effect arrives off the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[0].life,
        25,
        "\"You gain 5 life\" — one activation, five life"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the life belongs to the seat that paid, not to the opponent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{7}}{{W}} came out of the pool"
    );
    assert!(
        on_battlefield(&engine, p0, starlight_invoker()).is_some(),
        "the ability costs its controller nothing but the mana — the Invoker stays"
    );
}

fn steadfast_guard() -> CardIndex {
    card_index("0c3b3c04-017d-4741-90c8-4b6c0bd46e49")
}

/// Steadfast Guard is {W}{W} for a 2/2 Human Rebel whose entire text is
/// vigilance: "Attacking doesn't cause this creature to tap" (CR 702.20b).
/// The test plays the printed card in a real game — cast off two Plains in
/// one turn, attacking in the next, because a creature that arrived this turn
/// is sick (CR 302.6) — and the Llanowar Elves beside it is the control: it
/// has no vigilance, so the *same* declaration has to tap it. Without that,
/// `!is_tapped` on the Guard would be satisfied just as well by an attack step
/// that never happened. The 2/2 body is read too, so the card is not just its
/// keyword.
#[test]
fn steadfast_guard_attacks_without_tapping_for_its_vigilance() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .hand(0, &[steadfast_guard()])
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");
    cast_from_hand(&mut engine, p0, steadfast_guard());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, steadfast_guard()).is_some() && stack_is_empty(e)
    });

    let guard = on_battlefield(&engine, p0, steadfast_guard()).expect("the Guard resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf was already out");
    assert_eq!(pt(&engine, guard), (2, 2), "the printed 2/2");
    assert!(
        keywords(&engine, guard).contains(KeywordSet::VIGILANCE),
        "vigilance is the card's whole keyword line"
    );
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::VIGILANCE),
        "the control creature has none of it"
    );

    // A full turn cycle: the Guard was cast on p0's own turn and is sick
    // (CR 302.6) until p0's next one, and the same untap step that stands it
    // back up is what makes the comparison below a fair one.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(!is_tapped(&engine, guard), "the untap step stood it up");
    assert!(
        !is_tapped(&engine, elves),
        "and the Elf with it — otherwise the attack below is a tapped creature \
         against a tapped creature"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&guard) && attackers.contains(&elves),
        "both stand untapped and are offered: {attackers:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(guard, Defender::Player(p1)), (elves, Defender::Player(p1))],
            },
        )
        .unwrap();

    assert!(
        !is_tapped(&engine, guard),
        "vigilance: declaring it as an attacker does not tap it (CR 702.20b)"
    );
    assert!(
        is_tapped(&engine, elves),
        "the Elf without vigilance is tapped by the very same declaration"
    );
}

fn stern_proctor() -> CardIndex {
    card_index("5120bfdc-7201-420d-85a1-eeb4aba6632b")
}

/// Stern Proctor — {U}{U} — 1/2 Human Wizard: "When this creature enters,
/// return target artifact or enchantment to its owner's hand."
///
/// The board holds one of each thing the filter names and one thing it does
/// not: my Sol Ring, a Luminarch Ascension across the table, and an Elf that
/// must stay off the menu. Bouncing the *opponent's* enchantment is what
/// proves all three words at once — the type is read (a creature is not
/// offered), the side of the table is not (their permanent is), and "to its
/// owner's hand" is where it lands, not the hand of the seat that aimed it.
#[test]
fn stern_proctor_bounces_an_artifact_or_enchantment_to_its_owners_hand() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), quiet_artifact()])
        .hand(0, &[stern_proctor()])
        .battlefield(1, &[luminarch_ascension(), quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {U}{U} off the two Islands, and the Sol Ring named as the source kept
    // back: it taps for {C}{C} of its own, which pays none of a double-blue
    // cost, and it is the artifact this trigger is about to be offered.
    let ring = on_battlefield(&engine, p0, quiet_artifact()).expect("my Sol Ring is out");
    tap_mana_except(&mut engine, p0, ring);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands, two blue, and the Sol Ring untouched"
    );
    cast_with_floating(&mut engine, p0, stern_proctor());

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the Proctor's controller chooses its target");

    let ascension =
        on_battlefield(&engine, p1, luminarch_ascension()).expect("their enchantment is out");
    let elf = on_battlefield(&engine, p1, quiet_creature()).expect("their Elf is out");
    assert!(
        options.contains(&ring) && options.contains(&ascension),
        "\"target artifact or enchantment\" is either type and either side of \
         the table: {options:?}"
    );
    assert!(
        !options.contains(&elf),
        "a creature is neither type, and the Elf across the table is the \
         counter-half that says the filter is read: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![ascension],
            },
        )
        .expect("the permanent the question offered is the one that moves");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, luminarch_ascension()).is_none(),
        "the targeted enchantment left the battlefield"
    );
    assert!(
        in_hand(&engine, p1, luminarch_ascension()).is_some(),
        "\"to its owner's hand\" — the seat that owns it, not the seat that \
         aimed the bounce"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_some(),
        "the artifact the trigger did not name never moved"
    );
    assert_eq!(
        pt(
            &engine,
            on_battlefield(&engine, p0, stern_proctor()).expect("the Proctor resolved")
        ),
        (1, 2),
        "and the body that did it is the 1/2 the card prints"
    );
}

fn storm_crow() -> CardIndex {
    card_index("000d5588-5a4c-434e-988d-396632ade42c")
}

/// Storm Crow is `{1}{U}` for a 1/2 Bird with flying, and "flying" is
/// not a line one can read off the card file, but a block rule
/// (CR 702.9b): a creature without flying or reach cannot block it.
/// The scenario therefore puts **both** kinds on the opposite side —
/// a Llanowar Elves as ground control and a second Storm Crow as flyer —,
/// so that the absence of the Elves in the block offer says something
/// about `flying` and not about an empty board.
/// Body and keyword are read on the same creature that was cast;
/// the attack itself waits for the untap step, because a creature cast
/// just now is summoning sick (CR 302.6).
#[test]
fn storm_crow_flies_over_ground_creatures_and_only_a_flier_may_block_it() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(4242, island())
        .battlefield(0, &[island(), island()])
        .hand(0, &[storm_crow()])
        .battlefield(1, &[llanowar_elves(), storm_crow()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, storm_crow());
    pass_until(&mut engine, stack_is_empty);
    let crow = on_battlefield(&engine, p0, storm_crow()).expect("der Crow ist gelandet");
    assert_eq!(pt(&engine, crow), (1, 2), "die gedruckten Zahlen");
    assert!(
        keywords(&engine, crow).contains(KeywordSet::FLYING),
        "flying is on the creature after the layers have run"
    );

    let their_crow = on_battlefield(&engine, p1, storm_crow()).expect("der zweite Crow steht");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("der Elf steht");

    // Summoning sickness: the just-cast Crow may only attack on the next
    // own turn.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(crow, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until hält bei der Blockdeklaration")
    };
    let offered: Vec<ObjectId> = blockers
        .iter()
        .filter(|b| b.attackers.contains(&crow))
        .map(|b| b.blocker)
        .collect();
    assert!(
        offered.contains(&their_crow),
        "ein Flieger darf den Crow blocken (CR 702.9b): {offered:?}"
    );
    assert!(
        !offered.contains(&elf),
        "der Llanowar Elves hat weder flying noch reach und ist darum kein \
         legaler Blocker: {offered:?}"
    );
}

fn sword_dancer() -> CardIndex {
    card_index("9ae49b45-a38f-4bd6-aa08-b5a5da6e75a1")
}

/// Sword Dancer is a 1/2 for `{1}{W}` with exactly one line: "`{W}{W}`:
/// Target attacking creature gets −1/−0 until end of turn." The word the
/// card hangs on is *attacking* — so there is one **non**-
/// attacking creature under each player on the battlefield, and both must
/// stay out of the target list, while the only attacker is the whole list.
/// Two Plains pay the cost from a pool that was tapped beforehand
/// (`can_afford` reads the pool and not the untapped lands), and what the
/// −1/−0 did is read only on combat damage: an attacker with 0 power
/// takes no life from the defender, an unpumped 1/1 one.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn sword_dancer_shrinks_an_attacking_creature_and_no_other() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), plains(), sword_dancer(), festering_goblin()])
        .battlefield(1, &[festering_goblin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let dancer = on_battlefield(&engine, p0, sword_dancer()).expect("the Sword Dancer is out");
    let goblin = on_battlefield(&engine, p0, festering_goblin()).expect("my Goblin is out");
    let theirs = on_battlefield(&engine, p1, festering_goblin()).expect("their Goblin is out");
    assert_eq!(pt(&engine, dancer), (1, 2), "a printed 1/2 before the pump");

    // Attacker declared: the Sword Dancer is the only one that will meet the
    // filter condition in a moment.
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::ChooseAttackers { player, .. } if *player == p0),
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(dancer, Defender::Player(p1))],
            },
        )
        .expect("the Dancer was one of the offered attackers");

    // The active player holds priority after the attack declaration
    // (`CR 508.2`) — and only there is "attacking creature" true at all.
    // `pass_until` instead of a bare `matches!`: it also skips a
    // block declare that would lie before damage assignment, without the
    // attacker ceasing to be an attacker.
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::Priority { player, .. } if *player == p0),
    );

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Plains, two white — the Dancer and both Goblins make no mana"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(dancer, 0)),
        "{{W}}{{W}} is floating, so the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, sword_dancer(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target attacking creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        !options.contains(&goblin),
        "a creature that stayed home is no attacking creature: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "and the Goblin across the table is not attacking either, so it is no \
         more a legal target than mine: {options:?}"
    );
    assert_eq!(
        options,
        vec![dancer],
        "the one attacker in the game is the whole menu"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![dancer],
            },
        )
        .expect("the attacker was the only option the question enumerated");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "CR 601.2h: the target is named first and the {{W}}{{W}} paid last"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, dancer),
        (0, 2),
        "−1/−0 on the creature that was named, and no toughness either"
    );
    assert_eq!(
        pt(&engine, goblin),
        (1, 1),
        "the static reaches the target and no other creature"
    );

    // And the missing point of power is the card's purpose: without the
    // −1/−0, p1 would be at 19.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the 0-power attacker dealt no combat damage"
    );
}

// Talas Scout is `{1}{U}` for a 1/2 Human Pirate Scout whose entire text is
// flying, and the set of things a test could get wrong is exactly the set an
// empty-bodied card would hide behind: the body, the keyword, and the fact
// that the keyword means something in a combat step. The Scout is cast off
// two Islands, read off the battlefield (1/2, a creature, flying), left a
// whole turn cycle so that summoning sickness (CR 302.6) is behind it, and
// then sent at the opponent across a ground Elf. It arrives unblocked because
// flying is a *pairing* rule (CR 702.9b) — the Elf is a legal blocker for
// creatures in general and is offered nothing against a flier — and the one
// life the 1/2 takes is the evidence that the attack happened at all.

fn talas_scout() -> CardIndex {
    card_index("71b7d5c4-c16c-4c6b-8e2e-e9b5cc128e1f")
}

#[test]
fn talas_scout_flies_over_the_ground_and_takes_a_life() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island()])
        .hand(0, &[talas_scout()])
        // A creature on the ground: "can it be blocked" is a question about a
        // board with something on the other side of the table to ask it with.
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, talas_scout());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, talas_scout()).is_some()
    });
    let scout = on_battlefield(&engine, p0, talas_scout()).expect("the Scout resolved");
    let kinds = types(&engine, scout);
    assert!(
        kinds.contains(TypeSet::CREATURE),
        "a creature, and not the sorcery the rest of the pool is: {kinds:?}"
    );
    assert_eq!(pt(&engine, scout), (1, 2), "the body the card prints");
    assert!(
        keywords(&engine, scout).contains(KeywordSet::FLYING),
        "and the flying its whole text is"
    );

    // A turn cycle, because the Scout arrived this turn: CR 302.6 keeps a
    // creature that has not been under its controller's control since their
    // most recent turn began from attacking, and the attack below is the only
    // reading of flying this board can offer.
    reach_their_main_phase(&mut engine, p1);
    assert!(walk_to_own_main(&mut engine, p0), "back to p0's own main");

    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::ChooseAttackers { player, .. } if *player == p0),
    );
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stopped on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&scout),
        "an unsick, untapped 1/2 may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(scout, Defender::Player(p1))],
            },
        )
        .expect("the Scout was offered as an attacker");

    // Flying is a *pairing* rule (CR 702.9b), so the ground Elf is never
    // offered against the Scout. The walk answers whatever priority is handed
    // out on the way rather than assuming the question comes immediately, and
    // whether the engine asks at all is not what is asserted.
    for _ in 0..20 {
        match engine.pending().clone() {
            Pending::ChooseBlockers {
                player, blockers, ..
            } => {
                assert_eq!(player, p1, "the attacked seat is the one asked");
                for option in blockers {
                    assert!(
                        !option.attackers.contains(&scout),
                        "a ground creature cannot be paired with a flier: {option:?}"
                    );
                }
                break;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            _ => break,
        }
    }

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "the unblocked 1/2 took exactly one life — the Islands on p0's board \
         have no way of dealing damage, so the point can only be the Scout's"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the Elf that was offered nothing to block is still standing"
    );
}

fn talon_sliver() -> CardIndex {
    card_index("74910702-e385-48f7-a6b3-064ebed08be7")
}

/// Talon Sliver — {1}{W} 1/1 Sliver: "All Sliver creatures have first strike."
///
/// The grant is a continuous effect over a subtype filter, so the scenario reads
/// it where only the layers can be seen: nothing on this board has first strike
/// before the cast, and the Sliver that then arrives has it — from its own printed
/// static, which reaches its own source the way the card says it does. The
/// Llanowar Elves standing beside it are the control, a creature under the same
/// controller that the subtype filter has to decline, and the last claim pins the
/// static as a static: it is projected, never offered as something to press.
#[test]
fn talon_sliver_arrives_with_first_strike_and_grants_it_to_no_creature_without_its_subtype() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .hand(0, &[talon_sliver()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FIRST_STRIKE),
        "no Sliver is on the battlefield yet, so nothing grants anything"
    );

    // {1}{W} off the two Plains, with the Elves named as the printing kept back:
    // they are the creature this test reads afterwards, and a mana creature is a
    // mana route too (#159).
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Plains tapped and no creature of mine tapped for mana"
    );
    cast_with_floating(&mut engine, p0, talon_sliver());
    pass_until(&mut engine, stack_is_empty);

    let sliver = on_battlefield(&engine, p0, talon_sliver()).expect("the Sliver resolved");
    assert!(
        types(&engine, sliver).contains(TypeSet::CREATURE),
        "it arrives as the creature it prints"
    );
    assert_eq!(pt(&engine, sliver), (1, 1), "and with the printed 1/1 body");
    // Deliberately no "not yet": the Sliver **is** a Sliver creature, so its
    // own static reaches it the moment it is on the battlefield, and the two
    // assertions at the end of this test are where that is read. A grant is
    // separated from a printed keyword by the Elf beside it instead.
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FIRST_STRIKE),
        "and the creature without the subtype still has nothing"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!(
            "the spell resolved and the seat holds priority: {:?}",
            engine.pending()
        )
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == sliver),
        "a static is never offered as an activation: {:?}",
        legal.abilities
    );

    let armed = keywords(&engine, sliver);
    assert!(
        armed.contains(KeywordSet::FIRST_STRIKE),
        "\"All Sliver creatures have first strike\" — and this is one, so the \
         grant reaches its own source: {armed:?}"
    );
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FIRST_STRIKE),
        "a creature without the subtype gets nothing, on the very same side of \
         the table"
    );
}

fn temple_acolyte() -> CardIndex {
    card_index("17e4085e-af44-4ba8-af05-ccfe4b35f96a")
}

/// Temple Acolyte prints `{1}{W}` for a 1/3 Human Cleric whose whole text is
/// "When this creature enters, you gain 3 life" — one body and one trigger, and
/// neither is visible from the card file. So the spell is actually cast off two
/// tapped Plains and the two readings are taken where they happen: the card
/// sitting on the stack with both life totals still at twenty (it is an
/// *enters* ability and not a cast trigger), and then the 1/3 that arrived with
/// three life on the seat that cast it. The opponent's untouched total beside
/// it is the control — "you" is the controller and not the table.
#[test]
fn temple_acolyte_enters_as_a_one_three_and_gains_three_life_for_its_controller() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), plains()])
        .hand(0, &[temple_acolyte()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, temple_acolyte());
    assert!(
        on_stack(&engine, temple_acolyte()).is_some(),
        "the Acolyte is a spell before it is a creature"
    );
    assert_eq!(
        (
            engine.state().players[0].life,
            engine.state().players[1].life
        ),
        (20, 20),
        "nothing has been gained yet: the printed sentence is an *enters* \
         ability, so it waits for the creature to arrive"
    );

    pass_until(&mut engine, stack_is_empty);

    let acolyte = on_battlefield(&engine, p0, temple_acolyte()).expect("the Acolyte resolved");
    assert_eq!(
        pt(&engine, acolyte),
        (1, 3),
        "the body the card prints, and the one the trigger left alone"
    );
    assert_eq!(
        engine.state().players[0].life,
        23,
        "\"you gain 3 life\" — the seat that cast it, three and not one"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and nothing for the other seat, so the gain is read off the \
         controller and not off the table"
    );
}

fn tonic_peddler() -> CardIndex {
    card_index("9039f59a-915b-4b16-a5c4-1a5fbfb0b639")
}

/// Tonic Peddler is a `{1}{W}` 1/1 whose whole text is "`{W}`, `{T}`, Discard
/// a card: Target player gains 3 life."
///
/// Two halves of that line are the engine's answers rather than the card's.
/// The target is a *player*, so the offer has to name both seats and the life
/// has to land on the one that was picked — p1 here, with p0's own total as
/// the control. And "Discard a card" is a cost (CR 601.2h) that arrives as a
/// `CostDiscard` menu of hand cards, so the proof it was paid is the very card
/// the question offered lying in its owner's graveyard plus one card fewer in
/// the hand: costs are the *last* step of the activation, so while the target
/// question stood the card was still in hand and the Peddler still untapped.
/// It is cast on turn one and its ability is played a turn later, because a
/// creature has summoning sickness in the turn it arrives (CR 302.6) and a
/// `{T}` price cannot be paid there.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn tonic_peddler_discards_a_card_to_give_targeted_player_three_life() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    // Three Plains pay the {1}{W} and leave a white for the {W}; the Forest is
    // the card the ability will have to throw away, and without it in hand the
    // discard — and so the whole activation — would be unpayable.
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains()])
        .hand(0, &[tonic_peddler(), forest()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, tonic_peddler());
    pass_until(&mut engine, stack_is_empty);
    let peddler = on_battlefield(&engine, p0, tonic_peddler()).expect("the Peddler resolved");
    assert_eq!(pt(&engine, peddler), (1, 1), "the body the card prints");

    // A turn later: the creature arrived this turn and is summoning sick, so
    // the {T} in the price is not payable until its controller's next turn.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    // The offer is filtered by `can_afford`, which reads the pool and not the
    // untapped lands, so the mana is tapped before anything is claimed.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Plains, and the Peddler is no mana source of its own"
    );
    assert!(!is_tapped(&engine, peddler), "nothing has tapped it yet");
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(peddler, 0)),
        "{{W}}, {{T}}, Discard a card is payable with a card in hand: {:?}",
        legal.abilities
    );

    let hand_before = engine
        .state()
        .zones
        .list(crate::zone::ZoneLocation::Hand(p0))
        .len();
    activate(&mut engine, p0, tonic_peddler(), 0);

    // CR 601.2c names the target and CR 601.2h pays afterwards, so the two
    // questions are answered in whatever order they arrive rather than in the
    // order they are expected.
    let mut aimed_at_the_opponent = false;
    let mut discarded = None;
    for _ in 0..12 {
        if aimed_at_the_opponent && discarded.is_some() {
            break;
        }
        match engine.pending().clone() {
            Pending::ChoosePlayer { player, options } => {
                assert!(
                    options.contains(&p0) && options.contains(&p1),
                    "\"target player\" is either seat: {options:?}"
                );
                engine
                    .apply(player, PlayerAction::ChoosePlayer(p1))
                    .unwrap();
                aimed_at_the_opponent = true;
            }
            Pending::ChooseTargets {
                player,
                player_options,
                ..
            } => {
                assert!(
                    player_options.contains(&p0) && player_options.contains(&p1),
                    "\"target player\" is either seat: {player_options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseTargets {
                            objects: vec![],
                            players: vec![p1],
                        },
                    )
                    .unwrap();
                aimed_at_the_opponent = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostDiscard,
                    "a cost and not a search, which is all a client has to tell \
                     the two apart"
                );
                assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
                assert!(
                    !options.is_empty(),
                    "the hand the question is about is not empty"
                );
                let doomed = options[0];
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![doomed],
                        },
                    )
                    .unwrap();
                discarded = Some(doomed);
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while the Peddler's ability resolves: {other:?}"),
        }
    }
    assert!(
        aimed_at_the_opponent,
        "the ability asked whom to give the life to"
    );
    let discarded = discarded.expect("the discard cost is part of the price");

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[1].life,
        23,
        "\"Target player gains 3 life\" — three, on the seat that was named"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing for the seat that paid for it"
    );
    assert!(
        is_tapped(&engine, peddler),
        "{{T}} was half the price, paid by the Peddler itself"
    );
    assert_eq!(
        engine
            .state()
            .zones
            .list(crate::zone::ZoneLocation::Hand(p0))
            .len(),
        hand_before - 1,
        "\"Discard a card\" leaves the hand one card shorter"
    );
    assert_eq!(
        engine.state().object(discarded).map(|o| o.zone),
        Some(crate::zone::Zone::Graveyard),
        "and it is the very card the question offered, in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, tonic_peddler()).is_some(),
        "the Peddler outlives the card it threw away"
    );
}

fn uktabi_faerie() -> CardIndex {
    card_index("447f1cce-bbc5-473b-a838-34070f8fd2dc")
}

/// Uktabi Faerie is a 1/1 flier whose whole text is "{3}{G}, Sacrifice this
/// creature: Destroy target artifact."
///
/// The scenario reads all three parts of that price and the one word that
/// decides what the ability may point at: the four Forests are tapped before
/// anything is claimed, because `legal.abilities` is filtered through
/// `can_afford` and reads the pool rather than the untapped lands; the target
/// question is answered while the Faerie is still on the battlefield and the
/// mana still floating (CR 601.2h pays last); and the artifact across the
/// table stands beside an Elf, so "target artifact" is read and not skipped.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn uktabi_faerie_sacrifices_itself_to_destroy_a_target_artifact() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[forest(), forest(), forest(), forest(), uktabi_faerie()],
        )
        .battlefield(1, &[quiet_artifact(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let faerie = on_battlefield(&engine, p0, uktabi_faerie()).expect("the Faerie is out");
    let rock = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    let elves = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    assert_eq!(pt(&engine, faerie), (1, 1), "a printed 1/1");
    assert!(
        keywords(&engine, faerie).contains(KeywordSet::FLYING),
        "with the flying the card prints"
    );

    // The price is `{3}{G}`, and the pool is where the engine reads it. The
    // Faerie prints no mana ability of its own, so the four Forests are the
    // whole of the board's mana and the whole of the count.
    let taken = tap_all_mana(&mut engine, p0);
    assert_eq!(taken, 4, "the four Forests and nothing else on this board");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four green floating out of the four Forests"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(faerie, 0)),
        "with {{3}}{{G}} in the pool the Faerie's one line is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, uktabi_faerie(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target artifact\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&rock),
        "the artifact across the table is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&elves),
        "the Elf is a creature and no artifact: {options:?}"
    );
    assert!(
        !options.contains(&faerie),
        "the Faerie is the price, not a target: {options:?}"
    );
    assert_eq!(options, vec![rock], "the one artifact in the game");

    // CR 601.2h: the sacrifice and the mana are the last step of the
    // activation, so both are still here while the question stands.
    assert!(
        on_battlefield(&engine, p0, uktabi_faerie()).is_some(),
        "nothing is paid before the target is named"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "and the {{3}}{{G}} is still floating"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![rock],
            },
        )
        .expect("the artifact the question offered was chosen");

    assert!(
        on_battlefield(&engine, p0, uktabi_faerie()).is_none(),
        "\"Sacrifice this creature\" takes the Faerie itself"
    );
    assert!(
        in_graveyard(&engine, p0, uktabi_faerie()).is_some(),
        "and a sacrificed creature goes to its owner's graveyard"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{3}}{{G}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "destroying an artifact is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_none(),
        "the artifact that was named left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p1, quiet_artifact()).is_some(),
        "and it is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "while the Elf the ability did not name never moved"
    );
}

fn urborg_elf() -> CardIndex {
    card_index("9c382817-5c62-44ff-8f29-d283e65712a1")
}

/// Urborg Elf is a `{1}{G}` 1/1 printing one line: "{T}: Add {B}, {G}, or
/// {U}." Three colours and no default is the whole card, so the question has
/// to be asked and its menu has to hold exactly those three — a `{G}` read as
/// a fixed colour would float green off the tap and never ask anything. The
/// board is two Forests that are already spent paying for the Elf, so the pool
/// is empty when the tap is pressed and the one blue afterwards can only be
/// the Elf's: a creature's `{T}` is a mana ability whose whole price is its
/// own tap (CR 605.1), which is why the mana and the empty stack are read in
/// the same instant.
#[test]
fn urborg_elf_taps_for_one_mana_of_the_three_colors_it_names() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[urborg_elf()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} out of exactly two Forests, so the pool is empty once the Elf has
    // landed and every drop of mana below is accounted for by its own tap.
    cast_from_hand(&mut engine, p0, urborg_elf());
    pass_until(&mut engine, stack_is_empty);
    let elf = on_battlefield(&engine, p0, urborg_elf()).expect("the Elf resolved");
    assert_eq!(pt(&engine, elf), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "two Forests paid exactly the {{1}}{{G}}, so nothing is left floating"
    );
    for land in all_on_battlefield(&engine, p0, forest()) {
        assert!(
            is_tapped(&engine, land),
            "both Forests are spent, so no land on this board can be the source \
             of the mana the Elf is about to make"
        );
    }

    // Its own next turn: a `{T}` in a cost is unpayable for a creature that
    // arrived this turn (CR 302.6). The Forests stand back up with it and are
    // left standing — what is measured below is the Elf's tap and no other.
    reach_their_main_phase(&mut engine, PlayerId::new(1));
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the pool empties at the end of a step (CR 500.5), so every drop \
         below is the Elf's own"
    );

    // The whole price of the ability is the Elf's own {T}, so it is offered
    // with nothing in the pool at all.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(elf, 0)),
        "an untapped Elf is a paid {{T}}, so its mana line is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, urborg_elf(), 0);
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!(
            "\"Add {{B}}, {{G}}, or {{U}}\" is a question, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that names it");
    assert_eq!(
        options.len(),
        3,
        "exactly the three colours the card prints: {options:?}"
    );
    for color in [ManaColor::Black, ManaColor::Green, ManaColor::Blue] {
        assert!(
            options.contains(&color),
            "\"Add {{B}}, {{G}}, or {{U}}\" includes {color:?}: {options:?}"
        );
    }

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Blue))
        .expect("blue was one of the colours it offered");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Blue),
        1,
        "the colour that was named, off the Elf's own tap"
    );
    assert_eq!(pool.total(), 1, "one mana, and nothing else came with it");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, elf), "the Elf paid its own {{T}}");
}

fn abbey_matron() -> CardIndex {
    card_index("62e3f285-886c-414e-b4ff-403a7c01c23a")
}

/// Abbey Matron prints two lines: a 1/3 for {2}{W} and "{W}, {T}: This
/// creature gets +0/+3 until end of turn." Both numbers of the pump are
/// readable thereby — a 1/6 after activation rules out a "+3/+0" or
/// a "+0/+0", and the 1/3 before it says that the printed body does not
/// arrive already pumped. The cost is {W} **and** its own tap symbol,
/// so `tap_all_mana` does not tap the card along with it (#159): one half
/// is the white mana that has disappeared from the pool after activation,
/// the other the tapped Cleric. The Goblin next to it is the control for
/// `Filter::This` — a pump without a filter would have dragged it along.
#[test]
fn abbey_matron_pumps_only_herself_for_white_and_a_tap() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), abbey_matron(), festering_goblin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let matron = on_battlefield(&engine, p0, abbey_matron()).expect("the Matron is out");
    let bystander = on_battlefield(&engine, p0, festering_goblin()).expect("the Goblin is out");
    assert_eq!(
        pt(&engine, matron),
        (1, 3),
        "a printed 1/3 before anything is paid for"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "and a printed 1/1 beside her"
    );

    // The whole price is one white and her own tap. `tap_all_mana` leaves her
    // standing: it presses only abilities whose entire cost is their own {T}
    // (#159), and {W}, {T} is a larger price than that.
    let taken = tap_all_mana(&mut engine, p0);
    assert_eq!(taken, 1, "the one Plains, and the Matron left alone");
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::White), 1, "one white floating");
    assert_eq!(pool.total(), 1, "and nothing else on this board makes mana");
    assert!(!is_tapped(&engine, matron), "she is still standing");

    // The offer is read off the pool, so it is claimed only now.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(matron, 0)),
        "with {{W}} floating and the Cleric untapped her one line is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, abbey_matron(), 0);
    assert!(is_tapped(&engine, matron), "{{T}} is half the cost");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{W}} is spent: a pump costs no more than the card prints"
    );
    assert!(
        !stack_is_empty(&engine),
        "pumping is no mana ability, so the ability is on the stack"
    );
    assert_eq!(
        pt(&engine, matron),
        (1, 3),
        "CR 601.2h paid the price but nothing has resolved yet"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, matron),
        (1, 6),
        "+0/+3: the power stays where it was printed and only the toughness grows"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "`Filter::This` is the whole of what the pump reaches"
    );
}

fn akki_drillmaster() -> CardIndex {
    card_index("aa228a01-7de3-4539-9ebb-b3c546f72b41")
}

/// Akki Drillmaster is a `{2}{R}` 2/2 whose whole text is "`{T}`: Target
/// creature gains haste until end of turn." Two Llanowar Elves are cast in one
/// main phase, so both are summoning sick (CR 302.6) and neither may attack —
/// and the Drillmaster, which arrived a turn earlier so that its own `{T}` is
/// payable, is aimed at exactly one of them. The attack declaration then has to
/// name one Elf and not the other, which is haste doing its printed job rather
/// than a keyword projected onto a card: the untargeted twin stands on the same
/// board, cast in the same phase, with nothing missing from it, and the Elf
/// across the table is what shows the printed "target creature" is not "target
/// creature you control".
#[test]
fn akki_drillmaster_gives_one_of_two_freshly_cast_creatures_haste_and_leaves_the_other_sick() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), mountain(), mountain(), forest(), forest()])
        .hand(0, &[akki_drillmaster(), llanowar_elves(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{R} off the three Mountains. The Drillmaster arrives sick, so its own
    // `{T}` waits for the untap step that clears CR 302.6.
    tap_all_mana(&mut engine, p0);
    cast_with_floating(&mut engine, p0, akki_drillmaster());
    pass_until(&mut engine, stack_is_empty);
    let drillmaster =
        on_battlefield(&engine, p0, akki_drillmaster()).expect("the Drillmaster resolved");
    assert_eq!(pt(&engine, drillmaster), (2, 2), "the printed 2/2");

    // A full turn cycle, so the board stands back up and both Elves are cast in
    // *this* main phase — which is exactly what makes them summoning sick.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "three Mountains and two Forests, and the Drillmaster makes no mana"
    );
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, stack_is_empty);
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, stack_is_empty);

    let elves = all_on_battlefield(&engine, p0, llanowar_elves());
    assert_eq!(elves.len(), 2, "two Elves, both of them cast this turn");
    let (sick, untouched) = (elves[0], elves[1]);
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    assert!(
        !keywords(&engine, sick).contains(KeywordSet::HASTE)
            && !keywords(&engine, untouched).contains(KeywordSet::HASTE),
        "nothing on this board grants haste yet"
    );

    activate(&mut engine, p0, akki_drillmaster(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "the ability asks for a creature, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert!(
        options.contains(&sick) && options.contains(&untouched),
        "\"target creature\" offers both of mine: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"target creature\" reaches across the table, so it is not \"target \
         creature you control\": {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![sick],
            },
        )
        .expect("the creature the question offered");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        keywords(&engine, sick).contains(KeywordSet::HASTE),
        "the targeted creature has haste until end of turn"
    );
    assert!(
        !keywords(&engine, untouched).contains(KeywordSet::HASTE),
        "and the Elf nobody named does not"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::HASTE),
        "nor does the Elf across the table"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&sick),
        "a creature that arrived this turn may attack only because the grant \
         lifted CR 302.6: {attackers:?}"
    );
    assert!(
        !attackers.contains(&untouched),
        "its twin, cast in the same phase and granted nothing, is still \
         summoning sick: {attackers:?}"
    );
    assert!(
        is_tapped(&engine, drillmaster),
        "and {{T}} was the price the Drillmaster actually paid"
    );
}

fn alert_shu_infantry() -> CardIndex {
    card_index("0f019387-4684-493f-80c4-de6023096306")
}

/// Alert Shu Infantry is a `{2}{W}` 2/2 Human Soldier whose whole printed
/// text is vigilance, and vigilance is only readable in the combat step:
/// CR 508.1f taps every attacking creature *except* one that has it.
///
/// So the board carries a Llanowar Elves beside it as the control — a
/// creature with no vigilance under the same seat, declared in the same
/// attack — and the two readings are one: the Elf comes back tapped and the
/// Infantry stands. That the 3 damage actually reaches the defending player
/// is what says the declaration was real combat and not merely an offer the
/// engine had listed.
#[test]
fn alert_shu_infantry_attacks_without_tapping_where_the_elf_beside_it_taps() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains(), llanowar_elves()])
        .hand(0, &[alert_shu_infantry()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The three Plains pay the {2}{W}, and the Elf is named as the printing
    // kept back: it is the control this test turns on, and a creature tapped
    // for mana may not attack (rule 11 — a mana creature counts in the pool
    // and would have left the board, not filled it).
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Plains, and the Elf contributed nothing"
    );
    cast_with_floating(&mut engine, p0, alert_shu_infantry());
    pass_until(&mut engine, stack_is_empty);
    let soldier = on_battlefield(&engine, p0, alert_shu_infantry()).expect("the Infantry resolved");
    assert_eq!(pt(&engine, soldier), (2, 2), "the body the card prints");
    assert!(
        keywords(&engine, soldier).contains(KeywordSet::VIGILANCE),
        "the one printed word, projected onto the permanent"
    );

    // A creature cast this turn has summoning sickness (CR 302.6), so the
    // attack belongs to its controller's next turn — the turn cycle is what
    // makes the declaration below legal at all.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is still out");
    assert!(
        !is_tapped(&engine, soldier) && !is_tapped(&engine, elves),
        "both stood up in the untap step, so neither is tapped for another reason"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&soldier) && attackers.contains(&elves),
        "two untapped, unsick creatures of mine: {attackers:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (soldier, Defender::Player(p1)),
                    (elves, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    assert!(
        !is_tapped(&engine, soldier),
        "\"Vigilance\": the Infantry attacked and is still standing"
    );
    assert!(
        is_tapped(&engine, elves),
        "the Elf beside it has no vigilance and tapped to attack — the \
         counter-half that makes the sentence above a filter and not a board"
    );

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        17,
        "2 from the Infantry and 1 from the Elf reached the player they \
         attacked, so the declaration was no mere offer"
    );
}

fn alpha_kavu() -> CardIndex {
    card_index("f1a76cca-829a-4576-a560-f1af34b80b87")
}

/// Alpha Kavu — {2}{G} 2/2 Kavu: "{1}{G}: Target **Kavu** creature gets
/// -1/+1 until end of turn." The subtype is the whole of the filter, so the
/// board carries three creatures and only two of them are on the menu: the
/// Kavu under this seat and the one across the table are both "target Kavu
/// creature", while the Llanowar Elves beside them must be declined. The pump
/// is read as a *body* — a printed 2/2 becomes a 1/3, which no other reading
/// of "-1/+1" produces — and it lands on the creature that was named while the
/// Elf and the other Kavu keep their printed numbers.
#[test]
fn alpha_kavu_pumps_only_a_kavu_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), alpha_kavu(), llanowar_elves()])
        .battlefield(1, &[alpha_kavu()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, alpha_kavu()).expect("my Kavu is out");
    let theirs = on_battlefield(&engine, p1, alpha_kavu()).expect("their Kavu is out");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert_eq!(
        pt(&engine, mine),
        (2, 2),
        "a printed 2/2 before anything is asked"
    );

    // Mana first: the offer is read off the pool and not off untapped lands.
    // Two Forests and the Elf's own printed `{T}: Add {G}` are three sources.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "two Forests and one Elf tapped for it"
    );

    activate(&mut engine, p0, alpha_kavu(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target Kavu creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "a Kavu on either side of the table is \"target Kavu creature\": {options:?}"
    );
    assert!(
        !options.contains(&elves),
        "an Elf is no Kavu, whatever else it is: {options:?}"
    );
    assert_eq!(options.len(), 2, "and those two are the whole menu");

    // CR 601.2c before CR 601.2h: the target is named while the mana is still
    // floating and no pump has happened yet.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "the cost is the last step of the activation"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the Kavu the question offered was chosen");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "{{1}}{{G}} came out of the pool"
    );
    assert!(!stack_is_empty(&engine), "and it is no mana ability");

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, mine),
        (1, 3),
        "-1/+1 on the Kavu that was named"
    );
    assert_eq!(
        pt(&engine, theirs),
        (2, 2),
        "the Kavu it did not name never moved"
    );
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "and neither did the creature that is no Kavu at all"
    );
    assert!(
        !is_tapped(&engine, mine),
        "the printed price is mana, not the Kavu's own {{T}}"
    );
}

fn ambassador_laquatus() -> CardIndex {
    card_index("2df8f253-1d3c-4b1f-8549-93fb90623474")
}

/// Ambassador Laquatus is a `{1}{U}{U}` legend with a single printed
/// line: "{3}: Target player mills three cards." Six Islands pay for both
/// in one turn — the three for the creature and exactly the three that the
/// ability costs afterwards —, so the mana pool before activation and after
/// it carries the whole statement about the cost: the offer stands as long
/// as the three are floating, and is gone as soon as they are paid. The
/// second half of the card is the word "target player": the question names
/// both players, and the player that was named is milled — the untouched
/// graveyard of the activating player is the control for the fact that the
/// three cards did not simply end up "anywhere".
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn ambassador_laquatus_mills_three_for_the_player_it_names_for_three_mana() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, island())
        .battlefield(
            0,
            &[island(), island(), island(), island(), island(), island()],
        )
        .hand(0, &[ambassador_laquatus()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Six Islands, six blue: the `{1}{U}{U}` of the creature and exactly the
    // `{3}` that the ability demands afterwards remain in the pool beside it.
    tap_all_mana(&mut engine, p0);
    cast_with_floating(&mut engine, p0, ambassador_laquatus());
    pass_until(&mut engine, stack_is_empty);
    let ambassador = on_battlefield(&engine, p0, ambassador_laquatus())
        .expect("the Ambassador resolved onto the table");
    assert_eq!(pt(&engine, ambassador), (1, 3), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "the {{1}}{{U}}{{U}} is spent and the ability's {{3}} is still floating"
    );

    // The pool decides the offer (`can_afford` reads it and not the untapped
    // lands), so it is filled before the assertion.
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Ambassador holds it");
    assert!(
        legal.abilities.contains(&(ambassador, 0)),
        "with exactly {{3}} floating, the one line the card prints is offered: {:?}",
        legal.abilities
    );

    let their_library = library_size(&engine, p1);
    let their_graveyard = engine.state().zones.list(ZoneLocation::Graveyard(p1)).len();
    let my_library = library_size(&engine, p0);
    let my_graveyard = engine.state().zones.list(ZoneLocation::Graveyard(p0)).len();

    activate(&mut engine, p0, ambassador_laquatus(), 0);
    let Pending::ChooseTargets {
        player,
        player_options,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target player\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "CR 115.4: \"target player\" reaches either seat, its own included: {player_options:?}"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "CR 601.2c before CR 601.2h: nothing is paid while the question stands"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![],
                players: vec![p1],
            },
        )
        .expect("the opponent was one of the players offered");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{3}} is the last step of the activation and comes out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "milling is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        library_size(&engine, p1),
        their_library - 3,
        "\"mills three cards\" — three off the top of the library that was named"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p1)).len(),
        their_graveyard + 3,
        "and the three are in that player's graveyard, not merely missing"
    );
    assert_eq!(
        library_size(&engine, p0),
        my_library,
        "the seat that activated lost nothing off its own library"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        my_graveyard,
        "and its graveyard is empty of cards it never milled itself"
    );

    // And the cost was a cost: without floating mana the same line is no
    // longer on the same board in the offer.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds priority again, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(ambassador, 0)),
        "the {{3}} is spent, so the ability is unpayable and not offered: {:?}",
        legal.abilities
    );
}

fn apprentice_wizard() -> CardIndex {
    card_index("d16d2451-1c21-4a6b-8a4a-40ac8cd9fe08")
}

/// Apprentice Wizard — {1}{U}{U} — 0/1 Human Wizard: "{U}, {T}: Add {C}{C}{C}."
///
/// The price is a blue mana **and** the tap, and that is the whole card: with
/// an empty pool the {U} cannot be paid and `legal.abilities` does not list
/// the line at all, while `tap_all_mana` may not press it either — its whole
/// price is not its own tap (#159). What lands afterwards is three
/// *colourless*, which is the reading no other permanent on this board could
/// have produced: the two Islands make blue and nothing else, one blue is
/// gone to the price, and the mana arrives with an empty stack (CR 605.3b).
#[test]
fn apprentice_wizard_trades_a_blue_mana_and_its_tap_for_three_colourless() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), apprentice_wizard()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let wizard = on_battlefield(&engine, p0, apprentice_wizard()).expect("the Wizard is out");
    assert_eq!(pt(&engine, wizard), (0, 1), "a printed 0/1");
    assert!(!is_tapped(&engine, wizard), "and untapped to begin with");

    // `can_afford` reads the pool and not the untapped lands, so with nothing
    // floating the {U} half of the price is unpayable and the line is absent
    // from the offer rather than refused.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(wizard, 0)),
        "an empty pool pays no {{U}}, so the ability is not offered: {:?}",
        legal.abilities
    );

    // The Islands are the CR 305.6 shortcut and the Wizard is a larger price:
    // "{U}, {T}" is not a tap on its own, so the helper leaves it standing.
    let taken = tap_all_mana(&mut engine, p0);
    assert_eq!(taken, 2, "the two Islands, and the Wizard left alone");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands, two blue, and nothing off the Wizard"
    );
    assert!(
        !is_tapped(&engine, wizard),
        "a price this kit may not pay on a test's behalf is not a mana route"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(wizard, 0)),
        "with the {{U}} floating the whole price is payable: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, apprentice_wizard(), 0);
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, wizard), "{{T}} was half the price");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Colorless),
        3,
        "{{C}}{{C}}{{C}} — no land on this board produces a colourless mana"
    );
    assert_eq!(
        pool.available(ManaColor::Blue),
        1,
        "one of the two blue paid the {{U}}, and the other is still floating"
    );
    assert_eq!(pool.total(), 4, "and nothing else came with it");
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "the seat holds priority again, got {:?}",
        engine.pending()
    );
}

fn armor_thrull() -> CardIndex {
    card_index("35453c9e-e1ae-4fe9-926d-75724deb0555")
}

/// Armor Thrull — {2}{B} 1/3: "{T}, Sacrifice this creature: Put a +1/+2
/// counter on target creature."
///
/// The counter is +1/+2 and not +1/+1, so the target's body after the
/// activation is the whole card: `(1, 1)` would mean nothing was placed and
/// `(2, 2)` that the toughness half was read as power. "Target creature" is
/// the word that needs a witness on both sides of the table — an Elf across it
/// is a legal target and an Elf that was not named must stay a printed 1/1 —
/// and the sacrifice, being a cost (CR 601.2h), is read after the target
/// question is answered and before the counter ever lands.
#[test]
fn armor_thrull_sacrifices_itself_for_a_plus_one_plus_two_counter_on_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[armor_thrull()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");

    // {2}{B} off three Swamps; the Elves are named as the printing kept back,
    // so the board the counter lands on is the one that was dealt.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Swamps, and no creature tapped for mana"
    );
    cast_with_floating(&mut engine, p0, armor_thrull());
    pass_until(&mut engine, |e| {
        stack_is_empty(e) && on_battlefield(e, p0, armor_thrull()).is_some()
    });
    let thrull = on_battlefield(&engine, p0, armor_thrull()).expect("the Thrull resolved");
    assert_eq!(pt(&engine, thrull), (1, 3), "the body the card prints");
    assert_eq!(
        pt(&engine, mine),
        (1, 1),
        "a printed 1/1 before anything is placed"
    );

    // CR 302.6: a creature that arrived this turn cannot pay a `{T}`, so
    // the turn goes round once before the line is pressed. Both halves are
    // needed — `walk_to_own_main` on its own returns where it stands,
    // because this already *is* p0's own main phase.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    activate(&mut engine, p0, armor_thrull(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that chooses");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    // CR 601.2c names the target before CR 601.2h pays, so the Thrull is still
    // standing while this question is open — the sacrifice is a cost, not a
    // rider on the effect.
    assert!(
        on_battlefield(&engine, p0, armor_thrull()).is_some(),
        "the cost is paid after the target, not before it"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the Elf was one of the options it enumerated");

    assert!(
        on_battlefield(&engine, p0, armor_thrull()).is_none(),
        "sacrificing itself is half of the price the card prints"
    );
    assert!(
        in_graveyard(&engine, p0, armor_thrull()).is_some(),
        "and a sacrificed creature goes to its owner's graveyard"
    );
    assert!(
        !stack_is_empty(&engine),
        "placing a counter is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, mine),
        (2, 3),
        "+1/+2 on the creature that was named — a (2, 2) would mean the \
         toughness half was read as power"
    );
    assert_eq!(
        counters_on(
            &engine,
            mine,
            CounterKind::Plus {
                power: 1,
                toughness: 2
            }
        ),
        1,
        "one counter, of the kind the card prints"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "the Elf the ability did not name never moved"
    );
}

// oracle_id = "8ebc4198-7317-4ffb-b8b8-14733c2077ff"
fn arms_dealer() -> CardIndex {
    card_index("8ebc4198-7317-4ffb-b8b8-14733c2077ff")
}

/// Arms Dealer — {2}{R}, a 1/1 Goblin Rogue: "{1}{R}, Sacrifice a Goblin:
/// This creature deals 4 damage to target creature."
///
/// Both halves of the price are the engine's answer rather than the card's,
/// so the board is built to read both. The sacrifice menu has to name the
/// Dealer itself (a Goblin Rogue *is* a Goblin) and the Goblin beside it, and
/// has to decline the Elf ("a Goblin" is read, not skipped) and the Goblin of
/// the same printing across the table (CR 701.21a: a seat sacrifices only what
/// it controls). The {1}{R} is read off the *pool*, which is why the line is
/// not offered at one mana and is there at two — and the four damage is read
/// off the board, where a printed 1/1 dies and the player beside it keeps
/// every point of life.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn arms_dealer_eats_a_goblin_and_deals_four_damage_to_a_creature() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, mountain())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                llanowar_elves(),
                festering_goblin(),
            ],
        )
        .battlefield(1, &[festering_goblin()])
        .hand(0, &[arms_dealer(), mountain()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let fodder = on_battlefield(&engine, p0, festering_goblin()).expect("my Goblin is out");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    let theirs = on_battlefield(&engine, p1, festering_goblin()).expect("their Goblin is out");

    // Three Mountains and the Elf are four mana and the Dealer costs three, so
    // one is left — one short of the {1}{R} the ability charges. That is the
    // price read where the engine reads it (`can_afford` looks at the pool and
    // not at the untapped lands), with the Goblin it would eat already there.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "three Mountains and the Elf's own {{G}}"
    );
    cast_with_floating(&mut engine, p0, arms_dealer());
    pass_until(&mut engine, stack_is_empty);
    let dealer = on_battlefield(&engine, p0, arms_dealer()).expect("the Dealer resolved");
    assert_eq!(pt(&engine, dealer), (1, 1), "a printed 1/1 Goblin Rogue");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{2}}{{R}} came out of the pool"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(dealer, 0)),
        "one mana is not {{1}}{{R}}: the line is not offered at all while a \
         Goblin to eat stands beside it: {:?}",
        legal.abilities
    );

    // The land drop is still open, so the missing mana is one land away — and
    // with it the whole cost, read off the pool again.
    play_land(&mut engine, p0, mountain());
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the Mountain just played, and {{1}}{{R}} is now payable"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(dealer, 0)),
        "with {{1}}{{R}} floating the whole price is payable: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, arms_dealer(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&theirs) && options.contains(&elf),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Goblin across the table was one of the options");

    // CR 601.2c picked the target and CR 601.2h pays afterwards, so the
    // creature is still on the battlefield and the mana still in the pool
    // while the cost question is open.
    assert!(
        on_battlefield(&engine, p0, festering_goblin()).is_some(),
        "the cost is paid after the target, not before it"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "and the {{1}}{{R}} is still floating"
    );

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the sacrifice asks which Goblin, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one Goblin, no more and no fewer");
    assert!(
        options.contains(&dealer),
        "the Dealer is a Goblin Rogue, so it is on its own menu: {options:?}"
    );
    assert!(
        options.contains(&fodder),
        "and so is the Goblin beside it: {options:?}"
    );
    assert!(
        !options.contains(&elf),
        "an Elf is no Goblin: \"a Goblin\" is read, not skipped: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "CR 701.21a: an opponent's Goblin is not yours to sacrifice: {options:?}"
    );
    assert_eq!(options.len(), 2, "and those two are the whole menu");

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the Goblin the question offered pays the cost");

    // The sacrificed Goblin's own dies trigger goes on the stack above the
    // ability (CR 603.3b) and asks for a target of its own; it is aimed at the
    // Elf so that nothing but the four damage can account for the Goblin
    // across the table.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the controller of the dead Goblin chooses");
    assert!(
        options.contains(&elf),
        "any creature is a target for `-1/-1`: {options:?}"
    );
    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options it enumerated");

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{R}} came out of the pool"
    );
    assert!(
        on_battlefield(&engine, p0, arms_dealer()).is_some(),
        "the Dealer paid with a Goblin and not with itself"
    );
    assert!(
        in_graveyard(&engine, p0, festering_goblin()).is_some(),
        "the Goblin it ate is in its owner's graveyard, not merely gone"
    );
    assert!(
        on_battlefield(&engine, p1, festering_goblin()).is_none(),
        "four damage on a printed 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        in_graveyard(&engine, p1, festering_goblin()).is_some(),
        "and the card is in the graveyard of the seat that owned it"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "\"target creature\": the damage went to the creature and never to the player"
    );
}

fn utopia_tree() -> CardIndex {
    card_index("73a9122c-60d2-4fdc-bc7b-3576bcbca241")
}

/// Utopia Tree — {1}{G} — is a 0/2 Plant creature whose entire text
/// is "{T}: Add one mana of any color." The board holds the tree and nothing
/// else that could make mana, and before activation no mana is floating:
/// the pool is read empty, so the one mana afterwards can only come from
/// the tree's own tap, and black in the mana of a green creature is exactly
/// the "any color" that the card prints, rather than its color identity.
/// The question is five colors wide and without colorless (CR 105.4),
/// the mana lands on an empty stack (CR 605.3b), and what paid the cost is
/// the tapped tree itself.
#[test]
fn utopia_tree_taps_for_one_mana_of_the_color_its_controller_names() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[utopia_tree()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let tree = on_battlefield(&engine, p0, utopia_tree()).expect("the Tree is on the table");
    assert_eq!(pt(&engine, tree), (0, 2), "the printed 0/2 body");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats, and no other permanent on this board can make mana"
    );

    // Ability 0 is the printed `{T}: Add one mana of any color.` — a printed
    // mana ability has an index and therefore lies in `abilities`, not in the
    // CR-305.6 shorthand.
    activate(&mut engine, p0, utopia_tree(), 0);
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!("`any color` is a question, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat that tapped it names the color");
    assert_eq!(
        options.len(),
        5,
        "the five colors of the game, and colorless is no color at all \
         (CR 105.4): {options:?}"
    );
    for color in [
        ManaColor::White,
        ManaColor::Blue,
        ManaColor::Black,
        ManaColor::Red,
        ManaColor::Green,
    ] {
        assert!(
            options.contains(&color),
            "\"any color\" includes {color:?}: {options:?}"
        );
    }

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Black))
        .expect("black was one of the colors it offered");
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        1,
        "the color that was named, and not a default"
    );
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "and not the one the card is printed in"
    );
    assert_eq!(pool.total(), 1, "one mana, off one tap");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, tree), "the Tree paid its own {{T}}");

    // The other half of "its whole price is its own tap symbol":
    // for this turn, the line is no longer one that the seat may take.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds priority again, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(tree, 0)),
        "a tapped Tree has no {{T}} left to pay with: {:?}",
        legal.abilities
    );
}

fn vedalken_mastermind() -> CardIndex {
    card_index("1ba85537-6dc2-459e-8850-619b41c0a881")
}

/// Vedalken Mastermind — {U}{U} Creature — Vedalken Wizard, 1/2:
/// "{U}, {T}: Return target permanent you control to its owner's hand."
///
/// "You control" is the whole card, so the *same* artifact stands under each
/// seat — a Sol Ring a side — and a menu that names one and declines the other
/// is what reads the filter rather than `Filter::Any`; the Mastermind itself is
/// on that menu too, because it too is a permanent you control. The {U} is read
/// as a real price in both directions: with an empty pool the line is absent
/// from the offer rather than refused (`can_afford` reads the pool and never the
/// untapped lands), and the pool is one shorter only once the target has been
/// answered — CR 601.2c before CR 601.2h, so while the question stands the
/// Mastermind is still untapped and the mana still floating.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn vedalken_mastermind_bounces_a_permanent_you_control_and_declines_the_opponents() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    // The Mastermind is seated rather than cast: its price is `{U}` *and* `{T}`,
    // and a creature that arrived this turn may not pay the tap symbol at all
    // (CR 302.6). A `SeatSpec` placement is the same permanent a cast a turn
    // earlier would have left, and nothing about the cast is what this reads.
    let mut engine = Duel::new(SEED, island())
        .battlefield(
            0,
            &[
                island(),
                island(),
                island(),
                quiet_artifact(),
                vedalken_mastermind(),
            ],
        )
        .battlefield(1, &[quiet_artifact()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches their own main phase"
    );

    let mastermind =
        on_battlefield(&engine, p0, vedalken_mastermind()).expect("the Mastermind is out");
    let mine = on_battlefield(&engine, p0, quiet_artifact()).expect("my Sol Ring is out");
    let theirs = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    assert_eq!(pt(&engine, mastermind), (1, 2), "the body the card prints");

    // An empty pool pays no {U}, and the whole price is the mana plus a tap
    // nobody has spent — so the line is missing from the offer for the mana
    // alone, which is the control the mana below is measured against.
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Mastermind holds it");
    assert!(
        !legal.abilities.contains(&(mastermind, 0)),
        "with nothing floating the {{U}} cannot be paid, and an unpayable cost \
         is absent from the offer rather than refused: {:?}",
        legal.abilities
    );

    // Three Islands into the pool and the Sol Ring named as the thing kept
    // back: it is one of the permanents the bounce is about to choose between,
    // and a source tapped for mana has already changed for a reason of its own.
    tap_all_mana_but(&mut engine, p0, Some(quiet_artifact()));
    let floating = engine.state().players[0].mana_pool.total();
    assert_eq!(floating, 3, "three Islands, and the Sol Ring kept back");
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(mastermind, 0)),
        "with the {{U}} floating, the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, vedalken_mastermind(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target permanent you control\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat chooses");
    assert_eq!((min, max), (1, 1), "exactly one permanent");
    assert!(
        options.contains(&mine),
        "the Sol Ring beside it is a permanent this seat controls: {options:?}"
    );
    assert!(
        options.contains(&mastermind),
        "and so is the Mastermind itself — \"you control\" names no other \
         creature: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "\"you control\" is not \"any permanent\": the identical Sol Ring \
         across the table is not this seat's: {options:?}"
    );
    assert_eq!(
        options.len(),
        5,
        "the three Islands, the Sol Ring and the Mastermind — everything this \
         seat has and nothing else: {options:?}"
    );
    assert!(
        !is_tapped(&engine, mastermind),
        "CR 601.2c before CR 601.2h: the tap is not paid while the question stands"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        floating,
        "and neither is the {{U}}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the permanent the question offered was chosen");
    assert!(
        is_tapped(&engine, mastermind),
        "{{T}} is half the price and is paid as the activation completes"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        floating - 1,
        "and the {{U}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "returning a permanent is no mana ability, so it is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_none(),
        "the targeted permanent left the battlefield"
    );
    assert!(
        in_hand(&engine, p0, quiet_artifact()).is_some(),
        "\"to its owner's hand\": the Sol Ring is back in the hand of the seat \
         that owns it"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the permanent the ability did not name never moved"
    );
    assert!(
        on_battlefield(&engine, p0, vedalken_mastermind()).is_some(),
        "an activated ability costs the creature nothing but its tap"
    );
}

fn veteran_cavalier() -> CardIndex {
    card_index("2d02cfce-a142-4b3b-a01f-4e156e75164e")
}

/// Veteran Cavalier costs {W}{W}, arrives as a 2/2 Human Knight, and its
/// entire printed text is `Vigilance`: "Attacking doesn't cause this
/// creature to tap" (CR 702.20). That is only readable in combat — the
/// creature is still standing after the attack declaration, and next to it
/// stands a Llanowar Elves without the keyword, which the very same attack
/// does tap. That the combat damage arrives at the opponent (two plus one)
/// proves that the combat step really took place and not merely a board
/// that missed it.
#[test]
fn veteran_cavalier_attacks_without_tapping_while_the_elf_beside_it_does() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(4411, forest())
        .battlefield(0, &[plains(), plains(), llanowar_elves()])
        .hand(0, &[veteran_cavalier()])
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {W}{W} from the two Plains, and the Elf explicitly remains standing:
    // it is the control in combat below, and a creature tapped for mana
    // may not attack anymore.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Plains, and two white mana"
    );
    cast_with_floating(&mut engine, p0, veteran_cavalier());
    pass_until(&mut engine, stack_is_empty);
    let cavalier =
        on_battlefield(&engine, p0, veteran_cavalier()).expect("der Cavalier ist gelandet");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("der Elf steht noch");
    assert_eq!(pt(&engine, cavalier), (2, 2), "der gedruckte Körper");
    assert!(
        keywords(&engine, cavalier).contains(KeywordSet::VIGILANCE),
        "das gedruckte Keyword erreicht das Permanent"
    );

    // One turn later: if cast this turn, the Cavalier would still be
    // summoning sick in its own combat step (CR 302.6).
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, cavalier) && !is_tapped(&engine, elves),
        "der Enttappschritt hat beide aufgestellt"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player, attackers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until hält nur bei der Angriffserklärung an")
    };
    assert_eq!(player, p0, "the active player declares their attackers");
    assert!(
        attackers.contains(&cavalier) && attackers.contains(&elves),
        "both are untapped and not summoning sick: {attackers:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (cavalier, Defender::Player(p1)),
                    (elves, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    assert!(
        !is_tapped(&engine, cavalier),
        "Vigilance: the attack did not tap the Cavalier"
    );
    assert!(
        is_tapped(&engine, elves),
        "und der Elf daneben, ohne das Keyword, ist für seinen Angriff \
         getappt — ohne ihn läse der Test oben nur ein Brett, auf dem gar \
         nichts angreift"
    );

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        17,
        "zwei Schaden vom Cavalier und einer vom Elf: der Angriff ist wirklich \
         durchgekommen"
    );
}

fn vine_trellis() -> CardIndex {
    card_index("57de8fe7-3d1b-41cd-8354-38aff3d2d052")
}

/// Vine Trellis — {1}{G}, a 0/4 Plant Wall with "Defender" and
/// "{T}: Add {G}". Both printed lines are the test, and both need a control:
/// the untapped Llanowar Elves next to it may attack, the Trellis may not —
/// an empty attack declaration would also be fulfilled by a combat step that
/// never took place. It only becomes tapped on the next own turn, because a
/// creature that has only just arrived does not even offer its {T}
/// (CR 302.6); there the pool is empty, which makes "exactly one green" the
/// exact statement. That the ability stands in `legal.abilities` and not in
/// the CR-305.6 shorthand is the difference between a printed `{T}: Add {G}`
/// and a basic land type.
#[test]
fn vine_trellis_defends_and_taps_for_green_on_a_later_turn() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), llanowar_elves()])
        .hand(0, &[vine_trellis()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 erreicht seinen Main");

    // The Elf is exempted: `tap_all_mana` would have tapped its own
    // `{T}: Add {G}` along with it and thereby removed it from combat (#159).
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Forests, and the Elves paid nothing extra"
    );
    cast_with_floating(&mut engine, p0, vine_trellis());
    pass_until(&mut engine, stack_is_empty);

    let trellis = on_battlefield(&engine, p0, vine_trellis()).expect("die Trellis ist angekommen");
    assert_eq!(pt(&engine, trellis), (0, 4), "der gedruckte 0/4-Körper");
    assert!(
        types(&engine, trellis).contains(TypeSet::CREATURE),
        "and it is the creature that it prints: {:?}",
        types(&engine, trellis)
    );
    assert!(
        keywords(&engine, trellis).contains(KeywordSet::DEFENDER),
        "Defender erreicht das Permanent über das Layer-System"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "das {{1}}{{G}} ist ausgegeben"
    );

    // Attack: the untapped Elf is in, the Wall is not.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until hält auf nichts außer der Angriffserklärung")
    };
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("der Elf steht noch");
    assert!(
        attackers.contains(&elves),
        "the control: an untapped 1/1 may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&trellis),
        "\"This creature can't attack\" — the 0/4 Wall is not in the offer: {attackers:?}"
    );

    // A full turn around: only then is the {T} of the creature payable.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "no mana carries over into the new turn (CR 500.5)"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected: priority, got: {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(trellis, 0)),
        "a printed `{{T}}: Add {{G}}` is an ability with an index and \
         therefore appears in `abilities`: {:?}",
        legal.abilities
    );
    assert!(
        !legal.mana_abilities.contains(&trellis),
        "and not in the CR 305.6 shortcut, which carries basic land types and \
         granted mana abilities and nothing else: {:?}",
        legal.mana_abilities
    );

    activate(&mut engine, p0, vine_trellis(), 0);
    assert!(is_tapped(&engine, trellis), "{{T}} wurde bezahlt");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability does not use the stack"
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Green), 1, "{{T}}: Add {{G}}");
    assert_eq!(pool.total(), 1, "ein Mana, und sonst nichts");
}

fn viridian_zealot() -> CardIndex {
    card_index("9410ae41-b6db-47c6-ae0a-4e33aad1d3ce")
}

/// Viridian Zealot — {G}{G} 2/1 Elf Warrior: "{1}{G}, Sacrifice this
/// creature: Destroy target artifact or enchantment."
///
/// Four Forests, all tapped before anything is claimed: the {G}{G} brings the
/// Zealot to the table and the two mana left floating are exactly the
/// `{1}{G}` its ability charges, which is read off the pool and not off the
/// untapped lands. The Sol Ring across the table is the artifact the printed
/// word names, and the Elf beside it is the control — a creature is neither
/// an artifact nor an enchantment, so an offer holding exactly the Ring is
/// what reads `Filter::ARTIFACT_OR_ENCHANTMENT` rather than `Filter::Any`.
/// Both halves of the price are read where CR 601.2h puts them: the Zealot is
/// still standing and both green are still floating while the target question
/// is open, and the sacrifice and the mana are gone the moment it is
/// answered.
#[test]
fn viridian_zealot_sacrifices_itself_to_destroy_an_artifact() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, forest())
        .battlefield(0, &[forest(), forest(), forest(), forest()])
        .hand(0, &[viridian_zealot()])
        .battlefield(1, &[quiet_artifact(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, viridian_zealot());
    pass_until(&mut engine, stack_is_empty);
    let zealot = on_battlefield(&engine, p0, viridian_zealot()).expect("the Zealot resolved");
    let their_ring = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    let their_elves = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    assert_eq!(pt(&engine, zealot), (2, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "four Forests less the {{G}}{{G}} the Zealot cost is exactly its {{1}}{{G}}"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(zealot, 0)),
        "with the {{1}}{{G}} already floating the whole price is payable, so \
         the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, viridian_zealot(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target artifact or enchantment\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&their_ring),
        "the artifact across the table is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&their_elves),
        "and the Elf beside it is a creature, which is neither an artifact \
         nor an enchantment: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p0, viridian_zealot()).is_some(),
        "targets are chosen before costs are paid (CR 601.2c, then \
         CR 601.2h), so the Zealot has not sacrificed itself yet"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "and the {{1}}{{G}} is still in the pool for the same reason"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![their_ring],
            },
        )
        .expect("the Ring was one of the options it enumerated");

    assert!(
        on_battlefield(&engine, p0, viridian_zealot()).is_none(),
        "\"Sacrifice this creature\" is the last step of the activation"
    );
    assert!(
        in_graveyard(&engine, p0, viridian_zealot()).is_some(),
        "and a sacrificed creature goes to its owner's graveyard"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{G}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "destroying is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_none(),
        "the artifact that was named left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p1, quiet_artifact()).is_some(),
        "and it is in its owner's graveyard, not under the seat that aimed it"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "the permanent the ability did not name never moved"
    );
}

fn wall_of_blossoms() -> CardIndex {
    card_index("ef4d5fb3-70a3-433d-a9d3-18b2beb8d79f")
}

/// Wall of Blossoms prints a {1}{G} 0/4 Plant Wall with "Defender" and "When
/// this creature enters, draw a card", and the board reads each printed fact
/// as a different question: two Forests pay the {1}{G}, the permanent arrives
/// as the printed 0/4 with the printed keyword still on it, and the library is
/// exactly one shorter once the enters-trigger has resolved. The hand of the
/// same size is the other half of that claim — the Wall left the hand and the
/// draw put a single card back, so a hand one card *shorter* would be the same
/// library count with no draw at all. The Wall is cast and never seated: a
/// `starting_battlefield` permanent never runs its printed entry ability, so a
/// test built that way would be asserting a trigger the engine was never asked
/// to fire.
#[test]
fn wall_of_blossoms_arrives_as_a_defending_wall_and_draws_for_coming_in() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[wall_of_blossoms()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Both halves of the claim are read across the cast: the library the entry
    // trigger draws from, and the hand the Wall is asked to leave.
    let library_before = library_size(&engine, p0);
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    // Two Forests, and nothing else on this board makes mana — the whole cost
    // is `{1}{G}` and the lands are the whole of what pays it.
    cast_from_hand(&mut engine, p0, wall_of_blossoms());
    pass_until(&mut engine, stack_is_empty);

    let wall = on_battlefield(&engine, p0, wall_of_blossoms()).expect("the Wall resolved");
    assert_eq!(
        pt(&engine, wall),
        (0, 4),
        "the body the card prints: power 0 and toughness 4"
    );
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "\"Defender\" reaches the battlefield object through the layers"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"When this creature enters, draw a card\": one card off the top of \
         the library, and none for anything else on the board"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before,
        "the Wall left the hand and the entry draw put one card back: a hand \
         of the same size is what one-for-one looks like, where a hand one \
         short would be the same library count with no draw at all"
    );
}

fn wall_of_earth() -> CardIndex {
    card_index("1e3e1916-bb82-481e-9b10-225504ef06b3")
}

/// Wall of Earth is {1}{R} for a 0/6 Wall whose entire printed text is
/// "Defender". Defender restricts *attacking* and nothing else (CR 702.3b),
/// so the scenario reads both halves of it on one board: a turn after the Wall
/// resolved — so CR 302.6 cannot be what leaves it out — it is missing from
/// the declare-attackers offer while an untapped, non-sick Llanowar Elves
/// under the same seat is on it; and when the Elf across the table attacks,
/// that same Wall *is* offered as a blocker. A keyword read as "can't attack
/// or block" would pass the first assertion and fail the second, so the
/// control creature and the block together are what make the absence mean
/// "Defender" rather than "sick" or "nobody can attack here".
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn wall_of_earth_cannot_attack_but_still_blocks() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), mountain(), llanowar_elves()])
        .hand(0, &[wall_of_earth()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{R} out of the two Mountains, with the Elf named as the printing kept
    // back: it is the untapped, non-sick creature the attack declaration is
    // read against, and a creature tapped for mana may not attack at all.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Mountains, and the Elf still standing"
    );
    cast_with_floating(&mut engine, p0, wall_of_earth());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let wall = on_battlefield(&engine, p0, wall_of_earth()).expect("the Wall resolved");
    assert_eq!(pt(&engine, wall), (0, 6), "the body the card prints");
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "and the one keyword it prints"
    );

    // p1's turn: the Elf across the table attacks, and the Wall may block it.
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::ChooseAttackers { player, .. } if *player == p1),
    );
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(theirs, Defender::Player(p0))],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until only stops on the declare-blockers step")
    };
    assert_eq!(player, p0, "the seat being attacked declares the blockers");
    let pair = blockers
        .iter()
        .find(|option| option.blocker == wall)
        .expect("the Wall may block — Defender restricts attacking and nothing else");
    assert!(
        pair.attackers.contains(&theirs),
        "and it may block the attacking Elf: {:?}",
        pair.attackers
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareBlockers {
                blockers: vec![(wall, theirs)],
            },
        )
        .unwrap();

    // Onto p0's next turn. Walked by hand rather than with `pass_until`
    // because the cleanup step of the turn in between asks a seat to discard
    // down to seven cards, and that question has no arm in the shared walker.
    let mut arrival = false;
    for _ in 0..200 {
        match engine.pending().clone() {
            Pending::ChooseAttackers { player, .. } if player == p0 => {
                arrival = true;
                break;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::DiscardChoice { player, count } => {
                let hand = engine
                    .state()
                    .zones
                    .list(ZoneLocation::Hand(player))
                    .clone();
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: hand.into_iter().take(usize::from(count)).collect(),
                        },
                    )
                    .unwrap();
            }
            other => panic!("unexpected on the way to p0's next attack step: {other:?}"),
        }
    }
    assert!(arrival, "p0 takes another turn");

    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is still out");
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("the loop only leaves on the attack declaration")
    };
    assert!(
        attackers.contains(&elves),
        "an untapped Elf past summoning sickness may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&wall),
        "while the Wall, out since a turn ago, may not — that is \"Defender\" \
         (CR 702.3b) and not summoning sickness: {attackers:?}"
    );
    engine
        .apply(p0, PlayerAction::DeclareAttackers { attackers: vec![] })
        .unwrap();
    assert!(
        on_battlefield(&engine, p0, wall_of_earth()).is_some(),
        "and the 0/6 that blocked a 1/1 a turn earlier is still on the battlefield"
    );
}

fn wall_of_kelp() -> CardIndex {
    card_index("64722c32-975b-43b9-9b4a-9511c75740d9")
}

/// Wall of Kelp prints two lines: "Defender" on a 0/3 Plant Wall and
/// "{U}{U}, {T}: Create a 0/1 blue Plant Wall creature token with defender
/// named Kelp."
///
/// Both halves are played: the creature is cast for {U}{U} and
/// stands there as a 0/3 with projected Defender, and its ability — which in
/// its arrival turn fails at CR 302.6, because its cost is its own {T}
/// — is paid in the next own main phase for {U}{U} from the pool.
/// Tapped Wall, empty pool, and the resolved Kelp token are the cost
/// and the effect; the token is read via the projected characteristics
/// (0/1, creature, Defender) and via the token entry itself (name "Kelp",
/// blue), because neither of the two readings replaces the other.
#[test]
fn wall_of_kelp_taps_and_two_blue_for_a_kelp_token_with_defender() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), island()])
        .hand(0, &[wall_of_kelp()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, wall_of_kelp());
    pass_until(&mut engine, stack_is_empty);
    let wall = on_battlefield(&engine, p0, wall_of_kelp()).expect("the Wall resolved");
    assert_eq!(pt(&engine, wall), (0, 3), "the printed 0/3 body");
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "Defender is printed on the card and reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "four Islands pay {{U}}{{U}} for the Wall and leave exactly the \
         {{U}}{{U}} the ability charges still floating"
    );

    // A turn later — CR 302.6: a creature that arrived this turn
    // cannot activate an ability with the tap symbol in its cost,
    // and the Islands pay the next cost only again in
    // an own main phase from a fresh pool.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, wall),
        "der Enttappschritt hat sie aufgeweckt"
    );

    // First mana into the pool, then the claim: `tap_all_mana` taps any
    // ability whose entire cost is its own {T}, and the Wall is not one of
    // them — its cost is {U}{U} *and* the tap symbol (#159).
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Islands, and the Wall makes no mana"
    );
    activate(&mut engine, p0, wall_of_kelp(), 0);
    assert!(
        is_tapped(&engine, wall),
        "{{T}} ist die eine Hälfte des Preises (CR 601.2h)"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "{{U}}{{U}} is the other and came from the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "creating a token is not a mana ability, so it goes on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    let kelp = tokens_of(&engine, p0);
    assert_eq!(kelp.len(), 1, "eine Aktivierung, ein Kelp");
    let kelp = kelp[0];
    assert!(
        types(&engine, kelp).contains(TypeSet::CREATURE),
        "the Kelp is a creature"
    );
    assert_eq!(
        pt(&engine, kelp),
        (0, 1),
        "und hat den gedruckten 0/1-Körper"
    );
    assert!(
        keywords(&engine, kelp).contains(KeywordSet::DEFENDER),
        "\"with defender\" — the token cannot attack"
    );
    let printed = engine
        .state()
        .object(kelp)
        .and_then(|o| o.token)
        .expect("der Token weiß, welcher Token er ist");
    assert_eq!(printed.name, "Kelp", "der Token heißt Kelp");
    assert_eq!((printed.power, printed.toughness), (Some(0), Some(1)));
    assert!(
        printed.colors.contains(baylee_core::color::Color::Blue),
        "ein blauer Kelp"
    );
}

fn wall_of_mulch() -> CardIndex {
    card_index("afd2141f-1b0f-46b5-b1ac-aa28982d16c0")
}

/// Wall of Mulch prints two lines: "Defender" on a 0/4 Wall and
/// "`{G}`, Sacrifice a Wall: Draw a card."
///
/// The cost names no specific Wall, so the engine must ask, and
/// this question is half the card. Both halves of the filter need their
/// own bystander: the three Forests are permanent cards under this
/// control that are not Walls, and the Wall of Mulch on the other
/// side of the table is a Wall that this seat does not control — a
/// menu that allowed one of the two would still have offered something and
/// still passed. The Wall that the test itself brought into play is paid;
/// the drawn card is read as movement — library one shorter, hand one
/// longer — and not as a question posed.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn wall_of_mulch_eats_a_wall_you_control_for_a_card() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .battlefield(1, &[wall_of_mulch()])
        .hand(0, &[wall_of_mulch()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Three Forests in the pool: the {1}{G} for the Wall and the {G} that the
    // ability then requires. CR 500.5 empties a pool only at the end of a
    // step, and the whole scenario plays in this one main phase.
    cast_from_hand(&mut engine, p0, wall_of_mulch());
    pass_until(&mut engine, stack_is_empty);
    let wall = on_battlefield(&engine, p0, wall_of_mulch()).expect("the Wall resolved");
    let theirs = on_battlefield(&engine, p1, wall_of_mulch()).expect("their Wall is out");
    assert_eq!(pt(&engine, wall), (0, 4), "the printed 0/4 body");
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "and the printed defender reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{1}}{{G}} is spent and the ability's {{G}} is still floating"
    );

    let library_before = library_size(&engine, p0);
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(wall, 0)),
        "the one line the card prints is offered now that its {{G}} is in the \
         pool: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, wall_of_mulch(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the sacrifice is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell them apart"
    );
    assert_eq!((min, max), (1, 1), "one Wall, no more and no fewer");
    assert!(
        options.contains(&wall),
        "the Wall this seat cast is a Wall it controls, so it is on its own \
         menu: {options:?}"
    );
    assert_eq!(
        options.len(),
        1,
        "and nothing else is: the Forests are no Walls, and the Wall across \
         the table is not this seat's to give up: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: a Wall an opponent controls is not yours to sacrifice: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p0, wall_of_mulch()).is_some(),
        "nothing is gone while the question still stands"
    );

    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, wall_of_mulch()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![wall],
            },
        )
        .expect("the Wall the question offered pays the cost");
    assert!(
        !stack_is_empty(&engine),
        "drawing a card is no mana ability, so the ability is on the stack"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{G}} went with it"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, wall_of_mulch()).is_none(),
        "the sacrificed Wall left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p0, wall_of_mulch()).is_some(),
        "and a sacrificed permanent goes to its owner's graveyard"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"Draw a card\" — one off the top of the library"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before + 1,
        "and it is in hand, so a library that emptied would not satisfy the \
         count above"
    );
    assert!(
        on_battlefield(&engine, p1, wall_of_mulch()).is_some(),
        "the Wall across the table never moved"
    );
}

fn wall_of_razors() -> CardIndex {
    card_index("19ed5429-5631-4a36-a69c-ab35860160b6")
}

/// Wall of Razors is `{1}{R}` for a 4/1 with Defender and First Strike —
/// two printed keywords that pull in opposite directions
/// and both must be read on the permanent. The scenario casts it from
/// two Mountains and reads body and both keywords on the battlefield,
/// and then goes to the attacker declaration: the Llanowar Elf next to it is
/// untapped and is offered, so an offer without the 4/1 is the
/// Defender line and not a combat step that never came.
#[test]
fn wall_of_razors_lands_as_a_four_one_with_defender_and_first_strike_and_never_attacks() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), mountain(), llanowar_elves()])
        .hand(0, &[wall_of_razors()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert!(!is_tapped(&engine, elves), "and untapped, so it may attack");

    // {1}{R} from the two Mountains, with the Elf as a held-back
    // printing: it is the control against which the attacker
    // declaration below is read, and a creature tapped for mana no
    // longer attacks.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Mountains and no Elf: two red mana for the {{1}}{{R}}"
    );
    cast_with_floating(&mut engine, p0, wall_of_razors());
    pass_until(&mut engine, stack_is_empty);

    let wall = on_battlefield(&engine, p0, wall_of_razors()).expect("die Wall ist gelandet");
    assert_eq!(pt(&engine, wall), (4, 1), "der gedruckte Körper");
    let granted = keywords(&engine, wall);
    assert!(granted.contains(KeywordSet::DEFENDER), "Defender");
    assert!(
        granted.contains(KeywordSet::FIRST_STRIKE),
        "First strike, aus demselben projizierten Satz"
    );

    // The gap that the Defender line opens, and its control in the same
    // offer: the engine counts the Elf and not the Wall.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until hält nur bei der Angreifer-Erklärung")
    };
    assert!(
        attackers.contains(&elves),
        "an untapped 1/1 without its own text may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&wall),
        "the 4/1 may not: its first strike is printed, and so is the defender \
         that keeps it out of every attack declaration: {attackers:?}"
    );
}

fn waterfront_bouncer() -> CardIndex {
    card_index("b53a8cde-494c-43d0-8d08-7bdfe2e84064")
}

/// Waterfront Bouncer — {1}{U}, 1/1 Merfolk Spellshaper: "{U}, {T}, Discard a
/// card: Return target creature to its owner's hand."
///
/// The price is three separate things and each one leaves a mark somewhere a
/// test can read it: the blue out of a pool the three Islands actually
/// filled, the {T} on the 1/1 itself, and the discarded card in its owner's
/// graveyard. The order is the rules': the target is named at CR 601.2c and
/// everything is paid at CR 601.2h, so while the target question stands the
/// Bouncer is untapped and the blue is still floating — asserted rather than
/// assumed, because a cost paid on announcement would satisfy every count
/// below just as well. The target is the opponent's Elf, which is what makes
/// "to its *owner's* hand" a claim about which hand it lands in and not only
/// about it leaving the battlefield.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn waterfront_bouncer_pitches_a_card_to_bounce_a_creature_to_its_owners_hand() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), waterfront_bouncer()])
        .hand(0, &[counterspell()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let bouncer = on_battlefield(&engine, p0, waterfront_bouncer()).expect("the Bouncer is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let pitched = in_hand(&engine, p0, counterspell()).expect("a card to pitch is in hand");

    // Mana before the claim: `can_afford` reads the pool and never the
    // untapped Islands, so the offer is only worth reading once the three are
    // floating.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Islands, and the Bouncer makes no mana of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(bouncer, 0)),
        "with the {{U}} floating, the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, waterfront_bouncer(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "`target creature` is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&theirs),
        "\"target creature\" reaches across the table: {options:?}"
    );
    assert!(
        options.contains(&bouncer),
        "and it is any creature, its own source included — the card does not \
         say \"another\": {options:?}"
    );
    assert!(
        !is_tapped(&engine, bouncer),
        "CR 601.2c names the target before CR 601.2h pays for it, so the \
         {{T}} has not happened while the question stands"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "and neither has the {{U}}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Elf was one of the options it enumerated");

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "`Discard a card` is a cost and is asked once a target exists, \
             got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat pays its own price");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostDiscard,
        "a cost and not a cleanup discard, which is all a client has to tell \
         the two apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert!(
        options.contains(&pitched),
        "the card named in hand is on the menu: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![pitched],
            },
        )
        .expect("the card the question offered pays the cost");

    assert!(
        is_tapped(&engine, bouncer),
        "{{T}} is the second part of the price"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "and the {{U}} came out of the pool"
    );
    assert!(
        in_graveyard(&engine, p0, counterspell()).is_some(),
        "the discarded card is in its owner's graveyard"
    );
    assert!(
        !stack_is_empty(&engine),
        "returning a creature is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_none(),
        "the targeted creature left the battlefield"
    );
    assert!(
        in_hand(&engine, p1, llanowar_elves()).is_some(),
        "\"to its owner's hand\" — the Elf goes back to the seat that owns it"
    );
    assert!(
        in_hand(&engine, p0, llanowar_elves()).is_none(),
        "and not to the seat that aimed the bounce"
    );
    assert!(
        on_battlefield(&engine, p0, waterfront_bouncer()).is_some(),
        "and the Bouncer spent its tap and a card, never itself"
    );
}

fn wei_ambush_force() -> CardIndex {
    card_index("2d1446f4-cf71-4798-b921-8f6824350319")
}

/// Wei Ambush Force is a printed 1/1 for `{1}{B}` whose entire text is
/// "Whenever this creature attacks, it gets +2/+0 until end of turn." The
/// card *is* the gap between the body standing on the battlefield and the
/// body after the attack declaration, so the same permanent is read three
/// times: a printed `(1, 1)` before it has ever attacked, `(3, 1)` once it
/// has been declared an attacker and its trigger has resolved, and `(1, 1)`
/// again on the following turn — the last reading being the only thing
/// "until end of turn" can mean, since a permanent pump would still be a
/// 3/1 there. Nothing grants it haste, so the attack the trigger is about is
/// only legal after a whole turn cycle (CR 302.6).
#[test]
fn wei_ambush_force_pumps_itself_for_attacking_and_only_until_end_of_turn() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp()])
        .hand(0, &[wei_ambush_force()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, wei_ambush_force());
    pass_until(&mut engine, stack_is_empty);
    let soldier = on_battlefield(&engine, p0, wei_ambush_force()).expect("the Soldier resolved");
    assert_eq!(
        pt(&engine, soldier),
        (1, 1),
        "the printed body, on a creature that has not attacked"
    );

    // A whole turn cycle: nothing gives it haste, so the declaration below is
    // the first one that may legally name the creature (CR 302.6).
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&soldier),
        "an untapped 1/1 past summoning sickness may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(soldier, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, soldier),
        (3, 1),
        "\"Whenever this creature attacks, it gets +2/+0\""
    );

    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        pt(&engine, soldier),
        (1, 1),
        "and the printed duration is \"until end of turn\": the next turn's \
         main phase is past the cleanup step that ends it (CR 514.2)"
    );
}

fn willow_faerie() -> CardIndex {
    card_index("5390bb44-985e-473b-883e-c9562c06f210")
}

/// Willow Faerie is a `{1}{G}` 1/2 whose entire printed text is Flying, so a
/// game can only show the card by casting it and then swinging with it: the
/// keyword has no trigger and no cost that a state read could catch. Two
/// Forests are exactly the `{1}` and the `{G}`, and the offer is read while
/// that mana is already floating, because `can_afford` reads the pool and not
/// the untapped lands. A turn later the Faerie attacks over the untapped
/// Llanowar Elves standing across the table and takes a life off a player
/// whose only creature is on the ground — an evasive body the test actually
/// turned sideways, with a real blocker present so the damage is not proven
/// by an empty board.
#[test]
fn willow_faerie_lands_as_a_flying_one_two_and_attacks_over_the_ground() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .battlefield(1, &[quiet_creature()])
        .hand(0, &[willow_faerie()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Forests, two green, and no creature beside them that could have paid"
    );
    let card = in_hand(&engine, p0, willow_faerie()).expect("the Faerie is in hand");
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.castable.contains(&card),
        "{{1}}{{G}} is affordable off the two Forests: {:?}",
        legal.castable
    );
    cast_with_floating(&mut engine, p0, willow_faerie());
    pass_until(&mut engine, stack_is_empty);

    let faerie = on_battlefield(&engine, p0, willow_faerie()).expect("the Faerie resolved");
    assert_eq!(pt(&engine, faerie), (1, 2), "the printed 1/2 body");
    assert!(
        keywords(&engine, faerie).contains(KeywordSet::FLYING),
        "and `Flying`, read through the layers rather than off the card file"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{1}}{{G}} came out of the pool the two Forests filled"
    );

    // A whole turn cycle, so the Faerie is no longer summoning sick (CR 302.6).
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on the attack declaration")
    };
    assert!(
        attackers.contains(&faerie),
        "an untapped creature that has been on the table since last turn may \
         attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(faerie, Defender::Player(p1))],
            },
        )
        .unwrap();

    // Past the combat damage step (CR 510.2): the Elf across the table is a
    // ground creature and no blocker for a flyer, so it is the control that
    // keeps this from being an attack into nothing.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "one power of flying damage got through the Llanowar Elves"
    );
    assert_eq!(
        pt(&engine, faerie),
        (1, 2),
        "and the attacker is untouched, because nothing was able to block it"
    );
}

fn wind_dancer() -> CardIndex {
    card_index("e9903d75-f71d-45d0-ac5f-955c0c227e02")
}

/// Wind Dancer — {1}{U} 1/1 Faerie, printed with flying — says "{T}: Target
/// creature gains flying until end of turn." The grant is a keyword and no
/// body, so the only reading worth playing is the one that tells the creature
/// the ability *named* from every other creature on the table: a second Elf
/// under the same seat and an Elf across it must both stay grounded, and the
/// target's `0/0` has to leave its printed 1/1 exactly as it was. The whole
/// price is the Dancer's own `{T}` — the pool is empty before the activation
/// and still empty after it — which is what says the flying cost no mana.
#[test]
fn wind_dancer_grants_flying_to_the_creature_it_names_and_no_other() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[wind_dancer(), llanowar_elves(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let elves = all_on_battlefield(&engine, p0, llanowar_elves());
    assert_eq!(
        elves.len(),
        2,
        "two Elves, one of which stays on the ground"
    );
    let (host, bystander) = (elves[0], elves[1]);
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    let dancer = on_battlefield(&engine, p0, wind_dancer()).expect("the Dancer is out");
    assert!(
        keywords(&engine, dancer).contains(KeywordSet::FLYING),
        "the Dancer carries the flying its own card prints"
    );
    assert!(
        !keywords(&engine, host).contains(KeywordSet::FLYING),
        "nothing has been granted yet"
    );
    assert_eq!(pt(&engine, host), (1, 1), "a printed 1/1 before the grant");

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(dancer, 0)),
        "the one line the Dancer prints is paid by its own {{T}} and no mana, \
         so it is offered out of a bare board: {:?}",
        legal.abilities
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and nothing had to be floated for it — the pool is empty"
    );

    activate(&mut engine, p0, wind_dancer(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&host) && options.contains(&bystander),
        "both creatures under this seat are on the menu: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    assert!(
        options.contains(&dancer),
        "and the Dancer is a creature too, so it may name itself: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![host],
            },
        )
        .expect("the Elf the question offered was chosen");
    assert!(
        is_tapped(&engine, dancer),
        "CR 601.2h: the {{T}} is the last step of the activation, paid after \
         the target was named"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        keywords(&engine, host).contains(KeywordSet::FLYING),
        "the named creature gained flying until end of turn"
    );
    assert!(
        !keywords(&engine, bystander).contains(KeywordSet::FLYING),
        "the Elf nobody named is untouched"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::FLYING),
        "and nothing crossed the table"
    );
    assert_eq!(
        pt(&engine, host),
        (1, 1),
        "the grant is the keyword and no body: +0/+0 leaves the printed 1/1"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the whole price was the tap symbol and nothing else was spent"
    );
}

// oracle_id = "24e96682-14ca-4a62-a920-2d686c8a5dbf"
fn winged_sliver() -> CardIndex {
    card_index("24e96682-14ca-4a62-a920-2d686c8a5dbf")
}

/// Winged Sliver prints a single static line: "{1}{U} — 1/1 — All
/// Sliver creatures have flying." Two things are testable about this and each
/// needs its own witness: that the ability reaches the Sliver *itself*,
/// even though it comes from its own text, and that it only reaches
/// Slivers. The Elf under the same control and the Elf across the
/// table are therefore both there — a filter that had lost
/// `HasSubtype(SLIVER)` and would let every creature fly would be
/// immediately visible on both, and a filter that silently reads only
/// its own side, on the second. Payment is made with two Islands,
/// so that the Elf on which it is read does not have to be tapped
/// for its own mana.
#[test]
fn winged_sliver_grants_flying_to_slivers_and_to_no_other_creature() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[winged_sliver()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::FLYING),
        "no Sliver is on the table, so there is nothing to grant"
    );

    // The two Islands pay {1}{U}; the Elf is left named,
    // because it is the witness on which the subtype filter is read.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands in the mana pool and the Elf explicitly not among them"
    );
    cast_with_floating(&mut engine, p0, winged_sliver());
    pass_until(&mut engine, stack_is_empty);

    let sliver = on_battlefield(&engine, p0, winged_sliver()).expect("der Sliver ist angekommen");
    assert_eq!(pt(&engine, sliver), (1, 1), "der gedruckte 1/1-Körper");
    assert!(
        keywords(&engine, sliver).contains(KeywordSet::FLYING),
        "\"All Sliver creatures have flying\" — der Sliver ist einer davon, \
         also erreicht seine eigene Statik ihn selbst"
    );
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::FLYING),
        "a creature without the subtype gets nothing, no matter which \
         side it is on"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::FLYING),
        "and the static reaches no further across the table: the filter is the \
         subtype and not the battlefield"
    );
}

fn wirewood_elf() -> CardIndex {
    card_index("4aab6794-506f-413c-91e0-d886e0019dce")
}

/// Wirewood Elf is `{1}{G}` for a 1/2 Elf Druid whose entire printed
/// text line is `{T}: Add {G}` — both halves need the game, neither
/// of them is in the card def. The turn change before it is the cost
/// of the second: a creature that arrived this turn has summoning
/// sickness (CR 302.6), so its mana ability is not even offered on the
/// turn it arrives, although it stands untapped — and only after p0's
/// next untap step is the `{T}` something it may pay. Before that,
/// **nothing** is tapped: the whole cost is its own tap symbol, the
/// empty pool makes "exactly one green mana" a statement about the
/// Elf and not about the two Forests that remain untapped next to it.
#[test]
fn wirewood_elf_arrives_as_a_one_two_and_taps_for_one_green() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest()])
        .hand(0, &[wirewood_elf()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{G} off the two Forests, which is the only thing on the board that
    // can pay for it.
    cast_from_hand(&mut engine, p0, wirewood_elf());
    pass_until(&mut engine, stack_is_empty);
    let elf = on_battlefield(&engine, p0, wirewood_elf()).expect("the Elf resolved");
    assert_eq!(pt(&engine, elf), (1, 2), "the printed 1/2 body");
    assert!(
        types(&engine, elf).contains(TypeSet::CREATURE),
        "and it is the creature the card prints: {:?}",
        types(&engine, elf)
    );
    assert!(!is_tapped(&engine, elf), "nothing has tapped it");

    // The control on the turn change below: the same untapped creature, the
    // same empty pool, and the line is still not there, because a `{T}` may
    // not be paid by a permanent that has not been under its controller's
    // control since their most recent turn began (CR 302.6).
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        !legal.abilities.contains(&(elf, 0)),
        "untapped and yet not on offer: the Elf arrived this turn \
         (CR 302.6): {:?}",
        legal.abilities
    );

    // Through the opponent's turn and back.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 takes another turn and reaches its own main"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "a pool empties when a step or phase ends (CR 500.5), so anything in \
         it from here on has to be accounted for"
    );
    let forests = all_on_battlefield(&engine, p0, forest());
    assert_eq!(forests.len(), 2, "both Forests are still standing");
    assert!(
        forests.iter().all(|id| !is_tapped(&engine, *id)),
        "and untapped, so the green below has no other source on this board"
    );

    // The whole price is its own `{T}`, so the line is offered with nothing
    // floating — `can_afford` reads the *pool*, and an empty pool pays a tap.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        legal.abilities.contains(&(elf, 0)),
        "a printed mana ability has an index to name, so it is an ordinary \
         `(source, index)` entry in `abilities`: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, wirewood_elf(), 0);
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        1,
        "the one color the card names, and not a default"
    );
    assert_eq!(
        pool.total(),
        1,
        "one mana, off one tap, and nothing beside it"
    );
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, elf), "the Elf paid its own {{T}}");
    assert!(
        forests.iter().all(|id| !is_tapped(&engine, *id)),
        "and neither Forest moved, so the green mana is the Elf's own"
    );

    // The other half of "its whole price is its own tap": the tap is spent,
    // so the line is no longer one the seat may take.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds priority again, got {:?}", engine.pending());
    };
    assert!(
        !legal.abilities.contains(&(elf, 0)),
        "a tapped Elf has no {{T}} left to pay with: {:?}",
        legal.abilities
    );
}

fn wirewood_hivemaster() -> CardIndex {
    card_index("20339b68-b617-45a6-b569-cc6231641e88")
}

/// Wirewood Hivemaster — {1}{G} Elf 1/1: "Whenever another nontoken Elf
/// enters, you may create a 1/1 green Insect creature token."
///
/// Two Llanowar Elves are cast in the same main phase, so one board reads all
/// three words of the trigger at once: the Hivemaster's *own* entry makes no
/// token (`another`), the first Elf's entry asks a `MayDo` question that is
/// accepted and leaves exactly one 1/1 green Insect, and the second Elf's entry
/// asks again and is declined so the count stays at one — a trigger that never
/// asked, or a "may" that resolved without its answer, would move that number
/// in one direction or the other. All four Forests are tapped before anything
/// is cast and the Elves are cast off mana already floating, so the second Elf
/// is not paid for by the first one, which by then is a creature on the table.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn wirewood_hivemaster_asks_per_elf_and_makes_a_green_insect_for_each_yes() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), forest()])
        .hand(
            0,
            &[wirewood_hivemaster(), llanowar_elves(), llanowar_elves()],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Forests, and the Elves still in hand are not mana sources yet"
    );

    // {1}{G} off the pool, and the Hivemaster is an Elf entering under its own
    // trigger — "another" is the word under test, so no token may appear.
    cast_with_floating(&mut engine, p0, wirewood_hivemaster());
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, wirewood_hivemaster()).is_some(),
        "the Hivemaster resolved onto the battlefield"
    );
    assert!(
        tokens_of(&engine, p0).is_empty(),
        "\"another nontoken Elf\" — the Hivemaster is itself an Elf and its \
         own entry does not trigger it"
    );

    // The first Elf: the trigger asks, and the offer is taken.
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::YesNo {
                prompt: YesNoPrompt::MayDo,
                ..
            }
        )
    });
    engine
        .apply(p0, PlayerAction::YesNo(true))
        .expect("the may-question the trigger asked");
    pass_until(&mut engine, stack_is_empty);

    let tokens = tokens_of(&engine, p0);
    assert_eq!(
        tokens.len(),
        1,
        "one nontoken Elf entered and the offer was accepted"
    );
    let insect = engine
        .state()
        .object(tokens[0])
        .expect("the Insect is on the battlefield")
        .token
        .expect("it knows which token it is");
    assert_eq!(
        (insect.power, insect.toughness),
        (Some(1), Some(1)),
        "a 1/1 Insect"
    );
    assert!(
        insect.colors.contains(baylee_core::color::Color::Green),
        "and a *green* one"
    );

    // The second Elf: the same trigger, answered the other way.
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::YesNo {
                prompt: YesNoPrompt::MayDo,
                ..
            }
        )
    });
    engine
        .apply(p0, PlayerAction::YesNo(false))
        .expect("a second question, and it takes the other answer");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        tokens_of(&engine, p0).len(),
        1,
        "\"you may\" — declining leaves the board exactly where it was, so a \
         token-per-Elf reading would show two here"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{G}} and the two {{G}} came out of the four Forests"
    );
    assert_eq!(
        engine
            .state()
            .zones
            .list(ZoneLocation::Battlefield)
            .iter()
            .filter(|id| {
                engine
                    .state()
                    .object(**id)
                    .is_some_and(|o| o.card.is_some_and(|c| c.index == llanowar_elves()))
            })
            .count(),
        2,
        "both Elves resolved and are standing beside the Hivemaster"
    );
}

fn wretched_anurid() -> CardIndex {
    card_index("f8beeb0a-750f-4afa-a244-10011342bbeb")
}

/// Wretched Anurid is a {1}{B} 3/3 whose whole text is "Whenever another
/// creature enters, you lose 1 life." Two words carry the card, and each needs
/// a different arrival to be read: *another*, because the Anurid entering must
/// not drain the seat that played it, and the missing "you control", because
/// the drain is the Anurid's controller's life whoever's creature entered.
/// Three resolutions are played in one game — the Anurid, a second creature
/// under the same seat, and one across the table — and the life total of both
/// seats is read after each, so a trigger that fired on its own arrival, or
/// only on its controller's creatures, or on the wrong seat, fails one of them.
#[test]
fn wretched_anurid_drains_its_controller_for_another_creature_wherever_it_comes_from() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[swamp(), swamp(), forest()])
        .hand(0, &[wretched_anurid(), llanowar_elves()])
        .battlefield(1, &[forest()])
        .hand(1, &[llanowar_elves()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Two Swamps pay {1}{B} and the Forest is the thing kept back: it is the
    // source the second creature is cast off, and a Forest spent here would
    // make the second cast a claim about a board that had none.
    let land = on_battlefield(&engine, p0, forest()).expect("the Forest is out");
    tap_mana_except(&mut engine, p0, land);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Swamps, and nothing off the Forest"
    );
    cast_with_floating(&mut engine, p0, wretched_anurid());
    pass_until(&mut engine, |e| stack_is_empty(e) && at_rest(e, p0));

    let anurid = on_battlefield(&engine, p0, wretched_anurid()).expect("the Anurid resolved");
    assert_eq!(pt(&engine, anurid), (3, 3), "the printed 3/3 body");
    assert_eq!(
        engine.state().players[0].life,
        20,
        "\"another creature\": the Anurid's own arrival is not one, so nothing \
         is lost for it"
    );

    // A second creature under the same seat, so the drain can only come from
    // the printed trigger and not from a cost or a state-based effect.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the Forest that was held back, and nothing else on the board"
    );
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, |e| stack_is_empty(e) && at_rest(e, p0));
    assert_eq!(
        engine.state().players[0].life,
        19,
        "\"whenever another creature enters, you lose 1 life\" — one creature, \
         one life"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the life is the Anurid's controller's, not the table's"
    );

    // The half a narrower reading would lose. The card prints no "you
    // control", so the opponent's own Elf entering drains p0 again while p1
    // pays nothing for it.
    reach_their_main_phase(&mut engine, p1);
    tap_all_mana(&mut engine, p1);
    assert_eq!(
        engine.state().players[1].mana_pool.total(),
        1,
        "the opponent's one Forest, one green"
    );
    cast_with_floating(&mut engine, p1, llanowar_elves());
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "the creature across the table resolved"
    );
    assert_eq!(
        engine.state().players[0].life,
        18,
        "a creature entering under an opponent is still *another* creature"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the Elf's own controller pays none of that life"
    );
}

fn wyluli_wolf() -> CardIndex {
    card_index("00185f3b-2777-4417-a8e0-4691f41c0ec1")
}

/// Wyluli Wolf is a `{1}{G}` 1/1 whose whole text is "{T}: Target creature
/// gets +1/+1 until end of turn." The scenario gives that filter something to
/// *decline* on both sides of the table — an Elf under the same seat and an
/// Elf across it — and reads the printed word "creature" and not "creature you
/// control": both are offered, the Wolf itself is offered too, and only the
/// one that is named changes. `(2, 2)` against two untouched `(1, 1)`s is the
/// pump, and the same Elf reading `(1, 1)` again on the opponent's turn is the
/// "until end of turn" the card prints.
#[test]
fn wyluli_wolf_taps_to_pump_the_creature_it_names_and_no_other() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[wyluli_wolf()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");

    // {1}{G} off the Forests, which `cast_from_hand` taps before it casts: the
    // Wolf has to be a permanent on the table and not a card in a hand.
    cast_from_hand(&mut engine, p0, wyluli_wolf());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let wolf = on_battlefield(&engine, p0, wyluli_wolf()).expect("the Wolf resolved");
    assert_eq!(pt(&engine, wolf), (1, 1), "a printed 1/1");
    assert!(!is_tapped(&engine, wolf), "and it enters untapped");
    assert_eq!(pt(&engine, mine), (1, 1), "nothing is pumped yet");

    // Ability 0 is the only line the card prints: its whole price is its own
    // {T}, and it wants one target creature.
    // CR 302.6: a creature that arrived this turn cannot pay a `{T}`, so
    // the turn goes round once before the line is pressed. Both halves are
    // needed — `walk_to_own_main` on its own returns where it stands,
    // because this already *is* p0's own main phase.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    activate(&mut engine, p0, wyluli_wolf(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that activated chooses");
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    assert!(
        options.contains(&wolf),
        "the Wolf is a creature too, so its own ability may point at it — \
         the card says \"target creature\", not \"another\": {options:?}"
    );
    assert!(
        !is_tapped(&engine, wolf),
        "CR 601.2h: the tap is the last step of the activation, so the Wolf is \
         still standing while the question is open"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the creature the question offered is the one that gets pumped");
    assert!(
        is_tapped(&engine, wolf),
        "paying the {{T}} is what leaves the Wolf tapped"
    );
    pass_until(&mut engine, |e| pt(e, mine) == (2, 2));

    assert_eq!(
        pt(&engine, mine),
        (2, 2),
        "+1/+1 until end of turn on the creature that was named"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "the Elf across the table was a legal target and was not the one named"
    );
    assert_eq!(
        pt(&engine, wolf),
        (1, 1),
        "and the Wolf neither pumps itself nor keeps what it hands out"
    );

    // "until end of turn": by the opponent's main phase the cleanup step has
    // taken it back, so the Elf is the printed 1/1 again.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, mine),
        (1, 1),
        "the pump ended with the turn it was applied in"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "and nothing ever reached that side"
    );
}

fn youthful_knight() -> CardIndex {
    card_index("ef2a24f5-ce5e-4054-843a-2cae0c66318a")
}

/// Youthful Knight prints one line — "First strike" — onto a 2/1 for
/// {1}{W}, and none of it can be read off the card itself. The test
/// actually casts it and reads the projected 2/1 with the projected
/// first strike; then it blocks the 1/1 Elf on the table, which only
/// the line decides — the Knight strikes first and survives, where a
/// 2/1 without first strike would die together with it in one step.
#[test]
fn youthful_knight_costs_two_and_blocks_as_a_2_1_first_striker() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[youthful_knight()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);
    cast_from_hand(&mut engine, p0, youthful_knight());
    pass_until(&mut engine, stack_is_empty);

    let knight = on_battlefield(&engine, p0, youthful_knight()).expect("the Knight resolved");
    assert_eq!(pt(&engine, knight), (2, 1), "{{1}}{{W}} buys a 2/1");
    assert!(
        keywords(&engine, knight).contains(KeywordSet::FIRST_STRIKE),
        "the one line the card prints reaches the permanent through the layers"
    );

    // Summoning sickness keeps the Knight out of this turn's attack, so the
    // proof is on the other side of the table: p1's Elf attacks and the
    // Knight blocks.
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::ChooseAttackers { player, .. } if *player == p1),
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(elf, Defender::Player(p0))],
            },
        )
        .expect("the untapped Elf may attack");
    // CR 508.2: priority goes round once the attack is declared, so the
    // block question is not the next pending.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        panic!("p0 is asked for blockers, got {:?}", engine.pending());
    };
    assert!(
        blockers
            .iter()
            .any(|b| b.blocker == knight && b.attackers.contains(&elf)),
        "the Knight is offered as a blocker for the Elf: {blockers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareBlockers {
                blockers: vec![(knight, elf)],
            },
        )
        .expect("the pairing was one of the options");

    pass_until(&mut engine, |e| {
        on_battlefield(e, p1, llanowar_elves()).is_none()
    });

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "two first-strike damage on a printed 1/1 is lethal (CR 704.5f)"
    );
    let survivor = on_battlefield(&engine, p0, youthful_knight()).expect("the Knight survived");
    assert_eq!(
        pt(&engine, survivor),
        (2, 1),
        "and took no damage: the Elf was dead before the normal damage step"
    );
}

fn zephyr_falcon() -> CardIndex {
    card_index("b5e44bd6-0b67-4770-868d-c46af5b6a42f")
}

/// Zephyr Falcon — {1}{U} — 1/1 Bird with flying and vigilance.
///
/// Vigilance is not readable off the card file, only off a combat step: the
/// Falcon attacks and is still untapped afterwards, and a Llanowar Elves
/// attacks in the very same declaration beside it as the control — the Elf
/// prints no vigilance and is tapped, so an engine that simply never tapped
/// attackers could not pass both halves. The two damage that reached the
/// opponent are what say the declaration really happened rather than being
/// skipped, and the turn cycle before it is CR 302.6: a creature cast this
/// turn may not attack at all.
#[test]
fn zephyr_falcon_flies_and_attacks_without_tapping_itself() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), llanowar_elves()])
        .hand(0, &[zephyr_falcon()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{U} off the two Islands, with the Elf named as the printing kept
    // back: it is the control in the attack declaration below, and a mana
    // creature tapped for the cast could not attack afterwards.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands in the pool, and the Elf kept back"
    );
    cast_with_floating(&mut engine, p0, zephyr_falcon());
    pass_until(&mut engine, stack_is_empty);

    let falcon = on_battlefield(&engine, p0, zephyr_falcon()).expect("the Falcon resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the control is out");
    assert_eq!(pt(&engine, falcon), (1, 1), "the body the card prints");
    let kw = keywords(&engine, falcon);
    assert!(kw.contains(KeywordSet::FLYING), "flying");
    assert!(kw.contains(KeywordSet::VIGILANCE), "vigilance");

    // A creature summoned this turn cannot attack (CR 302.6), so the attack
    // belongs to the turn after it arrived: one whole cycle of the table.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, falcon),
        "the Falcon's own untap step left it standing, so it may be declared"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&falcon) && attackers.contains(&elves),
        "both are untapped, unsick creatures of mine: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (falcon, Defender::Player(p1)),
                    (elves, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    // Not `stack_is_empty`: that is already true the moment attackers are
    // declared, so it would stop the walk before the combat damage step and
    // both life totals would still read 20. The end step is past damage.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending) && e.state().turn.active == p0
    });

    assert_eq!(
        engine.state().players[1].life,
        18,
        "two 1/1s got through for two damage, so the attack was real"
    );
    assert!(
        is_tapped(&engine, elves),
        "the Elf prints no vigilance, and the same declaration tapped it"
    );
    assert!(
        !is_tapped(&engine, falcon),
        "while the Falcon is still untapped after attacking — that is what \
         vigilance does, and a board where nothing taps could not show it"
    );
}

fn zulaport_cutthroat() -> CardIndex {
    card_index("76b003e0-15af-4f22-bdf2-1ade5430964a")
}

/// Zulaport Cutthroat — {1}{B}, a 1/1: "Whenever this creature or another
/// creature you control dies, each opponent loses 1 life and you gain 1 life."
///
/// A three-seat table is what reads the word **each**: one death has to take a
/// life off both other seats at once, which a duel could not tell apart from
/// "target opponent". Both halves of the trigger's filter are then played with
/// Ashnod's Altar — first the Llanowar Elves beside it (another creature you
/// control) and then the Cutthroat itself — while the counter-proof comes
/// first of all: a creature dying *across* the table is just as dead, and only
/// the "you control" in that filter declines it.
#[test]
#[allow(clippy::too_many_lines)] // two deaths that count, one that must not, on a three-seat table
fn zulaport_cutthroat_drains_each_opponent_for_a_creature_its_controller_loses() {
    // The third seat is read by index below (`players[2]`) rather than by
    // handle, so only the two that name a seat to the engine are bound.
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::table(97, forest(), 3)
        .battlefield(
            0,
            &[
                forest(),
                swamp(),
                swamp(),
                swamp(),
                plains(),
                plains(),
                ashnods_altar(),
                llanowar_elves(),
            ],
        )
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[zulaport_cutthroat(), vindicate()])
        .life(0, 20)
        .life(1, 20)
        .life(2, 20)
        .start();
    keep_mulligans(&mut engine);
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::FirstMain)
            && e.state().turn.active == p0
            && at_rest(e, p0)
    });

    // Both spells come out of the one main phase the lands pay for: a pool
    // empties when a step ends (CR 500.5), and this test never leaves it.
    cast_from_hand(&mut engine, p0, zulaport_cutthroat());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let cutthroat =
        on_battlefield(&engine, p0, zulaport_cutthroat()).expect("the Cutthroat resolved");
    assert_eq!(pt(&engine, cutthroat), (1, 1), "the printed 1/1");

    // The counter-proof, taken while the Cutthroat is alive and watching: the
    // trigger is not "a creature dies", it is "a creature *you control* dies".
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    cast_from_hand(&mut engine, p0, vindicate());
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!("Vindicate targets a permanent, got {:?}", engine.pending())
    };
    assert!(
        options.contains(&theirs),
        "the Elf across the table is a permanent and a legal target: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "their creature is dead, which is what makes the control say anything"
    );
    assert_eq!(
        [
            engine.state().players[0].life,
            engine.state().players[1].life,
            engine.state().players[2].life,
        ],
        [20, 20, 20],
        "a death across the table is not a death this Cutthroat watches"
    );

    // "another creature you control dies" — the Altar's price *is* the
    // creature, so the death is a real one and not a board the harness built.
    let fodder = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves stand beside it");
    activate(&mut engine, p0, ashnods_altar(), 0);
    let Pending::ChooseCards {
        options,
        min,
        max,
        prompt,
        ..
    } = engine.pending().clone()
    else {
        panic!("the sacrifice is a cost, got {:?}", engine.pending())
    };
    assert_eq!(
        prompt,
        ChoicePrompt::CostSacrifice,
        "a cost and not a search, asked before it is paid"
    );
    assert_eq!((min, max), (1, 1), "one creature, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "the two creatures this seat controls: {options:?}"
    );
    assert!(options.contains(&fodder) && options.contains(&cutthroat));
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert_eq!(engine.state().players[0].life, 21, "\"you gain 1 life\"");
    assert_eq!(
        engine.state().players[1].life,
        19,
        "\"each opponent loses 1 life\""
    );
    assert_eq!(
        engine.state().players[2].life,
        19,
        "and \"each\" is both of them: one trigger, two seats"
    );

    // "whenever *this* creature … dies" — the half `Filter::This` carries and
    // a filter written as `Filter::Another` alone would have dropped.
    activate(&mut engine, p0, ashnods_altar(), 0);
    let Pending::ChooseCards {
        options, prompt, ..
    } = engine.pending().clone()
    else {
        panic!(
            "the second sacrifice is a cost too, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(prompt, ChoicePrompt::CostSacrifice);
    assert_eq!(
        options,
        vec![cutthroat],
        "the Cutthroat is the only creature this seat still has: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![cutthroat],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert_eq!(engine.state().players[0].life, 22, "you gain 1 life again");
    assert_eq!(engine.state().players[1].life, 18);
    assert_eq!(engine.state().players[2].life, 18);
    assert!(
        in_graveyard(&engine, p0, zulaport_cutthroat()).is_some(),
        "the trigger outlives the permanent that printed it"
    );
}

fn army_ants() -> CardIndex {
    card_index("c39112ab-ee1f-4f00-b18b-692b5fe32b80")
}

/// Army Ants prints "{T}, Sacrifice a land: Destroy target land." — one
/// activation whose price and whose target are both lands, on opposite sides
/// of the table. The board gives p0 two Forests so the sacrifice is a real
/// choice rather than the only land in play, and p1 two lands so the
/// destruction takes the one that was named and leaves the other. Nothing
/// taps for mana anywhere: the whole price is the Ants' own `{T}` and a land,
/// so an empty pool is what makes "no mana was spent" exact, and the target is
/// answered before the sacrifice (CR 601.2c, then 601.2h) — while the question
/// stands the Ants are untapped and both Forests are still standing.
#[test]
#[allow(clippy::too_many_lines)] // one activation, both halves of its price and its target read off it
fn army_ants_eats_a_land_of_its_own_to_destroy_a_land_across_the_table() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[army_ants(), forest(), forest()])
        .battlefield(1, &[mountain(), island()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let ants = on_battlefield(&engine, p0, army_ants()).expect("the Ants are on the table");
    let mine = all_on_battlefield(&engine, p0, forest());
    assert_eq!(
        mine.len(),
        2,
        "two Forests of my own, one of which stays standing"
    );
    let (eaten, kept) = (mine[0], mine[1]);
    let their_mountain = on_battlefield(&engine, p1, mountain()).expect("their Mountain is out");
    let their_island = on_battlefield(&engine, p1, island()).expect("their Island is out");

    // The whole price is the tap symbol and a land: no mana is involved, so
    // nothing is tapped to read the offer and the pool starts empty.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the Ants' price is their own {{T}} and a land, so no mana is on this board"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(ants, 0)),
        "an untapped creature with two lands to eat pays the cost, so the one \
         line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, army_ants(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target land\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&their_mountain) && options.contains(&their_island),
        "\"target land\" reaches across the table: {options:?}"
    );
    assert!(
        options.contains(&eaten) && options.contains(&kept),
        "and your own lands are lands too — the filter names no controller: {options:?}"
    );
    assert!(
        !options.contains(&ants),
        "a creature is no land, and the Ants are the source besides: {options:?}"
    );
    // CR 601.2c before CR 601.2h: the target is named while nothing is paid.
    assert!(
        !is_tapped(&engine, ants),
        "no cost is paid while the target question stands"
    );
    assert!(
        in_graveyard(&engine, p0, forest()).is_none(),
        "and no land has been sacrificed yet"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![their_mountain],
            },
        )
        .expect("the Mountain was one of the options");

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the sacrifice is a cost and is asked next, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one land, no more and no fewer");
    assert!(
        options.contains(&eaten) && options.contains(&kept),
        "both Forests this seat controls are on the menu: {options:?}"
    );
    assert_eq!(
        options.len(),
        2,
        "\"a land\" you control: the two Forests and nothing else: {options:?}"
    );
    assert!(
        !options.contains(&ants),
        "`Filter::YOUR_LAND` is read, not skipped: a creature pays nothing here: {options:?}"
    );
    assert!(
        !options.contains(&their_mountain) && !options.contains(&their_island),
        "`CR 701.21a`: the lands across the table are not yours to sacrifice: {options:?}"
    );
    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![their_island],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, island()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![eaten],
            },
        )
        .expect("the Forest the question offered pays the cost");

    assert!(
        is_tapped(&engine, ants),
        "{{T}} was the other half of the price"
    );
    assert!(
        in_graveyard(&engine, p0, forest()).is_some(),
        "a sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, mountain()).is_some(),
        "destroying is an effect, so the Mountain waits on the stack"
    );
    assert!(!stack_is_empty(&engine), "and the ability is on it");
    assert_eq!(
        lands_of(&engine, p0).len(),
        1,
        "exactly one land was given up: the other is still standing"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, mountain()).is_some(),
        "\"destroy target land\": the land that was named is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, island()).is_some(),
        "and the land nobody named never moved"
    );
    assert!(
        on_battlefield(&engine, p0, army_ants()).is_some(),
        "the Ants outlive the land they ate"
    );
}

fn azimaet_drake() -> CardIndex {
    card_index("a82d9c9b-ec17-4f51-a6bf-5984ca4433e5")
}

/// Azimaet Drake — {2}{U}, a 1/3 Drake with flying and "{U}: This creature gets
/// +1/+0 until end of turn. Activate only once each turn."
///
/// One scenario reads all three printed clauses. The body and the keyword are the
/// board it lands on; the pump is the {U} really spent out of a pool three Islands
/// filled, which leaves a 2/3 rather than a 2/1; and the limit is the same offer
/// read twice — *absent* at the end of the turn with blue still floating, so the
/// price cannot be what withheld it, and *present* again on the next turn, so what
/// barred it was "each turn" and not a permanent exhaustion.
#[test]
fn azimaet_drake_pumps_once_a_turn_and_pumps_again_on_the_next() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(71, island())
        .battlefield(0, &[island(), island(), island(), island(), island()])
        .hand(0, &[azimaet_drake()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Three Islands pay the {2}{U} and two are left standing: the pump's {U}
    // needs a source in the *same* turn, because a pool empties when the step
    // ends (CR 500.5) and everything below plays inside this one main phase.
    let islands = all_on_battlefield(&engine, p0, island());
    assert_eq!(islands.len(), 5, "five Islands were dealt");
    let held = [islands[3], islands[4]];
    tap_mana_where(&mut engine, p0, |id| !held.contains(&id));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Islands, three blue, and the other two still standing"
    );
    cast_with_floating(&mut engine, p0, azimaet_drake());
    pass_until(&mut engine, stack_is_empty);
    let drake = on_battlefield(&engine, p0, azimaet_drake()).expect("the Drake resolved");
    assert_eq!(pt(&engine, drake), (1, 3), "the printed 1/3 body");
    assert!(
        keywords(&engine, drake).contains(KeywordSet::FLYING),
        "and the flying it prints"
    );

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the two Islands held back: the whole price and one spare"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.iter().any(|(src, _)| *src == drake),
        "with {{U}} floating the one line the Drake prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, azimaet_drake(), 0);
    assert!(
        !stack_is_empty(&engine),
        "a pump is no mana ability, so it goes on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, drake),
        (2, 3),
        "+1/+0: power up and toughness untouched — a (2, 4) would be a \
         toughness the card does not print"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{U}} came out of the pool"
    );

    // The limit, read where only the limit can be the reason: one blue is
    // still floating, so `can_afford` has nothing to withhold the line for.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == drake),
        "\"Activate only once each turn\" — the {{U}} is still there, so the \
         limit and not the price keeps the line out of the offer: {:?}",
        legal.abilities
    );

    // And it is per *turn*, not once and for all: a turn later the same board
    // offers the same line, with the pump it bought already worn off.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        pt(&engine, drake),
        (1, 3),
        "\"until end of turn\": the pump did not survive the turn"
    );
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "every Island untapped across the turn"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.iter().any(|(src, _)| *src == drake),
        "on the next turn the same line is offered again: {:?}",
        legal.abilities
    );
    activate(&mut engine, p0, azimaet_drake(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, drake), (2, 3), "and it pumps the very same way");
}

fn balloon_peddler() -> CardIndex {
    card_index("10f182a7-ffa3-4128-8b2e-e05b97f92e00")
}

/// Balloon Peddler — {2}{U}, a 2/2 Human Spellshaper: "{U}, {T}, Discard a
/// card: Target creature gains flying until end of turn."
///
/// Three prices ride on one activation and each is read somewhere else: the
/// {U} out of a pool only the Islands paid into, the {T} off the Peddler's own
/// status, and "Discard a card" as a `CostDiscard` question whose answer ends
/// up in its owner's graveyard. A creature that arrived this turn cannot pay
/// its own {T} (CR 302.6), so the Peddler is cast on turn one and the ability
/// taken on the next — where the target question stands *before* any of the
/// three prices is asked (CR 601.2c, then 601.2h) and offers both Elves, one
/// on each side of the table, because "target creature" is not "target
/// creature you control".
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn balloon_peddler_pays_a_blue_a_tap_and_a_card_to_grant_flying() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), llanowar_elves()])
        .hand(0, &[balloon_peddler(), counterspell()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{U} off the three Islands, with the Elf named as the printing kept
    // back: it is a creature this test reads again below, and a source tapped
    // for mana has already changed for a reason of its own.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        3,
        "three Islands, and the Elf beside them paid nothing"
    );
    cast_with_floating(&mut engine, p0, balloon_peddler());
    pass_until(&mut engine, stack_is_empty);
    let peddler = on_battlefield(&engine, p0, balloon_peddler()).expect("the Peddler resolved");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(pt(&engine, peddler), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and {{2}}{{U}} took the whole pool, so nothing is floating"
    );

    // CR 302.6: a creature that came down this turn cannot pay its own {T}.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, peddler),
        "a turn later the Peddler is standing, and its {{T}} is finally its own"
    );

    let fodder = in_hand(&engine, p0, counterspell()).expect("the card to pitch is still in hand");
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(peddler, 0)),
        "with {{U}} floating, a card in hand and the Peddler untapped, the one \
         line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, balloon_peddler(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        3,
        "CR 601.2c before CR 601.2h: nothing is paid while the target is chosen"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the creature the question offered was chosen");

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the cost asks which card to discard, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat pays its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostDiscard,
        "a cost and not a cleanup, which is all a client has to tell the two apart"
    );
    assert_eq!(
        (min, max),
        (1, 1),
        "\"Discard a card\" — one card, no fewer"
    );
    assert!(
        options.contains(&fodder),
        "a card in hand is the price: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the card the question offered is the price");

    assert!(is_tapped(&engine, peddler), "{{T}} was the second price");
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        2,
        "and exactly one of the three blue paid the {{U}}"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before - 1,
        "the discarded card left the hand"
    );
    assert!(
        in_graveyard(&engine, p0, counterspell()).is_some(),
        "and it is in its owner's graveyard, which is where a discarded card goes"
    );
    assert!(
        !stack_is_empty(&engine),
        "granting flying is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        keywords(&engine, mine).contains(KeywordSet::FLYING),
        "\"target creature gains flying until end of turn\""
    );
    assert_eq!(
        pt(&engine, mine),
        (1, 1),
        "and nothing else about it changed: the pump is +0/+0 and the keyword is the card"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::FLYING),
        "the grant reaches the creature that was named and never across the table"
    );
    assert!(
        !keywords(&engine, peddler).contains(KeywordSet::FLYING),
        "nor the Spellshaper that paid for it"
    );
}

fn balthor_the_stout() -> CardIndex {
    card_index("23669721-fe9e-49d7-9504-ae6164de723a")
}

/// Balthor the Stout — {1}{R}{R} legendary 2/2 Dwarf Barbarian — prints
/// "Other Barbarian creatures get +1/+1" and "{R}: Another target Barbarian
/// creature gets +1/+0 until end of turn". Neither sentence says "you
/// control", so the board puts a Barbarian on each side of the table: each
/// one is a 3/3 because the *other* one hands it +1/+1, and the red
/// activation aimed across the table reads 4/3 rather than 3/3. The Elf
/// beside the opponent's Balthor is the counter-half of both words — it is
/// no Barbarian, so it is neither pumped nor offered as a target.
#[test]
fn balthor_the_stout_pumps_the_other_barbarian_and_never_himself() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[balthor_the_stout(), mountain()])
        .battlefield(1, &[balthor_the_stout(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let mine = on_battlefield(&engine, p0, balthor_the_stout()).expect("my Balthor is out");
    let theirs = on_battlefield(&engine, p1, balthor_the_stout()).expect("their Balthor is out");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");

    // "Other Barbarian creatures": each Balthor is the printed 2/2 plus the
    // +1/+1 the other one hands it, because the line names no controller.
    assert_eq!(pt(&engine, mine), (3, 3), "my Balthor, pumped by theirs");
    assert_eq!(pt(&engine, theirs), (3, 3), "and theirs, pumped by mine");
    assert_eq!(pt(&engine, elf), (1, 1), "the Elf is no Barbarian");

    // `can_afford` reads the pool and not the untapped land, so the red is
    // floating before anything is claimed about the offer.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one Mountain, and Balthor makes no mana of his own"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(mine, 1)),
        "ability 1 is the {{R}} pump, offered now that the red is in the pool: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, balthor_the_stout(), 1);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!("the pump targets a creature, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat chooses");
    assert!(
        options.contains(&theirs),
        "\"another target Barbarian creature\" reaches across the table: {options:?}"
    );
    assert!(
        !options.contains(&mine),
        "\"another\" is not the Balthor paying the red: {options:?}"
    );
    assert!(
        !options.contains(&elf),
        "the Elf beside them is no Barbarian: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the creature the question offered is the one it named");
    assert!(
        !stack_is_empty(&engine),
        "the pump is no mana ability, so it is waiting on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, theirs),
        (4, 3),
        "+1/+0 on top of the +1/+1 it was already handed by the other Balthor"
    );
    assert_eq!(
        pt(&engine, mine),
        (3, 3),
        "and the Balthor that paid is untouched"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{R}} came out of the pool"
    );
}

fn barbarian_lunatic() -> CardIndex {
    card_index("12b5fbe5-a426-4b7e-bef0-abea71170e49")
}

/// Barbarian Lunatic prints one sentence — "{2}{R}, Sacrifice this creature:
/// It deals 2 damage to target creature" — and its two halves have to be read
/// in two different places. The damage is read off a board with a 1/1 and a
/// 6/6 across the table, so "target creature" is lethal to exactly the one
/// that was named; the sacrifice is read where CR 601.2c and CR 601.2h put it,
/// with the target chosen while the Lunatic still stands and the four red
/// still float, and only afterwards is the card in its owner's graveyard and
/// the pool empty.
#[test]
fn barbarian_lunatic_sacrifices_itself_to_deal_two_damage_to_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[barbarian_lunatic(), mountain(), mountain(), mountain()],
        )
        .battlefield(1, &[llanowar_elves(), rootbreaker_wurm()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let lunatic = on_battlefield(&engine, p0, barbarian_lunatic()).expect("the Lunatic is out");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("a 1/1 across the table");
    let wurm = on_battlefield(&engine, p1, rootbreaker_wurm()).expect("and a 6/6 beside it");
    assert_eq!(pt(&engine, lunatic), (2, 1), "the body the card prints");
    assert_eq!(pt(&engine, elf), (1, 1), "two damage is lethal to this");
    assert_eq!(pt(&engine, wurm), (6, 6), "and not to that");

    // The {2}{R} is read off the pool and not off the untapped Mountains, so
    // the mana is floated before anything is claimed about the offer. The
    // Lunatic makes no mana of its own, so the pool is the Mountains exactly.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Mountains, three red — exactly the {{2}}{{R}} the line charges, \
         so the pool emptying below is a number and not a coincidence"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(lunatic, 0)),
        "with the price floating, the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, barbarian_lunatic(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&elf) && options.contains(&wurm) && options.contains(&lunatic),
        "\"target creature\" is any creature on the battlefield — the two \
         across the table and the Lunatic itself: {options:?}"
    );

    // CR 601.2c names the target before CR 601.2h pays, so while the question
    // stands the Lunatic is still a permanent and the three red are still
    // floating.
    assert!(
        on_battlefield(&engine, p0, barbarian_lunatic()).is_some(),
        "the sacrifice is a cost, and a cost follows the target"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "and the {{2}}{{R}} is still in the pool for the same reason"
    );

    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the creature the question offered was chosen");

    assert!(
        in_graveyard(&engine, p0, barbarian_lunatic()).is_some(),
        "\"Sacrifice this creature\" is the last thing paid, and it takes the \
         whole card"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{2}}{{R}} went with it"
    );
    assert!(
        !stack_is_empty(&engine),
        "dealing damage is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "two damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        on_battlefield(&engine, p1, rootbreaker_wurm()).is_some(),
        "the 6/6 the ability did not name is untouched"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the damage went to the creature that was named and never to the \
         player whose board it stood on"
    );
}

fn barrin_master_wizard() -> CardIndex {
    card_index("8c6d6684-1943-4af3-98da-951604193911")
}

// oracle_id = "d52b72ff-a82d-430e-94c7-675c83b43e50"
fn braidwood_cup() -> CardIndex {
    card_index("d52b72ff-a82d-430e-94c7-675c83b43e50")
}

/// Barrin, Master Wizard — {1}{U}{U}, 1/1 legendary Human Wizard:
/// "{2}, Sacrifice a permanent: Return target creature to its owner's hand."
///
/// Neither half of the price names a particular permanent, so the engine has
/// to ask twice and each menu is half the card: "target creature" carries no
/// controller (CR 115.1), so the Elf across the table is on the first menu,
/// while "sacrifice a permanent" is read against CR 701.21a and offers only
/// what this seat controls — the same Elf must not appear on the second.
/// The {2} is read off the pool and not off the untapped lands, so the empty
/// pool before anything is tapped is the control on the one line the card
/// prints, and the two Islands' worth of mana is what pays for it.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn barrin_master_wizard_trades_a_permanent_for_an_opponents_creature() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(
            0,
            &[barrin_master_wizard(), braidwood_cup(), island(), island()],
        )
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let barrin = on_battlefield(&engine, p0, barrin_master_wizard()).expect("Barrin is out");
    let fodder = on_battlefield(&engine, p0, braidwood_cup()).expect("the Cup is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(pt(&engine, barrin), (1, 1), "the body the card prints");

    // `legal.abilities` is filtered through `can_afford`, which reads the pool
    // rather than the untapped lands: nothing floats, so the {2} is unpayable
    // and the ability is absent from the offer altogether.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        !legal.abilities.contains(&(barrin, 0)),
        "an empty pool pays no {{2}}, so the offer is empty of Barrin: {:?}",
        legal.abilities
    );

    // Now the mana. Two Islands, and the Cup prints no mana ability of its
    // own — its whole text is a life gain, so `tap_all_mana` leaves it
    // standing while the lands pay the price Barrin charges.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Islands, and nothing off the artifact this test will sacrifice"
    );

    activate(&mut engine, p0, barrin_master_wizard(), 0);

    // CR 601.2c picks the target and CR 601.2h pays afterwards, so the two
    // questions arrive in that order — answered in the order they arrive
    // rather than the order they are expected in.
    let mut target_question: Vec<ObjectId> = Vec::new();
    let mut sacrifice_question: Vec<ObjectId> = Vec::new();
    for _ in 0..12 {
        if !target_question.is_empty() && !sacrifice_question.is_empty() {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player, options, ..
            } => {
                target_question = options;
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![theirs],
                        },
                    )
                    .expect("the Elf across the table was one of the options");
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostSacrifice,
                    "a cost and not a search, which is all a client has to tell the two apart"
                );
                assert_eq!((min, max), (1, 1), "one permanent, no more and no fewer");
                sacrifice_question = options;
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![fodder],
                        },
                    )
                    .expect("the Cup the question offered pays the cost");
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while Barrin's activation resolves: {other:?}"),
        }
    }

    assert!(
        target_question.contains(&theirs) && target_question.contains(&barrin),
        "\"target creature\" names no controller, so both sides of the table \
         are on the menu: {target_question:?}"
    );
    assert!(
        !target_question.contains(&fodder),
        "the Cup is an artifact and no creature: {target_question:?}"
    );
    assert!(
        sacrifice_question.contains(&fodder) && sacrifice_question.contains(&barrin),
        "every permanent this seat controls is on the sacrifice menu, Barrin \
         included: {sacrifice_question:?}"
    );
    assert!(
        !sacrifice_question.contains(&theirs),
        "`CR 701.21a`: an opponent's creature is not yours to sacrifice, even \
         when it is the very creature that was named: {sacrifice_question:?}"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_none(),
        "the targeted creature left the battlefield"
    );
    assert!(
        in_hand(&engine, p1, llanowar_elves()).is_some(),
        "\"to its owner's hand\": the Elf goes back to the seat that owns it, \
         not to the seat that aimed the bounce"
    );
    assert!(
        in_graveyard(&engine, p0, braidwood_cup()).is_some(),
        "and the sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, barrin_master_wizard()).is_some(),
        "only the permanent that was named: Barrin ate the Cup, not himself"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{2}} came out of the two mana the Islands made"
    );
}

fn battle_rampart() -> CardIndex {
    card_index("ec187304-4c05-44da-8ad5-7c56f6b05212")
}

/// Battle Rampart prints two things: "Defender" on a 1/3 Wall and
/// "`{T}`: Target creature gains haste until end of turn." Both are read on
/// a creature that is not the source — the ability costs only its own tap
/// symbol and is therefore not even tapped by `tap_all_mana` —, and "target
/// creature" is exactly that: the offer includes its own *and* the Elves on
/// the table, the chosen one gets HASTE and the unchosen ones do not. The
/// Wall itself may not attack a turn later, while the Elf next
/// to it is in the same attack offer.
#[test]
fn battle_rampart_grants_haste_to_the_creature_it_targets_and_never_attacks_itself() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain(), llanowar_elves()])
        .hand(0, &[battle_rampart()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::HASTE),
        "nothing has granted haste yet"
    );

    // {2}{R} from the three Mountains; the Elf is named as the source that
    // remains standing, because it is the creature in question below.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    cast_with_floating(&mut engine, p0, battle_rampart());
    pass_until(&mut engine, stack_is_empty);
    let rampart = on_battlefield(&engine, p0, battle_rampart()).expect("the Rampart resolved");
    assert_eq!(pt(&engine, rampart), (1, 3), "the printed 1/3 body");
    assert!(
        keywords(&engine, rampart).contains(KeywordSet::DEFENDER),
        "and the printed defender keyword reaches the permanent"
    );

    // The whole cost of the ability is its own {T}, so no mana: it is
    // offered even though the mana pool is empty.
    // CR 302.6: a creature that arrived this turn cannot pay a `{T}`, so
    // the turn goes round once before the line is pressed. Both halves are
    // needed — `walk_to_own_main` on its own returns where it stands,
    // because this already *is* p0's own main phase.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    activate(&mut engine, p0, battle_rampart(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that activated aims it");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" reaches across the table and not only your own side: {options:?}"
    );
    assert!(
        options.contains(&rampart),
        "and \"target creature\" is not \"another target creature\": the source is a creature: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Elf across the table was one of the options");
    assert!(
        is_tapped(&engine, rampart),
        "{{T}} was the price and is paid"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        keywords(&engine, theirs).contains(KeywordSet::HASTE),
        "the chosen creature has haste until end of turn"
    );
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::HASTE),
        "the creature that no one chose has no haste"
    );
    assert!(
        !keywords(&engine, rampart).contains(KeywordSet::HASTE),
        "and the Wall that distributes it doesn't keep it"
    );

    // One turn later, so that summoning sickness no longer excludes the Wall:
    // then defender alone keeps it from being declared an attacker.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&mine),
        "an untapped 1/1 without its own text may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&rampart),
        "the 1/3 Wall may not — that is the printed defender: {attackers:?}"
    );
}

fn bird_maiden() -> CardIndex {
    card_index("bddd6b93-7c69-427a-97ee-0c1f9f950f09")
}

// Bird Maiden — {2}{R} — Creature — Human Bird: 1/2 with flying.
//
// The whole printed card is a body and one keyword, so the scenario has to
// make both of them load-bearing. The board is built so the Maiden arrives
// the way the card arrives — cast off three Mountains for {2}{R} and nothing
// else — and then reads the two numbers that could be wrong: the printed 1/2
// and the flying the keyword line grants. The control that turns "it flies"
// into a claim about the *card* is the combat step: an untapped Llanowar
// Elves beside the Maiden is offered as an attacker while the Maiden is held
// back only by whatever the declaration says, so the offer is read to show
// the 1/2 flier is a legal attacker at all and the opponent's ground creature
// is what flying is *for* — the pair of blockers offered against an attack
// says which attacker the ground body can block.
#[test]
fn bird_maiden_lands_as_a_flying_one_two_and_attacks_where_the_ground_cannot_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain(), quiet_creature()])
        .battlefield(1, &[quiet_creature()])
        .hand(0, &[bird_maiden()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{R} off the three Mountains, with the Elf named as the printing kept
    // back: it is the creature the attack declaration below is read against,
    // and a mana creature tapped for the cost could not attack.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Mountains, three red — the {{2}}{{R}} is paid below, not here"
    );
    cast_with_floating(&mut engine, p0, bird_maiden());
    pass_until(&mut engine, stack_is_empty);

    let maiden = on_battlefield(&engine, p0, bird_maiden()).expect("the Maiden resolved");
    let elf = on_battlefield(&engine, p0, quiet_creature()).expect("the Elf is out");
    let their_elf = on_battlefield(&engine, p1, quiet_creature()).expect("an Elf across the table");
    assert_eq!(pt(&engine, maiden), (1, 2), "the printed 1/2 body");
    assert!(
        keywords(&engine, maiden).contains(KeywordSet::FLYING),
        "the keyword line reaches the permanent"
    );
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FLYING),
        "and the keyword is on the Maiden and not on the board"
    );
    assert!(
        types(&engine, maiden).contains(TypeSet::CREATURE),
        "and it is a creature: {:#?}",
        types(&engine, maiden)
    );

    // The attack declaration is where the keyword is worth anything: the
    // Maiden is a legal attacker, and the only creature that may block it is
    // one that flies — which the Elf across the table does not.
    // CR 302.6: a creature that arrived this turn cannot attack, so the turn
    // goes round once first. Both halves are needed — `walk_to_own_main` on
    // its own returns where it stands, because this already *is* p0's own
    // main phase.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        attackers,
        defenders,
        ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on the attack declaration")
    };
    assert!(
        attackers.contains(&maiden),
        "an untapped 1/2 with flying is a legal attacker: {attackers:?}"
    );
    assert!(
        attackers.contains(&elf),
        "and so is the ground Elf beside it: {attackers:?}"
    );
    assert!(
        defenders.contains(&Defender::Player(p1)),
        "the opponent is what may be attacked: {defenders:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(maiden, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The defending seat is offered its blockers, and the pairing is the
    // reading: the ground Elf across the table is not a legal blocker for a
    // flying attacker (CR 509.1b).
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on the block declaration")
    };
    // The Elf is not on the menu *at all*, which is the same sentence read
    // one level up: `progress` keeps a `BlockOption` only while it has an
    // attacker it could legally be paired with, so a ground creature facing
    // nothing but fliers is omitted rather than offered with an empty list.
    // Asserting "it is there and cannot block the Maiden" would have been
    // asserting a shape this engine never builds.
    assert!(
        !blockers.iter().any(|option| option.blocker == their_elf),
        "the ground Elf may not block a flier (CR 509.1b): {blockers:?}"
    );
    assert!(
        blockers.is_empty(),
        "and it is the only creature that seat has: {blockers:?}"
    );

    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "the unblocked 1/2 dealt its one damage to the player it attacked"
    );
}

fn blade_sliver() -> CardIndex {
    card_index("110e5695-a9df-4201-9230-99f6abe9978f")
}

/// Blade Sliver is a 2/2 Sliver whose entire text is „All Sliver creatures
/// get +1/+0" is, and the word the card hinges on is *all* and not
/// *you control*: therefore a Blade Sliver stands on **both** sides of the
/// table and the second pumps the first as soon as it arrives — a static that
/// reads only its own Slivers would leave the opposing one at (3, 2).
/// The Llanowar Elf next to one's own Sliver is the downward countercheck:
/// +1/+0 on a creature without the subtype would mean the filter is
/// `Filter::CREATURE` or `YOUR_CREATURE` instead of the printed subtype
/// check. (4, 2) in the end is the only number that reads both statics on
/// both Slivers simultaneously, and (1, 1) on the Elf says that exactly
/// two Slivers and one creature are on the battlefield.
#[test]
fn blade_sliver_pumps_every_sliver_at_the_table_and_no_other_creature() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain(), llanowar_elves()])
        .battlefield(1, &[blade_sliver()])
        .hand(0, &[blade_sliver()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");
    let theirs = on_battlefield(&engine, p1, blade_sliver()).expect("their Sliver is out");
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "an Elf is not a Sliver and is not pumped by anything"
    );
    assert_eq!(
        pt(&engine, theirs),
        (3, 2),
        "the one Sliver on the table pumps itself: 2/2 plus its own +1/+0"
    );

    // {2}{R} off three Mountains and the Elf that contributes its own mana
    // ability — none of it is needed afterward, because this test does not
    // read a combat phase, but only projections.
    cast_from_hand(&mut engine, p0, blade_sliver());
    pass_until(&mut engine, stack_is_empty);
    let mine = on_battlefield(&engine, p0, blade_sliver()).expect("the Sliver resolved");

    assert_eq!(
        pt(&engine, mine),
        (4, 2),
        "2/2 gedruckt, +1/+0 vom eigenen Static und +1/+0 vom Sliver gegenüber"
    );
    assert_eq!(
        pt(&engine, theirs),
        (4, 2),
        "\"All Sliver creatures\" — the opponent's Sliver grew when mine arrived, \
         so the static reads the subtype and not \"Slivers you control\""
    );
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "and the Elf under the same control gets nothing: it is the subtype that \
         counts and not `Filter::CREATURE`"
    );
}

fn blaster_mage() -> CardIndex {
    card_index("e5b35b54-77d9-4cb0-86a1-efc8e49aea09")
}

/// Blaster Mage — {2}{R}, 2/2 Human Spellshaper: "{R}, {T}, Discard a card:
/// Destroy target Wall."
///
/// The three parts of the price each leave a mark somewhere a test can read —
/// the {R} empties the single Mountain that paid it, the {T} taps the Mage, and
/// the discarded card lands in its owner's graveyard — so one activation says
/// which of them the engine actually charged. The target filter is read off the
/// offer rather than off the card file: two Walls stand on the table, one of
/// them across it, and the Llanowar Elf beside them together with the Mage
/// itself are the creatures a bare "target creature" would have named. Only the
/// Wall that was pointed at dies, which is the control that the other one was
/// not merely missed by a wipe.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn blaster_mage_discards_and_taps_to_kill_the_wall_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[blaster_mage(), mountain(), wall_of_roots()])
        .battlefield(1, &[wall_of_roots(), llanowar_elves()])
        .hand(0, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mage = on_battlefield(&engine, p0, blaster_mage()).expect("the Mage is on the table");
    let mine = on_battlefield(&engine, p0, wall_of_roots()).expect("my Wall is out");
    let theirs = on_battlefield(&engine, p1, wall_of_roots()).expect("their Wall is out");
    let elves = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let fodder = in_hand(&engine, p0, forest()).expect("the card to discard is in hand");

    // The whole price is a printed {R} and its own {T}, so the Mountain is the
    // only route on this board: the Wall's mana ability pays a -0/-1 counter
    // and the Mage's price is not its tap, so neither is one (#159).
    let taken = tap_all_mana(&mut engine, p0);
    assert_eq!(
        taken, 1,
        "one Mountain, and neither the Wall nor the Mage is a mana route"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one red, which is exactly the {{R}} the ability charges"
    );

    activate(&mut engine, p0, blaster_mage(), 0);

    // CR 601.2c names the target and CR 601.2h pays everything else, so the two
    // questions are answered where they arrive rather than where they were
    // expected, and both halves of the price are read while the other question
    // is still open.
    let mut aimed = false;
    let mut discarded = false;
    for _ in 0..12 {
        if aimed && discarded {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player, options, ..
            } => {
                assert_eq!(player, p0, "the activating seat aims it");
                assert!(
                    options.contains(&mine) && options.contains(&theirs),
                    "\"target Wall\" is any Wall, on either side of the table: {options:?}"
                );
                assert!(
                    !options.contains(&elves),
                    "a Llanowar Elf is no Wall: {options:?}"
                );
                assert!(
                    !options.contains(&mage),
                    "a Human Spellshaper is no Wall either: {options:?}"
                );
                assert_eq!(
                    options.len(),
                    2,
                    "the two Walls are the whole menu: {options:?}"
                );
                assert!(
                    !is_tapped(&engine, mage),
                    "CR 601.2h pays last: the tap has not happened while the \
                     target is still being chosen"
                );
                assert_eq!(
                    engine.state().players[0].mana_pool.total(),
                    1,
                    "and neither has the {{R}}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![theirs],
                        },
                    )
                    .expect("the Wall across the table was one of the options");
                aimed = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(player, p0, "the activating seat gives up its own card");
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostDiscard,
                    "a cost and not a cleanup, which is all a client has to tell \
                     the two apart"
                );
                assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
                assert!(
                    options.contains(&fodder),
                    "the card in hand is the whole of the answer: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![fodder],
                        },
                    )
                    .expect("the card the question offered pays the cost");
                discarded = true;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while the Mage's ability is paid for: {other:?}"),
        }
    }
    assert!(
        aimed && discarded,
        "both halves of the activation were asked"
    );

    assert!(
        !stack_is_empty(&engine),
        "destroying a Wall is no mana ability, so the effect is on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, wall_of_roots()).is_some(),
        "the Wall that was named is destroyed, and it goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, wall_of_roots()).is_none(),
        "and it left the battlefield"
    );
    assert!(
        on_battlefield(&engine, p0, wall_of_roots()).is_some(),
        "the other Wall was not the target and is still standing"
    );
    assert!(
        in_graveyard(&engine, p0, forest()).is_some(),
        "\"Discard a card\" put the card in the graveyard of the seat that gave it up"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "the Elf was never a legal target and never moved"
    );
    assert!(is_tapped(&engine, mage), "{{T}} was paid");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{R}} came out of the pool"
    );
}

fn blistering_barrier() -> CardIndex {
    card_index("8783533d-dd98-4b80-b348-29051e1b5c28")
}

/// Blistering Barrier prints `{2}{R}` for a 5/2 Wall with defender: “This
/// creature can't attack.” That one line is the entire card profile, so it is
/// read during the combat step and not on the body: a Llanowar Elves stands
/// untapped next to it and is the control for the `attackers` offer actually
/// naming attackers — and the Barrier is not included in the *same* offer,
/// even though the test advances a full turn cycle first so that summoning
/// sickness (CR 302.6) doesn't play the role of the defender.
#[test]
fn blistering_barrier_is_a_five_two_defender_never_offered_as_an_attacker() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain(), llanowar_elves()])
        .hand(0, &[blistering_barrier()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Three Mountains produce {2}{R}. The Elf is held back by name because
    // `tap_all_mana` would also take its printed `{T}: Add {G}` (#159) — and
    // a creature tapped for mana would no longer be allowed to attack below.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Red),
        3,
        "three Mountains, three red — the Elf contributed nothing"
    );
    cast_with_floating(&mut engine, p0, blistering_barrier());
    pass_until(&mut engine, stack_is_empty);

    let barrier = on_battlefield(&engine, p0, blistering_barrier()).expect("die Barriere landete");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("der Elf steht noch");
    assert_eq!(pt(&engine, barrier), (5, 2), "der gedruckte 5/2-Körper");
    assert!(
        types(&engine, barrier).contains(TypeSet::CREATURE),
        "and what landed is a creature: {:?}",
        types(&engine, barrier)
    );
    assert!(
        keywords(&engine, barrier).contains(KeywordSet::DEFENDER),
        "with Defender on the projected card"
    );

    // A full turn cycle before the attack is read: the Barrier is
    // then no longer summoning sick, so "not offered" is a statement
    // about the printed text and not about the arrival turn.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until bleibt nur auf der Angriffserklärung stehen")
    };
    assert!(
        attackers.contains(&elf),
        "the untapped Elf without its own text is the control: {attackers:?}"
    );
    assert!(
        !attackers.contains(&barrier),
        "and the 5/2 with Defender is not in the same offer: {attackers:?}"
    );
}

fn blood_vassal() -> CardIndex {
    card_index("f792f40d-1d37-4854-98da-e4020c6a44d4")
}

/// Blood Vassal is a {2}{B} 2/2 Thrull whose whole printed text is one mana
/// ability: "Sacrifice this creature: Add {B}{B}." Both halves of that price
/// are the engine's answer rather than the card's, so one activation is read
/// against a board that can account for every drop of mana: three Swamps pay
/// for the creature and are left tapped, which is what makes the two black
/// that appear afterwards impossible to source from anywhere else.
///
/// The price is a sacrifice and not a tap, so `tap_all_mana` never presses it
/// (#159) and the pool is empty when the ability is claimed —
/// `legal.abilities` is filtered through `can_afford`, which reads the pool.
/// The empty stack afterwards is CR 605.3b, and the creature in its owner's
/// graveyard is the other half of the cost actually paid.
#[test]
fn blood_vassal_sacrifices_itself_for_two_black_mana() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[blood_vassal()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, blood_vassal());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let vassal = on_battlefield(&engine, p0, blood_vassal()).expect("the Vassal resolved");
    assert_eq!(pt(&engine, vassal), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Swamps paid the {{2}}{{B}} and nothing is left floating"
    );
    assert!(
        all_on_battlefield(&engine, p0, swamp())
            .iter()
            .all(|id| is_tapped(&engine, *id)),
        "and every Swamp is spent, so no black source is left standing on the board"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(vassal, 0)),
        "the one line the card prints is offered with an empty pool, because \
         its price is the creature and not its own tap: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, blood_vassal(), 0);

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        2,
        "Add {{B}}{{B}} — two black, and not one per activation"
    );
    assert_eq!(pool.total(), 2, "two black and nothing else came with them");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        on_battlefield(&engine, p0, blood_vassal()).is_none(),
        "sacrificing the creature is the whole of the price"
    );
    assert!(
        in_graveyard(&engine, p0, blood_vassal()).is_some(),
        "and a sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "the seat holds priority again, got {:?}",
        engine.pending()
    );
}

fn bog_witch() -> CardIndex {
    card_index("85573cba-07ae-4421-a167-a8569f85c0f7")
}

/// Bog Witch is a {2}{B} 1/1 printing `{B}, {T}, Discard a card: Add
/// {B}{B}{B}` — a *mana* ability (CR 605.1a), so all three printed parts of
/// the price have to be paid and the three black arrive with nothing on the
/// stack (CR 605.3b). Four Swamps pay the {2}{B} to cast her and leave
/// exactly the {B} the ability charges still floating in the same main phase
/// (CR 500.5), so the offer can only be read off the pool. The discard is a
/// cost and not a search, and the leftover {B} answers the price exactly:
/// one black spent, three returned, nothing else on the board.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn bog_witch_taps_discards_and_adds_three_black_without_using_the_stack() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(917, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp()])
        .hand(0, &[bog_witch(), forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Four Swamps, and the Witch is still in hand: `tap_all_mana` cannot press
    // her own `{B}, {T}, Discard a card` line because she is not a permanent
    // yet, so the cast takes {2}{B} out of the four and leaves the {B} the
    // ability charges floating beside it.
    cast_from_hand(&mut engine, p0, bog_witch());
    pass_until(&mut engine, stack_is_empty);
    let witch = on_battlefield(&engine, p0, bog_witch()).expect("the Witch resolved");
    assert!(!is_tapped(&engine, witch), "she arrives untapped");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "four Swamps less the {{2}}{{B}} the Witch cost"
    );

    // And with the mana right there she is still not offered, because the
    // price has a `{T}` in it and she arrived this turn (CR 302.6). That is
    // the assertion the turn cross below is *for*: without it, "the line is
    // offered" would have been read off a board where it could not be.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(witch, 0)),
        "summoning sickness refuses the {{T}}: {:?}",
        legal.abilities
    );

    // The opponent's turn first, and only then back: `walk_to_own_main`
    // alone returns where it stands, because this *is* p0's own main phase.
    reach_their_main_phase(&mut engine, PlayerId::new(1));
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the next own main phase, where she is no longer newly arrived"
    );
    let swamps = all_on_battlefield(&engine, p0, swamp());
    let one = swamps[0];
    tap_mana_where(&mut engine, p0, |id| id == one);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "exactly one Swamp tapped, which is the {{B}} the line charges"
    );

    // The price is a mana *and* the tap *and* a card, so the line is an
    // ordinary entry in `abilities` — a printed mana ability carries an index,
    // unlike the CR 305.6 shortcut a basic land uses.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(witch, 0)),
        "with {{B}} floating the whole cost is payable, so the one line she \
         prints is offered: {:?}",
        legal.abilities
    );
    assert!(
        !legal.mana_abilities.contains(&witch),
        "a printed mana ability is never the no-index shortcut: {:?}",
        legal.mana_abilities
    );

    let graveyard_before = engine.state().zones.list(ZoneLocation::Graveyard(p0)).len();
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    activate(&mut engine, p0, bog_witch(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "`Discard a card` is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostDiscard,
        "a cost and not a search, which is all a client has to tell them apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert_eq!(
        options.len(),
        hand_before,
        "the whole hand is the menu and the battlefield is not: {options:?}"
    );
    assert!(
        !options.contains(&witch),
        "the Witch is a permanent on the battlefield, not a card in hand: {options:?}"
    );

    let discarded = options[0];
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![discarded],
            },
        )
        .expect("a card the question offered is a legal answer");

    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "and the seat holds priority again, got {:?}",
        engine.pending()
    );
    assert!(
        is_tapped(&engine, witch),
        "{{T}} is half the price she printed"
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        3,
        "{{B}}{{B}}{{B}}: the one floating {{B}} paid the price and three came back"
    );
    assert_eq!(
        pool.total(),
        3,
        "and nothing beside it — the tapped Swamps are spent, not still floating"
    );
    assert!(
        engine
            .state()
            .zones
            .list(ZoneLocation::Graveyard(p0))
            .contains(&discarded),
        "the discarded card is in its owner's graveyard"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        graveyard_before + 1,
        "one card given up and none in beside it"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before - 1,
        "the hand is one shorter, which a card merely revealed would not do"
    );
    assert!(
        on_battlefield(&engine, p0, bog_witch()).is_some(),
        "the tap is the whole of what the Witch herself gives up"
    );
}

fn bogardan_firefiend() -> CardIndex {
    card_index("1d61f3a7-5861-479b-8312-f2d308c35b68")
}

/// Bogardan Firefiend — {2}{R}, a 2/1 Elemental Spirit whose whole text is
/// "When this creature dies, it deals 2 damage to target creature."
///
/// The trigger only exists if the creature really dies, so the scenario kills
/// it the only way a 2/1 dies on this board: it attacks and is blocked by a
/// 1/1, and the two trade. The second Elf across the table is what the
/// ability has to aim at — the blocker is already in the graveyard by the
/// time the trigger reaches the stack, so a Fiend read as "the creature it
/// fought" would have nothing left to point at.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn bogardan_firefiend_deals_two_to_a_creature_when_it_dies() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain()])
        .hand(0, &[bogardan_firefiend()])
        .battlefield(1, &[llanowar_elves(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, bogardan_firefiend());
    pass_until(&mut engine, stack_is_empty);
    let fiend = on_battlefield(&engine, p0, bogardan_firefiend()).expect("the Firefiend resolved");
    assert_eq!(pt(&engine, fiend), (2, 1), "the body the card prints");
    assert_eq!(
        all_on_battlefield(&engine, p1, llanowar_elves()).len(),
        2,
        "one Elf to block with and one to be aimed at"
    );

    // A whole turn cycle, so the Fiend is no longer summoning sick.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    let elves = all_on_battlefield(&engine, p1, llanowar_elves());
    let (blocker, bystander) = (elves[0], elves[1]);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on the attack declaration")
    };
    assert!(
        attackers.contains(&fiend),
        "an untapped 2/1 with no text of its own may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(fiend, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on the block declaration")
    };
    let option = blockers
        .iter()
        .find(|o| o.blocker == blocker)
        .expect("a 1/1 may block a 2/1");
    assert!(
        option.attackers.contains(&fiend),
        "and it may block this one: {:?}",
        option.attackers
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(blocker, fiend)],
            },
        )
        .unwrap();

    // The trade is simultaneous, and the dies trigger is the next thing the
    // stack asks about — the creature it traded with is already gone.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on the target choice")
    };
    assert_eq!(player, p0, "the Fiend's controller aims its own trigger");
    assert!(
        !options.contains(&blocker),
        "the Elf it traded with died in the same damage step: {options:?}"
    );
    assert!(
        options.contains(&bystander),
        "\"target creature\" reaches the other side of the table: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![bystander],
            },
        )
        .expect("the creature the question offered is a legal target");

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, bogardan_firefiend()).is_some(),
        "the 2/1 died to the block that killed it, which is what the trigger waits for"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "and the blocker went with it, in the same damage step"
    );
    assert!(
        all_on_battlefield(&engine, p1, llanowar_elves()).is_empty(),
        "the trigger's two damage killed the creature it was aimed at — an \
         Elf still standing here is the trigger that never fired"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the damage went to a creature and never to the player whose board it stood on"
    );
}

fn breathstealer() -> CardIndex {
    card_index("17d18e2f-2d8d-449e-9356-a7351bf0f8c2")
}

/// Breathstealer is a 2/2 Nightstalker for {2}{B} printing one line: "{B}:
/// This creature gets +1/-1 until end of turn."
///
/// Both halves of that pump have to be read off one board, so five Swamps pay
/// the cast and leave exactly the two {B} the ability charges in the pool: the
/// first activation has to leave the creature a 3/1 — power up *and* toughness
/// down, which a test that only looked at power would miss — on mana that was
/// really spent. The second activation is what says the toughness is being
/// subtracted rather than clamped, because a 2/2 pumped twice is a 4/0 and
/// CR 704.5f cannot leave that standing.
#[test]
fn breathstealer_trades_toughness_for_power_until_it_dies() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp(), swamp()])
        .hand(0, &[breathstealer()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{B} out of the five Swamps, leaving the two {B} the ability charges
    // beside it: CR 500.5 empties a pool at the end of a step, and the whole
    // scenario plays inside this one main phase.
    cast_from_hand(&mut engine, p0, breathstealer());
    pass_until(&mut engine, stack_is_empty);
    let creature = on_battlefield(&engine, p0, breathstealer()).expect("it resolved");
    assert_eq!(pt(&engine, creature), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "five Swamps less the {{2}}{{B}} the cast cost"
    );

    // The pump is no mana ability, so it only lands when it resolves.
    activate(&mut engine, p0, breathstealer(), 0);
    assert!(
        !stack_is_empty(&engine),
        "getting +1/-1 is an activated ability like any other"
    );
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, creature),
        (3, 1),
        "+1/-1 read as both numbers: a (3, 2) would mean the minus was dropped"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "and the {{B}} came out of the pool"
    );

    // A second activation is lethal, which is the only reading that says the
    // toughness is really being subtracted rather than floored at one.
    activate(&mut engine, p0, breathstealer(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, breathstealer()).is_none(),
        "a 2/2 pumped twice is a 4/0, which CR 704.5f cannot leave standing"
    );
    assert!(
        in_graveyard(&engine, p0, breathstealer()).is_some(),
        "and a creature that dies goes to its owner's graveyard"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the second {{B}} was paid, and nothing else was left in the pool"
    );
}

fn cabal_archon() -> CardIndex {
    card_index("7d80f016-5a4a-4843-9aec-0fe64f7f7ae8")
}

/// Cabal Archon — {2}{B} — 2/2 Human Cleric: "{B}, Sacrifice a Cleric: Target
/// player loses 2 life and you gain 2 life."
///
/// No part of the line is readable from the card. "Sacrifice a Cleric" names
/// no particular creature, so the engine must ask — and its menu is half the
/// card: both Clerics on this side are on it (the Archon itself is a Human
/// Cleric; the cost does not say "another"), while the Elf next to it
/// (a Druid) and the Cleric on the other side (CR 701.21a) are missing.
/// "Target player" is the second question and reaches both sides, and only
/// together with the sacrifice does the life total explain that two
/// *different* players are meant: one loses two, the other gains two — a line
/// that credited the two only to the target would leave p0 at 20. The {2}{B}
/// of the cast leaves exactly one {B} in the mana pool, so the cost of the
/// activation is a real payment and not a label.
#[test]
#[allow(clippy::too_many_lines)] // eine Aktivierung, zwei Fragen, und jede Klausel am Brett gelesen
fn cabal_archon_sacrifices_a_cleric_to_drain_two_life_and_gain_two() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                ondu_cleric(),
                llanowar_elves(),
            ],
        )
        // A Cleric on the table: "Sacrifice a Cleric" says nothing about
        // "you control", so it must stay out of the menu.
        .battlefield(1, &[ondu_cleric()])
        .hand(0, &[cabal_archon()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Four Swamps into the pool; the Elf remains untapped, because its
    // own `{T}: Add {G}` would otherwise have been tapped as well, and it
    // is the creature on which the sacrifice menu reads its "you control".
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "vier Sümpfe, und der Elf hat nichts beigesteuert"
    );
    cast_with_floating(&mut engine, p0, cabal_archon());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let archon = on_battlefield(&engine, p0, cabal_archon()).expect("the Archon resolved");
    let fodder = on_battlefield(&engine, p0, ondu_cleric()).expect("der Kleriker steht");
    let theirs = on_battlefield(&engine, p1, ondu_cleric()).expect("ihr Kleriker steht");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("der Elf steht");
    assert_eq!(pt(&engine, archon), (2, 2), "der gedruckte 2/2-Körper");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{2}}{{B}} has been spent and exactly the {{B}} that the \
         ability requires is still in the pool"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(archon, 0)),
        "with {{B}} in the pool, the only line of the card is in the offer: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, cabal_archon(), 0);

    // Two questions in one activation: whom it targets (CR 601.2c) and which
    // Cleric pays (CR 601.2h) — answered in the order they arrive, not in the
    // order one expects them.
    let mut asked_whom = false;
    let mut menu: Vec<ObjectId> = Vec::new();
    for _ in 0..16 {
        if asked_whom && !menu.is_empty() {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player,
                player_options,
                ..
            } => {
                assert_eq!(player, p0, "der aktivierende Platz zielt");
                assert!(
                    player_options.contains(&p0) && player_options.contains(&p1),
                    "\"target player\" erreicht beide Plätze: {player_options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseTargets {
                            objects: vec![],
                            players: vec![p1],
                        },
                    )
                    .unwrap();
                asked_whom = true;
            }
            Pending::ChoosePlayer { player, options } => {
                assert_eq!(player, p0, "der aktivierende Platz zielt");
                assert!(
                    options.contains(&p0) && options.contains(&p1),
                    "beide Plätze sind legal: {options:?}"
                );
                engine
                    .apply(player, PlayerAction::ChoosePlayer(p1))
                    .unwrap();
                asked_whom = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(player, p0, "der aktivierende Platz zahlt seine Kosten");
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostSacrifice,
                    "a question of cost and not a search, that is all a \
                     client can use to distinguish the two"
                );
                assert_eq!(
                    (min, max),
                    (1, 1),
                    "a Cleric, nothing more and nothing less"
                );
                menu = options;
                let paying = on_battlefield(&engine, p0, ondu_cleric())
                    .expect("der Kleriker steht noch zum Opfern");
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![paying],
                        },
                    )
                    .unwrap();
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while the Archon's activation resolves: {other:?}"),
        }
    }
    assert!(asked_whom, "\"target player\" ist eine Zielwahl");
    assert_eq!(
        menu.len(),
        2,
        "die beiden Kleriker, die dieser Platz kontrolliert: {menu:?}"
    );
    assert!(
        menu.contains(&fodder),
        "der Kleriker steht auf dem Menü: {menu:?}"
    );
    assert!(
        menu.contains(&archon),
        "and the Archon is a Human Cleric, so it appears on its own menu — \
         the cost does not say \"another\": {menu:?}"
    );
    assert!(
        !menu.contains(&elves),
        "der Elf ist ein Druide und kein Kleriker: {menu:?}"
    );
    assert!(
        !menu.contains(&theirs),
        "`CR 701.21a`: a Cleric on the other side is not to be sacrificed: {menu:?}"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[1].life,
        18,
        "\"target player loses 2 life\" — the seat that was named, not the other"
    );
    assert_eq!(
        engine.state().players[0].life,
        22,
        "and \"you gain 2 life\" belongs to the slot that paid the cost"
    );
    assert!(
        on_battlefield(&engine, p0, ondu_cleric()).is_none(),
        "der geopferte Kleriker hat das Schlachtfeld verlassen"
    );
    assert!(
        in_graveyard(&engine, p0, ondu_cleric()).is_some(),
        "and is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, cabal_archon()).is_some(),
        "the Archon ate the Cleric and not itself"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "and the creature that the menu never named is still there"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{B}} is spent, and no more was in the pool"
    );
}

fn capashen_templar() -> CardIndex {
    card_index("ab9ad5e2-2bf3-450d-9d5c-c7280d368e10")
}

/// Capashen Templar is `{2}{W}` for a 2/2 Human Knight with one printed line:
/// "{W}: This creature gets +0/+1 until end of turn." Two readings hold the
/// number down from either side — a `+1/+1` or a `+0/+2` in the card file
/// would both satisfy a test that only looked at the toughness — so the
/// assertion is on the pair, `(2, 2)` to `(2, 3)` with the power untouched.
/// The Llanowar Elves beside it is a creature under the same seat that "This
/// creature" must not reach, and it is kept out of the mana so that the four
/// white in the pool are the four tapped Plains: three pay the creature and
/// the last one pays the activation, which is what makes the empty pool
/// afterwards a claim about the printed `{W}` rather than about a free
/// ability. The turn boundary is played out because "until end of turn" is
/// the half of the sentence a permanent pump would quietly keep.
#[test]
fn capashen_templar_pays_white_for_one_toughness_on_itself_and_only_until_the_turn_ends() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[plains(), plains(), plains(), plains(), llanowar_elves()],
        )
        .hand(0, &[capashen_templar()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The Elf is the bystander and is named as the printing kept back: a
    // source tapped for mana is a creature whose status has already changed
    // for a reason of its own, and its own {G} would make "four white" a
    // claim about a pool nothing on the board accounted for.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four tapped Plains, four white, and the Elf contributed nothing"
    );
    cast_with_floating(&mut engine, p0, capashen_templar());
    pass_until(&mut engine, stack_is_empty);

    let templar = on_battlefield(&engine, p0, capashen_templar()).expect("the Templar resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is still out");
    assert_eq!(pt(&engine, templar), (2, 2), "the printed 2/2 body");
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "and the bystander it may not touch"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "{{2}}{{W}} is three of the four, so one white is left for the ability"
    );

    // Ability 0 is the only line the card prints, and it targets nothing: the
    // pump is aimed at its own source by `Filter::This`, so no target
    // question stands between the activation and its payment.
    activate(&mut engine, p0, capashen_templar(), 0);
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, templar),
        (2, 3),
        "+0/+1 on this creature — a (3, 3) would mean the power was read too"
    );
    assert_eq!(
        pt(&engine, elves),
        (1, 1),
        "\"This creature\" is not \"creatures you control\": the Elf is untouched"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{W}} came out of the pool, so the price is real"
    );

    // The effect's duration. The whole of p0's turn is played out — combat
    // asks for attackers and blockers on the way and answers both empty —
    // because a pump that had no duration would still be standing here.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, templar),
        (2, 2),
        "\"until end of turn\": the toughness is the printed one again"
    );
}

fn charging_paladin() -> CardIndex {
    card_index("6cccf44e-c05e-4239-b643-54b559c98552")
}

/// Charging Paladin — {2}{W}, a 2/2 Human Knight with "Whenever this
/// creature attacks, it gets +0/+3 until end of turn."
///
/// The pump is only visible on the attack and must hit the Paladin and no
/// one else: the (2, 2) before the attack and the Llanowar Elves, which
/// remains (1, 1) under the same control, are the two sides of the same
/// claim — the +0/+3 come from the attack trigger and not from a static
/// ability on the whole battlefield. The final step reads "until end of
/// turn" a second time, where an expired pump showed 2/2 again.
#[test]
fn charging_paladin_pumps_itself_when_it_attacks_and_no_other_creature() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains(), quiet_creature()])
        .hand(0, &[charging_paladin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{W} off the three Plains, with the Elf named as the printing kept
    // back: it is the control the pump is read against, and a source tapped
    // for mana could not attack or block afterwards.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Plains, and the Elf kept standing"
    );
    cast_with_floating(&mut engine, p0, charging_paladin());
    pass_until(&mut engine, stack_is_empty);

    let paladin = on_battlefield(&engine, p0, charging_paladin()).expect("the Paladin resolved");
    let elf = on_battlefield(&engine, p0, quiet_creature()).expect("the Elf is still out");
    assert_eq!(
        pt(&engine, paladin),
        (2, 2),
        "a printed 2/2 before it attacks"
    );
    assert_eq!(pt(&engine, elf), (1, 1), "and nothing beside it is pumped");

    // CR 302.6: a creature that arrived this turn cannot attack, so the turn
    // goes round once first. Both halves are needed — `walk_to_own_main` on
    // its own returns where it stands, because this already *is* p0's own
    // main phase.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&paladin),
        "an untapped 2/2 may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(paladin, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The attack trigger is on the stack the moment attackers are declared,
    // and the pump is what is waiting there.
    pass_until(&mut engine, |e| !stack_is_empty(e));
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, paladin),
        (2, 5),
        "+0/+3 on the creature that attacked, and never a power pump"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the +0/+3 reaches the creature that attacked and no other"
    );

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        pt(&engine, paladin),
        (2, 5),
        "the pump is still in force in the end step: until end of turn"
    );
}

fn coastal_drake() -> CardIndex {
    card_index("d4220231-e9ac-4390-8c7b-979549b26d33")
}

/// Coastal Drake is a {2}{U} 2/1 Drake with flying whose whole text is one
/// line: "{1}{U}, {T}: Return target Kavu to its owner's hand." The word that
/// needs a witness is "Kavu", and this pool prints none — but Mutavault
/// animated by its own {1} ability is a 2/2 with *all* creature types, so it
/// is one, while the Elf beside it is a creature and no Kavu. So the ability
/// has to take the first and decline the second, tap the Drake for its {T},
/// spend exactly {1}{U}, and leave the land in its owner's hand and the Elf
/// where it stood.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn coastal_drake_bounces_an_animated_mutavault_and_declines_the_elf_beside_it() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, island())
        .battlefield(
            0,
            &[
                island(),
                island(),
                island(),
                island(),
                island(),
                mutavault(),
                coastal_drake(),
                llanowar_elves(),
            ],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let drake = on_battlefield(&engine, p0, coastal_drake()).expect("the Drake is on the table");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("an Elf stands beside it");
    let vault = on_battlefield(&engine, p0, mutavault()).expect("the Mutavault is out");
    assert_eq!(pt(&engine, drake), (2, 1), "the printed 2/1 body");
    assert!(
        keywords(&engine, drake).contains(KeywordSet::FLYING),
        "and the printed flying"
    );

    // `{1}{U}, {T}` is read off the *pool*, so the mana is floated before
    // anything is claimed about the offer. The Mutavault is the one source
    // kept back: its own animation is the next thing this test does, and
    // tapping it for {C} would make the pool a claim about a land that has
    // already been spent. The Drake prints no mana ability at all, so it
    // stands either way.
    tap_all_mana_but(&mut engine, p0, Some(mutavault()));
    let floating = engine.state().players[0].mana_pool.total();
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        5,
        "five Islands, five blue — the Elf beside them is a mana source too, \
         which is why the pool is counted as a whole below"
    );

    // Mutavault's animation is the only Kavu this pool can put on a
    // battlefield, and `Filter::HasSubtype(Kavu)` is what reads "all creature
    // types". Ability 0 is its `{T}: Add {C}`, ability 1 the animation.
    activate(&mut engine, p0, mutavault(), 1);
    // The animation is an ordinary activated ability and uses the stack
    // (CR 605.1a makes the exception a *mana* ability, which this is not),
    // so the land is still a land until it resolves.
    assert!(
        !types(&engine, vault).contains(TypeSet::CREATURE),
        "announced and not yet resolved: the land is still only a land"
    );
    pass_until(&mut engine, stack_is_empty);
    assert!(
        types(&engine, vault).contains(TypeSet::CREATURE),
        "the land is a creature now"
    );

    activate(&mut engine, p0, coastal_drake(), 0);
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!(
            "\"target Kavu\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert!(
        options.contains(&vault),
        "a creature with all creature types is a Kavu: {options:?}"
    );
    assert!(
        !options.contains(&elf),
        "the Elf is a creature and no Kavu — the filter is read, not skipped: {options:?}"
    );
    assert!(
        !options.contains(&drake),
        "a Drake is not a Kavu either: {options:?}"
    );

    // CR 601.2c before CR 601.2h: the target is named while the Drake is
    // still untapped, so the tap is read after the answer.
    assert!(
        !is_tapped(&engine, drake),
        "the tap is the last step of the activation, not the first"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![vault],
            },
        )
        .expect("the animated land was one of the options");
    assert!(
        is_tapped(&engine, drake),
        "{{T}} is paid once the target is chosen"
    );
    assert!(!stack_is_empty(&engine), "and bouncing is no mana ability");

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_hand(&engine, p0, mutavault()).is_some(),
        "\"return target Kavu to its owner's hand\""
    );
    assert!(
        on_battlefield(&engine, p0, mutavault()).is_none(),
        "the land left the battlefield"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the creature nobody named never moved"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        floating - 3,
        "{{1}} for the animation and {{1}}{{U}} for the ability: three mana \
         and not one more"
    );
}

fn council_of_advisors() -> CardIndex {
    card_index("ff427657-173a-4845-89af-6f0a93467130")
}

/// Council of Advisors — {2}{U}, a 1/1 Human Advisor: "When this creature
/// enters, draw a card." Nothing about a 1/1 for three is visible on the
/// board, so the trigger is read where it lands: the library is exactly one
/// card shorter and the hand holds exactly as many cards as before, because
/// the Advisor left the hand for the battlefield and its own arrival drew the
/// replacement. "Exactly one" is the whole claim — a trigger that never fired
/// leaves the library untouched, and one read as a repeatable draw would leave
/// the hand longer than it started.
#[test]
fn council_of_advisors_draws_a_card_when_it_enters() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island()])
        .hand(0, &[council_of_advisors()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();
    let library_before = library_size(&engine, p0);
    let their_library_before = library_size(&engine, p1);

    cast_from_hand(&mut engine, p0, council_of_advisors());
    pass_until(&mut engine, stack_is_empty);

    let advisor = on_battlefield(&engine, p0, council_of_advisors()).expect("the Advisor resolved");
    assert_eq!(pt(&engine, advisor), (1, 1), "the printed body");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Islands paid {{2}}{{U}}"
    );
    assert!(
        in_hand(&engine, p0, council_of_advisors()).is_none(),
        "the card it was cast from is the permanent on the table, not a card in hand"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"draw a card\" — one card off the top of the library, and not two"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before,
        "the Advisor left the hand and the card it drew took its place"
    );
    assert_eq!(
        library_size(&engine, p1),
        their_library_before,
        "\"draw a card\" on an enters trigger is the controller's: the \
         opponent's library is where it was"
    );
}

fn devout_witness() -> CardIndex {
    card_index("83647f5b-2b0f-4f9d-83c5-75c52460f35b")
}

/// Devout Witness — {2}{W}, a 2/2 Human Spellshaper: "{1}{W}, {T}, Discard a
/// card: Destroy target artifact or enchantment."
///
/// Three parts of one price are read in one activation, each in a different
/// place: the {1}{W} out of a pool the four Plains actually filled, the tap
/// symbol on the Witness itself, and the discarded card in its owner's
/// graveyard. The filter is the other half, and it needs bystanders on both
/// sides — the offer must hold the artifact *and* the enchantment standing
/// across the table while declining the Elf between them, because a creature
/// is neither one. Only the artifact is named, so exactly one permanent leaves
/// the battlefield and the enchantment is what says "target" is singular.
#[test]
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
fn devout_witness_discards_and_taps_to_destroy_the_artifact_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[plains(), plains(), plains(), plains(), devout_witness()],
        )
        .battlefield(
            1,
            &[quiet_artifact(), their_enchantment(), quiet_creature()],
        )
        .hand(0, &[festering_goblin()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let witness = on_battlefield(&engine, p0, devout_witness()).expect("the Witness is out");
    let artifact = on_battlefield(&engine, p1, quiet_artifact()).expect("their artifact is out");
    let enchantment =
        on_battlefield(&engine, p1, their_enchantment()).expect("their enchantment is out");
    let their_elf = on_battlefield(&engine, p1, quiet_creature()).expect("their creature is out");
    let fodder = in_hand(&engine, p0, festering_goblin()).expect("the card to discard is in hand");

    // `legal.abilities` is filtered through `can_afford`, which reads the pool
    // and not the untapped lands (CR 601.2h), so the mana comes first.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        4,
        "four Plains tapped, and the Witness makes no mana of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(witness, 0)),
        "with {{1}}{{W}} floating the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, devout_witness(), 0);

    // The two questions one activation asks — which permanent (CR 601.2c) and
    // which card is given up (CR 601.2h) — answered in the order they arrive
    // rather than in the order they are expected.
    let (mut aimed, mut discarded) = (false, false);
    for _ in 0..12 {
        if aimed && discarded {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player,
                options,
                min,
                max,
                ..
            } => {
                assert_eq!((min, max), (1, 1), "one artifact or enchantment");
                assert!(
                    options.contains(&artifact),
                    "\"target artifact\" reaches across the table: {options:?}"
                );
                assert!(
                    options.contains(&enchantment),
                    "and so does \"or enchantment\": {options:?}"
                );
                assert!(
                    !options.contains(&their_elf),
                    "a creature is neither of the two: {options:?}"
                );
                assert!(
                    !options.contains(&witness),
                    "the Witness is a creature and no artifact: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![artifact],
                        },
                    )
                    .expect("the permanent the question offered is the one that dies");
                aimed = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostDiscard,
                    "a cost and not a loot: the card is given up, not cycled"
                );
                assert_eq!((min, max), (1, 1), "exactly one card, no more and no fewer");
                assert!(
                    options.contains(&fodder),
                    "the hand the seat is holding is the menu: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![fodder],
                        },
                    )
                    .expect("the card the question offered pays the cost");
                discarded = true;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while the Witness' ability resolves: {other:?}"),
        }
    }
    assert!(aimed, "the target is chosen as the ability is announced");
    assert!(discarded, "and a card is given up to pay for it");

    assert!(
        !stack_is_empty(&engine),
        "destroying is no mana ability, so the ability is what is waiting"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        is_tapped(&engine, witness),
        "{{T}} is the other half of the price, paid by the Witness itself"
    );
    assert!(
        in_graveyard(&engine, p0, festering_goblin()).is_some(),
        "\"Discard a card\" — the discarded card is in its owner's graveyard"
    );
    assert!(
        in_graveyard(&engine, p1, quiet_artifact()).is_some(),
        "the artifact that was named is destroyed and went to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, their_enchantment()).is_some(),
        "one target, one destruction: the enchantment the ability did not name never moved"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_creature()).is_some(),
        "nor did the creature, which was never a legal target"
    );
    assert!(
        on_battlefield(&engine, p0, devout_witness()).is_some(),
        "the Witness survives its own ability"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        2,
        "{{1}}{{W}} came out of the four white that were floating"
    );
}

fn diving_griffin() -> CardIndex {
    card_index("8785f9b4-eea2-4b45-9ae4-194b9a715702")
}

/// Diving Griffin is `{1}{W}{W}` for a 2/2 Griffin with flying and vigilance,
/// and the two printed keywords are proven the two different ways this rig
/// can: flying is a characteristic the layer system projects, so it is read
/// off `characteristics().keywords`, while vigilance is a *behaviour* —
/// CR 508.1f taps an attacker as it is declared and CR 702.20 is the
/// exception — so the Griffin is declared as an attacker and read afterwards,
/// still standing and still having dealt its two damage. The three Plains are
/// the whole payment and no other permanent on the board makes mana or has a
/// keyword, so every number here belongs to the card and nothing else.
#[test]
fn diving_griffin_attacks_and_stays_untapped() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(4711, plains())
        .battlefield(0, &[plains(), plains(), plains()])
        .hand(0, &[diving_griffin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Three Plains pay exactly `{1}{W}{W}`, and `cast_from_hand` taps them
    // before the cast, so the spell comes off mana that is really floating.
    cast_from_hand(&mut engine, p0, diving_griffin());
    pass_until(&mut engine, stack_is_empty);
    let griffin = on_battlefield(&engine, p0, diving_griffin()).expect("the Griffin resolved");
    assert_eq!(pt(&engine, griffin), (2, 2), "the body the card prints");
    assert!(
        types(&engine, griffin).contains(TypeSet::CREATURE),
        "and it is the creature it prints"
    );
    let granted = keywords(&engine, griffin);
    assert!(
        granted.contains(KeywordSet::FLYING),
        "Flying, read through the layers: {granted:?}"
    );
    assert!(
        granted.contains(KeywordSet::VIGILANCE),
        "and vigilance, which the combat step below puts to work: {granted:?}"
    );
    assert!(
        !is_tapped(&engine, griffin),
        "it entered untapped, so there is a `{{T}}` for the combat step to spend"
    );

    // CR 302.6: a creature that arrived this turn cannot attack, so the turn
    // goes round once first. Both halves are needed — `walk_to_own_main` on
    // its own returns where it stands, because this already *is* p0's own
    // main phase.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until only stops on the attack declaration")
    };
    assert!(
        attackers.contains(&griffin),
        "an untapped 2/2 with no summoning sickness may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(griffin, Defender::Player(p1))],
            },
        )
        .unwrap();

    // CR 508.1f taps an attacker as it is declared, and vigilance is the
    // printed exception — read here, the moment the declaration has landed,
    // because that is the only reading that tells it from a creature that
    // simply was never tapped.
    assert!(
        !is_tapped(&engine, griffin),
        "vigilance: the Griffin attacks and stays standing"
    );

    // Not `stack_is_empty`: the stack is empty the moment attackers are
    // declared, so that would stop *before* the combat damage step. The end
    // step is past damage (CR 510.2).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        18,
        "two combat damage off the Griffin's printed power"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing came back for it: the damage is one-way"
    );
    assert!(
        !is_tapped(&engine, griffin),
        "still untapped at the end step, which is what vigilance bought — a \
         creature without it would have been tapped by its own declaration"
    );
    assert!(
        on_battlefield(&engine, p0, diving_griffin()).is_some(),
        "and the Griffin is still on the battlefield it attacked from"
    );
}

fn dogged_hunter() -> CardIndex {
    card_index("cf5b3249-619f-48f5-8885-00fd41d24825")
}

/// Dogged Hunter — {2}{W} 1/1 Human Nomad: "{T}: Destroy target creature
/// token." Neither word of that reads off the card file, so the scenario
/// plays the token into existence first: Thopter Foundry's own activated
/// ability eats a Sol Ring and leaves a Thopter, which is the only creature
/// token in the game and therefore the only thing the Hunter's filter may
/// name. The Llanowar Elves standing beside it are the control — a filter
/// that had lost `Filter::IsToken` would offer the same printed 1/1 — and the
/// {T} is read where CR 601.2h puts it: after the target question, with the
/// token already off the battlefield and the Elves still on it.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn dogged_hunter_destroys_a_creature_token_and_not_the_creature_beside_it() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                forest(),
                forest(),
                dogged_hunter(),
                thopter_foundry(),
                quiet_artifact(),
                quiet_creature(),
            ],
        )
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let hunter = on_battlefield(&engine, p0, dogged_hunter()).expect("the Hunter is seated");
    let elves = on_battlefield(&engine, p0, quiet_creature()).expect("the Elves are standing");
    let ring = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring is out");
    assert!(
        !is_tapped(&engine, hunter),
        "nothing has paid the Hunter's {{T}} yet"
    );

    // {1} for the Foundry, out of a pool the two Forests actually filled —
    // and a source it did not have to count on, because a Sol Ring tapped for
    // mana is a Sol Ring that can no longer be the sacrifice this token is
    // made of. So the artifact is the printing kept back, and the mana for the
    // Foundry comes off the lands and the Elf beside it.
    tap_all_mana_but(&mut engine, p0, Some(quiet_artifact()));
    assert!(
        engine.state().players[0].mana_pool.total() >= 1,
        "two Forests and one Llanowar Elves is three mana, and the Foundry \
         charges one: {:?}",
        engine.state().players[0].mana_pool
    );
    activate(&mut engine, p0, thopter_foundry(), 0);
    let Pending::ChooseCards {
        options,
        min,
        max,
        prompt,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "the Foundry asks which artifact to eat, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(
        prompt,
        ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
    assert!(
        options.contains(&ring),
        "the Sol Ring is the fodder this scenario is built around: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![ring],
            },
        )
        .expect("the artifact the question offered pays the cost");
    pass_until(&mut engine, stack_is_empty);

    let tokens = tokens_of(&engine, p0);
    assert_eq!(
        tokens.len(),
        1,
        "one activation of the Foundry, one Thopter — the only creature token \
         in the game, and so the only thing the Hunter may name"
    );
    let thopter = tokens[0];
    assert!(
        types(&engine, thopter).contains(TypeSet::CREATURE),
        "an artifact *creature* token, so \"target creature token\" has a target"
    );

    // The offer is read off the board the Hunter stands on; its whole price is
    // its own {T} and it still has it.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(hunter, 0)),
        "the one line the card prints is offered: {:?}",
        legal.abilities
    );
    activate(&mut engine, p0, dogged_hunter(), 0);

    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature token\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "exactly one creature token");
    assert!(
        player_options.is_empty(),
        "the card names no player, so no player is on the menu: {player_options:?}"
    );
    assert!(
        options.contains(&thopter),
        "the token the Foundry made is a creature token: {options:?}"
    );
    assert!(
        !options.contains(&elves),
        "a printed 1/1 that is no token is not a creature token, so it is not \
         on the menu: {options:?}"
    );
    assert_eq!(
        options.len(),
        1,
        "and the token is the whole of it — no artifact, no land, and not the \
         Hunter itself, which is a creature and no token: {options:?}"
    );
    assert!(
        !is_tapped(&engine, hunter),
        "CR 601.2c before CR 601.2h: the target is named before the tap is paid"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![thopter],
            },
        )
        .expect("the token the question offered was chosen");
    assert!(
        is_tapped(&engine, hunter),
        "{{T}} is the whole price, and the last step of the activation is \
         where it is paid (CR 601.2h)"
    );
    assert!(
        !stack_is_empty(&engine),
        "destroying a creature is no mana ability, so it uses the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        tokens_of(&engine, p0).is_empty(),
        "the token left the battlefield: nothing on this side is a token"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_creature()).is_some(),
        "the creature the ability did not name never moved"
    );
    assert!(
        on_battlefield(&engine, p0, dogged_hunter()).is_some(),
        "and the Hunter outlives what it aimed at"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        1,
        "the Sol Ring the Foundry ate is the only card in the graveyard: a \
         destroyed token ceases to exist (CR 704.5d) rather than being buried"
    );
}

fn drake_hatchling() -> CardIndex {
    card_index("bd55bcc4-f0c5-4c09-8b3b-2e25e9fbd9ee")
}

/// Drake Hatchling is a {2}{U} 1/3 Drake with flying whose only other text is
/// "{U}: This creature gets +1/+0 until end of turn. Activate only once each
/// turn." Five Islands are tapped in one go: three pay for the Drake and the
/// two left floating are what the pump draws on, so the one blue still in the
/// pool after the pump is the control that makes the ability's disappearance a
/// statement about the printed once-a-turn limit rather than about a cost the
/// board could not pay — `legal.abilities` is filtered through `can_afford`,
/// which reads the mana pool and not the untapped lands. The whole scenario
/// stays in this one main phase, so CR 500.5 never empties what is left over.
#[test]
fn drake_hatchling_pumps_once_a_turn_off_a_pool_that_could_still_pay_again() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), island(), island()])
        .hand(0, &[drake_hatchling()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "five Islands, and the Drake is not on the table yet"
    );
    cast_with_floating(&mut engine, p0, drake_hatchling());
    pass_until(&mut engine, stack_is_empty);
    let drake = on_battlefield(&engine, p0, drake_hatchling()).expect("the Drake resolved");
    assert_eq!(pt(&engine, drake), (1, 3), "the body the card prints");
    assert!(
        keywords(&engine, drake).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "five Islands less the {{2}}{{U}} the Drake cost"
    );

    // Ability 0 is the only line the card prints, and the offer is read off
    // the mana already floating rather than off the untapped lands.
    activate(&mut engine, p0, drake_hatchling(), 0);
    assert!(
        !stack_is_empty(&engine),
        "a pump is no mana ability, so it uses the stack"
    );
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, drake), (2, 3), "+1/+0 until end of turn");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{U}} came out of the pool"
    );

    // The second activation is the claim. One blue is still floating, so
    // `can_afford` has everything it needs: the ability's absence is the
    // printed "activate only once each turn" and nothing else.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == drake),
        "`{{U}}`: +1/+0 has been taken for this turn, so it is not offered \
         again even with the mana to pay it: {:?}",
        legal.abilities
    );
}

fn dusk_imp() -> CardIndex {
    card_index("1389ae4a-c3a5-4678-9012-937a3cbaf7f7")
}

/// Dusk Imp is the whole card in its cost and its keyword: `{2}{B}` for a 2/1
/// Imp with flying. Casting it spends exactly the three Swamps the Elf beside
/// them is kept out of, and the body is read off the *projection*, so an Imp
/// that arrives but never carries its keyword cannot pass. The combat step a
/// turn later — needed because a creature cast this turn may not attack
/// (CR 302.6) — is what makes flying an effect rather than a characteristic:
/// both creatures attack, and the defender's printed 1/1 Elf is offered as a
/// blocker for the ground attacker while the flier is declined (CR 702.9a).
#[test]
fn dusk_imp_lands_as_a_flying_two_one_that_a_ground_creature_cannot_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[dusk_imp()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{B} off the three Swamps. The Elf is named as the thing kept back
    // because it is the creature that has to attack beside the Imp next turn.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Black),
        3,
        "three Swamps, and the Elf beside them still standing"
    );
    cast_with_floating(&mut engine, p0, dusk_imp());
    pass_until(&mut engine, stack_is_empty);

    let imp = on_battlefield(&engine, p0, dusk_imp()).expect("the Imp resolved");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(pt(&engine, imp), (2, 1), "the printed 2/1 body");
    assert!(
        types(&engine, imp).contains(TypeSet::CREATURE),
        "and the type line it was played for"
    );
    assert!(
        keywords(&engine, imp).contains(KeywordSet::FLYING),
        "`flying` reaches the permanent through the layers"
    );

    // A full turn cycle: the Imp was cast this turn and a creature that has
    // not been under its controller's control since their turn began cannot
    // attack (CR 302.6) or use a {T} ability.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::ChooseAttackers { player, .. } if *player == p0),
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(imp, Defender::Player(p1)), (mine, Defender::Player(p1))],
            },
        )
        .expect("both are untapped and have been controlled since the turn began");
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });

    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        panic!(
            "the defending seat is asked which of its creatures block, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p1, "the seat being attacked declares the blocks");
    let ground = blockers
        .iter()
        .find(|option| option.blocker == theirs)
        .expect("the Elf across the table may block something");
    assert!(
        ground.attackers.contains(&mine),
        "the ground attacker is one it may block, so the list is not empty for \
         the wrong reason: {:?}",
        ground.attackers
    );
    assert!(
        !ground.attackers.contains(&imp),
        "`flying` is the whole of the Imp's text, and a creature with neither \
         flying nor reach cannot block it (CR 702.9a): {:?}",
        ground.attackers
    );
}

fn dwarven_bloodboiler() -> CardIndex {
    card_index("cbbca098-0b33-4693-8ea7-a2005b79af3d")
}

/// Dwarven Bloodboiler costs `{R}{R}{R}` and is a 2/2 Dwarf with an
/// activated ability: "Tap an untapped Dwarf you control: Target creature
/// gets +2/+0 until end of turn." The card's text line does not answer the
/// cost itself — *which* Dwarf and whether the Elf next to it is one is only
/// in the offer —, so there are two Dwarf controls: the Armorer as the Dwarf
/// to tap, and one Llanowar Elves each below and above the table, both of
/// which are not Dwarfs. `+2/+0` on a printed 1/1 reads as `(3, 1)`; a
/// `(3, 3)` would be a boost that the card does not print.
#[test]
#[allow(clippy::too_many_lines)] // eine Aktivierung, beide Fragen und jede gedruckte Klausel daran gelesen
fn dwarven_bloodboiler_taps_a_dwarf_you_control_to_pump_a_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                dwarven_armorer(),
                llanowar_elves(),
            ],
        )
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[dwarven_bloodboiler()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The {R}{R}{R} from the three Mountains: the Dwarf enters, as a
    // creature enters, and neither the Armorer nor the Elf next to it tapped
    // for it.
    cast_from_hand(&mut engine, p0, dwarven_bloodboiler());
    pass_until(&mut engine, stack_is_empty);
    let boiler =
        on_battlefield(&engine, p0, dwarven_bloodboiler()).expect("the Bloodboiler resolved");
    let dwarf = on_battlefield(&engine, p0, dwarven_armorer()).expect("the Armorer is out");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(pt(&engine, mine), (1, 1), "a printed 1/1 before the pump");
    assert!(
        !is_tapped(&engine, dwarf),
        "the Dwarf the cost wants is untapped"
    );

    activate(&mut engine, p0, dwarven_bloodboiler(), 0);

    // Two questions, in the order the rules give them — the target at
    // CR 601.2c and the tap symbol at CR 601.2h —, answered as they
    // arrive.
    let mut aimed = false;
    let mut menu: Vec<ObjectId> = Vec::new();
    for _ in 0..12 {
        if aimed && !menu.is_empty() {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player, options, ..
            } => {
                assert_eq!(player, p0, "der aktivierende Sitz zielt selbst");
                assert!(
                    options.contains(&mine) && options.contains(&theirs),
                    "\"target creature\" is any creature, on either side of the table: \
                     {options:?}"
                );
                assert!(
                    options.contains(&boiler),
                    "and the Bloodboiler is itself a creature: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![mine],
                        },
                    )
                    .unwrap();
                aimed = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(player, p0, "the activating seat pays its own cost");
                assert_eq!(
                    prompt,
                    ChoicePrompt::CostTap,
                    "a cost and not a search — and the variant is everything \
                     by which a client recognizes that the response is not \
                     lost"
                );
                assert_eq!((min, max), (1, 1), "a Dwarf, no more and no less");
                menu = options;
                assert!(
                    !is_tapped(&engine, dwarf),
                    "the question stands before the cost is paid"
                );
                assert_eq!(
                    pt(&engine, mine),
                    (1, 1),
                    "and the pump only drops when the ability is resolved"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![dwarf],
                        },
                    )
                    .unwrap();
            }
            other => panic!("unerwartet zwischen den zwei Fragen einer Aktivierung: {other:?}"),
        }
    }
    assert!(aimed, "the pump has a target");
    assert!(!menu.is_empty(), "the tap cost is queried");
    assert!(
        menu.contains(&dwarf),
        "ein Zwerg unter eigener Kontrolle ist die ganze Antwort: {menu:?}"
    );
    assert!(
        !menu.contains(&mine) && !menu.contains(&theirs),
        "\"an untapped **Dwarf** you control\": no Llanowar Elves, and the one \
         across the table is not yours anyway: {menu:?}"
    );

    assert!(
        !stack_is_empty(&engine),
        "paying the cost is not resolving the ability"
    );
    assert_eq!(pt(&engine, mine), (1, 1), "also ist noch nichts gepumpt");
    assert!(is_tapped(&engine, dwarf), "the tap symbol was the cost");
    assert!(
        !is_tapped(&engine, boiler),
        "the Bloodboiler paid nothing: the cost is *another* creature"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, mine),
        (3, 1),
        "+2/+0 on the creature the ability named — (3, 3) would be a \
         boost that the card does not print"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "and nothing on the creature that it did not name"
    );
}

// oracle_id = "caf3c6ec-d17e-497c-8fe7-6f818ce93f96"
fn dwarven_demolition_team() -> CardIndex {
    card_index("caf3c6ec-d17e-497c-8fe7-6f818ce93f96")
}

/// Dwarven Demolition Team is a 1/1 Dwarf printing one line: "{T}: Destroy
/// target Wall." The scenario plays exactly that, and the board is built so
/// that both halves of the sentence have to come from the engine rather than
/// from the card file. The whole price is the Dwarf's own `{T}`, so the empty
/// pool is the point: the offer cannot be an affordability accident. And
/// "Wall" is a *subtype*, so an untargeted Llanowar Elves stands on each side
/// of the table as the control — a filter that had widened to any creature
/// would offer both of them.
#[test]
fn dwarven_demolition_team_taps_to_destroy_a_wall_and_no_other_creature() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let wall = card_index("3a21a6ae-b2f2-4f0c-acfd-5f3e8d63fd2f");
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[dwarven_demolition_team(), llanowar_elves()])
        .battlefield(1, &[wall, llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let dwarf = on_battlefield(&engine, p0, dwarven_demolition_team()).expect("the Dwarf is out");
    let my_elves = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let their_wall = on_battlefield(&engine, p1, wall).expect("their Wall is out");
    let their_elves = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");

    // `{T}` and nothing else, so nothing has to be tapped first: a pool of
    // zero says the offer below is about the tap symbol and not about mana.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the whole price is the tap, so no mana floats for this"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(dwarf, 0)),
        "an untapped Dwarf on an empty pool is offered its one line: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, dwarven_demolition_team(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target Wall\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that chooses");
    assert!(
        options.contains(&their_wall),
        "\"target Wall\" reaches the Wall across the table: {options:?}"
    );
    assert!(
        !options.contains(&my_elves) && !options.contains(&their_elves),
        "a subtype and not \"target creature\": the Elves on either side are no \
         Wall: {options:?}"
    );
    assert_eq!(
        options.len(),
        1,
        "the Wall is the whole menu on this board: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![their_wall],
            },
        )
        .expect("the Wall was one of the options it enumerated");
    // CR 601.2h: the {T} is the last step of the activation, so it is read
    // after the target question has been answered.
    assert!(is_tapped(&engine, dwarf), "{{T}} was the cost");
    assert!(
        !stack_is_empty(&engine),
        "destroying a permanent is no mana ability, so the ability is waiting"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, wall).is_none(),
        "the targeted Wall left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p1, wall).is_some(),
        "and went to its owner's graveyard, which is the seat that controlled it"
    );
    assert!(
        on_battlefield(&engine, p0, dwarven_demolition_team()).is_some(),
        "the Dwarf is untouched — the ability destroys its target and nothing else"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the creature the ability did not name never moved"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "on either side of the table"
    );
}

fn ertai_wizard_adept() -> CardIndex {
    card_index("f2902dfd-888f-4b02-b8ad-1056f0059fc3")
}

/// Ertai, Wizard Adept is a legendary 1/1 whose whole text is
/// "`{2}{U}{U}`, `{T}`: Counter target spell." — a card that only exists at
/// the moment somebody else's spell is on the stack. The scenario builds
/// exactly that: seven untapped Islands and the Wizard already in play, and
/// p1 casting Dark Ritual — a spell with no target whose resolution would be
/// legible as three black mana in p1's pool — inside p0's own main phase, so
/// the mana p0 floats survives the pass. The offer is read on both sides of
/// the tap for the same reason `claws_of_gix` reads it twice: with an empty
/// pool the ability is *absent* from `LegalActions::abilities` (`can_afford`
/// looks at the pool, not at untapped lands) and it appears the moment four
/// of the seven float, which is what says the four mana are a price and not
/// a label. The tap and the {2}{U}{U} are asserted after the target is
/// answered, because CR 601.2c picks the target and CR 601.2h pays last, and
/// what the card does is then the only thing left to see: Dark Ritual in its
/// owner's graveyard, its black mana never arriving, and Ertai still standing.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn ertai_wizard_adept_counters_a_spell_for_four_mana_and_its_own_tap() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(
            0,
            &[
                island(),
                island(),
                island(),
                island(),
                island(),
                island(),
                island(),
                ertai_wizard_adept(),
            ],
        )
        .battlefield(1, &[swamp()])
        .hand(1, &[dark_ritual()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let ertai = on_battlefield(&engine, p0, ertai_wizard_adept()).expect("Ertai is out");
    assert!(!is_tapped(&engine, ertai), "nothing has tapped him yet");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and nothing of p0's is floating"
    );

    // Read before a single mana is floating: `can_afford` reads the pool, so
    // an ability whose price is four mana is simply not on the list.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(ertai, 0)),
        "{{2}}{{U}}{{U}} off an empty pool is unpayable, and an ability nobody \
         can afford is left out of the offer rather than refused: {:?}",
        legal.abilities
    );

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        7,
        "seven Islands and no other mana source on this board"
    );
    // And with the money on the table it is *still* not offered, which is
    // the sharper half: "counter target spell" is the only thing this card
    // does, the stack is empty, and an ability with no legal target is left
    // out of the offer exactly as an unaffordable one is (CR 115.2 — only a
    // spell is a legal target here, and there is no spell). Without this
    // reading the assertion above would have been satisfied by either
    // reason, and the one below by neither.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(ertai, 0)),
        "paid for and aimed at nothing: {:?}",
        legal.abilities
    );

    // The spell to counter has to come from somebody else, so p0 hands
    // priority over inside the same main phase — a pool is not emptied until
    // the step or phase ends (CR 500.5).
    engine.apply(p0, PlayerAction::PassPriority).unwrap();
    cast_from_hand(&mut engine, p1, dark_ritual());
    let spell = on_stack(&engine, dark_ritual()).expect("Dark Ritual is on the stack");
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::Priority { player, .. } if *player == p0),
    );

    // Now both halves of the price are met and the target exists, so the one
    // line the card prints is on the list.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(ertai, 0)),
        "with four of the seven floating and a spell to aim at, the line is \
         offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, ertai_wizard_adept(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"counter target spell\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "exactly one spell");
    assert!(
        options.contains(&spell),
        "the spell on the stack is the whole of what may be countered: {options:?}"
    );
    assert_eq!(
        options.len(),
        1,
        "and it is the only spell in the game: {options:?}"
    );
    assert!(
        on_stack(&engine, dark_ritual()).is_some(),
        "the target is chosen before the costs are paid (CR 601.2c, then CR 601.2h)"
    );
    assert!(
        !is_tapped(&engine, ertai),
        "so neither half of the price has been paid yet"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![spell],
            },
        )
        .expect("the spell the question offered is the one that answers it");

    assert!(
        is_tapped(&engine, ertai),
        "{{T}} is half the printed price and the Wizard paid it"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "and {{2}}{{U}}{{U}} came out of the seven"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, dark_ritual()).is_some(),
        "a countered spell is put into its owner's graveyard (CR 701.5a)"
    );
    assert_eq!(
        engine.state().players[1].mana_pool.total(),
        0,
        "and the Ritual that never resolved added none of its three black mana"
    );
    assert!(
        on_battlefield(&engine, p0, ertai_wizard_adept()).is_some(),
        "the Wizard outlives the spell he countered"
    );
}

fn fallow_wurm() -> CardIndex {
    card_index("7b414f70-a9b1-42c3-9655-6aa520d3b19b")
}

/// Fallow Wurm is a `{2}{G}` 4/4 whose entire rules text is one price: "When
/// this creature enters, sacrifice it unless you discard a land card." Both
/// arms of that card are read off one board. With no land in hand there is
/// nothing to pay with — `PlayerMayPayCostOr` opens no question it has no
/// answer for — so the Wurm dies where it lands. With a Forest in hand the
/// same board asks for it: the seven Elves beside it are no lands and stay off
/// the menu, and the 4/4 is still standing once the Forest is gone. The Elf
/// filler is what makes "no land in hand" reachable at all, because a Forest
/// deck draws one.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn fallow_wurm_is_eaten_unless_a_land_card_is_discarded_for_it() {
    let p0 = PlayerId::new(0);
    let three_forests = [forest(), forest(), forest()];

    // No land in hand: every card drawn off the filler is an Elf, so the
    // printed price is unpayable and the trigger resolves without asking
    // anything at all.
    let mut engine = Duel::new(SEED, quiet_creature())
        .battlefield(0, &three_forests)
        .hand(0, &[fallow_wurm()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);
    cast_from_hand(&mut engine, p0, fallow_wurm());
    for _ in 0..40 {
        if at_rest(&engine, p0) {
            break;
        }
        let Pending::Priority { player, .. } = engine.pending().clone() else {
            panic!(
                "there is no land card to discard, so there is no price to ask \
                 about — the twin that does not ask what cannot be paid: got {:?}",
                engine.pending()
            )
        };
        engine.apply(player, PlayerAction::PassPriority).unwrap();
    }
    assert!(
        in_graveyard(&engine, p0, fallow_wurm()).is_some(),
        "with nothing to discard the Wurm sacrifices itself"
    );
    assert!(
        on_battlefield(&engine, p0, fallow_wurm()).is_none(),
        "and it is not on the battlefield — nothing kept it there"
    );

    // The same board with one Forest in hand: the price is payable, so the
    // question is asked and answering it is what keeps the Wurm alive.
    let mut engine = Duel::new(SEED, quiet_creature())
        .battlefield(0, &three_forests)
        .hand(0, &[fallow_wurm(), forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);
    cast_from_hand(&mut engine, p0, fallow_wurm());

    let mut asked_for_a_land = false;
    for _ in 0..40 {
        if at_rest(&engine, p0) {
            break;
        }
        match engine.pending().clone() {
            // The price is offered before it is charged.
            Pending::YesNo { player, .. } => {
                engine.apply(player, PlayerAction::YesNo(true)).unwrap();
            }
            Pending::ChooseCards {
                player,
                options,
                prompt,
                ..
            } => {
                asked_for_a_land = true;
                assert_eq!(
                    prompt,
                    ChoicePrompt::CostDiscard,
                    "paying the printed price is a discard cost and not a search"
                );
                assert_eq!(
                    options.len(),
                    1,
                    "\"discard a **land** card\": the seven Elves in hand are \
                     lands on no reading, so the Forest is the whole menu: {options:?}"
                );
                let land = options[0];
                assert!(
                    engine
                        .state()
                        .object(land)
                        .and_then(|o| o.card)
                        .is_some_and(|c| c.index == forest()),
                    "and the one card offered is the Forest that was dealt"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![land],
                        },
                    )
                    .expect("a card the question offered is a legal answer");
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while the Wurm's trigger resolves: {other:?}"),
        }
    }

    assert!(
        asked_for_a_land,
        "a land card in hand is a price this Wurm can be paid with, so it is \
         asked for"
    );
    let wurm =
        on_battlefield(&engine, p0, fallow_wurm()).expect("the discard bought the Wurm its life");
    assert_eq!(
        pt(&engine, wurm),
        (4, 4),
        "and what was bought is the body the card prints"
    );
    assert!(
        in_graveyard(&engine, p0, forest()).is_some(),
        "the land card went to its owner's graveyard to pay the price"
    );
    assert!(
        in_hand(&engine, p0, forest()).is_none(),
        "and it left the hand, so it was discarded and not merely revealed"
    );
}

fn fault_riders() -> CardIndex {
    card_index("df516046-7f83-4d64-aa0d-d687631d919a")
}

/// Fault Riders — {2}{R}, a 2/2 — "Sacrifice a land: This creature gets +2/+0
/// and gains first strike until end of turn. Activate only once each turn."
///
/// The cost names no particular land, so the engine has to ask which one, and
/// that menu is half the card: all four Mountains this seat controls are on it
/// (a Mountain tapped for the cast is still a permanent its controller may
/// sacrifice), while the Elf beside them is a creature and the Forest across
/// the table is not this seat's. The pump needs a bystander of its own — a
/// second creature under the same seat that must stay a printed 1/1 with no
/// keyword — and the "only once each turn" clause is read off a board where
/// three lands still stand to pay it, so an absent second offer can only be
/// the printed limit.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn fault_riders_eats_a_land_for_two_power_and_first_strike_once_a_turn() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                quiet_creature(),
            ],
        )
        // A land across the table, so "you control" is read and not assumed.
        .battlefield(1, &[forest()])
        .hand(0, &[fault_riders()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // One Mountain is left standing: {2}{R} is what the Riders cost, and every
    // other source on the board pays it, so the lands the ability is about to
    // eat are all still on the table afterwards.
    let kept_land = on_battlefield(&engine, p0, mountain()).expect("a Mountain is out");
    tap_mana_except(&mut engine, p0, kept_land);
    cast_with_floating(&mut engine, p0, fault_riders());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let riders = on_battlefield(&engine, p0, fault_riders()).expect("the Riders resolved");
    let bystander = on_battlefield(&engine, p0, quiet_creature()).expect("the Elf is out");
    let theirs = on_battlefield(&engine, p1, forest()).expect("their Forest is out");
    assert_eq!(
        pt(&engine, riders),
        (2, 2),
        "the printed 2/2, with nothing given up yet"
    );
    assert!(
        !keywords(&engine, riders).contains(KeywordSet::FIRST_STRIKE),
        "and no keyword on a card whose own text is the only source of one"
    );

    let lands = lands_of(&engine, p0);
    assert_eq!(lands.len(), 4, "all four Mountains are still on the table");
    let fodder = lands[0];
    let pool_before = engine.state().players[0].mana_pool.total();

    activate(&mut engine, p0, fault_riders(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the cost names a land and not a particular one, so it asks which: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat pays its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one land, no more and no fewer");
    assert_eq!(
        options.len(),
        4,
        "the four Mountains this seat controls and nothing else: {options:?}"
    );
    for land in &lands {
        assert!(
            options.contains(land),
            "every land under my control is on the menu, tapped or not: {options:?}"
        );
    }
    assert!(
        !options.contains(&bystander),
        "the Elf is a creature, and the cost names a land: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: an opponent's Forest is not yours to sacrifice: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the land the question offered pays the cost");
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert!(
        engine
            .state()
            .zones
            .list(ZoneLocation::Graveyard(p0))
            .contains(&fodder),
        "a sacrificed permanent goes to its owner's graveyard"
    );
    assert_eq!(
        lands_of(&engine, p0).len(),
        3,
        "exactly one land was given up"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        pool_before,
        "the price is a land and no mana, so the pool is exactly where it was"
    );

    assert_eq!(
        pt(&engine, riders),
        (4, 2),
        "+2/+0 on the creature the ability names"
    );
    assert!(
        keywords(&engine, riders).contains(KeywordSet::FIRST_STRIKE),
        "and the printed first strike arrives with it"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "the Elf beside it is still the 1/1 it was printed as"
    );
    assert!(
        !keywords(&engine, bystander).contains(KeywordSet::FIRST_STRIKE),
        "\"This creature\" is not \"creatures you control\""
    );
    assert!(
        on_battlefield(&engine, p1, forest()).is_some(),
        "and the land across the table never moved"
    );

    // The second activation. The price is still payable — three Mountains
    // stand, and the cost asks for no mana and no untapped permanent — so an
    // absent offer here is the printed limit and nothing else.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(riders, 0)),
        "\"Activate only once each turn\": the ability is off the offer with \
         three lands still standing to pay it: {:?}",
        legal.abilities
    );
}

fn feral_shadow() -> CardIndex {
    card_index("cf26dcb4-e181-4ba5-bc03-b56f57032b85")
}

/// Feral Shadow prints one line — flying — on a {2}{B} 2/1 Nightstalker, so
/// the whole card is whether that body arrives off the printed cost and
/// whether the keyword is what the combat step reads. Three Swamps pay
/// {2}{B} exactly and leave nothing floating, the layer projection hands back
/// a 2/1 with flying, and the attack is declared past a Llanowar Elves: a
/// ground creature with neither flying nor reach may never be offered as its
/// blocker (CR 509.1b), and the two damage it deals are the only thing on
/// this board that can move a life total.
#[test]
fn feral_shadow_arrives_as_a_two_one_flier_that_a_ground_creature_cannot_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[feral_shadow()])
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The printed {2}{B} off three Swamps. The pool is read afterwards so
    // that the body below is the card's and not a leftover of the payment.
    cast_from_hand(&mut engine, p0, feral_shadow());
    pass_until(&mut engine, stack_is_empty);
    let shadow = on_battlefield(&engine, p0, feral_shadow()).expect("the Shadow resolved");
    assert_eq!(pt(&engine, shadow), (2, 1), "the printed body");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Swamps paid {{2}}{{B}} and nothing came back"
    );
    assert!(
        keywords(&engine, shadow).contains(KeywordSet::FLYING),
        "which is the whole of its rules text"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "an Elf across the table is the control for the keyword"
    );

    // A whole turn cycle: the Shadow was cast this turn and is summoning
    // sick (CR 302.6), so the attack only becomes available on p0's next one.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player, attackers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert_eq!(player, p0, "the active player declares attackers");
    assert!(
        attackers.contains(&shadow),
        "an untapped 2/1 with no other duty is offered as an attacker: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(shadow, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The block step, walked by hand so that the menu itself can be read.
    // The Elf is p1's whole board, so one entry in this list would be the
    // keyword missing rather than a board that had nothing to block with.
    for _ in 0..20 {
        if matches!(engine.state().turn.phase, Phase::Ending) {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseBlockers {
                player, blockers, ..
            } => {
                assert_eq!(player, p1, "the defending player is asked to block");
                assert!(
                    blockers.is_empty(),
                    "a Llanowar Elves has neither flying nor reach, so it is \
                     no legal blocker for a flier (CR 509.1b): {blockers:?}"
                );
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected between attackers and damage: {other:?}"),
        }
    }

    assert_eq!(
        engine.state().players[1].life,
        18,
        "two damage to the player it flew over"
    );
    assert!(
        on_battlefield(&engine, p0, feral_shadow()).is_some(),
        "and the Shadow is a live creature afterwards: nothing blocked it"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "while the Elf across the table never moved"
    );
}

fn fire_drake() -> CardIndex {
    card_index("fd3bcc9b-7d84-478e-aef5-2e44610107c7")
}

/// Fire Drake is `{1}{R}{R}` for a flying 1/2 with `{R}: This creature gets
/// +1/+0 until end of turn. Activate only once each turn.` Both printed halves
/// need the card to actually be played: the flying is only readable once the
/// permanent is on the battlefield and projected, and the pump is the only
/// thing that ever moves its power off the printed 1. Five Mountains pay the
/// spell and leave two red floating, so the pool still holds a red when the
/// second claim is made — which is what makes the ability's absence after one
/// activation the once-each-turn clause rather than an unpayable `{R}`.
#[test]
fn fire_drake_pumps_once_a_turn_while_the_pool_still_has_the_red_to_pay() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[mountain(), mountain(), mountain(), mountain(), mountain()],
        )
        .hand(0, &[fire_drake()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, fire_drake());
    pass_until(&mut engine, stack_is_empty);
    let drake = on_battlefield(&engine, p0, fire_drake()).expect("the Drake resolved");
    assert_eq!(pt(&engine, drake), (1, 2), "the body the card prints");
    assert!(
        keywords(&engine, drake).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "five Mountains paid {{1}}{{R}}{{R}} and left two red"
    );

    // `legal.abilities` is filtered through `can_afford`, which reads the
    // pool, so the offer is only worth reading with the mana already floating.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(drake, 0)),
        "a red is floating, so the pump is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, fire_drake(), 0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{R}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "gaining +1/+0 is no mana ability, so the pump uses the stack"
    );
    assert_eq!(
        pt(&engine, drake),
        (1, 2),
        "and has not resolved yet: the body is still the printed one"
    );
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, drake),
        (2, 2),
        "\"{{R}}: This creature gets +1/+0 until end of turn\""
    );

    // The limit, and its control: one red is still floating, so the ability
    // is affordable and its absence is the once-each-turn clause and not an
    // empty pool.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the red the second activation would need is still there"
    );
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == drake),
        "\"Activate only once each turn\" — the pump is gone from the offer \
         with the mana still floating: {:?}",
        legal.abilities
    );
}

fn fire_imp() -> CardIndex {
    card_index("5bd806e7-3f9b-4bb4-9708-f87a578f531e")
}

/// Fire Imp is `{2}{R}` for a 2/1 whose whole text is "When this creature
/// enters, it deals 2 damage to target creature" — a trigger, a target and a
/// number, none of which the card file can be asked about. The board carries
/// three creatures so that both halves of `Filter::CREATURE` are struck: the
/// offer has to name the Elf under the Imp's *own* control beside the two
/// across the table, because the card prints no "you control", and the two
/// damage has to fall on the single Elf that was named, because the card
/// prints "target creature" and not "each". The Sol Ring across the table is
/// the counter-half of the filter, and the Elf nobody named is what keeps the
/// lethal 1/1 from being read as a board sweep.
#[test]
fn fire_imp_deals_two_damage_to_the_creature_it_names_and_no_other() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), mountain(), mountain(), llanowar_elves()])
        .hand(0, &[fire_imp()])
        .battlefield(1, &[llanowar_elves(), llanowar_elves(), quiet_artifact()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = all_on_battlefield(&engine, p1, llanowar_elves());
    assert_eq!(theirs.len(), 2, "two Elves across the table");
    let (victim, bystander) = (theirs[0], theirs[1]);
    let rock = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    assert_eq!(
        pt(&engine, victim),
        (1, 1),
        "a printed 1/1 for the Imp's two damage"
    );

    // Three Mountains pay the {2}{R}; the Elf is named as the printing to keep
    // back, so what pays for the Imp is the lands and not a creature this test
    // reads again afterwards.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Mountains, and the Elf kept back"
    );
    cast_with_floating(&mut engine, p0, fire_imp());

    // The spell resolves, the Imp enters, and its enters-trigger asks for the
    // one target the card prints.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(
        player, p0,
        "the controller of the trigger chooses its target"
    );
    assert!(
        options.contains(&mine) && options.contains(&victim) && options.contains(&bystander),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    assert!(
        !options.contains(&rock),
        "a Sol Ring is an artifact and no creature: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![victim],
            },
        )
        .expect("the Elf across the table was one of the options it enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "two damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        all_on_battlefield(&engine, p1, llanowar_elves()).contains(&bystander),
        "the Elf nobody named is still the 1/1 it was printed as"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "and so is the creature under the Imp's own control, which the card \
         was free to name and this test did not"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the Sol Ring was never a target and never moved"
    );
    let imp = on_battlefield(&engine, p0, fire_imp()).expect("the Imp resolved and stayed");
    assert_eq!(
        pt(&engine, imp),
        (2, 1),
        "\"it deals 2 damage\": the ability damages and the body is untouched"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{2}}{{R}} it cost came out of the pool the Mountains filled"
    );
}

fn fledgling_imp() -> CardIndex {
    card_index("e7eaffd5-bdaf-4f72-9c88-8196b3411894")
}

/// Fledgling Imp is a {2}{B} 2/2 whose whole printed text is one activated
/// line: "{B}, Discard a card: This creature gains flying until end of turn."
///
/// Both halves of that price are read in a different place, and each needs its
/// own control. The {B} is a real payment out of a pool the Swamps actually
/// filled (the pool is read *after* the cast, so the single mana left over is
/// the ability's own), and the discard is asked as a cost — `CostDiscard`, one
/// card, out of the hand — before anything is paid (CR 601.2h), which is why
/// the Imp is still grounded while the question stands. The granted keyword is
/// the half no card file can show: an Elf beside it is the creature "this
/// creature" must *not* reach.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn fledgling_imp_discards_a_card_for_its_own_flying_and_no_one_elses() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(211, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp(), llanowar_elves()])
        .hand(0, &[fledgling_imp(), forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Mana into the pool first: "is the creature castable" and "is the ability
    // offered" are both read off the pool and never off the untapped lands.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "four Swamps and the Elf's own {{G}} are every mana source on this board"
    );

    cast_with_floating(&mut engine, p0, fledgling_imp());
    pass_until(&mut engine, stack_is_empty);

    let imp = on_battlefield(&engine, p0, fledgling_imp()).expect("the Imp resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert_eq!(pt(&engine, imp), (2, 2), "the body the card prints");
    assert!(
        !keywords(&engine, imp).contains(KeywordSet::FLYING),
        "a grounded 2/2 until something grants it flying"
    );
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::FLYING),
        "and the Elf beside it is grounded too"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "{{2}}{{B}} left two of the five in the pool"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(imp, 0)),
        "with {{B}} floating the one line the card prints is offered: {:?}",
        legal.abilities
    );
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    activate(&mut engine, p0, fledgling_imp(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the discard is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostDiscard,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert_eq!(
        options.len(),
        hand_before,
        "every card in hand is a legal answer: {options:?}"
    );
    assert!(
        !keywords(&engine, imp).contains(KeywordSet::FLYING),
        "the pump resolves off the stack, so nothing is granted while the cost is still open"
    );

    let discarded = options[0];
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![discarded],
            },
        )
        .expect("a card the cost question offered is a legal answer");

    assert!(
        engine
            .state()
            .object(discarded)
            .is_some_and(|o| o.zone == Zone::Graveyard),
        "CR 701.9a: a discarded card goes to its owner's graveyard"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before - 1,
        "and it left the hand it was discarded from"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{B}} half of the price went with it"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        keywords(&engine, imp).contains(KeywordSet::FLYING),
        "\"This creature gains flying until end of turn\""
    );
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::FLYING),
        "\"this creature\" is not \"creatures you control\": the Elf beside it stays grounded"
    );
}

fn fleshgrafter() -> CardIndex {
    card_index("04b1fb9e-4aef-46d9-b163-f9beff198bad")
}

/// Fleshgrafter — {2}{B}, a 2/2 — prints one line: "Discard an artifact card:
/// This creature gets +2/+2 until end of turn."
///
/// The cost is the whole card, so two cards sit in hand and the discard menu
/// has to offer the artifact card while declining the land card beside it:
/// "an artifact card" read and not skipped. The pump is then read off the
/// Grafter *and* off a bare Elf standing next to it, because `Filter::This`
/// names one creature and not the seat's board.
#[test]
fn fleshgrafter_discards_an_artifact_card_for_two_power_and_leaves_the_board_alone() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[fleshgrafter(), llanowar_elves()])
        .hand(0, &[quiet_artifact(), island()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let grafter = on_battlefield(&engine, p0, fleshgrafter()).expect("the Grafter is on the table");
    let bystander = on_battlefield(&engine, p0, llanowar_elves()).expect("an Elf beside it");
    let fodder = in_hand(&engine, p0, quiet_artifact()).expect("an artifact card in hand");
    let spare = in_hand(&engine, p0, island()).expect("a land card in the same hand");
    assert_eq!(
        pt(&engine, grafter),
        (2, 2),
        "a printed 2/2 before anything"
    );
    assert_eq!(pt(&engine, bystander), (1, 1), "and the Elf a printed 1/1");

    activate(&mut engine, p0, fleshgrafter(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the discard is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostDiscard,
        "a cost and not an effect, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert_eq!(
        options,
        vec![fodder],
        "the artifact card is the whole menu: {options:?}"
    );
    assert!(
        !options.contains(&spare),
        "\"an artifact card\" — a land card in the same hand is not one: {options:?}"
    );

    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![spare],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        in_hand(&engine, p0, island()).is_some(),
        "and the refusal costs nothing: the land card is still in hand"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the card the question offered pays the cost");

    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "CR 601.2h: the price is paid as the ability is activated, so the \
         artifact card is already in its owner's graveyard"
    );
    assert!(
        in_hand(&engine, p0, island()).is_some(),
        "and nothing else was discarded"
    );
    assert_eq!(
        pt(&engine, grafter),
        (2, 2),
        "nothing has resolved yet: the ability is on the stack"
    );
    assert!(
        !stack_is_empty(&engine),
        "the pump is no mana ability, so it is waiting to resolve"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, grafter),
        (4, 4),
        "+2/+2 until end of turn on the creature the ability names"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "the Elf beside it is untouched: `Filter::This` is one creature, not \
         the seat's board"
    );
}

fn flowstone_shambler() -> CardIndex {
    card_index("e72ae9ab-7405-4ea7-b075-42d0ddc352db")
}

/// Flowstone Shambler is {2}{R} for a 2/2 Beast whose whole text is
/// "{R}: This creature gets +1/-1 until end of turn."
///
/// The exchange is read off the projected body: `(3, 1)` is the only answer
/// that shows both halves, where `(3, 3)` would mean the toughness was never
/// reduced and `(2, 2)` that nothing happened at all. The four Mountains pay
/// the {2}{R} and leave exactly the {R} the ability charges, so the
/// activation is a real payment out of the pool and not a label on a free
/// ability, and the second reading — in p1's main phase, with the same
/// permanent still standing — is what "until end of turn" has to give back.
#[test]
fn flowstone_shambler_trades_toughness_for_power_and_gives_it_back_with_the_turn() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(27, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain(), mountain()])
        .hand(0, &[flowstone_shambler()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{R} out of the four Mountains, and the {R} the ability charges is
    // what stays floating beside it: a pool survives until the step ends
    // (CR 500.5) and this whole scenario plays inside this one main phase.
    cast_from_hand(&mut engine, p0, flowstone_shambler());
    pass_until(&mut engine, stack_is_empty);
    let shambler =
        on_battlefield(&engine, p0, flowstone_shambler()).expect("the Shambler resolved");
    assert_eq!(pt(&engine, shambler), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "four Mountains paid {{2}}{{R}} and left exactly the {{R}}"
    );
    assert!(!is_tapped(&engine, shambler), "nothing has tapped it yet");

    // Ability 0 is the only line the card prints.
    activate(&mut engine, p0, flowstone_shambler(), 0);
    assert!(
        !stack_is_empty(&engine),
        "the pump is no mana ability (CR 605.1), so it goes on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, shambler),
        (3, 1),
        "+1/-1: a (3, 3) would be a toughness pump the card does not print, \
         and a (2, 2) that nothing happened at all"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{R}} came out of the pool"
    );
    assert!(
        !is_tapped(&engine, shambler),
        "the price is a red mana and no tap symbol, so the Shambler could do \
         it again"
    );

    // Across the opponent's turn: "until end of turn" ends in the cleanup step
    // of the turn that made it, so p1's main phase reads the printed body
    // again — and the reading is of the same permanent, still on the table.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        on_battlefield(&engine, p0, flowstone_shambler()).is_some(),
        "the same permanent is still standing, so the reading below is not a \
         fresh one"
    );
    assert_eq!(
        pt(&engine, shambler),
        (2, 2),
        "\"until end of turn\": the pump went with the turn that paid for it"
    );
}

fn flowstone_wall() -> CardIndex {
    card_index("5fa86b45-1d5b-42df-8811-6a10903f3039")
}

/// Flowstone Wall is a `{2}{R}` 0/6 Wall with defender and "`{R}`: This
/// creature gets +1/-1 until end of turn".
///
/// One board reads both printed lines and the price of the second, which
/// reading the card cannot do: five Mountains pay the `{2}{R}` and leave
/// exactly the two red the pump charges, so the pump is a real payment out of
/// the pool rather than a label on a free ability, and the pool is empty once
/// both are spent. The body after each activation — `(1, 5)` then `(2, 4)` —
/// is the only pair that applies +1/-1 twice; a card that read the ability as
/// +1/+1, or as a one-shot, cannot produce both, and the Wall standing
/// untapped after each says the price is mana and not a tap. The Llanowar
/// Elves kept untapped beside it are the control for defender: the combat
/// step is reached at all and offers the Elf, so the Wall's absence is the
/// keyword and not a phase that never came.
#[test]
fn flowstone_wall_trades_toughness_for_power_one_point_of_red_at_a_time() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                llanowar_elves(),
            ],
        )
        .hand(0, &[flowstone_wall()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Five Mountains pay the {2}{R} and nothing else is tapped: the Elf is
    // the control the attack declaration below reads, and it has to still be
    // standing untapped when the combat step asks.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "five Mountains, and the Elf paid nothing into it"
    );
    cast_with_floating(&mut engine, p0, flowstone_wall());
    pass_until(&mut engine, stack_is_empty);
    let wall = on_battlefield(&engine, p0, flowstone_wall()).expect("the Wall resolved");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the {{2}}{{R}} is spent and the two red the pump charges are left"
    );
    assert_eq!(pt(&engine, wall), (0, 6), "the printed 0/6 body");
    assert!(
        types(&engine, wall).contains(TypeSet::CREATURE),
        "a Wall is a creature"
    );
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "and it prints defender"
    );

    // Ability 0 is the only line the card prints, and its whole price is one
    // red — not its own tap — so the Wall is still standing to go again.
    let mut pumped = 0;
    for expected in [(1, 5), (2, 4)] {
        activate(&mut engine, p0, flowstone_wall(), 0);
        // `Effect::PumpFilter` over `Filter::This` names its own permanent;
        // answered here if a question arrives rather than assumed either way.
        if let Pending::ChooseTargets { player, .. } = engine.pending().clone() {
            engine
                .apply(
                    player,
                    PlayerAction::ChooseObjects {
                        objects: vec![wall],
                    },
                )
                .expect("the Wall is the creature the pump is about");
        }
        pass_until(&mut engine, stack_is_empty);
        pumped += 1;
        assert_eq!(
            pt(&engine, wall),
            expected,
            "+1/-1 for each red spent, after {pumped} activation(s)"
        );
        assert!(
            !is_tapped(&engine, wall),
            "the price is one red and no tap, so the Wall is still up"
        );
    }
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "both red were spent: two activations, two mana"
    );

    // Defender: the combat step is reached, the untapped Elf beside it is
    // offered, and the 2/4 Wall is not.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is still out");
    assert!(
        attackers.contains(&elves),
        "an untapped 1/1 with no text of its own may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&wall),
        "\"Defender (This creature can't attack.)\" keeps the Wall home even \
         as a 2/4: {attackers:?}"
    );
}

fn foratog() -> CardIndex {
    card_index("77f257b9-2047-40a3-85c2-00ad17deeb08")
}

/// Foratog — `{2}{G}`, a printed 1/2 Atog: "`{G}`, Sacrifice a Forest: This
/// creature gets +2/+2 until end of turn."
///
/// The price names a *Forest* and not a land, so the board carries the three
/// cases a filter has to separate: two Forests under the same seat (the
/// price), the Atog itself (a permanent, and no Forest), and a Forest across
/// the table (a Forest, and not this seat's to give up). Exactly one Forest is
/// tapped for the `{G}` and the other, left standing, is the one eaten — so
/// the pool reads empty once the ability is on the stack and the green in it
/// belonged to the mana rather than to change. `(3, 4)` on a printed `(1, 2)`
/// is the only body that reads `+2/+2` as a pump on this creature, and the
/// typed cost is what makes the offer worth playing: reading the card file
/// cannot tell "a Forest you control" from "a permanent you control".
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn foratog_eats_a_forest_of_your_own_for_two_and_two() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[foratog(), forest(), forest()])
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let toad = on_battlefield(&engine, p0, foratog()).expect("the Atog is on the table");
    let lands = all_on_battlefield(&engine, p0, forest());
    assert_eq!(lands.len(), 2, "two Forests of its own to give up");
    let (food, fuel) = (lands[0], lands[1]);
    let theirs = on_battlefield(&engine, p1, forest()).expect("a Forest across the table");
    assert_eq!(
        pt(&engine, toad),
        (1, 2),
        "a printed 1/2 before anything is eaten"
    );

    // `legal.abilities` is filtered through `can_afford`, and that reads the
    // pool rather than the untapped lands: no {G}, no offer.
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Atog");
    assert!(
        !legal.abilities.contains(&(toad, 0)),
        "an empty pool pays no {{G}}, and an unaffordable ability is absent from \
         the offer rather than refused: {:?}",
        legal.abilities
    );

    // One Forest pays the {G} and the other is written down as the one that
    // stays untapped: the Atog is a 1/2 and taps for nothing, so nothing else
    // on this board can move the pool between here and the claim.
    tap_mana_except(&mut engine, p0, food);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one Forest in the pool and the other kept back for the sacrifice"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(toad, 0)),
        "with {{G}} floating the whole price is payable: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, foratog(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which Forest, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one Forest, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "the two Forests this seat controls and nothing else: {options:?}"
    );
    assert!(
        options.contains(&food) && options.contains(&fuel),
        "a tapped Forest is still a Forest, so both are on the menu: {options:?}"
    );
    assert!(
        !options.contains(&toad),
        "the Atog is a creature: \"a Forest\" is read, not skipped: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: an opponent's Forest is not yours to sacrifice: {options:?}"
    );
    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, forest()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![food],
            },
        )
        .expect("the Forest the question offered pays the cost");

    // CR 601.2h: the {G} and the sacrifice are the last step of the
    // activation, so both are already paid while the ability waits to resolve.
    assert!(
        in_graveyard(&engine, p0, forest()).is_some(),
        "a sacrificed Forest goes to its owner's graveyard"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{G}} was the other half of the price"
    );
    assert_eq!(
        pt(&engine, toad),
        (1, 2),
        "the pump is an effect and resolves off the stack, so the body has not \
         moved yet"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, toad),
        (3, 4),
        "+2/+2 until end of turn on the creature the ability belongs to"
    );
    assert_eq!(
        all_on_battlefield(&engine, p0, forest()),
        vec![fuel],
        "exactly one Forest was given up: the other is still standing"
    );
    assert!(
        on_battlefield(&engine, p1, forest()).is_some(),
        "and nothing of the opponent's ever moved"
    );
}

// oracle_id = "f75f9006-217d-4ec8-9c35-ceefe1c5ae4e"
fn frozen_shade() -> CardIndex {
    card_index("f75f9006-217d-4ec8-9c35-ceefe1c5ae4e")
}

/// Frozen Shade is `{2}{B}` for a 0/1 and its whole printed text is one
/// activated ability with no tap and no target: "{B}: This creature gets +1/+1
/// until end of turn." None of that can be read off the card file — that the
/// price is a real black mana, that the pump lands on the Shade and not on the
/// creature beside it, and that it is *until end of turn* — so the board is
/// five Swamps and one Elf. Five Swamps pay the `{2}{B}` and leave exactly two
/// activations of black floating, which is what makes "one `{B}` is one +1/+1"
/// an exact claim rather than a guess, and the Elf is the bystander the pump's
/// `Filter::This` has to decline.
#[test]
fn frozen_shade_pumps_itself_for_one_black_and_not_the_creature_beside_it() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(
            0,
            &[
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                llanowar_elves(),
            ],
        )
        .hand(0, &[frozen_shade()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The Elf is kept back for two reasons at once: it is the bystander the
    // pump must decline, and it is a mana source whose own `{G}` would make
    // every count below a claim about mana nothing on the board accounted for.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    cast_with_floating(&mut engine, p0, frozen_shade());
    pass_until(&mut engine, stack_is_empty);
    let shade = on_battlefield(&engine, p0, frozen_shade()).expect("the Shade resolved");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert_eq!(
        pt(&engine, shade),
        (0, 1),
        "the shaded body the card prints"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "five Swamps pay `{{2}}{{B}}` and exactly two black are left floating"
    );

    // Ability 0 is the only thing the card prints.
    activate(&mut engine, p0, frozen_shade(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, shade), (1, 2), "one {{B}} is one +1/+1");

    activate(&mut engine, p0, frozen_shade(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, shade),
        (2, 3),
        "and a second activation stacks on the first"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "each activation spent one black, and the pool held nothing else"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the pump is `Filter::This`: the creature beside it never grew"
    );

    // "Until end of turn": the pumps are gone by the opponent's next main
    // phase, which is past the cleanup step that removes them (CR 514.2).
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, shade),
        (0, 1),
        "both pumps fell off with the turn they were made in"
    );
    assert_eq!(pt(&engine, elf), (1, 1), "and the Elf never moved");
}

fn furnace_spirit() -> CardIndex {
    card_index("86b33d25-6123-439c-9026-a4e835b48562")
}

/// Furnace Spirit prints haste and "{R}: This creature gets +1/+0 until end of
/// turn", and this scenario plays both halves inside the one turn the first one
/// is about: the Spirit is cast, pumps itself twice off the red the five
/// Mountains left floating, and then attacks — which a 1/1 that arrived this
/// turn may only do because of the printed haste (CR 302.6). Reading the card
/// file cannot tell a real {R} from a label on a free ability, so the pool is
/// asserted around each activation, and the untapped Llanowar Elves beside it
/// stays a printed 1/1: the pump names `Filter::This` and never the board.
#[test]
fn furnace_spirit_attacks_the_turn_it_arrives_and_pumps_only_itself() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(37, forest())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                llanowar_elves(),
            ],
        )
        .hand(0, &[furnace_spirit()])
        .battlefield(1, &[llanowar_elves()])
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Five Mountains are five red. The Elf is named as the printing kept back:
    // it is the bystander the pump has to leave alone, and its own `{T}` would
    // put a green in the pool that no count below accounts for.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "five Mountains tapped for five red"
    );

    cast_with_floating(&mut engine, p0, furnace_spirit());
    pass_until(&mut engine, stack_is_empty);
    let spirit = on_battlefield(&engine, p0, furnace_spirit()).expect("the Spirit resolved");
    let bystander = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    assert_eq!(pt(&engine, spirit), (1, 1), "the body the card prints");
    assert!(
        keywords(&engine, spirit).contains(KeywordSet::HASTE),
        "the printed haste reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "three of the five paid {{2}}{{R}}, and nothing else moved"
    );

    // {R}: this creature gets +1/+0. No target question — the pump names
    // `Filter::This` — so the body and the pool are the whole of what there is
    // to read afterwards.
    activate(&mut engine, p0, furnace_spirit(), 0);
    assert!(!stack_is_empty(&engine), "a pump is no mana ability");
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, spirit), (2, 1), "one activation is +1/+0");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "and one red left the pool for it"
    );

    // A second activation: "until end of turn" stacks, and a cost that is
    // really paid is a cost the pool can run out of.
    activate(&mut engine, p0, furnace_spirit(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, spirit), (3, 1), "two activations, +2/+0");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the last red is spent"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "the pump reaches the Spirit and no other creature"
    );

    // Haste is what lets a creature that entered this turn attack (CR 302.6),
    // and the three power it carries is what the pump added.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&spirit),
        "haste: the Spirit arrived this turn and is still offered as an \
         attacker: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(spirit, Defender::Player(p1))],
            },
        )
        .unwrap();

    // Not `stack_is_empty`: the stack is already empty the moment attackers are
    // declared, so that predicate stops the walk *before* the combat damage
    // step and p1 would still read 20 (CR 510.2).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        17,
        "a 1/1 that pumped itself twice deals 3 combat damage"
    );
}

fn fyndhorn_brownie() -> CardIndex {
    card_index("6d1f8073-4da2-4abc-abb4-2053c4a40bbf")
}

/// Fyndhorn Brownie — {2}{G} 1/1 Ouphe: "{2}{G}, {T}: Untap target creature."
///
/// Two Forests and two Llanowar Elves are four mana and nothing else on the
/// board makes any, so a pool that reads empty once the ability is announced is
/// the {2}{G} really paid — and CR 601.2c names the target before CR 601.2h
/// pays, which the four mana still floating and the untapped Brownie *while the
/// target question stands* are the other half of.
///
/// The untap is read off the two Elves that tapping for that mana left down:
/// the one that was named stands back up while its twin stays where the mana
/// left it, so the sentence is "target creature" and not "each creature you
/// control". The Elf across the table and the Brownie itself are the same
/// reading from the other two directions — the offer reaches both. The turn
/// cycle in the middle is the tap symbol (CR 302.6): the Brownie entered this
/// turn and could not have paid it yet.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn fyndhorn_brownie_taps_for_two_green_to_untap_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, forest())
        .battlefield(0, &[forest(), forest(), llanowar_elves(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[fyndhorn_brownie()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{G} out of the four sources, which is every mana this board has.
    cast_from_hand(&mut engine, p0, fyndhorn_brownie());
    pass_until(&mut engine, stack_is_empty);
    let brownie = on_battlefield(&engine, p0, fyndhorn_brownie()).expect("the Brownie resolved");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "four tapped sources against a {{2}}{{G}} leaves one green floating, \
         and the turn cycle below is what empties it (CR 500.4)"
    );

    // A whole turn cycle, because the price includes the tap symbol (CR 302.6).
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    let elves = all_on_battlefield(&engine, p0, llanowar_elves());
    assert_eq!(elves.len(), 2, "the two Elves untapped with the lands");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let (aimed, bystander) = (elves[0], elves[1]);

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "two Forests and two Elves: four mana and no more"
    );
    assert!(
        is_tapped(&engine, aimed) && is_tapped(&engine, bystander),
        "both Elves tapped for the mana, which is what there now is to untap"
    );
    assert!(
        !is_tapped(&engine, theirs),
        "and the Elf across the table never moved"
    );

    activate(&mut engine, p0, fyndhorn_brownie(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that chooses");
    assert!(
        options.contains(&aimed) && options.contains(&bystander),
        "both creatures you control are on the menu: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"target creature\" is no \"you control\": the Elf across the table is \
         a legal target too: {options:?}"
    );
    assert!(
        options.contains(&brownie),
        "the source is a creature as well, so it is on its own menu: {options:?}"
    );
    // CR 601.2c picked the target, so nothing of the price has been paid yet.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "the {{2}}{{G}} is the last step of the activation, after the target"
    );
    assert!(!is_tapped(&engine, brownie), "and so is its {{T}}");

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![aimed],
            },
        )
        .expect("the Elf was one of the options it enumerated");
    assert!(
        is_tapped(&engine, brownie),
        "{{T}} was paid as the answer was applied"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "three of the four went on the {{2}}{{G}} — the fourth is the Elf's \
         own green, tapped because a tapped Elf is what there is to untap"
    );
    assert!(
        !stack_is_empty(&engine),
        "untapping is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        !is_tapped(&engine, aimed),
        "\"untap target creature\": the Elf that was named is standing again"
    );
    assert!(
        is_tapped(&engine, bystander),
        "the Elf it did not name is still down — the ability untaps its own \
         target and no other creature on the table"
    );
    assert!(
        !is_tapped(&engine, theirs),
        "and the opponent's board was never touched"
    );
}

fn fyndhorn_elder() -> CardIndex {
    card_index("507bdb1a-90b4-4fd3-a1a3-e8be316e97f3")
}

/// Fyndhorn Elder is a 1/1 for {2}{G} whose whole printed text is one mana
/// ability: "{T}: Add {G}{G}." The scenario really casts it — three Forests pay
/// {2}{G} and the pool is empty when it lands — and then lets a full turn cycle
/// pass before pressing that ability, because a creature's own `{T}` is
/// unavailable the turn it arrives (CR 302.6) and a test that tapped it on
/// arrival would be measuring summoning sickness instead of the card.
///
/// Two green out of one activation is the claim, and nothing is tapped
/// beforehand so the empty pool makes it exact: `{G}{G}` names its colour and
/// asks nothing, which is why a `ChooseColor` here would mean the engine read a
/// printed {G} as a choice; and a mana ability resolves as it is activated
/// (CR 605.3b), so the mana and the tap are in place with an empty stack.
#[test]
fn fyndhorn_elder_taps_for_two_green_out_of_an_empty_pool() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[fyndhorn_elder()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{G} off the three Forests, spent down to nothing by the cast.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Forests, three green"
    );
    cast_with_floating(&mut engine, p0, fyndhorn_elder());
    pass_until(&mut engine, stack_is_empty);
    let elder = on_battlefield(&engine, p0, fyndhorn_elder()).expect("the Elder resolved");
    assert_eq!(pt(&engine, elder), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{2}}{{G}} took all three green with it, so the board floats nothing"
    );

    // Summoning sickness (CR 302.6): the Elder cannot pay its own {T} on the
    // turn it arrived, so the board waits out a turn cycle before the claim.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, elder),
        "and nothing tapped it on the way"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(elder, 0)),
        "a printed mana ability has an index to name, so the Elder's one line \
         is an ordinary entry in `abilities`: {:?}",
        legal.abilities
    );
    assert!(
        !legal.mana_abilities.contains(&elder),
        "the CR 305.6 shortcut is for mana a permanent has with no ability to \
         point at, which a printed {{T}} is not: {:?}",
        legal.mana_abilities
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the pool is empty, so whatever the next line adds is the Elder's alone"
    );

    activate(&mut engine, p0, fyndhorn_elder(), 0);

    assert!(
        !matches!(engine.pending(), Pending::ChooseColor { .. }),
        "the card names its colour, so there is nothing to choose: {:?}",
        engine.pending()
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        2,
        "one activation, two green — a card printing a single {{G}} would leave one"
    );
    assert_eq!(
        pool.total(),
        2,
        "and nothing else: one tap, one colour, two mana"
    );
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, elder), "the Elder paid its own {{T}}");
}

fn ghosts_of_the_damned() -> CardIndex {
    card_index("1b3bbd3c-f5ef-4940-82a2-d36f4d148b9a")
}

/// Ghosts of the Damned is a printed 0/2 Spirit whose whole text is "{T}:
/// Target creature gets -1/-0 until end of turn."
///
/// The scenario crosses a turn boundary before pressing it, because a creature
/// cast this turn may not pay a tap symbol (CR 302.6) — so the permanent that
/// is tapped is the one the cast actually left behind and not a body the
/// harness seated. Four creatures stand on the table (two of mine, one across
/// it, and the Ghosts itself), which is what makes "target creature" readable
/// as any creature rather than "creatures you control". The numbers the card
/// prints then separate the readings: the aimed-at Elf is a (0, 1) — one power
/// gone and the toughness the card never touches — and the three creatures
/// nobody named stay printed 1/1s and 0/2.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn ghosts_of_the_damned_taps_to_take_one_power_off_the_creature_it_targets() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(
            0,
            &[
                swamp(),
                swamp(),
                swamp(),
                llanowar_elves(),
                llanowar_elves(),
            ],
        )
        .hand(0, &[ghosts_of_the_damned()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{B}{B} off the three Swamps, with both Elves named as kept back: they
    // are two of the creatures this test reads back afterwards.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Swamps, three black, and no Elf tapped for any of it"
    );
    cast_with_floating(&mut engine, p0, ghosts_of_the_damned());
    pass_until(&mut engine, stack_is_empty);
    let ghosts = on_battlefield(&engine, p0, ghosts_of_the_damned())
        .expect("the Ghosts resolved onto the table");
    assert_eq!(pt(&engine, ghosts), (0, 2), "the body the card prints");

    // Summoning sickness (CR 302.6): the Ghosts arrived this turn, so its
    // {T} is not even offered yet. One turn has to pass and come back.
    reach_their_main_phase(&mut engine, p1);
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");
    assert!(
        !is_tapped(&engine, ghosts),
        "and the untap step stood the Ghosts back up"
    );

    let elves = all_on_battlefield(&engine, p0, llanowar_elves());
    assert_eq!(
        elves.len(),
        2,
        "two Elves of mine, one of which stays alone"
    );
    let (target, bystander) = (elves[0], elves[1]);
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    assert_eq!(
        pt(&engine, target),
        (1, 1),
        "a printed 1/1 before the shrink"
    );

    activate(&mut engine, p0, ghosts_of_the_damned(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        options.contains(&target) && options.contains(&bystander),
        "both creatures you control are on the menu: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"target creature\" is not \"creatures you control\": the Elf across \
         the table is offered, and this test declines it: {options:?}"
    );
    assert!(
        options.contains(&ghosts),
        "and the Ghosts is a creature itself, so its own body may be aimed at: {options:?}"
    );
    assert_eq!(
        options.len(),
        4,
        "four creatures stand on the table and nothing else is offered: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![target],
            },
        )
        .expect("the Elf the question offered is a legal answer");
    assert!(
        is_tapped(&engine, ghosts),
        "{{T}} is the whole price, and CR 601.2h pays it after the target"
    );
    assert!(
        !stack_is_empty(&engine),
        "shrinking a creature is no mana ability, so the ability is on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, target),
        (0, 1),
        "-1/-0 on a printed 1/1: one power gone, and the toughness the card \
         never touches"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "the Elf nobody aimed at is still the 1/1 it was printed as"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "an Elf across the table that the ability was not pointed at would \
         read (0, 1) here if the pump had leaked"
    );
    assert_eq!(
        pt(&engine, ghosts),
        (0, 2),
        "the Ghosts aimed at the Elf, so its own body never moved"
    );

    // "until end of turn" is the other half of the sentence: past p0's
    // cleanup the same Elf has its printed power back.
    let mut reached_p1 = false;
    for _ in 0..400 {
        if matches!(engine.state().turn.phase, Phase::FirstMain)
            && engine.state().turn.active == p1
            && matches!(engine.pending(), Pending::Priority { player, .. } if *player == p1)
        {
            reached_p1 = true;
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::DiscardChoice { player, count } => {
                let hand = engine
                    .state()
                    .zones
                    .list(ZoneLocation::Hand(player))
                    .clone();
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: hand.into_iter().take(usize::from(count)).collect(),
                        },
                    )
                    .unwrap();
            }
            other => panic!("unexpected on the way past the end of the turn: {other:?}"),
        }
    }
    assert!(reached_p1, "p1 takes its own turn");
    assert_eq!(
        pt(&engine, target),
        (1, 1),
        "\"until end of turn\": across the boundary the Elf is a printed 1/1 again"
    );
    assert!(
        on_battlefield(&engine, p0, ghosts_of_the_damned()).is_some(),
        "and the Ghosts, which the effect never touched, is still on the table"
    );
}

fn glacial_wall() -> CardIndex {
    card_index("7fcf8faa-2c93-4dc8-aa56-6fc40340e212")
}

/// Glacial Wall is a `{2}{U}` 0/7 whose entire printed text is one keyword:
/// "Defender (This creature can't attack.)". The body and the keyword are read
/// on the battlefield, and the keyword is then played out in the combat step
/// that can see it — an untapped Elf beside it is offered in the attack
/// declaration and the Wall is not, which is what separates "Defender" from a
/// board that simply never reached CR 508.1. The Elf carries the second half
/// too: on the following turn the Wall is offered as its blocker, because
/// "can't attack" is not "can't block", and a creature that could do neither
/// would print the same keyword and pass the offer above.
#[test]
fn glacial_wall_is_a_zero_seven_that_cannot_attack_but_may_still_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), llanowar_elves()])
        .hand(0, &[glacial_wall()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Three Islands pay the {2}{U}, and the Elf is named as the printing kept
    // back: it is this test's control in the attack declaration below, and a
    // creature tapped for mana may not attack.
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Islands and nothing else: the Elf kept its own {{G}} to itself"
    );
    cast_with_floating(&mut engine, p0, glacial_wall());
    pass_until(&mut engine, stack_is_empty);

    let wall = on_battlefield(&engine, p0, glacial_wall()).expect("the Wall resolved");
    assert_eq!(
        pt(&engine, wall),
        (0, 7),
        "the printed 0/7, projected on the battlefield"
    );
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "Defender reaches the permanent it is printed on"
    );

    // CR 508.1a enumerates what may attack, and the control is what makes the
    // absence readable: the untapped 1/1 is on that list and the Wall is not.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&elf),
        "an untapped 1/1 with no text of its own may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&wall),
        "CR 702.3: the 0/7 may not, whatever its body is worth in combat: {attackers:?}"
    );

    // Empty attackers on p0's side, the rest of that turn, and then p1's
    // combat: the same 0/7 is offered as a blocker, where the keyword says
    // nothing at all — and blocking is the only thing a Wall is for.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::FirstMain) && e.state().turn.active == p1
    });
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(theirs, Defender::Player(p0))],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("the predicate just matched")
    };
    let option = blockers
        .iter()
        .find(|o| o.blocker == wall)
        .expect("a creature with defender may still block");
    assert!(
        option.attackers.contains(&theirs),
        "and it may block the Elf attacking its controller: {option:?}"
    );
}

fn goblin_chariot() -> CardIndex {
    card_index("6ef0dd51-31df-4fd3-8153-49a427a7fdcf")
}

/// Goblin Chariot is `{2}{R}` for a 2/2 Goblin Warrior with haste, and haste
/// is the whole card: a creature that came under its controller's control this
/// turn may not attack (CR 302.6), so the Chariot appearing in the attack
/// declaration of the very turn it was cast is the only reading that says the
/// keyword reached the battlefield rather than the card file. Three Mountains
/// are exactly the printed `{2}{R}`, and the two damage p1 loses are dealt in
/// the same turn the creature arrived — which no printed 2/2 without the
/// keyword could do.
#[test]
fn goblin_chariot_attacks_the_turn_it_arrives_because_it_has_haste() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain()])
        .hand(0, &[goblin_chariot()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The three Mountains are the whole cost, so nothing on this board is a
    // creature that could have attacked on an earlier turn.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats before the Chariot is paid for"
    );
    cast_from_hand(&mut engine, p0, goblin_chariot());
    pass_until(&mut engine, stack_is_empty);

    let chariot = on_battlefield(&engine, p0, goblin_chariot()).expect("the Chariot resolved");
    assert_eq!(pt(&engine, chariot), (2, 2), "the body the card prints");
    assert!(
        keywords(&engine, chariot).contains(KeywordSet::HASTE),
        "haste is the keyword the card prints"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration");
    };
    assert!(
        attackers.contains(&chariot),
        "\"This creature can attack and {{T}} as soon as it comes under your \
         control\": a 2/2 that entered this turn is offered anyway: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(chariot, Defender::Player(p1))],
            },
        )
        .unwrap();

    // Not `stack_is_empty`: the stack is empty the moment attackers are
    // declared, so that predicate stops the walk *before* the combat damage
    // step (CR 510.2) and both life totals still read 20.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert_eq!(
        engine.state().players[1].life,
        18,
        "the 2/2 dealt its two combat damage in the turn it was cast"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing attacked back"
    );
    assert_eq!(
        on_battlefield(&engine, p0, goblin_chariot()),
        Some(chariot),
        "the Chariot is still on the battlefield after it attacked"
    );
}

fn goblin_medics() -> CardIndex {
    card_index("457bee4c-2332-440c-9336-36f6a69614f9")
}

/// Goblin Medics — {2}{R}, a 1/1 Goblin Shaman — prints one line: "Whenever
/// this creature becomes tapped, it deals 1 damage to any target."
///
/// So the scenario has to produce a tap, and attacking is the tap the rules
/// hand it: declaring the Medics as an attacker taps it and puts the trigger
/// on the stack (CR 508.2), before any combat damage exists to be mistaken
/// for it. That mistake is why the damage is aimed at a 1/1 Elf across the
/// table rather than at the player — one life lost by a player would have
/// been explained just as well by the Medics' own combat damage a step later,
/// while a dead Elf with the opponent still at 20 life at that moment can only
/// be the trigger. The card is cast for its printed {2}{R} off three
/// Mountains, and the turn cycle before the attack is what summoning sickness
/// costs (CR 302.6).
#[test]
fn goblin_medics_deals_its_damage_when_it_becomes_tapped() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain()])
        .hand(0, &[goblin_medics()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{R} off the three Mountains, so the card arrives the way the card
    // arrives instead of merely being believed in.
    cast_from_hand(&mut engine, p0, goblin_medics());
    pass_until(&mut engine, stack_is_empty);
    let medics = on_battlefield(&engine, p0, goblin_medics()).expect("the Medics resolved");
    assert_eq!(pt(&engine, medics), (1, 1), "the body the card prints");

    // A creature cast this turn is summoning sick, so the attack is a whole
    // turn cycle away — and the walk is where the Medics untaps again.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "a printed 1/1, which is one damage from death"
    );
    assert!(
        !is_tapped(&engine, medics),
        "and the Medics untapped on the way back"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&medics),
        "an untapped, unsick Medics may be declared: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(medics, Defender::Player(p1))],
            },
        )
        .unwrap();
    assert!(
        is_tapped(&engine, medics),
        "attacking is the tap the card is about"
    );

    // The trigger is on the stack and asks for its target while the Medics is
    // still unblocked and no combat damage has been dealt by anybody.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on the target question")
    };
    assert_eq!(player, p0, "the controller of the tapped creature chooses");
    assert_eq!((min, max), (1, 1), "one target, no more and no fewer");
    assert!(
        options.contains(&elf),
        "\"any target\" reaches a creature across the table: {options:?}"
    );
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "CR 115.4: and players are in the same choice: {player_options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![elf],
                players: vec![],
            },
        )
        .expect("the Elf was one of the options it enumerated");
    assert!(
        !stack_is_empty(&engine),
        "dealing damage is no mana ability, so the trigger is on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "one damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the Elf died in the declare attackers step, before the Medics \
         could have dealt combat damage: the untouched life total is what \
         pins the kill to the trigger"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "the damage belongs to the target that was named and to nobody else"
    );
}

fn goblin_sky_raider() -> CardIndex {
    card_index("9e0ebf3b-9295-43a9-9b5c-4ffac6a6b630")
}

/// Goblin Sky Raider is `{2}{R}` for a printed 1/2 whose whole text is flying,
/// so the keyword is only worth reading where it changes an answer: the combat
/// step. The board therefore carries a ground creature *and* a flier on the
/// other side, and the block declaration is read between them — the Llanowar
/// Elves are never paired with the Raider while the Baleful Strix is, which a
/// bare `keywords()` assertion could not tell apart from a pairing that
/// offered every blocker against every attacker. The attack waits a full turn
/// cycle, because a creature cast this turn is sick (CR 302.6), and the three
/// Mountains are read empty afterwards so the `{2}{R}` is a payment and not a
/// label.
#[test]
fn goblin_sky_raider_flies_over_a_ground_creature_and_is_met_only_by_a_flier() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain()])
        .hand(0, &[goblin_sky_raider()])
        .battlefield(1, &[llanowar_elves(), baleful_strix()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, goblin_sky_raider());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, goblin_sky_raider()).is_some() && stack_is_empty(e)
    });
    let raider = on_battlefield(&engine, p0, goblin_sky_raider()).expect("the Raider resolved");
    assert_eq!(pt(&engine, raider), (1, 2), "the 1/2 body the card prints");
    assert!(
        keywords(&engine, raider).contains(KeywordSet::FLYING),
        "and the one keyword it prints"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Mountains paid {{2}}{{R}} and left nothing floating"
    );

    // A creature cast this turn is sick (CR 302.6), so the attack happens on
    // p0's next turn, across p1's.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until only stops on the attack declaration")
    };
    assert!(
        attackers.contains(&raider),
        "an untapped, unsick flier is offered as an attacker: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(raider, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until only stops on the block declaration")
    };
    let elves = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("their flier is out");
    let options_for = |blocker: ObjectId| -> Vec<ObjectId> {
        blockers
            .iter()
            .find(|option| option.blocker == blocker)
            .map_or_else(Vec::new, |option| option.attackers.clone())
    };
    assert!(
        !options_for(elves).contains(&raider),
        "a ground creature cannot block a flier: {:?}",
        options_for(elves)
    );
    assert!(
        options_for(strix).contains(&raider),
        "while a creature with flying is exactly what may: {:?}",
        options_for(strix)
    );
    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();

    // Nothing blocked, so the one power the card prints is the damage it deals.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "the unblocked Raider connected for its one power"
    );
}

fn goliath_beetle() -> CardIndex {
    card_index("86ab4400-fbdd-4c18-a893-441286a9d7d0")
}

/// Goliath Beetle is `{2}{G}` for a 3/1 Insect whose entire printed text is
/// trample, and trample is a claim about damage assignment rather than a
/// label: a 3/1 blocked by a 1/1 spends one damage on the blocker and has two
/// left over for the defending player. So the Beetle is cast off three
/// Forests, sits out its own summoning sickness (CR 302.6 — a 3/1 that cannot
/// attack on the turn it arrives is a body, not a card), and swings into the
/// Elf across the table a turn later. `(3, 1)` read off the layers before and
/// after is what says the printed numbers are the projected ones, and the
/// Elf's graveyard entry beside p1's missing two life is the half that
/// separates trample from a plain 3/1: a blocked attacker that kept all of
/// its damage would leave that life total alone.
#[test]
fn goliath_beetle_tramples_two_damage_past_a_one_one_blocker() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[goliath_beetle()])
        .battlefield(1, &[llanowar_elves()])
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{G} off the three Forests, which are every mana source on this board.
    cast_from_hand(&mut engine, p0, goliath_beetle());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, goliath_beetle()).is_some()
    });
    let beetle = on_battlefield(&engine, p0, goliath_beetle()).expect("the Beetle resolved");
    let elf =
        on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf stands across the table");
    assert_eq!(
        pt(&engine, beetle),
        (3, 1),
        "the printed 3/1, read off the layer system"
    );
    assert!(
        keywords(&engine, beetle).contains(KeywordSet::TRAMPLE),
        "the one word the card prints reaches the permanent"
    );

    // CR 302.6: the Beetle arrived this turn and may not attack, so a whole
    // turn cycle is what makes the swing below legal at all.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        pt(&engine, beetle),
        (3, 1),
        "still a 3/1 a turn later, so nothing transient was what was read"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("the predicate just matched")
    };
    assert!(
        attackers.contains(&beetle),
        "an untapped, unsick attacker is offered: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(beetle, Defender::Player(p1))],
            },
        )
        .unwrap();

    // One blocker, and whether it may block which attacker is a pairing the
    // engine enumerates rather than a fact to assume (CR 509.1a).
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p1, "the defending seat declares the blockers");
    assert!(
        blockers
            .iter()
            .any(|o| o.blocker == elf && o.attackers.contains(&beetle)),
        "the Elf may block the Beetle: {blockers:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(elf, beetle)],
            },
        )
        .unwrap();

    // Past the combat damage step (CR 510.2) and on to the end of the turn:
    // damage is dealt as the step turns, so a walk that stopped at the first
    // quiet priority would still read the life total twenty.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert_eq!(
        engine.state().players[1].life,
        18,
        "one damage is lethal to a 1/1 and the other two trample over — a \
         blocked attacker that kept its damage would leave this at twenty"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "the blocker did not survive the damage that was assigned to it"
    );
    assert!(
        in_graveyard(&engine, p0, goliath_beetle()).is_some(),
        "and the Elf's one point of damage is lethal to a 3/1, so the \
         toughness the card prints is real on both sides of the block"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "the damage that trampled over went to the defending player and never \
         to the controller of the attacker"
    );
}

fn granite_gargoyle() -> CardIndex {
    card_index("ef5248d4-4cd1-447c-bdcc-78a09a67d923")
}

/// Granite Gargoyle prints two things: flying on a 2/2 body for `{2}{R}`, and
/// "`{R}`: This creature gets +0/+1 until end of turn" — an ability with no
/// once-per-turn clause, so it stacks. Both halves are read off one board of
/// five Mountains: three pay for the creature and the two left in the pool buy
/// the pump twice. `(2, 3)` then `(2, 4)` is the only pair of numbers that shows
/// the toughness moving while the power stays exactly where it was printed — a
/// `(3, 3)` would mean the pump was written +1/+1, and a single activation
/// alone could not tell a repeatable ability from a one-shot.
#[test]
fn granite_gargoyle_pumps_its_own_toughness_once_per_red() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(1701, mountain())
        .battlefield(
            0,
            &[mountain(), mountain(), mountain(), mountain(), mountain()],
        )
        .hand(0, &[granite_gargoyle()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, granite_gargoyle());
    pass_until(&mut engine, stack_is_empty);
    let gargoyle = on_battlefield(&engine, p0, granite_gargoyle()).expect("the Gargoyle resolved");
    assert!(
        keywords(&engine, gargoyle).contains(KeywordSet::FLYING),
        "the printed flying reaches the permanent"
    );
    assert_eq!(pt(&engine, gargoyle), (2, 2), "the body it prints");
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Red),
        2,
        "five Mountains paid {{2}}{{R}} and left two red floating"
    );

    // Ability 0 is the only line the card prints and its whole price is the
    // {R}: no {T} is on it, so the Gargoyle stays untapped and may pay the
    // same price again.
    activate(&mut engine, p0, granite_gargoyle(), 0);
    assert!(
        !stack_is_empty(&engine),
        "a pump is no mana ability, so it uses the stack"
    );
    assert_eq!(
        pt(&engine, gargoyle),
        (2, 2),
        "and nothing has happened while the targetless ability is still there"
    );
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, gargoyle),
        (2, 3),
        "{{R}} buys +0/+1, and not a point of power"
    );

    activate(&mut engine, p0, granite_gargoyle(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, gargoyle),
        (2, 4),
        "the ability carries no once-per-turn clause, so the second {{R}} \
         stacks on the first"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "both red were spent"
    );
    assert!(
        !is_tapped(&engine, gargoyle),
        "the price was mana and never its own {{T}}"
    );
}

fn helionaut() -> CardIndex {
    card_index("8d4de785-20e9-430e-8df1-f39dac0ef07d")
}

/// Helionaut prints two lines — flying, and "{1}, {T}: Add one mana of any
/// color." — and the scenario plays both off one board: the seated Soldier's
/// mana is made first, so four white Plains read as three white and one named
/// color afterwards, and the copy in hand is then cast for its {2}{W} out of
/// the mana the ability left floating. The {1} is paid from the pool and not
/// from an untapped land, which is what makes "one white less" an exact
/// statement about the price; the body and the keyword are read on both
/// objects, because a cast copy and a seated copy are the same card only if
/// nothing about either changed.
#[test]
fn helionaut_flies_and_taps_for_one_mana_of_the_color_its_controller_names() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), plains(), plains(), plains(), helionaut()])
        .hand(0, &[helionaut()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let seated = on_battlefield(&engine, p0, helionaut()).expect("the seated Soldier stands");
    assert_eq!(pt(&engine, seated), (1, 2), "the body the card prints");
    assert!(
        keywords(&engine, seated).contains(KeywordSet::FLYING),
        "flying is printed on the card and projected onto the permanent"
    );
    assert!(
        types(&engine, seated).contains(TypeSet::CREATURE),
        "a Human Soldier is a creature"
    );

    // The price of the mana line is {1} *and* its own tap, so `tap_all_mana`
    // does not press it (#159): only the four Plains go, which leaves the
    // Soldier standing to pay the {T} below.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Plains, and the Soldier's own line is not a route the helper takes"
    );
    assert!(
        !is_tapped(&engine, seated),
        "so the source is still untapped"
    );

    activate(&mut engine, p0, helionaut(), 0);
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!("\"any color\" is a question, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat is the one that names it");
    assert_eq!(
        options.len(),
        5,
        "the five colours of the game, and colorless is no colour at all \
         (CR 105.4): {options:?}"
    );
    for color in [
        ManaColor::White,
        ManaColor::Blue,
        ManaColor::Black,
        ManaColor::Red,
        ManaColor::Green,
    ] {
        assert!(
            options.contains(&color),
            "\"any color\" includes {color:?}: {options:?}"
        );
    }

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Black))
        .expect("black was one of the colours it offered");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        1,
        "the colour that was named, and not a default"
    );
    assert_eq!(
        pool.available(ManaColor::White),
        3,
        "one of the four white paid the {{1}}, so exactly three are left"
    );
    assert_eq!(pool.total(), 4, "one mana spent and one mana added");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        is_tapped(&engine, seated),
        "{{T}} is the other half of the price"
    );

    // And the card is castable for what it prints: {2}{W} out of the pool the
    // ability left behind, arriving as the same 1/2 flier the seated copy is.
    cast_with_floating(&mut engine, p0, helionaut());
    pass_until(&mut engine, stack_is_empty);
    let soldiers = all_on_battlefield(&engine, p0, helionaut());
    assert_eq!(
        soldiers.len(),
        2,
        "the second Soldier resolved onto the table"
    );
    let summoned = *soldiers
        .iter()
        .find(|id| **id != seated)
        .expect("the object that was not the seated one");
    assert_eq!(pt(&engine, summoned), (1, 2), "and is the card it prints");
    assert!(
        keywords(&engine, summoned).contains(KeywordSet::FLYING),
        "with flying, like the copy beside it"
    );
    assert!(
        is_tapped(&engine, seated),
        "the ability's tap stands after the cast"
    );
    assert!(
        !is_tapped(&engine, summoned),
        "the cast spent mana and nothing else: the new Soldier entered untapped"
    );
}

fn hidden_horror() -> CardIndex {
    card_index("db7c5a2f-9aea-4b14-86cf-7af79d6484af")
}

/// Hidden Horror is a `{1}{B}{B}` 4/4 whose one printed sentence is a price
/// asked as it enters: "sacrifice it unless you discard a creature card"
/// (`Effect::PlayerMayPayCostOr`). Both answers are played here, because
/// neither half alone is the card — the first board trades the Elf in hand for
/// the 4/4, and the second holds no creature card at all, which is the control
/// that tells a Horror kept by paying from one that merely survived.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn hidden_horror_trades_a_creature_card_for_itself_and_dies_without_one() {
    let p0 = PlayerId::new(0);

    // ---- the price is paid: a creature card is discarded and the Horror stays
    let mut engine = Duel::new(31, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[hidden_horror(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");
    cast_from_hand(&mut engine, p0, hidden_horror());

    // The trigger asks before it does anything, so the two questions it can
    // raise — "will you pay?" and "which card pays?" — are answered in the
    // order they arrive rather than in the order they are expected.
    let mut asked = false;
    for _ in 0..40 {
        if at_rest(&engine, p0) {
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::YesNo { player, .. } => {
                engine.apply(player, PlayerAction::YesNo(true)).unwrap();
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(
                    prompt,
                    ChoicePrompt::CostDiscard,
                    "the discard is a price and not a search"
                );
                // Zero is a legal answer and that is the whole sentence:
                // "sacrifice it unless you discard a creature card" asks no
                // yes-or-no question, and naming nothing is how the price is
                // declined. The `max` is what says one card pays it.
                assert_eq!(
                    (min, max),
                    (0, 1),
                    "declining is naming nothing, and one card is the price"
                );
                assert_eq!(
                    options.len(),
                    1,
                    "and the only creature card in hand is the whole menu: {options:?}"
                );
                let elf = options
                    .iter()
                    .copied()
                    .find(|id| {
                        engine
                            .state()
                            .object(*id)
                            .is_some_and(|o| o.card.is_some_and(|c| c.index == llanowar_elves()))
                    })
                    .expect("the creature card in hand is on its own menu");
                engine
                    .apply(player, PlayerAction::ChooseObjects { objects: vec![elf] })
                    .unwrap();
                asked = true;
            }
            other => panic!("unexpected while the enters-trigger resolves: {other:?}"),
        }
    }
    assert!(
        asked,
        "a creature card was in hand, so the price was offered and paid"
    );
    let horror = on_battlefield(&engine, p0, hidden_horror())
        .expect("the price was paid, so the Horror is still on the battlefield");
    assert_eq!(pt(&engine, horror), (4, 4), "and it is the body it prints");
    assert!(
        in_hand(&engine, p0, llanowar_elves()).is_none()
            && in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "the creature card left the hand that gave it up and is in its owner's graveyard"
    );

    // ---- the price cannot be paid: no creature card, so the Horror dies
    let mut engine = Duel::new(31, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[hidden_horror()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");
    assert!(
        in_hand(&engine, p0, llanowar_elves()).is_none(),
        "the control: this seat holds no creature card to discard"
    );
    cast_from_hand(&mut engine, p0, hidden_horror());
    for _ in 0..40 {
        if at_rest(&engine, p0) {
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::YesNo { player, .. } => {
                // Declining and never being asked are the same branch: with no
                // creature card in hand there is no price, and the `or` half
                // of the sentence is the Horror's own death.
                engine.apply(player, PlayerAction::YesNo(false)).unwrap();
            }
            other => panic!(
                "nothing in hand can pay `discard a creature card`, so the \
                 trigger has only its `or` branch left: {other:?}"
            ),
        }
    }
    assert!(
        in_graveyard(&engine, p0, hidden_horror()).is_some(),
        "with no creature card to discard, the enters-trigger sacrifices the Horror"
    );
    assert!(
        on_battlefield(&engine, p0, hidden_horror()).is_none(),
        "so it never stays on the battlefield"
    );
}

// oracle_id = "64553181-9852-459f-a6e0-54ce188dd937"
fn horned_sliver() -> CardIndex {
    card_index("64553181-9852-459f-a6e0-54ce188dd937")
}

/// Horned Sliver is a {2}{G} 2/2 Sliver with one printed sentence — "All
/// Sliver creatures have trample" — and that sentence takes three witnesses
/// to read. The Sliver itself is a Sliver creature, so the word is "all" and
/// not "another": the permanent printing the sentence has to carry trample.
/// The Elf beside it is a creature of the same seat that is not a Sliver, so
/// the subtype half of the filter has to be read rather than skipped, and the
/// Elf across the table says the grant is not "Sliver creatures you control"
/// either.
///
/// Then the keyword is spent, because a projection is not a rule in play. A
/// 2/2 with trample blocked by a 1/1 puts lethal damage on the blocker and
/// the other point over it: a board where the life total never moves would
/// satisfy every reading above while trample did nothing at all.
#[test]
fn horned_sliver_grants_trample_to_every_sliver_and_the_sliver_tramples_over_a_blocker() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[horned_sliver(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let sliver = on_battlefield(&engine, p0, horned_sliver()).expect("the Sliver is out");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let blocker = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert!(
        keywords(&engine, sliver).contains(KeywordSet::TRAMPLE),
        "\"all Sliver creatures\" includes the Sliver printing the sentence"
    );
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::TRAMPLE),
        "a creature of the same seat that is not a Sliver is declined"
    );
    assert!(
        !keywords(&engine, blocker).contains(KeywordSet::TRAMPLE),
        "and the static is not \"Sliver creatures you control\", so the Elf \
         across the table is declined too"
    );
    assert_eq!(
        pt(&engine, sliver),
        (2, 2),
        "the static grants a keyword and no body"
    );

    // Combat, so the keyword is spent rather than merely projected. Both
    // Elves stay home: the only attacker declared is the Sliver, and the
    // only blocker is the one across the table.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(sliver, Defender::Player(p1))],
            },
        )
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(blocker, sliver)],
            },
        )
        .unwrap();
    // Not `stack_is_empty`: the stack is empty before the combat damage step
    // too, so that predicate would stop the walk with every life total still
    // reading 20 (CR 510.2).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert_eq!(
        engine.state().players[1].life,
        19,
        "one damage kills the 1/1 blocker and the other tramples over it"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "the blocker took lethal damage"
    );
    assert!(
        on_battlefield(&engine, p0, horned_sliver()).is_some(),
        "and the 2/2 survived the one damage the Elf dealt back"
    );
}

// oracle_id = "4958baf3-2f5a-4087-bc14-ffee9887db1d"
fn hornet_cobra() -> CardIndex {
    card_index("4958baf3-2f5a-4087-bc14-ffee9887db1d")
}

/// Hornet Cobra is a printed 2/1 Snake whose entire text is "First strike",
/// so the only thing worth playing is a combat it survives by killing its
/// blocker before the blocker can strike back. It is cast off three Forests
/// on p0's own turn and attacks one turn later, because a creature that
/// arrived this turn may not attack (CR 302.6). The 1/1 Llanowar Elves that
/// blocks it deals the one damage that is lethal to a 1-toughness attacker,
/// so the Cobra standing at the end of the turn is the first-strike damage
/// step and nothing else.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn hornet_cobra_kills_its_blocker_before_the_blocker_can_strike_back() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(821, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[hornet_cobra()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches their own main"
    );

    // {1}{G}{G} off the three Forests, so the 2/1 on the table arrived the
    // way the card arrives rather than by being seated there.
    cast_from_hand(&mut engine, p0, hornet_cobra());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let cobra = on_battlefield(&engine, p0, hornet_cobra()).expect("the Cobra resolved");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("the Elf is seated");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Forests paid exactly {{1}}{{G}}{{G}}"
    );
    assert_eq!(pt(&engine, cobra), (2, 1), "the printed 2/1 body");
    assert!(
        keywords(&engine, cobra).contains(KeywordSet::FIRST_STRIKE),
        "and the whole of the card's text, projected onto the permanent"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the blocker is a printed 1/1: its one damage is lethal to a 2/1, \
         which is exactly what the first strike has to avoid"
    );

    // A turn later, because a creature that entered this turn may not attack
    // (CR 302.6) — the untap step is what makes the attack below legal.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, cobra),
        "the untap step stood the Cobra back up"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        attackers,
        defenders,
        ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&cobra),
        "an untapped, unsick 2/1 may attack: {attackers:?}"
    );
    assert!(
        defenders
            .iter()
            .any(|d| matches!(d, Defender::Player(p) if *p == p1)),
        "and the seat across the table is what it may be aimed at: {defenders:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(cobra, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player,
        attacker,
        blockers,
        ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the block declaration")
    };
    assert_eq!(player, p1, "the defending seat declares the blockers");
    assert_eq!(attacker, p0, "and it is p0's attack being blocked");
    assert!(
        blockers
            .iter()
            .any(|option| option.blocker == elf && option.attackers.contains(&cobra)),
        "the Elf is offered against the Cobra: {blockers:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(elf, cobra)],
            },
        )
        .unwrap();

    // Past the combat damage step to the end step: the stack is empty the
    // moment blockers are declared, so `stack_is_empty` would stop the walk
    // before any damage was dealt at all.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "two first-strike damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        on_battlefield(&engine, p0, hornet_cobra()).is_some(),
        "and the Cobra is still standing, which is the whole card: without \
         first strike the Elf's one damage would have landed in the same step \
         and killed it too"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the two damage went into the blocker, so nothing reached the player"
    );
}

fn horseshoe_crab() -> CardIndex {
    card_index("793f29ac-8a5d-49bf-91e8-a32f771268f3")
}

/// Horseshoe Crab is a {2}{U} 1/3 whose entire printed text is "{U}: Untap
/// this creature." — and on an untapped creature that sentence is invisible, so
/// the scenario plays the card the way the card is played: the 1/3 attacks, and
/// one blue stands it back up while the combat it is still part of carries on.
/// `legal.abilities` is filtered through `can_afford`, which reads the mana
/// pool and not the untapped Islands, so the offer is read on both sides of the
/// price — absent on an empty pool, present the moment three Islands have paid
/// in — and the pool is read a last time to say exactly one of those three blue
/// went into the untap.
#[test]
fn horseshoe_crab_attacks_and_stands_back_up_for_one_blue() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), horseshoe_crab()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches their own main"
    );

    let crab = on_battlefield(&engine, p0, horseshoe_crab()).expect("the Crab is on the table");
    assert_eq!(pt(&engine, crab), (1, 3), "the body the card prints");
    assert!(!is_tapped(&engine, crab), "and it arrives untapped");

    // Nothing is floating, and `legal.abilities` is filtered through
    // `can_afford`, which reads the pool rather than the untapped Islands.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("p0 holds a quiet main phase: {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(crab, 0)),
        "an empty pool pays no {{U}}, so the untap is not offered: {:?}",
        legal.abilities
    );

    // The card's own line: attack with it, because a tapped Crab is the only
    // Crab on which an untap can be read.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on the attack declaration")
    };
    assert!(
        attackers.contains(&crab),
        "an untapped 1/3 with no clause against it may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(crab, Defender::Player(p1))],
            },
        )
        .unwrap();
    assert!(
        is_tapped(&engine, crab),
        "declaring it as an attacker is what taps it"
    );

    // The mana is tapped only here: a pool is emptied when a step ends
    // (CR 500.5), and the precombat main phase is already behind us.
    pass_until(&mut engine, |e| {
        is_tapped(e, crab)
            && stack_is_empty(e)
            && matches!(e.pending(), Pending::Priority { player, .. } if *player == p0)
    });
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        3,
        "three Islands, and the Crab prints no mana ability of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(crab, 0)),
        "with {{U}} floating, the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, horseshoe_crab(), 0);
    assert!(
        !stack_is_empty(&engine),
        "untapping is no mana ability, so the ability waits on the stack"
    );
    assert!(
        is_tapped(&engine, crab),
        "and has not happened yet: the {{U}} is paid on announcement \
         (CR 601.2h) while the effect resolves off the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        !is_tapped(&engine, crab),
        "\"{{U}}: Untap this creature.\" — the Crab is standing again"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        2,
        "exactly one of the three blue went into the untap"
    );

    // It is still the attacking creature the tap paid for: untapping does not
    // remove it from combat, so the damage is still coming.
    pass_until(&mut engine, |e| e.state().players[1].life == 19);
    assert!(
        !is_tapped(&engine, crab),
        "and the 1/3 is still standing at the end of the combat it attacked in"
    );
}

fn juniper_order_druid() -> CardIndex {
    card_index("943ab696-470b-488f-9567-c8cd89ec06e3")
}

/// Juniper Order Druid — {2}{G} 1/1 Human Cleric Druid: "{T}: Untap target
/// land." The whole card is that one line, and it carries two claims a board
/// can separate: the tap is the price, and the target is *any* land. So the
/// Druid is cast off four Forests — which is exactly what leaves lands tapped
/// for it to untap — and a turn is walked, because a creature's {T} is not
/// payable before its controller's next turn begins (CR 302.6). The
/// opponent's own lands are tapped on their own turn, so the land this test
/// names lies across the table: the ability stands it back up, while every
/// land it did not name is still lying tapped — the single-target half of the
/// same sentence.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn juniper_order_druid_taps_itself_to_untap_one_land_of_either_seat() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), forest()])
        .battlefield(1, &[forest(), forest()])
        .hand(0, &[juniper_order_druid()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches their own main phase"
    );

    // {2}{G} off the four Forests. Tapping them is the point of the board: a
    // land already tapped is the only thing "untap target land" can be seen
    // to do.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Forests, four green — the Druid prints no mana of its own"
    );
    cast_with_floating(&mut engine, p0, juniper_order_druid());
    pass_until(&mut engine, stack_is_empty);
    let druid = on_battlefield(&engine, p0, juniper_order_druid()).expect("the Druid resolved");
    assert_eq!(pt(&engine, druid), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{2}}{{G}} came out of the four green"
    );

    // The Druid arrived this turn, so its {{T}} is not payable yet (CR 302.6).
    // The opponent's main phase is also where their lands can be tapped by
    // hand, which is what puts a tapped land on the far side of the table.
    assert!(
        walk_to_own_main(&mut engine, p1),
        "p1 reaches their own main phase"
    );
    let theirs = on_battlefield(&engine, p1, forest()).expect("an opponent's Forest is out");
    tap_all_mana(&mut engine, p1);
    assert!(
        is_tapped(&engine, theirs),
        "the opponent tapped their own lands for mana"
    );
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the Druid's controller takes another turn"
    );
    assert!(!is_tapped(&engine, druid), "and the Druid untapped with it");

    let mine = all_on_battlefield(&engine, p0, forest());
    assert_eq!(mine.len(), 4, "the four Forests that paid for the Druid");
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four tapped Forests and nothing else on this board makes mana"
    );
    assert!(
        !is_tapped(&engine, druid),
        "the helper left it standing, because the Druid is no mana source: \
         its {{T}} is the price the ability below is about to charge"
    );
    assert!(
        is_tapped(&engine, theirs),
        "and the Forest across the table is still tapped"
    );

    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the Druid's controller holds priority");
    assert!(
        legal.abilities.contains(&(druid, 0)),
        "`{{T}}: Untap target land` — the Druid's own tap is the whole price, \
         so the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, juniper_order_druid(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"untap target land\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that chooses");
    assert_eq!((min, max), (1, 1), "exactly one land");
    assert!(
        options.contains(&theirs),
        "the sentence says \"target land\" and not \"a land you control\": the \
         opponent's tapped Forest is on the menu: {options:?}"
    );
    assert!(
        mine.iter().all(|id| options.contains(id)),
        "and so is every Forest of the activating seat: {options:?}"
    );
    assert!(
        !options.contains(&druid),
        "the Druid is a creature and no land: {options:?}"
    );
    assert_eq!(
        options.len(),
        6,
        "the six lands on the table and nothing else: {options:?}"
    );
    assert!(
        !is_tapped(&engine, druid),
        "CR 601.2c before CR 601.2h: the tap is still unpaid while the target \
         question stands"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Forest across the table was one of the options it enumerated");
    assert!(
        is_tapped(&engine, druid),
        "{{T}} is the last step of the activation, paid by the Druid itself"
    );
    assert!(
        !stack_is_empty(&engine),
        "untapping a permanent is no mana ability, so the ability uses the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        !is_tapped(&engine, theirs),
        "\"untap target land\": the Forest that lay across the table stood back up"
    );
    assert!(
        mine.iter().all(|id| is_tapped(&engine, *id)),
        "and only the land that was named: every Forest the ability did not \
         target is still lying tapped"
    );
    assert!(
        on_battlefield(&engine, p0, juniper_order_druid()).is_some(),
        "an activated ability costs the Druid nothing but the tap it already paid"
    );
}

fn kabuto_moth() -> CardIndex {
    card_index("537a255c-a77b-4691-9461-68efb1aba7d4")
}

/// Kabuto Moth is a `{2}{W}` 1/2 Spirit whose whole printed text is flying and
/// "`{T}`: Target creature gets +1/+2 until end of turn." The board puts a
/// printed 1/1 on each side of the table, because "target creature" is any
/// creature and not "a creature you control" — and the answer is given to the
/// Elf *across* the table, so a pump that had quietly narrowed to the Moth's
/// own side could not satisfy it while the Elf under the same seat reads
/// `(1, 1)`. The `{T}` is read where CR 601.2h puts it: the Moth is still
/// untapped while the target question stands and tapped once it is answered,
/// and getting +1/+2 is no mana ability, so the ability uses the stack. The
/// next main phase is the other half of "until end of turn".
#[test]
fn kabuto_moth_gives_one_power_and_two_toughness_to_the_creature_it_targets() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(17, forest())
        .battlefield(
            0,
            &[
                plains(),
                plains(),
                plains(),
                llanowar_elves(),
                kabuto_moth(),
            ],
        )
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let moth = on_battlefield(&engine, p0, kabuto_moth()).expect("the Moth is out");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    assert_eq!(pt(&engine, moth), (1, 2), "the printed 1/2 body");
    assert!(
        keywords(&engine, moth).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );
    assert_eq!(pt(&engine, mine), (1, 1), "a printed 1/1 before the pump");

    // Ability 0 is the only line the card prints, and its whole price is its
    // own tap symbol: the pool is empty and stays empty, which is what says no
    // mana is part of this activation.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the pump costs no mana at all"
    );
    activate(&mut engine, p0, kabuto_moth(), 0);

    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" reaches either side of the table: {options:?}"
    );
    assert!(
        player_options.is_empty(),
        "\"target creature\" names no player (CR 115.4): {player_options:?}"
    );
    // CR 601.2c picks the target and CR 601.2h pays afterwards, so the tap is
    // still owed while this question stands.
    assert!(
        !is_tapped(&engine, moth),
        "{{T}} is the last step of the activation, not the first"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Elf across the table was one of the options");
    assert!(
        is_tapped(&engine, moth),
        "the tap was paid after the target"
    );
    assert!(
        !stack_is_empty(&engine),
        "getting +1/+2 is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, theirs),
        (2, 3),
        "+1/+2 on the creature the Moth named, and the printed 1/1 is what makes \
         both numbers legible"
    );
    assert_eq!(
        pt(&engine, mine),
        (1, 1),
        "the creature it did not name is untouched, so this is a target and not \
         a board buff"
    );
    assert_eq!(pt(&engine, moth), (1, 2), "nor does the Moth pump itself");

    // "Until end of turn", read from the far side: an effect that had no
    // duration at all would still be sitting there in the next main phase.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "the +1/+2 lasted only the turn it was given"
    );
}

fn kami_of_the_hunt() -> CardIndex {
    card_index("96e68c7a-f187-4aa6-998c-238e7c833809")
}

/// Kami of the Hunt prints "Whenever you cast a Spirit or Arcane spell, this
/// creature gets +1/+1 until end of turn" on a 2/2, so the card is only itself
/// when the trigger reads the subtype of the spell being *cast* rather than
/// something standing on the board. A second Kami out of hand is a Spirit spell
/// and pumps the Kami that was already watching, while an Elf Druid cast by the
/// same seat in the same main phase must pump nothing — the half a trigger that
/// had lost its filter would fail. The newcomer is read beside the source
/// because `Filter::This` is the reading that matters: the +1/+1 lands on the
/// Kami that saw the spell, and the copy that has only just arrived is still
/// the printed 2/2.
#[test]
fn kami_of_the_hunt_grows_for_a_spirit_spell_and_not_for_an_elf() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(76, forest())
        .battlefield(
            0,
            &[
                forest(),
                forest(),
                forest(),
                forest(),
                forest(),
                forest(),
                kami_of_the_hunt(),
            ],
        )
        .hand(0, &[kami_of_the_hunt(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let source = on_battlefield(&engine, p0, kami_of_the_hunt()).expect("the Kami is out");
    assert_eq!(
        pt(&engine, source),
        (2, 2),
        "the printed 2/2 before anything is cast"
    );

    // A Spirit spell: the copy out of hand is one, so the Kami already on the
    // battlefield grows. Six Forests pay {2}{G} and leave the control's {G}.
    cast_from_hand(&mut engine, p0, kami_of_the_hunt());
    pass_until(&mut engine, stack_is_empty);
    let copies = all_on_battlefield(&engine, p0, kami_of_the_hunt());
    assert_eq!(
        copies.len(),
        2,
        "the second Kami resolved onto the battlefield"
    );
    let newcomer = *copies
        .iter()
        .find(|id| **id != source)
        .expect("the copy that just arrived is a distinct object");
    assert_eq!(
        pt(&engine, source),
        (3, 3),
        "a Spirit spell was cast, so the Kami that watched it grew by one"
    );
    assert_eq!(
        pt(&engine, newcomer),
        (2, 2),
        "the +1/+1 belongs to the Kami that watched the spell, not to every \
         Spirit on the table"
    );

    // The control: an Elf Druid is a creature spell and neither a Spirit nor an
    // Arcane one, so the Kami that has just grown must not grow again.
    cast_from_hand(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the Elf resolved, so the claim below is about a spell that was really cast"
    );
    assert_eq!(
        pt(&engine, source),
        (3, 3),
        "an Elf Druid is neither a Spirit nor an Arcane spell"
    );
}

fn kavu_glider() -> CardIndex {
    card_index("425050a7-41d2-4850-bb45-3a83275d3c50")
}

/// Kavu Glider is a `{2}{R}` 2/1 Kavu with two one-colour activated
/// abilities that each reach only itself: "{W}: This creature gets +0/+1
/// until end of turn" and "{U}: This creature gains flying until end of
/// turn". They are played on separate turns because each price is a single
/// coloured mana and the pool on the turn one is taken holds exactly one
/// mana of that colour — so "the price was paid" is an exact reading rather
/// than a claim about which of several floating sources got spent. The Elf
/// kept standing beside the Glider is the control: `Filter::This` is not "a
/// creature you control", and turning the page between the two activations
/// is what reads "until end of turn", because the toughness is back to the
/// printed 1 by the time the flying is granted.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn kavu_glider_pays_white_for_toughness_and_blue_for_flying_on_itself_alone() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(8241, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain(), llanowar_elves()])
        .hand(0, &[kavu_glider(), plains(), island()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Three Mountains pay `{2}{R}` and nothing else, and the Elf is named as
    // the printing kept back: it is this test's control creature, and a
    // source tapped for mana has already changed status for a reason of its
    // own.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Mountains tapped and the Elf left standing"
    );
    cast_with_floating(&mut engine, p0, kavu_glider());
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{2}}{{R}} is the whole of the printed cost"
    );

    let glider = on_battlefield(&engine, p0, kavu_glider()).expect("the Glider resolved");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is on the table");
    assert_eq!(pt(&engine, glider), (2, 1), "the body the card prints");
    assert!(
        !keywords(&engine, glider).contains(KeywordSet::FLYING),
        "and neither ability has been paid for yet"
    );

    // Turn two: the Plains, whose single white is the only white in the pool
    // when the first ability is taken.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    play_land(&mut engine, p0, plains());
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        1,
        "the Plains tapped and one white is floating"
    );

    // Ability 0 is "{W}: This creature gets +0/+1 until end of turn."
    activate(&mut engine, p0, kavu_glider(), 0);
    assert!(
        !stack_is_empty(&engine),
        "a pump is no mana ability, so it uses the stack (CR 605.1)"
    );
    assert_eq!(
        pt(&engine, glider),
        (2, 1),
        "and nothing has happened while it is still on the stack (CR 608.2)"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, glider),
        (2, 2),
        "+0/+1 on itself: the toughness moved and the power did not, which a \
         (3, 2) would deny"
    );
    assert!(
        !keywords(&engine, glider).contains(KeywordSet::FLYING),
        "the white ability grants no keyword"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        0,
        "the {{W}} was the whole price and it is gone"
    );
    assert_eq!(pt(&engine, elf), (1, 1), "the Elf was not pumped");

    // Turn three: the Island, and with it the other half of "until end of
    // turn" — last turn's +0/+1 did not survive its own cleanup step.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        pt(&engine, glider),
        (2, 1),
        "\"until end of turn\": the pump lasted the turn it was paid for and \
         no longer"
    );
    play_land(&mut engine, p0, island());
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        1,
        "the Island tapped and one blue is floating"
    );

    // Ability 1 is "{U}: This creature gains flying until end of turn."
    activate(&mut engine, p0, kavu_glider(), 1);
    pass_until(&mut engine, stack_is_empty);

    assert!(
        keywords(&engine, glider).contains(KeywordSet::FLYING),
        "{{U}}: the Glider gains flying"
    );
    assert_eq!(
        pt(&engine, glider),
        (2, 1),
        "and the blue ability moves no numbers at all"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        0,
        "the {{U}} was the whole price of the second activation"
    );
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FLYING),
        "the Elf stays on the ground: `Filter::This` names one creature"
    );
}

fn keen_eyed_archers() -> CardIndex {
    card_index("0ace32d6-7261-447c-9ee2-e03febaab91b")
}

/// Keen-Eyed Archers — {2}{W}, a 2/2 Elf Archer whose whole printed text is
/// reach: "This creature can block creatures with flying."
///
/// Reach is neither a body nor a pump, so the one place it can be read is the
/// pairing `Pending::ChooseBlockers` publishes. p1 attacks with a flier and
/// with a ground 1/1, and beside the Archer stands an untapped Elf of p0's
/// own: the Archer is paired with both attackers while the Elf is paired with
/// the ground one alone — same table, same flier, and the keyword is the only
/// difference. The blocks are then really declared and the attack is stopped,
/// so the offer was a permission the board acted on and not merely a list.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn keen_eyed_archers_blocks_the_flier_where_the_plain_elf_beside_it_cannot() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains(), llanowar_elves()])
        .battlefield(1, &[sphinx_of_the_final_word(), llanowar_elves()])
        .hand(0, &[keen_eyed_archers()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches a main phase of its own"
    );

    // Three Plains pay {2}{W}. The Elf is named as the one source kept back:
    // it is the untapped bystander the block offer below is read against, and
    // a creature tapped for mana has a status that changed for its own reason.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    cast_with_floating(&mut engine, p0, keen_eyed_archers());
    pass_until(&mut engine, stack_is_empty);

    let archers = on_battlefield(&engine, p0, keen_eyed_archers()).expect("the Archers resolved");
    let bystander =
        on_battlefield(&engine, p0, llanowar_elves()).expect("the kept Elf is still standing");
    assert_eq!(pt(&engine, archers), (2, 2), "the body the card prints");
    assert!(
        keywords(&engine, archers).contains(KeywordSet::REACH),
        "reach is printed on the card and reached the characteristics through the layers"
    );
    assert!(
        !keywords(&engine, bystander).contains(KeywordSet::REACH),
        "and the Elf beside it prints none, which is what makes the pairing below a filter"
    );

    // Across the table and into p1's combat. The walk uses the kit's own
    // answerer rather than `pass_until`, because a turn boundary is crossed
    // here: a seat over its hand size is asked to discard on the way, and
    // `answer_one` answers that question too.
    let mut asked_for_attackers = false;
    for _ in 0..600 {
        if matches!(engine.pending(), Pending::ChooseAttackers { player, .. } if *player == p1) {
            asked_for_attackers = true;
            break;
        }
        let (player, action) = answer_one(&engine)
            .expect("a turn cycle on this board asks only questions this kit can answer");
        engine
            .apply(player, action)
            .expect("the answer came out of the question");
    }
    assert!(
        asked_for_attackers,
        "p1's combat step arrives and asks for attackers"
    );

    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("the walk stopped on the attack declaration")
    };
    let flier =
        on_battlefield(&engine, p1, sphinx_of_the_final_word()).expect("the flier is on the table");
    let ground = on_battlefield(&engine, p1, llanowar_elves()).expect("their ground 1/1 is out");
    assert!(
        attackers.contains(&flier) && attackers.contains(&ground),
        "both of p1's untapped creatures may attack: {attackers:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (flier, Defender::Player(p0)),
                    (ground, Defender::Player(p0)),
                ],
            },
        )
        .expect("both were enumerated as attackers");

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the block declaration")
    };
    assert_eq!(player, p0, "the attacked seat is the one asked to block");

    let archer_pairing = blockers
        .iter()
        .find(|o| o.blocker == archers)
        .expect("an untapped creature with reach is a blocker, so the Archer is on the menu");
    assert!(
        archer_pairing.attackers.contains(&flier),
        "reach: the Archer can block the creature with flying: {:?}",
        archer_pairing.attackers
    );
    assert!(
        archer_pairing.attackers.contains(&ground),
        "and the ground attacker is blockable by it too, so the flight rule is \
         read per pairing and not as a filter over the whole list: {:?}",
        archer_pairing.attackers
    );

    let elf_pairing = blockers
        .iter()
        .find(|o| o.blocker == bystander)
        .expect("the Elf beside it may block the ground attacker, so it is on the menu too");
    assert!(
        elf_pairing.attackers.contains(&ground),
        "an untapped 1/1 with no evasion of its own may block a ground 1/1: {:?}",
        elf_pairing.attackers
    );
    assert!(
        !elf_pairing.attackers.contains(&flier),
        "and it may not block the flier — no reach, no flying, no pairing: {:?}",
        elf_pairing.attackers
    );

    // The offer is a permission and this is the act: both attackers are
    // blocked, so no combat damage reaches the player (CR 509.1, CR 510.1).
    engine
        .apply(
            p0,
            PlayerAction::DeclareBlockers {
                blockers: vec![(archers, flier), (bystander, ground)],
            },
        )
        .expect("both pairings were enumerated");
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[0].life,
        20,
        "every attacker was blocked, so the reach pairing resolved into a real \
         block and nothing got through"
    );
}

// Killer Bees — {1}{G}{G} — Creature — Insect, printed 0/1.

fn killer_bees() -> CardIndex {
    card_index("5da1f1af-d2e5-4e14-914b-d93f15626636")
}

/// Killer Bees is a `{1}{G}{G}` 0/1 Insect with flying and one activated
/// line: "{G}: This creature gets +1/+1 until end of turn."
///
/// The word the card turns on is *repeatable*: the pump has no `{T}` and no
/// once-a-turn clause, so one pool of green has to buy two counters rather
/// than one — a one-shot pump would leave a 1/2 after the first activation
/// and pass a test that stopped there. Five Forests pay the cast and leave
/// exactly the two `{G}` the scenario then spends, which is also why the
/// pool is read after each step: three green gone on the cast, one per
/// activation, and nothing left at the end. The empty pool is the control
/// for the last claim — with no mana floating the ability is not offered at
/// all, because `can_afford` reads the pool and not the Forests beside it.
#[test]
fn killer_bees_pumps_itself_once_per_green_paid() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), forest(), forest()])
        .hand(0, &[killer_bees()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Five Forests into the pool first: a cast is only claimable against
    // what is actually floating (rule 6), and the same mana is what the two
    // activations below are read against.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        5,
        "five Forests, five green — the Bees are a card in hand, not a source"
    );
    cast_with_floating(&mut engine, p0, killer_bees());
    pass_until(&mut engine, stack_is_empty);

    let bees = on_battlefield(&engine, p0, killer_bees()).expect("the Bees resolved");
    assert_eq!(
        pt(&engine, bees),
        (0, 1),
        "the printed body, before anything pumps it"
    );
    assert!(
        keywords(&engine, bees).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the {{1}}{{G}}{{G}} came out of the pool and left two green"
    );

    // Ability 0 is the printed "{G}: This creature gets +1/+1 until end of
    // turn." Its price is mana and not its own tap, so `tap_all_mana` never
    // pressed it and the creature is still standing to be pumped.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(bees, 0)),
        "with two green floating the pump is affordable, so it is offered: {:?}",
        legal.abilities
    );
    assert!(
        !is_tapped(&engine, bees),
        "the price is not the tap symbol; nothing has tapped the creature"
    );

    // The first payment, and the order CR 601.2h puts on it: the ability is
    // on the stack and the green is already spent, while the body is still
    // the printed 0/1 because nothing has resolved yet.
    activate(&mut engine, p0, killer_bees(), 0);
    assert!(
        !stack_is_empty(&engine),
        "the pump is no mana ability, so it waits on the stack"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{G}} is paid as the ability is activated"
    );
    assert_eq!(
        pt(&engine, bees),
        (0, 1),
        "and the pump has not happened yet"
    );
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, bees),
        (1, 2),
        "+1/+1 on the creature the ability names, and no other"
    );

    // The second payment is the whole card: the line is repeatable, so the
    // counter stacks instead of replacing itself.
    activate(&mut engine, p0, killer_bees(), 0);
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, bees),
        (2, 3),
        "a second {{G}} buys a second +1/+1 — a one-shot pump would read 1/2"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "both green are spent and the pool is empty"
    );
    assert!(
        keywords(&engine, bees).contains(KeywordSet::FLYING),
        "and the printed flying survives every layer of the pump"
    );

    // The emptied pool is the control: an unaffordable ability is absent
    // from the offer rather than refused, so an empty pool means no pump.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(bees, 0)),
        "with nothing floating the {{G}} cannot be paid, so the pump is not \
         offered at all — the five tapped Forests beside it are not mana the \
         engine may spend: {:?}",
        legal.abilities
    );
}

fn krark_clan_grunt() -> CardIndex {
    card_index("e7be5ab3-a11f-4786-9b0b-1daa94f59440")
}

/// Krark-Clan Grunt is a `{2}{R}` 2/2 Goblin Warrior whose whole text is one
/// line: "Sacrifice an artifact: This creature gets +1/+0 and gains first
/// strike until end of turn."
///
/// The price names no artifact in particular, so the engine has to ask which
/// one — and that menu is half the card: both Sol Rings under this seat are on
/// it, while the Sol Ring across the table is not (CR 701.21a, a seat
/// sacrifices only what it controls) and the Grunt itself is a creature, not
/// an artifact. Two Rings stand on the board so the second activation's menu
/// can show that a cost letting one artifact answer twice would have eaten both
/// from a single press, and the pump is read off the layer projection — 2/2 to
/// 3/2 to 4/2, first strike with the first one — which no count of activations
/// could tell from a body that never changed.
#[allow(clippy::too_many_lines)] // two activations, and every clause of the card read off them
#[test]
fn krark_clan_grunt_eats_its_own_artifacts_to_pump_itself_one_at_a_time() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                quiet_artifact(),
                quiet_artifact(),
                krark_clan_grunt(),
            ],
        )
        // An artifact on the other side of the table: "sacrifice an artifact"
        // is not an invitation to eat somebody else's.
        .battlefield(1, &[quiet_artifact()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let grunt = on_battlefield(&engine, p0, krark_clan_grunt()).expect("the Grunt is out");
    let rings = all_on_battlefield(&engine, p0, quiet_artifact());
    assert_eq!(rings.len(), 2, "two artifacts, one per activation");
    let (first, second) = (rings[0], rings[1]);
    let theirs = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    assert_eq!(pt(&engine, grunt), (2, 2), "a printed 2/2");
    assert!(
        !keywords(&engine, grunt).contains(KeywordSet::FIRST_STRIKE),
        "and nothing has pumped it yet"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the price is an artifact and no mana, so nothing is floating"
    );

    // The cost is a sacrifice, so `can_afford` turns on the board and not on
    // the pool: the line is offered with an empty pool and an untapped Grunt.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(grunt, 0)),
        "an artifact to eat is the whole price, so the line is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, krark_clan_grunt(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which artifact, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "the two artifacts this seat controls: {options:?}"
    );
    assert!(
        options.contains(&first) && options.contains(&second),
        "both Sol Rings are on the menu: {options:?}"
    );
    assert!(
        !options.contains(&grunt),
        "the Grunt is a Goblin Warrior and no artifact: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "CR 701.21a: an opponent's artifact is not yours to sacrifice: {options:?}"
    );

    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![first],
            },
        )
        .expect("the artifact the question offered pays the cost");
    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "CR 601.2h: the sacrifice is the last step and is already paid"
    );
    assert!(
        !stack_is_empty(&engine),
        "pumping a creature is no mana ability, so the ability is on the stack"
    );
    assert_eq!(
        pt(&engine, grunt),
        (2, 2),
        "and nothing has resolved yet, so the pump is still on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(pt(&engine, grunt), (3, 2), "+1/+0 from the first Ring");
    assert!(
        keywords(&engine, grunt).contains(KeywordSet::FIRST_STRIKE),
        "and the printed first strike arrives with it"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_some(),
        "the second Ring is still standing to be eaten"
    );

    // The second activation, and the same menu one shorter. A cost that let
    // one artifact answer twice would have emptied the board from the first
    // press and offered nothing here.
    activate(&mut engine, p0, krark_clan_grunt(), 0);
    let Pending::ChooseCards { options, .. } = engine.pending().clone() else {
        panic!(
            "the second activation asks again, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(
        options,
        vec![second],
        "one Ring left, and the one already eaten is not on the menu"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![second],
            },
        )
        .expect("the artifact the question offered pays the cost");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, grunt),
        (4, 2),
        "two activations stack: +1/+0 twice"
    );
    assert!(
        keywords(&engine, grunt).contains(KeywordSet::FIRST_STRIKE),
        "and the keyword it already had is still there"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_none(),
        "both artifacts were spent rather than one answering twice"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        2,
        "and both are in their owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the opponent's board never moved"
    );
}

// oracle_id = "756b4bc9-6f3f-4eae-b6b0-63c94ed8482f"
fn krark_clan_stoker() -> CardIndex {
    card_index("756b4bc9-6f3f-4eae-b6b0-63c94ed8482f")
}

/// Krark-Clan Stoker is `{2}{R}` for a 2/2 Goblin Shaman whose whole text is
/// `{T}, Sacrifice an artifact: Add {R}{R}` — a *mana* ability (CR 605.1)
/// whose price is a tap and an artifact and no mana, so the pool read empty
/// before the activation and exactly two red after it is a statement about
/// the Stoker and about nothing else on the board. The menu the cost opens is
/// the other half: the two Sol Rings under the same seat are on it, while the
/// Elf beside them and the Sol Ring across the table are not, which is
/// `YOUR_ARTIFACT` read rather than skipped (CR 701.21a). And because the
/// Stoker is a creature, it cannot be one of the artifacts it eats — the half
/// a filter widened to "any permanent you control" would quietly lose.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn krark_clan_stoker_taps_and_eats_an_artifact_for_two_red() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                krark_clan_stoker(),
                quiet_artifact(),
                quiet_artifact(),
                llanowar_elves(),
            ],
        )
        // The same artifact on the other side of the table: "sacrifice an
        // artifact" is not an invitation to eat somebody else's.
        .battlefield(1, &[quiet_artifact()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let stoker = on_battlefield(&engine, p0, krark_clan_stoker()).expect("the Stoker is out");
    let rings = all_on_battlefield(&engine, p0, quiet_artifact());
    assert_eq!(rings.len(), 2, "two artifacts to choose between");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    let theirs = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");

    // The price is `{T}` and an artifact and nothing else, so no source has to
    // be tapped before the offer is read — and an empty pool is what makes the
    // two red below exact rather than two red on top of whatever was floating.
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert_eq!(player, p0, "and it is the seat with the Stoker");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats before the Stoker is paid"
    );
    assert!(
        legal.abilities.contains(&(stoker, 0)),
        "an untapped Stoker with an artifact to eat, so its one line is \
         offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, krark_clan_stoker(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the sacrifice is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell them apart"
    );
    assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "the two artifacts this seat controls and nothing else: {options:?}"
    );
    assert!(
        options.contains(&rings[0]) && options.contains(&rings[1]),
        "both Sol Rings are artifacts you control: {options:?}"
    );
    assert!(
        !options.contains(&elves),
        "the Elf is a creature: \"an artifact\" is read, not skipped: {options:?}"
    );
    assert!(
        !options.contains(&stoker),
        "and the Stoker is the other creature on this board — a creature \
         cannot pay an artifact price, not even with itself: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: an opponent's artifact is not yours to sacrifice: {options:?}"
    );
    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![rings[1]],
            },
        )
        .expect("the artifact the question offered pays the cost");

    assert!(
        stack_is_empty(&engine),
        "`CR 605.3b`: a mana ability uses no stack, so the mana is already here"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "and the seat holds priority again, got {:?}",
        engine.pending()
    );

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Red), 2, "`Add {{R}}{{R}}`");
    assert_eq!(
        pool.total(),
        2,
        "and nothing else: the pool was empty before the activation, so both \
         red came off the Stoker's own ability"
    );

    assert!(
        is_tapped(&engine, stoker),
        "`{{T}}` was half the cost, paid by the Stoker itself"
    );
    assert!(
        on_battlefield(&engine, p0, krark_clan_stoker()).is_some(),
        "the Stoker ate an artifact and not itself"
    );
    let left = all_on_battlefield(&engine, p0, quiet_artifact());
    assert_eq!(left.len(), 1, "one of the two Sol Rings paid the price");
    assert!(
        left.contains(&rings[0]) && !left.contains(&rings[1]),
        "and it is the artifact that was not named that is still standing"
    );
    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "a sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the opponent's board never moved"
    );

    // The tap is spent, so the line is no longer one the seat may take — the
    // same pool-and-permanent reading as above, one activation later.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds priority again, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(stoker, 0)),
        "a tapped Stoker has no `{{T}}` left to pay with: {:?}",
        legal.abilities
    );
}

// oracle_id = "228f0afa-146b-4564-a380-71595cdf1ef4"
fn land_leeches() -> CardIndex {
    card_index("228f0afa-146b-4564-a380-71595cdf1ef4")
}

/// Land Leeches — {1}{G}{G}, a 2/2 Leech whose whole printed text is first
/// strike, and first strike is a claim about *when* the body deals damage and
/// not about the body. So the scenario is a trade that does not happen: a
/// Llanowar Elves under a Rancor is a 3/2 attacker — three power to kill the
/// Leech, two toughness for the Leech to kill — and simultaneous damage would
/// kill both while trampling a point through to the player. Because the Leech
/// strikes first, the Elf is dead in the first-strike combat damage step
/// before it can deal anything at all, and the Leech is still standing with no
/// damage marked on it and the defending player's life untouched.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn land_leeches_strikes_first_so_the_attacker_it_blocks_never_deals_its_damage() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(1919, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[land_leeches()])
        .battlefield(1, &[forest(), llanowar_elves()])
        .hand(1, &[rancor()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{G}{G} off the three Forests. The body is read off the layer
    // projection, which is the only reading that sees a printed keyword as a
    // keyword the game will act on.
    cast_from_hand(&mut engine, p0, land_leeches());
    pass_until(&mut engine, stack_is_empty);
    let leech = on_battlefield(&engine, p0, land_leeches()).expect("the Leech resolved");
    assert_eq!(pt(&engine, leech), (2, 2), "the body the card prints");
    assert!(
        keywords(&engine, leech).contains(KeywordSet::FIRST_STRIKE),
        "first strike is the whole of the card's text"
    );
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("the Elf is out");
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FIRST_STRIKE),
        "an ordinary creature beside it has none, so the reading above is \
         about this card and not about the reader"
    );

    // p1's turn: Rancor on the Elf turns a printed 1/1 into the 3/2 the trade
    // needs. The Forest pays for it and the Elf is named as the source kept
    // back, because the Elf is this turn's attacker.
    reach_their_main_phase(&mut engine, p1);
    tap_all_mana_but(&mut engine, p1, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[1].mana_pool.total(),
        1,
        "one Forest tapped, and the Elf still standing"
    );
    cast_with_floating(&mut engine, p1, rancor());
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!("an Aura is cast at a creature, got {:?}", engine.pending())
    };
    assert!(
        options.contains(&elf),
        "\"enchant creature\" offers the only creature on p1's side: {options:?}"
    );
    engine
        .apply(p1, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options it enumerated");
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, elf),
        (3, 1),
        "Rancor prints +2/+0 and not +2/+1: a 1/1 becomes a 3/1, which is \
         three power to kill the Leech and one toughness for first strike to \
         kill first"
    );
    assert!(
        keywords(&engine, elf).contains(KeywordSet::TRAMPLE),
        "and the trample that would carry the odd point through to the player"
    );

    // The attack and the block. Both creatures die to one simultaneous damage
    // step; the printed first strike is what decides that only one of them
    // does.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(elf, Defender::Player(p0))],
            },
        )
        .expect("an untapped 3/2 with no text of its own may attack");
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareBlockers {
                blockers: vec![(leech, elf)],
            },
        )
        .expect("the Leech may block the attacker it can kill");

    // Past both damage steps and the post-combat main: the end step is where
    // the death, the marked damage and the trample would all have shown.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "the first-strike damage step killed the attacker (CR 510.4)"
    );
    assert!(
        on_battlefield(&engine, p0, land_leeches()).is_some(),
        "and the Leech is still on the battlefield: without first strike both \
         would have died in the same damage step"
    );
    assert_eq!(
        pt(&engine, leech),
        (2, 2),
        "nothing was dealt back to it, so no damage is marked on it"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and the trample never had a combat damage step to carry anything \
         through in"
    );
}

// oracle_id = "23d42beb-5293-4f12-a732-3531a0fa0ca0"
fn leaping_lizard() -> CardIndex {
    card_index("23d42beb-5293-4f12-a732-3531a0fa0ca0")
}

/// Leaping Lizard — {1}{G}{G} 2/3 Lizard: "{1}{G}: This creature gets -0/-1
/// and gains flying until end of turn."
///
/// Both halves of the pump are read off one activation, and each is something
/// the card file alone cannot say happened: the toughness moves (2, 3) →
/// (2, 2) while the power stays, and `KeywordSet::FLYING` appears only once
/// the layers have projected it. The Elf beside it is the control —
/// `Filter::This` is not "creatures you control", so a filter that had widened
/// would have shrunk and lifted the Elf too. The two Forests are named as the
/// printing kept untapped, so the pool the ability empties is exactly the
/// {1}{G} it charges.
#[test]
fn leaping_lizard_trades_toughness_for_flying_and_for_nothing_else() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), leaping_lizard(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let lizard = on_battlefield(&engine, p0, leaping_lizard()).expect("the Lizard is out");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert_eq!(
        pt(&engine, lizard),
        (2, 3),
        "a printed 2/3 before anything is asked"
    );
    assert!(
        !keywords(&engine, lizard).contains(KeywordSet::FLYING),
        "and nothing has granted it flying yet"
    );

    // `legal.abilities` is filtered through `can_afford`, and that reads the
    // pool rather than the untapped lands: no {1}{G}, no offer.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(lizard, 0)),
        "with an empty pool the {{1}}{{G}} is unpayable, so the one line the \
         card prints is not offered: {:?}",
        legal.abilities
    );

    // The Elf is named as the printing kept back: it prints its own
    // `{T}: Add {G}` (#159), and a pool of three would make the payment below
    // a claim about mana nothing on this board accounted for.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Forests tapped, and the Elf left standing"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(lizard, 0)),
        "with {{1}}{{G}} floating the whole price is payable: {:?}",
        legal.abilities
    );

    // Ability 0 is the only ability the card prints.
    activate(&mut engine, p0, leaping_lizard(), 0);
    assert!(
        !stack_is_empty(&engine),
        "shrinking a creature and granting it flying is no mana ability, so it \
         is on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, lizard),
        (2, 2),
        "\"gets -0/-1\": the toughness moves and the power does not"
    );
    assert!(
        keywords(&engine, lizard).contains(KeywordSet::FLYING),
        "and the resolution grants flying, which only the layers can project"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{G}} it charges came out of the pool"
    );

    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the Elf nothing named never moved"
    );
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FLYING),
        "and gained none of the keyword"
    );
    assert!(
        !is_tapped(&engine, lizard),
        "the price is mana and not a tap, so the Lizard may still attack"
    );
}

fn ley_druid() -> CardIndex {
    card_index("a4ae41c7-9631-407d-8fd3-04f403d940a8")
}

/// Ley Druid — {2}{G}, a 1/1 Human Druid whose whole printed text is one line:
/// "{T}: Untap target land."
///
/// The board is built so three readings of that line disagree. Two tapped
/// Forests under the Druid's own seat say the untap is not "untap each land",
/// the Sol Ring beside them is a nonland permanent the word "land" must
/// decline, and the Forest across the table is the other half of "target land",
/// which names no controller at all. The mana floated before the activation is
/// read again afterwards, because the price is the tap symbol and no mana — an
/// ability that had spent it would read one or more lower.
#[test]
fn ley_druid_taps_to_untap_one_land_on_either_side_of_the_table() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[ley_druid(), forest(), forest(), quiet_artifact()])
        .battlefield(1, &[forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let druid = on_battlefield(&engine, p0, ley_druid()).expect("the Druid is out");
    let rock = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring is out");
    let theirs = on_battlefield(&engine, p1, forest()).expect("their Forest is out");
    let forests = all_on_battlefield(&engine, p0, forest());
    assert_eq!(forests.len(), 2, "two Forests under the Druid's seat");
    let (wanted, bystander) = (forests[0], forests[1]);

    // The Forests need a reason to stand back up, so every source is tapped
    // first — and the Druid is not one of them: `{{T}}: Untap target land` is
    // no mana ability, so the helper never presses it.
    tap_all_mana(&mut engine, p0);
    assert!(
        is_tapped(&engine, wanted) && is_tapped(&engine, bystander),
        "both Forests paid their {{T}}"
    );
    assert!(is_tapped(&engine, rock), "and so did the Sol Ring");
    assert!(
        !is_tapped(&engine, druid),
        "the Druid's own line is still paid for by a tap nobody has spent"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "two Forests and the Sol Ring's own {{T}}: Add {{C}}{{C}}"
    );

    activate(&mut engine, p0, ley_druid(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target land\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that activated chooses");
    assert!(
        options.contains(&wanted) && options.contains(&bystander),
        "both of this seat's lands are on the menu: {options:?}"
    );
    assert!(
        options.contains(&theirs),
        "\"target land\" names no controller, so a land across the table is as \
         legal as one of our own: {options:?}"
    );
    assert!(
        !options.contains(&rock),
        "the Sol Ring is an artifact and no land: {options:?}"
    );
    assert!(
        !options.contains(&druid),
        "and the Druid is a creature: a land is what this line turns back over: \
         {options:?}"
    );
    assert_eq!(
        options.len(),
        3,
        "two Forests of ours and one of theirs, and nothing else on this board \
         is a land: {options:?}"
    );

    // CR 601.2c names the target and CR 601.2h pays afterwards, so the Druid
    // is still standing while the question is open.
    assert!(
        !is_tapped(&engine, druid),
        "the cost is the last step of the activation, not the first"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![wanted],
            },
        )
        .expect("the Forest was one of the options it enumerated");

    assert!(is_tapped(&engine, druid), "{{T}} is what the line charges");
    assert!(
        is_tapped(&engine, wanted),
        "and untapping is no mana ability, so the named land is still down \
         while the ability sits on the stack"
    );
    assert!(!stack_is_empty(&engine), "which is where it went");

    pass_until(&mut engine, stack_is_empty);

    assert!(
        !is_tapped(&engine, wanted),
        "\"Untap target land\" — the land that was named stands back up"
    );
    assert!(
        is_tapped(&engine, bystander),
        "the Forest nobody named is still down, so this untaps one land and not \
         every land its controller has"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "the {{T}} was the whole price: the mana the Forests and the Sol Ring \
         made is still floating, and an ability that had spent any of it would \
         read lower here"
    );
}

fn lieutenant_kirtar() -> CardIndex {
    card_index("ad39e859-e4a6-49cc-b738-4578a5250538")
}

/// Lieutenant Kirtar is a 2/2 flier whose whole printed text is one
/// sacrifice: "{1}{W}, Sacrifice Lieutenant Kirtar: Exile target attacking
/// creature."
///
/// The scenario plays that sentence at the only moment it exists — inside the
/// opponent's combat, after attackers are declared — and reads the word
/// "attacking" off the menu: one of p1's two identical Elves was sent and the
/// other stayed home, so an offer holding exactly the first is the filter and
/// not a board buff. Both prices are read where CR 601.2h puts them, after the
/// target is answered, and the exile is read as a zone rather than as an
/// absence, because the Elf leaving the battlefield would look the same.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn lieutenant_kirtar_sacrifices_itself_to_exile_the_creature_that_attacked() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[lieutenant_kirtar(), plains(), plains()])
        .battlefield(1, &[llanowar_elves(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);

    // p1's attack: one Elf is sent across the table, the other stays home.
    reach_their_main_phase(&mut engine, p1);
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let elves = all_on_battlefield(&engine, p1, llanowar_elves());
    assert_eq!(elves.len(), 2, "two Elves, one of which is sent");
    let (attacker, home) = (elves[0], elves[1]);
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(attacker, Defender::Player(p0))],
            },
        )
        .unwrap();

    // Walk the combat step until the defending seat holds priority — the only
    // window the printed sentence can be used in — answering the block
    // declaration with nothing on the way.
    let mut offered = false;
    for _ in 0..20 {
        match engine.pending().clone() {
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::Priority { player, .. } if player == p0 => {
                offered = true;
                break;
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!("unexpected while the Elf attacks: {other:?}"),
        }
    }
    assert!(offered, "the defender is offered priority inside combat");

    let kirtar = on_battlefield(&engine, p0, lieutenant_kirtar()).expect("the Bird is out");
    assert!(
        keywords(&engine, kirtar).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );
    assert_eq!(pt(&engine, kirtar), (2, 2), "the body the card prints");

    // The offer is read off the *pool*, so the two Plains are tapped first.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Plains, and the Bird makes no mana of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(kirtar, 0)),
        "with {{1}}{{W}} floating the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, lieutenant_kirtar(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target attacking creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&attacker),
        "the Elf that attacked is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&home),
        "and the Elf that stayed home is not: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p0, lieutenant_kirtar()).is_some(),
        "CR 601.2h pays last, so the Bird is still on the battlefield while \
         the target question stands"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "and the {{1}}{{W}} is still in the pool for the same reason"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![attacker],
            },
        )
        .expect("the attacking Elf was one of the options it enumerated");

    assert!(
        in_graveyard(&engine, p0, lieutenant_kirtar()).is_some(),
        "sacrificing the Bird is the other half of the price"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{1}}{{W}} came out of the pool"
    );
    assert!(!stack_is_empty(&engine), "exiling is no mana ability");

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "the Elf that did not attack is still standing"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Exile(p1)).len(),
        1,
        "exile is where the card went, which a battlefield count alone would \
         not have told apart from a graveyard"
    );
    assert!(
        engine
            .state()
            .zones
            .list(ZoneLocation::Exile(p1))
            .contains(&attacker),
        "and the exiled card is the creature that was named"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_none(),
        "\"exile\": nothing of the Elf reached a graveyard"
    );
}

fn llanowar_cavalry() -> CardIndex {
    card_index("3e6e70eb-6638-4aa6-997b-90f5810e12a0")
}

/// Llanowar Cavalry is a printed `{2}{G}` 1/4 with one activated line —
/// "`{W}`: This creature gains vigilance until end of turn." — and nothing
/// else, so the whole card is the difference between a body and a body that
/// can attack and still block. The board separates the two halves of the
/// price: three Forests pay the `{2}{G}` while the Plains is named as the
/// thing kept back, because it is the only source on the table that can pay
/// the `{W}`, and the offer for the ability is read twice — absent on an
/// empty pool and present once white is floating — which is the reading
/// `can_afford` actually does (it reads the pool, never the untapped lands).
/// The keyword is read off the layer projection afterwards, where a granted
/// vigilance is the only kind that can be seen.
#[test]
fn llanowar_cavalry_spends_a_white_for_vigilance_it_never_printed() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), plains()])
        .hand(0, &[llanowar_cavalry()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{G} off the three Forests, with the Plains named as the source kept
    // back: it is the only one that can pay the {W} the ability charges, and
    // a Plains tapped for the creature would leave the second half of the
    // card unpayable for the rest of the turn.
    tap_all_mana_but(&mut engine, p0, Some(plains()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Forests tapped, and the Plains still standing for the {{W}}"
    );
    cast_with_floating(&mut engine, p0, llanowar_cavalry());
    pass_until(&mut engine, stack_is_empty);

    let cavalry = on_battlefield(&engine, p0, llanowar_cavalry()).expect("the Cavalry resolved");
    assert_eq!(pt(&engine, cavalry), (1, 4), "the body the card prints");
    assert!(
        !keywords(&engine, cavalry).contains(KeywordSet::VIGILANCE),
        "and no vigilance until something is spent on it"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the cast's three mana left nothing floating"
    );

    // An ability is offered or not by what the pool can pay, not by what is
    // untapped: an empty pool pays no {W}, so the line is not there yet.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(cavalry, 0)),
        "an unpayable {{W}} is how the ability is absent rather than refused: {:?}",
        legal.abilities
    );

    let land = on_battlefield(&engine, p0, plains()).expect("the Plains is still standing");
    engine
        .apply(p0, PlayerAction::ActivateManaAbility { source: land })
        .expect("an untapped Plains pays its own {{T}}");
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        1,
        "one white, off the one source that makes it"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(cavalry, 0)),
        "with the {{W}} floating the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, llanowar_cavalry(), 0);
    assert!(
        !stack_is_empty(&engine),
        "granting a keyword is no mana ability, so the ability is on the stack"
    );
    assert!(
        !keywords(&engine, cavalry).contains(KeywordSet::VIGILANCE),
        "and nothing has happened yet — the keyword waits for the resolution"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{W}} came out of the pool to pay for it"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        keywords(&engine, cavalry).contains(KeywordSet::VIGILANCE),
        "\"This creature gains vigilance until end of turn\""
    );
    assert_eq!(
        pt(&engine, cavalry),
        (1, 4),
        "and a keyword is all it bought: the body is untouched"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_cavalry()).is_some(),
        "the creature is still on the battlefield, untapped and now able to block"
    );
}

fn llanowar_vanguard() -> CardIndex {
    card_index("9123086e-ae67-46c5-aed5-6366e2fe5a8c")
}

/// Llanowar Vanguard is a `{2}{G}` 1/1 Dryad printing one line: "{T}: This
/// creature gets +0/+4 until end of turn." The word that needs a witness is
/// *This* — a second creature under the same seat is what tells a self-pump
/// from a board pump, and `(1, 5)` on the host with `(1, 1)` on the Elf beside
/// it is the only pair of numbers that applies the printed toughness half
/// without inventing the power half or reaching across the seat. The Elves are
/// left untapped on purpose, so the three Forests are exactly the mana the
/// `{2}{G}` was cast off and the offer below is read off a board rather than
/// off a source that might still be hiding green. The turn cycle at the end is
/// the "until end of turn" the card actually prints.
#[test]
fn llanowar_vanguard_taps_for_four_toughness_of_its_own_and_nothing_else() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), llanowar_elves()])
        .hand(0, &[llanowar_vanguard()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");

    // `{2}{G}` out of the three Forests, with the Elves named as the printing
    // kept back: they are the creature the pump must leave alone, and a mana
    // creature tapped for the cast would be a fourth green nothing here counts.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Forests, and the Elves contributed nothing"
    );
    cast_with_floating(&mut engine, p0, llanowar_vanguard());
    pass_until(&mut engine, stack_is_empty);
    let vanguard = on_battlefield(&engine, p0, llanowar_vanguard())
        .expect("the Vanguard resolved onto the table");
    assert_eq!(
        pt(&engine, vanguard),
        (1, 1),
        "a printed 1/1 before its own tap"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "and the Elf beside it is untouched"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the card arrived by being paid for, not by a source still floating"
    );

    // CR 302.6: a creature that arrived this turn cannot pay a `{{T}}`, so
    // the turn goes round once before the line is pressed. Both halves are
    // needed — `walk_to_own_main` on its own returns where it stands.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    // The whole price of the one line the card prints is its own {T}, so it is
    // offered with an empty pool and there is nothing to tap for it.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(vanguard, 0)),
        "{{T}}: This creature gets +0/+4 is offered on an empty pool: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, llanowar_vanguard(), 0);
    assert!(
        is_tapped(&engine, vanguard),
        "{{T}} is the whole cost and the Vanguard paid it itself"
    );
    assert!(
        !stack_is_empty(&engine),
        "a pump is no mana ability, so it is on the stack before it happens"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, vanguard),
        (1, 5),
        "+0/+4 on the creature that tapped — a (5, 5) would be a power the card never grants"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "\"This creature\" is not \"creatures you control\": the Elf is still the 1/1 it was printed as"
    );

    // "Until end of turn" is half the sentence, and the untap step read beside
    // it is what says the step ran rather than the game having stopped.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the Vanguard's controller takes another turn"
    );
    assert_eq!(
        pt(&engine, vanguard),
        (1, 1),
        "\"until end of turn\" — the toughness is gone once that turn has ended"
    );
    assert!(
        !is_tapped(&engine, vanguard),
        "and the untap step stood it back up, so the tap is not what was read"
    );
}

fn lumengrid_sentinel() -> CardIndex {
    card_index("ede92fb6-dfd6-40b4-b58f-af1f7a155efc")
}

/// Lumengrid Sentinel — {2}{U}, a 1/2 Human Wizard with flying and "Whenever
/// an artifact you control enters, you may tap target permanent."
///
/// Both ends of the trigger are played. The seat's own Sol Ring entering is
/// what fires it, and the two questions it asks are taken in the order the
/// rules put them: whether the tap happens at all, and what it aims at. The
/// offer is where "target permanent" is legible — a land, the artifact that
/// just triggered the ability and an Elf across the table are one menu — and
/// the tap lands on the Elf alone, so the permanents still standing afterwards
/// say which one was named. The quiet turn after it is the other half of "you
/// control": an artifact entering under the other seat asks nothing, and that
/// ring is checked onto the battlefield so the silence is the filter and not a
/// spell that never resolved.
#[test]
#[allow(clippy::too_many_lines)] // one trigger, both of its questions, and the turn that must not ask
fn lumengrid_sentinel_may_tap_any_permanent_when_your_artifact_enters() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[lumengrid_sentinel(), island(), island()])
        .hand(0, &[quiet_artifact()])
        // Across the table: a plain 1/1 whose whole text is one mana ability,
        // plus the mana the other seat needs to cast an artifact of its own
        // in the control turn below.
        .battlefield(1, &[llanowar_elves(), island(), island()])
        .hand(1, &[quiet_artifact()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let sentinel = on_battlefield(&engine, p0, lumengrid_sentinel()).expect("the Sentinel is out");
    let mine = on_battlefield(&engine, p0, island()).expect("an Island is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(pt(&engine, sentinel), (1, 2), "a printed 1/2");
    assert!(
        keywords(&engine, sentinel).contains(KeywordSet::FLYING),
        "and flying is a keyword the layers project onto it"
    );

    // {1} off the two Islands: what enters is an artifact under this seat.
    cast_from_hand(&mut engine, p0, quiet_artifact());

    let mut saw_may_do = false;
    let mut aimed = false;
    for _ in 0..30 {
        if is_tapped(&engine, theirs) {
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::YesNo {
                player,
                prompt: YesNoPrompt::MayDo,
                ..
            } => {
                saw_may_do = true;
                engine.apply(player, PlayerAction::YesNo(true)).unwrap();
            }
            Pending::ChooseTargets {
                player, options, ..
            } => {
                let ring = on_battlefield(&engine, p0, quiet_artifact())
                    .expect("the Sol Ring that triggered the ability is on the battlefield");
                assert!(
                    options.contains(&ring),
                    "\"target permanent\" includes the artifact that triggered it: {options:?}"
                );
                assert!(options.contains(&mine), "and a land beside it: {options:?}");
                assert!(
                    options.contains(&theirs),
                    "and a permanent across the table, which is what `any` means: {options:?}"
                );
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![theirs],
                        },
                    )
                    .expect("the Elf was one of the options it published");
                aimed = true;
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            other => panic!("unexpected between the Sol Ring entering and the tap: {other:?}"),
        }
    }
    assert!(
        saw_may_do,
        "\"you may tap target permanent\" is a question the trigger asks"
    );
    assert!(
        aimed,
        "and the permanent it taps is chosen out of the offer it published"
    );
    let ring = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring resolved");
    assert!(
        is_tapped(&engine, theirs),
        "the Elf across the table is the permanent that was named, and it is tapped"
    );
    assert!(
        !is_tapped(&engine, ring),
        "while the artifact that triggered the ability was never the one it spent"
    );

    // The control: the same artifact entering under the *other* seat.
    reach_their_main_phase(&mut engine, p1);
    cast_from_hand(&mut engine, p1, quiet_artifact());

    let mut asked = false;
    for _ in 0..20 {
        if on_battlefield(&engine, p1, quiet_artifact()).is_some()
            && stack_is_empty(&engine)
            && matches!(engine.pending(), Pending::Priority { player, .. } if *player == p1)
        {
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::YesNo {
                prompt: YesNoPrompt::MayDo,
                ..
            }
            | Pending::ChooseTargets { .. } => {
                asked = true;
                break;
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            other => panic!("unexpected while the other seat's artifact entered: {other:?}"),
        }
    }
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the Sol Ring really did enter under the other seat, so the silence \
         below is the filter `you control` and not a spell that never resolved"
    );
    assert!(
        !asked,
        "the Sentinel watches artifacts *you* control: the artifact entering \
         across the table asked nothing"
    );
}

fn man_o_war() -> CardIndex {
    card_index("67a3541c-8408-40c8-b44f-90035b860f57")
}

/// Man-o'-War — {2}{U} 2/2 Jellyfish: "When this creature enters, return
/// target creature to its owner's hand."
///
/// Two printed words are what the board has to separate, and neither is
/// visible in the card file. "Target creature" is not "creatures you
/// control", so an Elf under the same seat stands beside the one across the
/// table and only the second is named; and "its owner's hand" is not the
/// hand of the seat that aimed the bounce, so the Elf is read in the hand of
/// the seat that owns it. The Jellyfish itself stays on the battlefield
/// afterwards, which is what tells a bounce apart from a sweeper.
#[test]
fn man_o_war_bounces_the_creature_it_names_to_its_owners_hand() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, island())
        .battlefield(0, &[island(), island(), island(), llanowar_elves()])
        .hand(0, &[man_o_war()])
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");

    cast_from_hand(&mut engine, p0, man_o_war());
    // The spell resolves and its enters-trigger asks who is being returned.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until only stops on a target choice")
    };
    assert_eq!(
        player, p0,
        "the Jellyfish's controller aims its own trigger"
    );
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the Elf across the table was one of the options");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_none(),
        "the targeted creature left the battlefield"
    );
    assert!(
        in_hand(&engine, p1, llanowar_elves()).is_some(),
        "\"to its owner's hand\": the Elf goes back to the seat that owns it, \
         not to the seat that aimed the bounce"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_none(),
        "a bounce is not a kill: nothing was put into a graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the creature nobody named never moved"
    );
    let jelly =
        on_battlefield(&engine, p0, man_o_war()).expect("the Jellyfish resolved and stayed");
    assert_eq!(pt(&engine, jelly), (2, 2), "the body the card prints");
}

fn marker_beetles() -> CardIndex {
    card_index("4b1614fd-2810-4d4d-a0d6-934f27adbe65")
}

/// Marker Beetles prints two sentences and one play makes both happen at
/// once. `{2}, Sacrifice this creature: Draw a card` is the only way to kill
/// it on demand, and a creature sacrificed to a cost still *dies* (CR 700.4)
/// — so the sacrifice turns on the second line, "When this creature dies,
/// target creature gets +1/+1 until end of turn", which lands on the stack
/// above the draw. Answering its target question with the Elf under the same
/// seat and reading the Elf across the table back at (1, 1) is what tells
/// "target creature" from "creatures you control"; the library one shorter
/// and the hand one longer are the third clause, and the pool emptied to zero
/// says the `{2}` was a real price and not a label.
#[test]
fn marker_beetles_sacrifices_itself_to_draw_and_pumps_a_creature_when_it_dies() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[forest(), forest(), forest(), forest(), llanowar_elves()],
        )
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[marker_beetles()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Five sources pay {{1}}{{G}}{{G}} and leave exactly the {{2}} the second
    // line charges. The Elf is one of them, which changes nothing about the
    // body the dies trigger is aimed at.
    cast_from_hand(&mut engine, p0, marker_beetles());
    pass_until(&mut engine, stack_is_empty);
    let beetles = on_battlefield(&engine, p0, marker_beetles()).expect("the Beetles resolved");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(pt(&engine, mine), (1, 1), "a printed 1/1 before the pump");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the cast is paid and the {{2}} the ability charges is still floating"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(beetles, 0)),
        "with the {{2}} in the pool the sacrifice line is offered: {:?}",
        legal.abilities
    );

    let library_before = library_size(&engine, p0);
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    // Ability 0 is the activated line and ability 1 is the trigger behind it.
    activate(&mut engine, p0, marker_beetles(), 0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{2}} came out of the pool"
    );
    assert!(
        in_graveyard(&engine, p0, marker_beetles()).is_some(),
        "CR 601.2h: the sacrifice is a cost, so the Beetles are gone before \
         anything resolves"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until only stops on a target choice")
    };
    assert_eq!(
        player, p0,
        "the seat that sacrificed the Beetles answers its own trigger"
    );
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target creature\" is any creature, on either side of the table: {options:?}"
    );
    assert!(
        !options.contains(&beetles),
        "the Beetles are in a graveyard and no creature to target at all: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the creature the question offered was chosen");

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, mine),
        (2, 2),
        "\"target creature gets +1/+1 until end of turn\""
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "the pump reaches the creature that was named and never across the table"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before - 1,
        "\"Draw a card\": one card off the top of the library"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before + 1,
        "and it reached the hand, so a library that emptied would not satisfy \
         the count above"
    );
}

fn mercenary_knight() -> CardIndex {
    card_index("ed5429bb-233a-4528-bf7d-df5f6b192b1c")
}

/// Mercenary Knight prints one clause of its own — "When this creature enters,
/// sacrifice it unless you discard a creature card" — and it is a price with a
/// **filter** inside it, so a single board answers both halves of the card.
/// Two copies are cast off six Swamps in the same main phase: the first is
/// asked for the discard, and the menu it publishes has to be exactly the
/// creature cards in hand, with the Forest beside them as the control for
/// `Filter::CREATURE`; the second, with no creature card left to give up, is
/// sacrificed with no question asked at all, which is where a may-pay-cost-or
/// goes when its price cannot be paid. The Knight that paid is a 4/4 still on
/// the battlefield with the Elf it paid with in the graveyard, and the one
/// that could not pay is in the graveyard beside it.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn mercenary_knight_keeps_itself_for_a_creature_card_and_is_sacrificed_without_one() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp(), swamp(), swamp()])
        .hand(
            0,
            &[
                mercenary_knight(),
                mercenary_knight(),
                llanowar_elves(),
                forest(),
            ],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        6,
        "six Swamps, and each Knight costs {{2}}{{B}}"
    );
    cast_with_floating(&mut engine, p0, mercenary_knight());

    // The entry trigger, answered in the order it is asked and out of what it
    // published: the discard menu is the creature cards in hand, and the cost
    // is taken from that very menu rather than named from outside it.
    let mut paid = false;
    for _ in 0..20 {
        if paid && stack_is_empty(&engine) {
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::YesNo { player, .. } => {
                engine.apply(player, PlayerAction::YesNo(true)).unwrap();
            }
            Pending::ChooseCards {
                player,
                options,
                max,
                prompt,
                ..
            } => {
                assert_eq!(player, p0, "the seat that cast it pays its own price");
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostDiscard,
                    "a cost and not a search, which is all a client has to tell the two apart"
                );
                assert_eq!(max, 1, "one card is the whole price");
                let elf = in_hand(&engine, p0, llanowar_elves()).expect("the Elf is in hand");
                let land = in_hand(&engine, p0, forest()).expect("the Forest is in hand");
                assert!(
                    options.contains(&elf),
                    "a creature card in hand is the price: {options:?}"
                );
                assert!(
                    !options.contains(&land),
                    "`Filter::CREATURE` is read and not skipped: a Forest is a card \
                     and no creature card: {options:?}"
                );
                assert_eq!(
                    options.len(),
                    2,
                    "the Elf and the second Knight, which has not been cast yet: {options:?}"
                );
                for option in &options {
                    assert!(
                        engine.state().object(*option).is_some_and(|o| {
                            o.characteristics().types.contains(TypeSet::CREATURE)
                        }),
                        "every card on the menu is a creature card: {options:?}"
                    );
                }
                engine
                    .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
                    .expect("the Elf the question offered pays the price");
                paid = true;
            }
            other => panic!("unexpected while the entry trigger asks: {other:?}"),
        }
    }
    assert!(paid, "the discard was asked for and paid");

    let survivor =
        on_battlefield(&engine, p0, mercenary_knight()).expect("the first Knight is on the table");
    assert_eq!(pt(&engine, survivor), (4, 4), "the body the card prints");
    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "the discarded creature card is in the graveyard, which is where a discard puts it"
    );

    // The second Knight. No card in hand is a creature card any more — the Elf
    // is in a graveyard, and the Knight being cast is on the stack while its
    // own trigger asks — so the price cannot be paid and nothing is asked:
    // the print's "unless" is what happens, and the body is sacrificed.
    cast_with_floating(&mut engine, p0, mercenary_knight());
    let mut resolved = false;
    for _ in 0..8 {
        if stack_is_empty(&engine) && in_graveyard(&engine, p0, mercenary_knight()).is_some() {
            resolved = true;
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            other => panic!(
                "with no creature card to discard there is no price to offer, so \
                 nothing should be asked — got {other:?}"
            ),
        }
    }
    assert!(resolved, "the second Knight's trigger resolved");
    assert_eq!(
        all_on_battlefield(&engine, p0, mercenary_knight()).len(),
        1,
        "the second Knight sacrificed itself: only the copy that paid its price is left"
    );
    assert!(
        in_graveyard(&engine, p0, mercenary_knight()).is_some(),
        "and it is in its owner's graveyard, which is where a sacrificed permanent goes"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the two casts spent the six Swamps down to nothing"
    );
}

fn merchant_of_secrets() -> CardIndex {
    card_index("f6aebd42-0150-4741-84c2-4c85893640e9")
}

/// Merchant of Secrets — {2}{U} — Creature — Human Wizard (1/1): "When this
/// creature enters, draw a card."
///
/// The draw is read as a *move* and not as a count: the card that was on top
/// of the library before the cast is the one in hand afterwards, and the hand
/// is exactly the size it was — the Merchant leaving it and one card arriving
/// — so a trigger that drew nothing, or drew twice, cannot satisfy both
/// readings at once. Three Islands pay the {2}{U} down to an empty pool, and
/// the body that lands is the printed 1/1, so what is being looked at is a
/// cast creature and its own enters-trigger rather than a placement.
#[test]
fn merchant_of_secrets_draws_one_card_when_it_enters() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island()])
        .hand(0, &[merchant_of_secrets()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The top of the library is its last entry, named before anything is
    // cast, so the draw can be followed to a particular card.
    let library_before = engine.state().zones.list(ZoneLocation::Library(p0)).clone();
    let top = *library_before.last().expect("p0 has a library");
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    cast_from_hand(&mut engine, p0, merchant_of_secrets());
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Islands pay {{2}}{{U}} and nothing is left floating"
    );
    pass_until(&mut engine, stack_is_empty);

    let merchant = on_battlefield(&engine, p0, merchant_of_secrets()).expect("it resolved");
    assert_eq!(pt(&engine, merchant), (1, 1), "the body the card prints");
    assert_eq!(
        library_size(&engine, p0),
        library_before.len() - 1,
        "\"draw a card\" — one card off the top of the library"
    );
    assert!(
        engine
            .state()
            .zones
            .list(ZoneLocation::Hand(p0))
            .contains(&top),
        "and it is the very card that was on top, not merely some card"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before,
        "the Merchant left the hand and one card arrived, which is what \
         exactly one draw off one cast puts back"
    );
}

fn moaning_spirit() -> CardIndex {
    card_index("78962897-e2e3-4cb2-ae97-eca5dbe74e49")
}

/// Moaning Spirit is `{2}{B}` for a 2/1 Spirit whose entire printed text is
/// "Flying", so the test has to play both halves of it: the body arrives off
/// three Swamps, and the keyword is read where it does something — the block
/// declaration. The grounded Elf across the table is offered against a second,
/// grounded attacker and refused against the Spirit, which is what tells a
/// flier from a creature that merely carries the word in its card file.
#[test]
fn moaning_spirit_arrives_as_a_flying_two_one_a_ground_elf_cannot_block() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[moaning_spirit()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // `{2}{B}` off the three Swamps. The Elf is named as the printing kept
    // back: it is the grounded attacker the block offer below is measured
    // against, and a creature tapped for mana may not attack.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Swamps, and the Elf contributed nothing"
    );
    cast_with_floating(&mut engine, p0, moaning_spirit());
    pass_until(&mut engine, stack_is_empty);

    let spirit = on_battlefield(&engine, p0, moaning_spirit()).expect("the Spirit resolved");
    assert!(
        types(&engine, spirit).contains(TypeSet::CREATURE),
        "what arrived is a creature"
    );
    assert_eq!(pt(&engine, spirit), (2, 1), "the printed 2/1 body");
    assert!(
        keywords(&engine, spirit).contains(KeywordSet::FLYING),
        "and the keyword the card prints"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{2}}{{B}} came out of the pool"
    );

    // Both of p0's creatures attack — the Spirit through the air, the Elf on
    // the ground — so one defender has one legal block and one illegal one.
    // CR 302.6: a creature that arrived this turn cannot attack, so
    // the turn goes round once before the line is pressed. Both halves are
    // needed — `walk_to_own_main` on its own returns where it stands.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the turn came back round, and the summoning sickness with it"
    );
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player, attackers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until only stops on the attack declaration")
    };
    assert_eq!(player, p0, "the active player declares");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    assert!(
        attackers.contains(&spirit) && attackers.contains(&elves),
        "an untapped flier and an untapped 1/1 may both attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (spirit, Defender::Player(p1)),
                    (elves, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until only stops on the block declaration")
    };
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let can_block: Vec<ObjectId> = blockers
        .iter()
        .filter(|option| option.blocker == their_elf)
        .flat_map(|option| option.attackers.iter().copied())
        .collect();
    assert!(
        can_block.contains(&elves),
        "the grounded Elf is a legal block for the grounded attacker, so the \
         offer is not empty of this defender: {can_block:?}"
    );
    assert!(
        !can_block.contains(&spirit),
        "and the same Elf may not block the flier: {can_block:?}"
    );
}

fn moonwing_moth() -> CardIndex {
    card_index("6501b3c7-fd21-4668-b647-db12f0cc23f7")
}

/// Moonwing Moth — {1}{W}{W} — Creature — Insect 2/1 with flying and
/// "{W}: This creature gets +0/+1 until end of turn."
///
/// The pump is the whole card, and three things about it are the engine's
/// answer rather than the printing's. `legal.abilities` is filtered through
/// `can_afford`, which reads the *pool* and not the untapped lands, so the
/// line is absent on an empty pool and present the moment one white floats.
/// The activation leaves the Moth standing, because the price is the mana it
/// prints and not a tap symbol it does not. And `UntilEndOfTurn` is worth
/// exactly one turn: a 2/1 becomes a 2/2 now and is a printed 2/1 again on
/// the next one.
#[test]
fn moonwing_moth_turns_a_white_into_one_toughness_until_end_of_turn() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains()])
        .hand(0, &[moonwing_moth(), plains()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Three Plains pay {1}{W}{W} to the last drop, which is what the first
    // reading of the offer below rests on.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Plains, three white"
    );
    cast_with_floating(&mut engine, p0, moonwing_moth());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let moth = on_battlefield(&engine, p0, moonwing_moth()).expect("the Moth resolved");
    assert_eq!(pt(&engine, moth), (2, 1), "the body the card prints");
    assert!(
        keywords(&engine, moth).contains(KeywordSet::FLYING),
        "and the keyword it prints"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the cast took the whole pool, so nothing is floating for the pump"
    );

    // No white, no offer: `can_afford` reads the pool and not the untapped
    // lands, so the pump is not among the activations offered right now.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == moth),
        "{{W}} is not one white, so the pump is not offered: {:?}",
        legal.abilities
    );

    // The fourth Plains, played as this turn's land drop, is that white.
    play_land(&mut engine, p0, plains());
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the untapped Plains and nothing else: the Moth prints no mana ability"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(moth, 0)),
        "with the white floating, the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, moonwing_moth(), 0);
    assert!(
        !stack_is_empty(&engine),
        "a pump is no mana ability, so it uses the stack"
    );
    assert!(
        !is_tapped(&engine, moth),
        "the price is the {{W}} the card prints and not a tap symbol it does not"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, moth),
        (2, 2),
        "+0/+1 is one toughness: a 2/1 becomes a 2/2"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the white that paid for it is gone"
    );

    // Across the opponent's turn and back into the Moth's controller's next
    // one, where the duration has run out.
    pass_until(&mut engine, |e| {
        e.state().turn.number >= 3
            && e.state().turn.active == p0
            && matches!(e.pending(), Pending::Priority { player, .. } if *player == p0)
    });
    assert_eq!(
        pt(&engine, moth),
        (2, 1),
        "\"until end of turn\": the pump is gone once the turn that took it is over"
    );
}

fn morgue_thrull() -> CardIndex {
    card_index("fc759e09-34b2-4004-8474-a6500dd1280c")
}

/// Morgue Thrull is a {2}{B} 2/2 Thrull whose whole printed text is
/// "Sacrifice this creature: Mill three cards."
///
/// The sacrifice is the cost and the mill is the effect, so the two are read
/// off different places: the Thrull must already be in its owner's graveyard
/// when the ability goes on the stack (CR 601.2h), and the three cards can
/// only leave the library when it resolves. The board has a second Thrull
/// under the same seat so the graveyard entry is the one that was sacrificed
/// and not merely a printing that vanished, and the ability costs no mana —
/// so the offer is read off an empty pool rather than off tapped lands.
#[test]
fn morgue_thrull_sacrifices_itself_to_mill_three() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[morgue_thrull(), morgue_thrull()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let thrulls = all_on_battlefield(&engine, p0, morgue_thrull());
    assert_eq!(thrulls.len(), 2, "two copies, one of which stays out");
    let fodder = thrulls[0];

    let library_before = library_size(&engine, p0);
    let graveyard_before = engine.state().zones.list(ZoneLocation::Graveyard(p0)).len();
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the whole price is the creature, so no mana is involved"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        legal.abilities.contains(&(fodder, 0)),
        "an untapped Thrull with itself to give up is offered its one line: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, morgue_thrull(), 0);
    assert!(
        in_graveyard(&engine, p0, morgue_thrull()).is_some(),
        "`Sacrifice this creature` is paid on announcement (CR 601.2h)"
    );
    assert!(
        !stack_is_empty(&engine),
        "milling is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        library_size(&engine, p0),
        library_before - 3,
        "\"mill three cards\": exactly three off the top of the library"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        graveyard_before + 4,
        "the three milled cards, and the Thrull that ate itself to mill them \
         — the count was taken before the sacrifice paid the cost"
    );
    assert_eq!(
        all_on_battlefield(&engine, p0, morgue_thrull()).len(),
        1,
        "the printed card was the price: one Thrull ate itself and the other stands"
    );
}

fn morgue_toad() -> CardIndex {
    card_index("c615540b-bf85-4e16-8ac2-9d541cba732f")
}

/// Morgue Toad is a `{2}{B}` 2/2 whose only line is a *mana* ability paid
/// with the creature itself: "Sacrifice this creature: Add {U}{R}"
/// (CR 605.1a). The three Swamps are spent to the last drop by the cast, so
/// the blue and the red that appear afterwards have no other source on the
/// board — and the Llanowar Elves standing beside it are the control for
/// "this creature": the price names the source, so nothing is asked on the
/// way and the Elf is still untapped when the Toad is already in its owner's
/// graveyard. The empty stack is the third reading: a mana ability resolves
/// as it is activated (CR 605.3b), so the mana and the card's departure are
/// one step and not two.
#[test]
fn morgue_toad_sacrifices_itself_for_blue_and_red_and_asks_nothing_on_the_way() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), quiet_creature()])
        .hand(0, &[morgue_toad()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{B} out of the three Swamps, and the Elf named as the printing kept
    // back: `tap_all_mana` would have drunk its own `{T}: Add {G}` and made
    // every count below a claim about a fourth mana.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Swamps tapped, and the Elf contributed nothing"
    );
    cast_with_floating(&mut engine, p0, morgue_toad());
    pass_until(&mut engine, stack_is_empty);

    let toad = on_battlefield(&engine, p0, morgue_toad()).expect("the Toad resolved");
    let elf = on_battlefield(&engine, p0, quiet_creature()).expect("the Elf is out");
    assert_eq!(pt(&engine, toad), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the cast spent all three Swamps, so nothing this board can produce \
         stands behind the two mana read below"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(toad, 0)),
        "a mana ability the card prints is an ordinary indexed entry in \
         `abilities` (CR 605.1a), and its only price is the creature: {:?}",
        legal.abilities
    );

    // By hand and not through `tap_all_mana`, which presses only what costs
    // its own `{T}`: this ability costs the permanent outright.
    activate(&mut engine, p0, morgue_toad(), 0);

    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "and nothing was asked on the way — the price names the source itself, \
         so this is no `ChooseCards` question about which creature, got {:?}",
        engine.pending()
    );

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Blue), 1, "Add {{U}}");
    assert_eq!(pool.available(ManaColor::Red), 1, "and Add {{R}}");
    assert_eq!(
        pool.total(),
        2,
        "two mana out of one sacrifice, and the only source still standing on \
         this board made neither of them"
    );
    assert!(
        on_battlefield(&engine, p0, morgue_toad()).is_none(),
        "sacrificing itself is the whole price, so the Toad is gone"
    );
    assert!(
        in_graveyard(&engine, p0, morgue_toad()).is_some(),
        "and a sacrificed creature goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_creature()).is_some(),
        "the Elf was never on a menu: the price is *this* creature and not \
         \"a creature\""
    );
    assert!(
        !is_tapped(&engine, elf),
        "which is also why it is still standing untapped — the price was no tap"
    );
}

fn moriok_rigger() -> CardIndex {
    card_index("9364b5bc-3e78-4b9d-9993-0081bbe2eef6")
}

/// Moriok Rigger is a {2}{B} 2/2 whose whole text is one trigger: "Whenever an
/// artifact is put into a graveyard from the battlefield, you may put a +1/+1
/// counter on this creature." Nothing about that sentence is readable off the
/// card file — not that the question is optional, not that the counter is one,
/// and not that the trigger survives the artifact's own death — so the Rigger
/// is cast, a real artifact *creature* is destroyed by the opponent's
/// Vindicate, and the Rigger is read at 2/2 before the question and 3/3 after
/// it was answered.
#[test]
fn moriok_rigger_grows_when_an_artifact_is_put_into_a_graveyard() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        // {2}{B} off three Swamps, and the artifact the Rigger is watching for
        // is an artifact *creature*: whichever way the engine reads "dies", a
        // 1/1 artifact creature reaching a graveyard satisfies it.
        .battlefield(0, &[swamp(), swamp(), swamp(), baleful_strix()])
        .hand(0, &[moriok_rigger()])
        // Vindicate is {1}{W}{B}: two Plains and a Swamp pay for it.
        .battlefield(1, &[plains(), swamp(), plains()])
        .hand(1, &[vindicate()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, moriok_rigger());
    pass_until(&mut engine, stack_is_empty);
    let rigger = on_battlefield(&engine, p0, moriok_rigger()).expect("the Rigger resolved");
    let strix = on_battlefield(&engine, p0, baleful_strix()).expect("the Strix is on the table");
    assert_eq!(
        pt(&engine, rigger),
        (2, 2),
        "a printed 2/2 while no artifact has gone to a graveyard"
    );

    // The artifact dies to a spell from the other seat, so the trigger is
    // reading a real battlefield-to-graveyard move and not a harness shortcut.
    reach_their_main_phase(&mut engine, p1);
    cast_from_hand(&mut engine, p1, vindicate());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        unreachable!("pass_until stopped on Vindicate's target question")
    };
    assert!(
        options.contains(&strix),
        "\"target permanent\" reaches the artifact creature: {options:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::ChooseObjects {
                objects: vec![strix],
            },
        )
        .unwrap();

    // The Rigger's controller is the seat asked, and `MayDo` is the word that
    // says the counter is offered rather than imposed.
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::YesNo {
                prompt: YesNoPrompt::MayDo,
                ..
            }
        )
    });
    let Pending::YesNo { player, .. } = engine.pending().clone() else {
        unreachable!("pass_until stopped on the Rigger's question")
    };
    assert_eq!(player, p0, "the Rigger's controller answers for the Rigger");
    assert!(
        in_graveyard(&engine, p0, baleful_strix()).is_some(),
        "the artifact is already in a graveyard when the question is asked"
    );
    engine.apply(p0, PlayerAction::YesNo(true)).unwrap();
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, rigger),
        (3, 3),
        "exactly one +1/+1 counter for one artifact put into a graveyard \
         from the battlefield"
    );
}

fn mournful_zombie() -> CardIndex {
    card_index("f0ed2cf1-7bd4-4586-a682-fd588632cb3d")
}

/// Mournful Zombie prints one line — "{W}, {T}: Target player gains 1 life."
/// — and the word that carries it is *target*: the life goes to whoever was
/// named, which is the opposite of a Zombie helping the seat that paid for it.
/// So the ability is aimed at the opponent and both life totals are read
/// afterwards: p1 gains the one life, and p0 — a Plains and a tap poorer —
/// gains nothing. Both halves of the price leave a mark, so both are read: the
/// {W} is the white that leaves a pool three Swamps could never have put
/// there, and the tapped Zombie is the {T}.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn mournful_zombie_gives_the_life_to_the_player_it_names_and_not_to_its_controller() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), plains()])
        .hand(0, &[mournful_zombie()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{B} off the three Swamps alone: the Plains is the {W} the ability
    // charges, and it is kept back so the cast cannot spend it first.
    tap_all_mana_but(&mut engine, p0, Some(plains()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Swamps, and no white in the pool"
    );
    cast_with_floating(&mut engine, p0, mournful_zombie());
    pass_until(&mut engine, stack_is_empty);
    let zombie = on_battlefield(&engine, p0, mournful_zombie()).expect("the Zombie resolved");
    assert_eq!(pt(&engine, zombie), (2, 1), "the printed 2/1 body");

    // Its price is its own tap, and a creature cast this turn is summoning
    // sick (CR 302.6), so the activation belongs to the next turn.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(!is_tapped(&engine, zombie), "it untapped on the way round");

    tap_all_mana(&mut engine, p0);
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        (
            pool.available(ManaColor::Black),
            pool.available(ManaColor::White)
        ),
        (3, 1),
        "the three Swamps and the one Plains that can pay the {{W}}"
    );

    activate(&mut engine, p0, mournful_zombie(), 0);
    // "target player" is any player at the table, which is what makes the
    // answer below a choice rather than a rule — and it arrives as one of two
    // questions, so both are read rather than one assumed.
    let (chooser, answer) = match engine.pending().clone() {
        Pending::ChooseTargets {
            player,
            player_options,
            ..
        } => {
            assert!(
                player_options.contains(&p0) && player_options.contains(&p1),
                "either seat may be named: {player_options:?}"
            );
            (
                player,
                PlayerAction::ChooseTargets {
                    objects: vec![],
                    players: vec![p1],
                },
            )
        }
        Pending::ChoosePlayer { player, options } => {
            assert!(
                options.contains(&p0) && options.contains(&p1),
                "either seat may be named: {options:?}"
            );
            (player, PlayerAction::ChoosePlayer(p1))
        }
        other => panic!("`target player` is a choice of player, got {other:?}"),
    };
    assert_eq!(chooser, p0, "the activating seat is the one that names it");
    assert!(
        !is_tapped(&engine, zombie),
        "the target is answered before the price is paid (CR 601.2c, then CR 601.2h)"
    );
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::White),
        1,
        "and the {{W}} is still in the pool for the same reason"
    );
    engine
        .apply(chooser, answer)
        .expect("the seat the question offered is a legal answer");

    assert!(
        is_tapped(&engine, zombie),
        "{{T}} is the other half of the price"
    );
    assert!(
        !stack_is_empty(&engine),
        "gaining life is no mana ability, so the ability waits on the stack"
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::White), 0, "the {{W}} was paid");
    assert_eq!(
        pool.available(ManaColor::Black),
        3,
        "and it was the white that paid it: the Swamps' mana is untouched"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "nothing has been gained yet — the ability resolves off the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        engine.state().players[1].life,
        21,
        "\"target player gains 1 life\" — the seat that was named, and one life"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and the seat that paid the price and the tap gains nothing"
    );
}

fn nantuko_elder() -> CardIndex {
    card_index("001c233f-2959-479b-a82a-64a25ac60830")
}

/// Nantuko Elder is a {2}{G} 1/2 Insect Druid whose whole printed text is one
/// mana ability: "{T}: Add {C}{G}." Two mana of two *different* kinds out of
/// one activation is the claim, and the board is built so that neither half
/// can be borrowed: the pool is empty when the Elder taps, the only other
/// permanents are Forests that make {G} and can never make {C}, and every one
/// of them is still standing afterwards — the colorless is the half no Forest
/// on this table could have produced at all.
///
/// A turn is spent before the tap because of CR 302.6: a creature's {T}
/// ability cannot be activated the turn it arrives, so the Elder is cast,
/// walked around to its controller's next main phase, and tapped there with
/// the Forests untapped and the pool still empty.
#[test]
fn nantuko_elder_taps_for_one_colorless_and_one_green_the_turn_after_it_arrives() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[nantuko_elder()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{G} off the three Forests, every one of which is spent: a 1/2 body
    // that arrives with an empty pool is what makes the two mana below the
    // Elder's own rather than a land's.
    cast_from_hand(&mut engine, p0, nantuko_elder());
    pass_until(&mut engine, stack_is_empty);
    let elder = on_battlefield(&engine, p0, nantuko_elder()).expect("the Elder resolved");
    assert_eq!(pt(&engine, elder), (1, 2), "the printed 1/2 body");
    assert!(
        types(&engine, elder).contains(TypeSet::CREATURE),
        "an Insect Druid is a creature and nothing else: {:?}",
        types(&engine, elder)
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Forests paid the {{2}}{{G}} exactly, so nothing is floating"
    );
    assert!(!is_tapped(&engine, elder), "and the Elder is untapped");

    // Around to its controller's next turn: the untap step stands the Forests
    // back up, and CR 302.6 has stopped applying to the Elder.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    let forests = all_on_battlefield(&engine, p0, forest());
    assert_eq!(forests.len(), 3, "the same three Forests are still there");
    assert!(
        forests.iter().all(|id| !is_tapped(&engine, *id)),
        "the untap step ran, so a green source stands beside the Elder"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and nothing is floating"
    );

    // Ability 0 is the printed "{T}: Add {C}{G}", and it is an ordinary
    // `abilities` entry rather than the CR 305.6 shortcut: a card that prints
    // its own mana line has an index to name.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(elder, 0)),
        "the whole price is the tap symbol, so the line is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, nantuko_elder(), 0);

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Colorless),
        1,
        "{{C}} — which no Forest on this board could have made"
    );
    assert_eq!(
        pool.available(ManaColor::Green),
        1,
        "and {{G}} beside it, off the same activation"
    );
    assert_eq!(pool.total(), 2, "two mana, one tap, and nothing else");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(is_tapped(&engine, elder), "the Elder paid its own {{T}}");
    assert!(
        forests.iter().all(|id| !is_tapped(&engine, *id)),
        "and every Forest is still standing, so the colorless came from the \
         Elder and not from a land"
    );
}

fn nantuko_husk() -> CardIndex {
    card_index("0dcefc00-9425-43e3-bd47-1e34fff8b0e2")
}

/// Nantuko Husk is a {2}{B} 2/2 whose only printed line is "Sacrifice a
/// creature: This creature gets +2/+2 until end of turn." The price names no
/// creature in particular, so the engine has to ask which one — and that menu
/// is half the card: both creatures this seat controls are on it (the Husk is
/// one of them, CR 701.16a) while CR 701.21a keeps the opponent's Elf off it.
/// Sacrificing is the last step of the activation (CR 601.2h), so the fodder
/// is already buried while the +2/+2 is still on the stack, which is the only
/// way one board can tell the printed 2/2 from the pumped 4/4.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn nantuko_husk_eats_a_creature_you_control_to_grow_itself() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[nantuko_husk()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    cast_from_hand(&mut engine, p0, nantuko_husk());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let husk = on_battlefield(&engine, p0, nantuko_husk()).expect("the Husk resolved");
    let fodder = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    assert_eq!(pt(&engine, husk), (2, 2), "the body the card prints");

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(husk, 0)),
        "the one line the Husk prints costs a creature and no mana at all, so \
         it is offered without a single mana floating: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, nantuko_husk(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which creature, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat is the one asked");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one creature, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "the two creatures this seat controls and nothing else: {options:?}"
    );
    assert!(
        options.contains(&husk),
        "the Husk is itself a creature you control, so it is on its own menu: {options:?}"
    );
    assert!(
        options.contains(&fodder),
        "and the Elf beside it is as much a creature as the Husk: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: an opponent's creature is not yours to sacrifice: {options:?}"
    );

    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the creature the question offered pays the cost");

    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "CR 601.2h: the creature is sacrificed as the cost, before the ability \
         is on the stack"
    );
    assert!(
        !stack_is_empty(&engine),
        "and the ability is what is waiting: it is no mana ability"
    );
    assert_eq!(
        pt(&engine, husk),
        (2, 2),
        "nothing is pumped until the ability resolves"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, husk),
        (4, 4),
        "+2/+2 until end of turn, on the permanent that paid the price"
    );
    assert!(
        on_battlefield(&engine, p0, nantuko_husk()).is_some(),
        "the Husk ate the Elf and not itself, so it is still standing"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the opponent's board never moved"
    );
}

fn nightguard_patrol() -> CardIndex {
    card_index("bb482f90-5624-4e2c-9916-85fb09a3639a")
}

/// Nightguard Patrol is `{2}{W}` for a 2/1 Human Soldier whose whole printed
/// text is two words: first strike and vigilance. Both are read on a real board
/// rather than out of the card file — the cast, the 2/1 body through the layer
/// system, and then a combat step. Vigilance (CR 702.20) is the half a board can
/// *contrast*, so an untapped Llanowar Elves attacks beside the Patrol and the
/// declaration that taps the Elves is the same one that leaves the Patrol
/// standing; the Elves are named as the printing `tap_all_mana_but` keeps back,
/// because a control creature tapped for the cast's mana would have had a reason
/// of its own to be down. Both attackers are unblocked, so the three damage the
/// defending player takes is the 2/1 and the 1/1 and nothing else — and the
/// combat has to be the *next* turn's, since a creature that entered this turn
/// may not attack at all (CR 302.6).
#[test]
fn nightguard_patrol_attacks_without_tapping_and_the_creature_beside_it_taps() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains(), llanowar_elves()])
        .hand(0, &[nightguard_patrol()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Three Plains pay {2}{W}; the Elves are kept back because they are the
    // control the combat below is measured against, and a source tapped for
    // mana has already changed status for a reason of its own.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Plains tapped and no creature"
    );
    cast_with_floating(&mut engine, p0, nightguard_patrol());
    pass_until(&mut engine, stack_is_empty);

    let patrol = on_battlefield(&engine, p0, nightguard_patrol()).expect("the Patrol resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves stand");
    assert_eq!(pt(&engine, patrol), (2, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{2}}{{W}} came out of the pool"
    );
    let granted = keywords(&engine, patrol);
    assert!(
        granted.contains(KeywordSet::FIRST_STRIKE),
        "printed first strike reaches the permanent: {granted:?}"
    );
    assert!(
        granted.contains(KeywordSet::VIGILANCE),
        "and printed vigilance beside it: {granted:?}"
    );
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::VIGILANCE),
        "the control creature prints no such word"
    );

    // A creature cast this turn may not attack (CR 302.6), so the combat the
    // two keywords are read off is p0's next one.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, patrol),
        "untapped, and no longer summoning sick"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&patrol),
        "the 2/1 may attack: {attackers:?}"
    );
    assert!(
        attackers.contains(&elves),
        "and so may the untapped Elf beside it: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (patrol, Defender::Player(p1)),
                    (elves, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    // Not `stack_is_empty`: the stack is already empty the moment attackers are
    // declared, so that predicate stops the walk *before* the combat damage step
    // and every life total still reads 20. The end step is past damage
    // (CR 510.2).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert_eq!(
        engine.state().players[1].life,
        17,
        "two damage from the Patrol and one from the Elves, and nothing else"
    );
    assert!(
        !is_tapped(&engine, patrol),
        "\"vigilance\" (CR 702.20): attacking does not tap it"
    );
    assert!(
        is_tapped(&engine, elves),
        "while the very same declaration taps the creature without the word — \
         which is what tells the keyword from an attack that never happened"
    );
}

fn nim_abomination() -> CardIndex {
    card_index("b0713b1e-544d-4549-9371-61ac7f6c2a6a")
}

/// Nim Abomination — {2}{B} Zombie, 3/4: "At the beginning of your end step,
/// if this creature is untapped, you lose 3 life."
///
/// That "if" is the whole card, so one permanent is read twice and the only
/// thing that differs between the two readings is its status. The turn it is
/// cast it stands untapped through its controller's end step and three life go
/// missing; the turn after, it attacks — a creature that attacked is a tapped
/// creature — and the same step costs nothing, which a card that simply drained
/// its controller every end step could not do.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn nim_abomination_drains_only_while_it_stands_untapped_at_your_end_step() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[nim_abomination()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, nim_abomination());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, nim_abomination()).is_some()
    });
    let zombie = on_battlefield(&engine, p0, nim_abomination()).expect("the Zombie resolved");
    assert_eq!(pt(&engine, zombie), (3, 4), "the body the card prints");
    assert!(!is_tapped(&engine, zombie), "and it arrives untapped");

    // The end step of the turn it was cast. Nothing on this board aims at
    // anything, so the one question the walk can meet is the one the trigger
    // asks — and every answer it takes is p0, which is what "you" means on
    // the card.
    let full = engine.state().players[0].life;
    for _ in 0..200 {
        if engine.state().players[0].life != full {
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::ChooseTargets {
                player,
                options,
                player_options,
                ..
            } => {
                let players: Vec<PlayerId> = player_options
                    .iter()
                    .copied()
                    .filter(|seat| *seat == p0)
                    .take(1)
                    .collect();
                let objects = if players.is_empty() {
                    options.into_iter().take(1).collect()
                } else {
                    Vec::new()
                };
                engine
                    .apply(player, PlayerAction::ChooseTargets { objects, players })
                    .unwrap();
            }
            Pending::ChoosePlayer { player, .. } => {
                engine
                    .apply(player, PlayerAction::ChoosePlayer(p0))
                    .unwrap();
            }
            other => panic!("unexpected on the way to the end step: {other:?}"),
        }
    }
    assert_eq!(
        engine.state().players[0].life,
        full - 3,
        "\"at the beginning of your end step, if this creature is untapped, \
         you lose 3 life\" — the Zombie is untapped and standing"
    );

    // The following turn: the Zombie turns sideways, which is the one thing on
    // this board that can leave it tapped when an end step begins.
    let first_turn = engine.state().turn.number;
    let their_life = engine.state().players[1].life;
    let mut attacked = false;
    let mut at_end_step = false;
    for _ in 0..600 {
        if engine.state().turn.number > first_turn
            && matches!(engine.state().turn.phase, Phase::Ending)
            && engine.state().turn.active == p0
            && stack_is_empty(&engine)
            && matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0)
        {
            at_end_step = true;
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers {
                player, attackers, ..
            } => {
                if player == p0 && !attacked {
                    assert!(
                        attackers.contains(&zombie),
                        "an untapped 3/4 deployed last turn may attack: {attackers:?}"
                    );
                    engine
                        .apply(
                            p0,
                            PlayerAction::DeclareAttackers {
                                attackers: vec![(zombie, Defender::Player(p1))],
                            },
                        )
                        .unwrap();
                    attacked = true;
                } else {
                    engine
                        .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                        .unwrap();
                }
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            other => panic!("unexpected on the way to the next end step: {other:?}"),
        }
    }
    assert!(
        at_end_step,
        "the walk reaches the Zombie's controller's next end step"
    );
    assert!(
        attacked,
        "the Zombie attacked on its controller's next turn"
    );
    assert!(
        is_tapped(&engine, zombie),
        "and it is still tapped when the end step begins"
    );
    assert_eq!(
        engine.state().players[1].life,
        their_life - 3,
        "the 3/4 connected, which is what made it a tapped attacker"
    );
    assert_eq!(
        engine.state().players[0].life,
        full - 3,
        "the same trigger that drained three life while the Zombie stood \
         untapped costs nothing while it is tapped, so the printed \"if\" is a \
         condition and not decoration"
    );
}

fn noble_panther() -> CardIndex {
    card_index("bfb799d2-b2fa-4efb-91d7-a457230b370f")
}

/// Noble Panther — {1}{G}{W}, a 3/3 Cat — "{1}: This creature gains first
/// strike until end of turn."
///
/// The price is the mana and *not* the creature's own tap, so the board carries
/// four sources: they pay the {1}{G}{W} and leave exactly the {1} the ability
/// charges floating in the same main phase (CR 500.5). The offer is read after
/// that, because `legal.abilities` is filtered by `can_afford`, which reads the
/// pool and not the untapped lands — and read again once the pool is empty,
/// where the same untapped Panther is offered nothing, which is what tells a
/// mana price from a tap. The body staying a printed 3/3 through the activation
/// separates a keyword grant from a pump, and the second walk is the "until end
/// of turn" half.
#[test]
fn noble_panther_buys_first_strike_for_one_mana_until_end_of_turn() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), plains(), plains(), plains()])
        .hand(0, &[noble_panther()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, noble_panther());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let cat = on_battlefield(&engine, p0, noble_panther()).expect("the Panther resolved");
    assert_eq!(pt(&engine, cat), (3, 3), "the body the card prints");
    assert!(
        !keywords(&engine, cat).contains(KeywordSet::FIRST_STRIKE),
        "nothing has been bought yet"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{1}}{{G}}{{W}} is spent and exactly the {{1}} the ability charges is left"
    );
    assert!(
        !is_tapped(&engine, cat),
        "the price is mana, not the creature's own {{T}}"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(cat, 0)),
        "with the {{1}} floating the Panther's only line is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, noble_panther(), 0);
    pass_until(&mut engine, stack_is_empty);

    assert!(
        keywords(&engine, cat).contains(KeywordSet::FIRST_STRIKE),
        "{{1}}: this creature gains first strike"
    );
    assert_eq!(
        pt(&engine, cat),
        (3, 3),
        "the ability grants a keyword and no body"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{1}} came out of the pool"
    );

    // The other half of the price, read with the Panther still untapped: an
    // empty pool pays no {1}, so the line is not offered — a cost that were
    // the tap would still be payable here.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(cat, 0)),
        "nothing floating means no {{1}}, so there is nothing to activate: {:?}",
        legal.abilities
    );

    // "until end of turn": the grant is read once more with the turn behind
    // it. Nothing attacks, so the Panther is the only thing that can have
    // moved a keyword.
    pass_until(&mut engine, |e| {
        !keywords(e, cat).contains(KeywordSet::FIRST_STRIKE)
    });
    assert!(
        on_battlefield(&engine, p0, noble_panther()).is_some(),
        "the grant expired and the creature did not"
    );
}

fn orcish_mechanics() -> CardIndex {
    card_index("0ec58835-de2d-4064-89a9-f92db80bc276")
}

/// Orcish Mechanics — {2}{R}, a 1/1 Orc printing one line: "{T}, Sacrifice an
/// artifact: This creature deals 2 damage to any target."
///
/// The cost names no artifact in particular, so the engine has to ask which
/// one, and that question is half the card: the Sol Ring under the same seat is
/// the whole of its menu — the Mechanics is a creature and no artifact, the Elf
/// beside it is a creature too, and the Sol Ring across the table is not this
/// seat's to give up (CR 701.21a). The other half is that "any target"
/// (CR 115.4) is one choice carrying both the object and the player lists, so an
/// activation aimed at the Elf has to leave the opponent at twenty: the two
/// damage went where the answer pointed and nowhere else. The whole price is a
/// tap and an artifact and no mana at all, so the board holds an empty pool and
/// nothing on it is tapped by hand.
#[allow(clippy::too_many_lines)] // one activation, and every gate it passes asserted
#[test]
fn orcish_mechanics_eats_an_artifact_of_yours_for_two_damage_to_any_target() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[orcish_mechanics(), quiet_artifact(), llanowar_elves()])
        // An Elf to aim at, and an artifact across the table that "sacrifice
        // an artifact" is not an invitation to eat.
        .battlefield(1, &[llanowar_elves(), quiet_artifact()])
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let mechanics = on_battlefield(&engine, p0, orcish_mechanics()).expect("the Mechanics is out");
    let fodder = on_battlefield(&engine, p0, quiet_artifact()).expect("the Sol Ring is out");
    let ours = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let prey = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    let theirs = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");

    assert_eq!(pt(&engine, mechanics), (1, 1), "the body the card prints");
    let kinds = types(&engine, mechanics);
    assert!(
        kinds.contains(TypeSet::CREATURE) && !kinds.contains(TypeSet::ARTIFACT),
        "and it is a creature and no artifact, which is why its own cost can \
         never eat it: {kinds:?}"
    );
    assert_eq!(
        pt(&engine, prey),
        (1, 1),
        "a printed 1/1 for two damage to kill"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the price is a tap and an artifact: there is no mana anywhere on this board"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(mechanics, 0)),
        "an untapped Orc with an artifact to give up is offered its one line \
         with nothing floating: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, orcish_mechanics(), 0);

    // Two questions, and the order they arrive in is threaded rather than
    // assumed: the target is chosen at CR 601.2c and the sacrifice is paid at
    // CR 601.2h, and both answers are taken out of what the question itself
    // enumerated.
    let mut menu: Vec<ObjectId> = Vec::new();
    let mut aimed = false;
    for _ in 0..12 {
        if aimed && !menu.is_empty() {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseTargets {
                player,
                options,
                player_options,
                min,
                max,
                ..
            } => {
                assert_eq!(player, p0, "the activating seat aims it");
                assert_eq!((min, max), (1, 1), "one target, no more and no fewer");
                assert!(
                    options.contains(&prey),
                    "the creature across the table is one of the object options: {options:?}"
                );
                assert!(
                    player_options.contains(&p0) && player_options.contains(&p1),
                    "CR 115.4: \"any target\" counts players in the same choice: {player_options:?}"
                );
                if menu.is_empty() {
                    // Nothing has been given up yet: the target is named first
                    // and the costs are the last step of the activation
                    // (CR 601.2c, then CR 601.2h).
                    assert!(
                        on_battlefield(&engine, p0, quiet_artifact()).is_some(),
                        "the sacrifice is a cost and is paid after the target"
                    );
                    assert!(!is_tapped(&engine, mechanics), "and so is the tap symbol");
                }
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![prey],
                        },
                    )
                    .expect("the creature was one of the options it enumerated");
                aimed = true;
            }
            Pending::ChooseCards {
                player,
                options,
                min,
                max,
                prompt,
            } => {
                assert_eq!(player, p0, "the activating seat answers its own cost");
                assert_eq!(
                    prompt,
                    crate::choice::ChoicePrompt::CostSacrifice,
                    "a cost and not a search, which is all a client has to tell the two apart"
                );
                assert_eq!((min, max), (1, 1), "one artifact, no more and no fewer");
                menu = options;
                engine
                    .apply(
                        player,
                        PlayerAction::ChooseObjects {
                            objects: vec![fodder],
                        },
                    )
                    .expect("the artifact the question offered pays the cost");
            }
            Pending::Priority { .. } => break,
            other => panic!("unexpected while the Mechanics' activation resolves: {other:?}"),
        }
    }
    assert!(aimed, "\"any target\" asks where the damage goes");
    assert!(
        !menu.contains(&theirs),
        "`CR 701.21a`: an opponent's artifact is not yours to sacrifice: {menu:?}"
    );
    assert!(
        !menu.contains(&ours) && !menu.contains(&mechanics),
        "and neither creature is an artifact: {menu:?}"
    );
    assert_eq!(
        menu,
        vec![fodder],
        "so the one artifact this seat controls is the whole menu"
    );

    assert!(
        is_tapped(&engine, mechanics),
        "{{T}} paid the other half of the cost"
    );
    assert!(
        !stack_is_empty(&engine),
        "dealing damage is no mana ability, so the ability is waiting on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[1].life,
        20,
        "the damage went to the creature the answer pointed at and not to the \
         player whose board it stood on"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "two damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        in_graveyard(&engine, p0, quiet_artifact()).is_some(),
        "the sacrificed artifact is in its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, orcish_mechanics()).is_some(),
        "the Mechanics ate the Sol Ring and not itself: its own source is no artifact"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the creature nobody named never moved"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "and the permanent across the table was never on the menu"
    );
}

fn overeager_apprentice() -> CardIndex {
    card_index("3ea71eed-e1ae-4e28-a4f5-44ff115949f4")
}

/// Overeager Apprentice is a `{2}{B}` 1/2 whose whole printed text is one
/// mana ability: "Discard a card, Sacrifice this creature: Add {B}{B}{B}."
/// Both halves of that price have to actually happen and neither is readable
/// off the card file, so the board is three Swamps and an opening hand of
/// filler: the Swamps pay the cast and leave an empty pool, which makes the
/// three black that appear afterwards something only the Apprentice's own
/// line can have produced. The discard arrives as `ChoicePrompt::CostDiscard`
/// with the cards in hand as its menu — a cost and not a search — and while
/// that question still stands the creature is on the battlefield and the mana
/// is unspent (CR 601.2c before CR 601.2h). Nothing touches the stack
/// (CR 605.3b), and the creature ends up in its owner's graveyard beside the
/// card it discarded.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn overeager_apprentice_discards_a_card_and_eats_itself_for_three_black() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[overeager_apprentice(), swamp()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{B} off the three Swamps, which spends them down to nothing: every
    // claim about the pool below is read against an empty one.
    cast_from_hand(&mut engine, p0, overeager_apprentice());
    pass_until(&mut engine, stack_is_empty);
    let apprentice = on_battlefield(&engine, p0, overeager_apprentice())
        .expect("the Apprentice resolved onto the table");
    assert_eq!(pt(&engine, apprentice), (1, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the three Swamps paid the cast and are spent"
    );

    let hand = engine.state().zones.list(ZoneLocation::Hand(p0)).clone();
    assert!(
        !hand.is_empty(),
        "the opening hand's filler cards are what the discard costs"
    );

    // A printed mana ability is an ordinary `(source, index)` entry in the
    // offer, and this one's price is a discard and the source itself — no
    // mana and no tap, so the offer does not turn on the pool.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(apprentice, 0)),
        "the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, overeager_apprentice(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the discard is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostDiscard,
        "a cost and not a search, which is all a client has to tell them apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    assert!(!options.is_empty(), "there is a card in hand to give up");
    for id in &options {
        assert!(
            hand.contains(id),
            "the menu is the cards in hand: {id:?} is not one of them"
        );
    }
    assert!(
        on_battlefield(&engine, p0, overeager_apprentice()).is_some(),
        "CR 601.2h: the costs are paid after the question, so nothing has moved yet"
    );

    let discarded = options[0];
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![discarded],
            },
        )
        .expect("a card the question offered pays the discard");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Black), 3, "Add {{B}}{{B}}{{B}}");
    assert_eq!(
        pool.total(),
        3,
        "three black and nothing else, off a pool that was empty a moment ago"
    );
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so the mana and the \
         sacrifice are already here"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "and the seat holds priority again, got {:?}",
        engine.pending()
    );

    assert!(
        on_battlefield(&engine, p0, overeager_apprentice()).is_none(),
        "sacrificing the creature is the other half of the price"
    );
    assert!(
        in_graveyard(&engine, p0, overeager_apprentice()).is_some(),
        "a sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        in_graveyard(&engine, p0, swamp()).is_some(),
        "and the discarded card is in the same graveyard"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand.len() - 1,
        "the hand is one card smaller: the Apprentice left it for the stack \
         and the discard cost one more"
    );
}

fn pegasus_charger() -> CardIndex {
    card_index("81a5ac8d-b904-4755-a5bc-650e95f4138f")
}

/// Pegasus Charger is `{2}{W}` for a 2/1 Pegasus whose whole text is flying
/// and first strike, and both words only ever matter in combat, so the card
/// is cast and then attacks. Flying is read off the block question rather
/// than off the card file: the Elf across the table may block the ground
/// attacker beside the Charger and may not be assigned the Charger, while a
/// Baleful Strix — the pool's flier — may block either. First strike is then
/// read off the aftermath: a 2/1 that blocks-and-dies to a 1/1 in the
/// ordinary damage step instead kills it in the first one and never takes the
/// counter-blow, so the Strix is in its owner's graveyard and the Charger is
/// still standing.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn pegasus_charger_flies_over_the_ground_and_strikes_first() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains(), llanowar_elves()])
        .hand(0, &[pegasus_charger()])
        // A flier and a ground creature across the table: the two halves of
        // the block question the flying line is read from.
        .battlefield(1, &[baleful_strix(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The card arrives the way the card arrives: {2}{W} out of three Plains,
    // with the Elf named as the source kept back — it is the ground attacker
    // the block question below needs, and `tap_all_mana` would have spent its
    // own printed `{T}: Add {G}`.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Plains, and the Elf is still standing to attack with"
    );
    cast_with_floating(&mut engine, p0, pegasus_charger());
    pass_until(&mut engine, stack_is_empty);

    let charger = on_battlefield(&engine, p0, pegasus_charger()).expect("the Charger resolved");
    let my_elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    assert_eq!(pt(&engine, charger), (2, 1), "the body the card prints");
    let granted = keywords(&engine, charger);
    assert!(granted.contains(KeywordSet::FLYING), "printed flying");
    assert!(
        granted.contains(KeywordSet::FIRST_STRIKE),
        "printed first strike"
    );
    assert!(
        !keywords(&engine, my_elf).contains(KeywordSet::FLYING),
        "the projection reaches the Charger and no other creature on the board"
    );

    // One full turn cycle: a creature that has not been under its controller's
    // control since their last untap step may not attack (CR 302.6).
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&charger) && attackers.contains(&my_elf),
        "both untapped creatures may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (charger, Defender::Player(p1)),
                    (my_elf, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    // CR 508.2: priority goes round once the attack is declared, so the
    // block question is not the next pending.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player,
        attacker,
        blockers,
    } = engine.pending().clone()
    else {
        panic!(
            "two attackers declare a block step, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p1, "the defending seat declares");
    assert_eq!(attacker, p0, "against the attacking seat");

    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("the Strix is out");
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let may_block = |blocker: ObjectId| -> Vec<ObjectId> {
        blockers
            .iter()
            .find(|option| option.blocker == blocker)
            .unwrap_or_else(|| panic!("{blocker:?} is on the block menu"))
            .attackers
            .clone()
    };

    let strix_may_block = may_block(strix);
    assert!(
        strix_may_block.contains(&charger),
        "flying blocks flying: {strix_may_block:?}"
    );
    let elf_may_block = may_block(their_elf);
    assert!(
        elf_may_block.contains(&my_elf),
        "an untapped ground creature may still block the ground attacker: {elf_may_block:?}"
    );
    assert!(
        !elf_may_block.contains(&charger),
        "\"can't be blocked except by creatures with flying or reach\": the Elf \
         has neither, so the flier is not one of the attackers it may be \
         assigned to: {elf_may_block:?}"
    );

    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(strix, charger)],
            },
        )
        .expect("the question offered exactly this pairing");
    // Not `stack_is_empty`: the stack is already empty the moment blockers are
    // declared, so that would stop the walk before the first-strike damage
    // step. The end step is past both damage steps (CR 510.2).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert!(
        in_graveyard(&engine, p1, baleful_strix()).is_some(),
        "first strike deals its damage first, so two damage to a printed 1/1 \
         is lethal before the ordinary damage step ever begins"
    );
    assert!(
        on_battlefield(&engine, p0, pegasus_charger()).is_some(),
        "and the Strix was gone by then, so it never dealt its one damage — \
         which is lethal to a 2/1 and would have taken the Charger with it"
    );
    assert_eq!(
        engine.state().players[1].life,
        19,
        "the unblocked Elf got through for one, and the Charger's damage went \
         to the blocker that was assigned to it and never to the player"
    );
}

fn phyrexian_broodlings() -> CardIndex {
    card_index("7d5e4033-bd58-4854-b9d3-a440240995ee")
}

/// Phyrexian Broodlings prints exactly one line — "{1}, Sacrifice a creature:
/// Put a +1/+1 counter on this creature." — and its two halves land in
/// different places, so one activation has to be read in three: the {1} leaves
/// the pool, the creature named at the cost menu leaves the battlefield for
/// its owner's graveyard, and the counter lands on the *source* rather than on
/// whatever was given up. The menu is half the card, and both of its edges are
/// struck here: `Filter::YOUR_CREATURE` offers both creatures this seat
/// controls — the Broodlings among them, because the source is still on the
/// battlefield when CR 601.2h asks — and declines the Elf across the table,
/// which CR 701.21a keeps off it whatever the filter says. The surviving
/// bystander is the third reading: a `+1/+1` on a printed 2/2 is a 3/3, so a
/// counter that never arrived would leave the pair at 2/2 and 1/1 with one
/// creature missing from the board.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn phyrexian_broodlings_eats_a_creature_of_yours_for_a_counter_on_itself() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[phyrexian_broodlings(), quiet_creature(), swamp()])
        .battlefield(1, &[quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let broodlings =
        on_battlefield(&engine, p0, phyrexian_broodlings()).expect("the Broodlings is seated");
    let fodder = on_battlefield(&engine, p0, quiet_creature()).expect("a creature to give up");
    let theirs = on_battlefield(&engine, p1, quiet_creature()).expect("their creature is out");
    assert_eq!(
        pt(&engine, broodlings),
        (2, 2),
        "the printed 2/2 body, before anything is paid"
    );
    assert_eq!(
        counters_on(&engine, broodlings, CounterKind::P1P1),
        0,
        "and nothing has been put on it yet"
    );

    // `legal.abilities` is filtered through `can_afford`, which reads the
    // *pool* and not the untapped lands, so the {1} has to be floating before
    // anything is claimed about the offer. The Elf is named as the printing
    // kept back: it is the creature this test sacrifices, and a source tapped
    // for mana is a source whose status has already changed for a reason of
    // its own.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one Swamp tapped, and no creature paid in"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        legal.abilities.contains(&(broodlings, 0)),
        "the one line the card prints is offered with {{1}} floating: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, phyrexian_broodlings(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the sacrifice is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one creature, no more and no fewer");
    assert!(
        options.contains(&fodder),
        "the creature beside it is on the menu: {options:?}"
    );
    assert!(
        options.contains(&broodlings),
        "and so is the Broodlings itself: \"a creature\" is every creature \
         this seat controls, and the source is still on the battlefield while \
         the cost is being chosen (CR 601.2h): {options:?}"
    );
    assert_eq!(
        options.len(),
        2,
        "those two are the whole menu: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "`CR 701.21a`: an opponent's creature is not yours to sacrifice: {options:?}"
    );

    assert!(
        engine
            .apply(
                p0,
                PlayerAction::ChooseObjects {
                    objects: vec![theirs],
                },
            )
            .is_err(),
        "an answer the question did not enumerate is refused"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_creature()).is_some(),
        "and the refusal costs the other seat nothing"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the creature the question offered pays the cost");

    // CR 601.2h: the {1} goes out of the pool as the last step of the
    // activation, and putting a counter on a creature is no mana ability.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "the ability is on the stack, waiting to resolve"
    );
    assert_eq!(
        counters_on(&engine, broodlings, CounterKind::P1P1),
        0,
        "and the counter has not landed yet"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        counters_on(&engine, broodlings, CounterKind::P1P1),
        1,
        "\"Put a +1/+1 counter on this creature\" — one counter, on the source"
    );
    assert_eq!(
        pt(&engine, broodlings),
        (3, 3),
        "a printed 2/2 with one +1/+1 counter on it"
    );
    assert!(
        on_battlefield(&engine, p0, phyrexian_broodlings()).is_some(),
        "the creature that took the counter is still on the battlefield, which \
         is what says it was not the one sacrificed"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_creature()).is_none(),
        "the sacrificed creature left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p0, quiet_creature()).is_some(),
        "and a sacrificed permanent goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_creature()).is_some(),
        "the creature the ability did not name never moved"
    );
}

fn phyrexian_rager() -> CardIndex {
    card_index("e409c9be-0c9a-43c3-adb4-8c47afc1d551")
}

/// Phyrexian Rager prints one line — "When this creature enters, you draw a
/// card and you lose 1 life" — and both halves have to be read off the board
/// rather than off the card file. The draw is asserted as the *named* top card
/// of the library arriving in hand, so an effect that merely emptied the
/// library would not pass; the loss is read against both seats, so "you" is
/// checked and not assumed. Three Swamps pay {2}{B} and are named nowhere else,
/// which leaves the life total the only thing on this board that can move.
#[test]
fn phyrexian_rager_draws_a_card_and_costs_its_controller_one_life() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(211, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[phyrexian_rager()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Named before the cast: the card the enters-trigger is about to draw is
    // the one on top now, and nothing between here and the assertion touches
    // the library. `list` runs bottom-first, so the top is the last entry.
    let library_before = engine.state().zones.list(ZoneLocation::Library(p0)).clone();
    let top = *library_before.last().expect("p0 has a library");
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();

    cast_from_hand(&mut engine, p0, phyrexian_rager());
    pass_until(&mut engine, stack_is_empty);

    let rager = on_battlefield(&engine, p0, phyrexian_rager()).expect("the Rager resolved");
    assert_eq!(pt(&engine, rager), (2, 2), "the printed 2/2 body");

    assert_eq!(
        engine.state().players[0].life,
        19,
        "\"you lose 1 life\" — the controller pays for the card"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the loss is not the opponent's, which is the other reading of `you`"
    );

    assert!(
        engine
            .state()
            .zones
            .list(ZoneLocation::Hand(p0))
            .contains(&top),
        "\"you draw a card\": the very card that was on top of the library is \
         in hand, and not some other card that happened to move"
    );
    assert_eq!(
        library_size(&engine, p0),
        library_before.len() - 1,
        "one card left the top of the library and nothing put one back"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before,
        "the Rager left the hand when it was cast and one card came back for \
         it — a count that never moved would be satisfied by a trigger that \
         drew nothing and a cast that never happened"
    );
    assert_eq!(
        engine.state().players[p1.get() as usize].life,
        20,
        "\"its controller\": the seat across the table paid nothing for a \
         card it never drew"
    );
}

fn pincher_beetles() -> CardIndex {
    card_index("0fae1c73-fd34-433e-8989-fbd80e3b1c70")
}

/// Pincher Beetles prints Shroud and nothing else (CR 702.18: "This creature
/// can't be the target of spells or abilities"), so the whole card is a
/// targeting restriction and it cuts both ways. One board is asked both
/// halves: the Beetles' own controller cannot point Giant Growth at it, and
/// the opponent cannot point Swords to Plowshares at it, while the plain
/// Llanowar Elves beside it is offered to both spells — which rules out "there
/// was nothing to target" as the reason a menu looks short. What is read is
/// the offer itself, because shroud never refuses a spell; it declines to put
/// the permanent on the list, and a spell whose only candidate was shrouded
/// would not even be castable.
#[test]
fn pincher_beetles_shroud_keeps_it_off_its_own_controllers_and_its_opponents_target_menus() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), pincher_beetles(), llanowar_elves()])
        .hand(0, &[giant_growth()])
        .battlefield(1, &[plains(), plains()])
        .hand(1, &[swords_to_plowshares()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let beetles = on_battlefield(&engine, p0, pincher_beetles()).expect("the Beetles is out");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert!(
        keywords(&engine, beetles).contains(KeywordSet::SHROUD),
        "shroud is what the layers hand the permanent, got {:?}",
        keywords(&engine, beetles)
    );

    // The offer is read off the pool, so the mana is floated first — and the
    // Elf is a mana source of its own, which is why this is two green and not
    // the Forest's one.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Green),
        2,
        "the Forest and the Llanowar Elves are both mana sources here"
    );

    // Half one: shroud is not "your opponents' spells". Giant Growth's own
    // controller is the one casting it, and the Beetles is still not offered.
    cast_with_floating(&mut engine, p0, giant_growth());
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!(
            "Giant Growth targets a creature, got {:?}",
            engine.pending()
        )
    };
    assert!(
        options.contains(&elves),
        "the Elf beside it has no shroud, so it is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&beetles),
        "\"can't be the target of spells\" is its own controller's spell as \
         much as anyone's: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .unwrap();
    pass_until(&mut engine, stack_is_empty);

    // Half two: the opponent's targeted removal, which is the whole reason the
    // keyword is printed on a 3/1.
    reach_their_main_phase(&mut engine, p1);
    cast_from_hand(&mut engine, p1, swords_to_plowshares());
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!(
            "Swords to Plowshares targets a creature, got {:?}",
            engine.pending()
        )
    };
    assert!(
        options.contains(&elves),
        "\"target creature\" reaches across the table, so the Elf is offered: {options:?}"
    );
    assert!(
        !options.contains(&beetles),
        "and the shrouded one is not — which is the whole of what the card \
         prints: {options:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .unwrap();
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, pincher_beetles()).is_some(),
        "nothing ever named the Beetles, so it is still standing"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_none(),
        "while the Elf that was named is gone: both spells really resolved \
         rather than being refused for want of a target"
    );
}

fn pradesh_gypsies() -> CardIndex {
    card_index("37c49483-bef6-47c6-9354-ead8560d48da")
}

/// Pradesh Gypsies cost `{2}{G}` for a 1/1 body and print one line: `{1}{G},
/// {T}: Target creature gets -2/-0 until end of turn`. Every number in that
/// sentence is read off one board, so the first three are paid on turn one out
/// of three Forests and the last two on turn two out of the same three, once
/// the creature is past summoning sickness (CR 302.6) — target named at
/// CR 601.2c, the mana and the `{T}` only at CR 601.2h. The pump is aimed at a
/// creature whose power and toughness have been pulled apart by Giant Growth:
/// `2/4` is the only body that reads `-2` with a toughness line of `+0`, where
/// `-2/-2` would read `2/2` and a pump that never happened `4/4`.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn pradesh_gypsies_taps_two_mana_for_minus_two_power_and_leaves_toughness_alone() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), llanowar_elves()])
        // The Elf across the table: "target creature" is not "a creature you
        // control", so the offer below has to name it and the pump must leave
        // it alone.
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[pradesh_gypsies(), giant_growth()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("and one across the table");
    assert_eq!(pt(&engine, elf), (1, 1), "a printed 1/1 before anything");

    // Three Forests, and the Elf kept back: it is the creature both spells are
    // about, and `tap_all_mana` presses every ability whose whole price is its
    // own {T} — a mana creature's included (#159).
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Forests, and nothing off the Elf"
    );

    cast_with_floating(&mut engine, p0, pradesh_gypsies());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let gypsies = on_battlefield(&engine, p0, pradesh_gypsies()).expect("the Gypsies resolved");
    assert_eq!(pt(&engine, gypsies), (1, 1), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{2}}{{G}} is three, and three Forests paid for it"
    );

    // A creature's {{T}} ability waits for its controller's next turn
    // (CR 302.6), which is why the pump is played a turn later and out of the
    // same three sources the cast came from.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, gypsies),
        "the untap step ran: the Gypsies came back with the Forests"
    );
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "the same three Forests, tapped a second turn"
    );

    // Giant Growth first, so the target's two halves disagree and the pump's
    // "-2 and +0" is a body no single number of the card could fake.
    cast_with_floating(&mut engine, p0, giant_growth());
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert!(
        options.contains(&elf) && options.contains(&theirs),
        "Giant Growth reaches either side of the table: {options:?}"
    );
    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options");
    pass_until(&mut engine, |e| at_rest(e, p0));
    assert_eq!(pt(&engine, elf), (4, 4), "the printed 1/1 is a 4/4");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the {{G}} is spent and the Gypsies' {{1}}{{G}} is still floating"
    );

    // The card's own line, read where the engine offers it: `activate` looks
    // the ability up in `LegalActions`, so an unpayable or missing line would
    // panic here rather than pass quietly.
    activate(&mut engine, p0, pradesh_gypsies(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "the Gypsies' line targets a creature, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one asked");
    assert!(
        options.contains(&elf) && options.contains(&theirs) && options.contains(&gypsies),
        "\"target creature\" is any creature — the Elf just pumped, the Elf \
         across the table and the Gypsies themselves: {options:?}"
    );
    // CR 601.2c names the target before CR 601.2h pays, so neither half of the
    // price has moved while the question stands.
    assert!(
        !is_tapped(&engine, gypsies),
        "{{T}} is the last step of the activation"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "and the mana is with it: nothing is spent while the target is unanswered"
    );

    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the pumped Elf was one of the options");
    assert!(
        is_tapped(&engine, gypsies),
        "{{T}} is paid once the target is named"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{1}}{{G}} went with it, so the three Forests paid for the Growth and \
         the pump and nothing is left"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, elf),
        (2, 4),
        "-2/-0 on the 4/4: power down two, toughness exactly where it was"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "and the Elf the ability did not name never moved"
    );
}

fn priest_of_gix() -> CardIndex {
    card_index("d93f82ce-0eed-45cc-a7b1-50fd4cbb6152")
}

/// Priest of Gix prints one line and it is the whole card: `{2}{B}` for a 2/1
/// whose enters-trigger adds `{B}{B}{B}`. That mana is the point, so the board
/// is three Swamps and nothing else — the pool is read **empty** while the
/// creature is still on the stack, which is what says the `{2}{B}` was really
/// spent, and then exactly three black appear off the trigger, which no
/// permanent left standing could have produced. The 2/1 body is read beside it
/// so that a trigger resolving against nothing would not pass on the pool
/// alone.
#[test]
fn priest_of_gix_spends_three_swamps_and_hands_back_three_black() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[priest_of_gix()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, priest_of_gix());
    // Cost is paid before the creature is anywhere, so an empty pool here is
    // what makes the three black below the trigger's and not three the cast
    // never spent.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the three Swamps paid the {{2}}{{B}} and there were exactly three of them"
    );
    assert!(
        on_stack(&engine, priest_of_gix()).is_some(),
        "the creature is on the stack, not yet on the battlefield"
    );

    pass_until(&mut engine, stack_is_empty);

    let priest = on_battlefield(&engine, p0, priest_of_gix()).expect("the Priest resolved");
    assert_eq!(pt(&engine, priest), (2, 1), "the printed 2/1 body");
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Black),
        3,
        "\"When this creature enters, add {{B}}{{B}}{{B}}\""
    );
    assert_eq!(
        pool.total(),
        3,
        "three black and nothing else: every Swamp on the board is tapped and \
         no permanent left there makes mana at all"
    );
}

fn prodigal_sorcerer() -> CardIndex {
    card_index("5e961d15-5972-4e4b-9385-1cd7cd7c6bbe")
}

/// Prodigal Sorcerer is a `{2}{U}` 1/1 whose entire text is "`{T}`: This
/// creature deals 1 damage to any target." Two are seated rather than cast —
/// a Sorcerer cast this turn is summoning sick (CR 302.6) and could not tap
/// until its controller's next turn, so the one doing the pinging has to be a
/// permanent that has been under that seat's control since the turn began —
/// and between them they take both halves of *any target* (CR 115.4): one
/// kills a printed 1/1 Elf across the table, the other takes exactly one life
/// off the opponent. The Elf is what makes the object half a real choice, and
/// the opponent's untouched life total after the first ping says the damage
/// landed where it was aimed and not on the seat that Elf stood on.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn prodigal_sorcerer_taps_to_deal_one_damage_to_any_target() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[prodigal_sorcerer(), prodigal_sorcerer()])
        .battlefield(1, &[llanowar_elves()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let wizards = all_on_battlefield(&engine, p0, prodigal_sorcerer());
    assert_eq!(wizards.len(), 2, "two Sorcerers are seated");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    assert_eq!(pt(&engine, wizards[0]), (1, 1), "a printed 1/1 body");

    // The whole price of the line is the Sorcerer's own {T}, so no mana has to
    // be made before the offer can be read.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        wizards.iter().all(|id| legal.abilities.contains(&(*id, 0))),
        "each untapped Sorcerer offers its one line: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, prodigal_sorcerer(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "one target, no more and no fewer");
    assert!(
        options.contains(&elf),
        "the creature across the table is one of the object options: {options:?}"
    );
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "CR 115.4: \"any target\" counts players in the same choice: {player_options:?}"
    );
    assert!(
        wizards.iter().all(|id| !is_tapped(&engine, *id)),
        "targets are named before costs are paid (CR 601.2c, then CR 601.2h), \
         so no Sorcerer has tapped itself yet"
    );

    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options it enumerated");
    assert_eq!(
        wizards
            .iter()
            .copied()
            .filter(|id| is_tapped(&engine, *id))
            .count(),
        1,
        "exactly one Sorcerer paid the {{T}}, which is the whole price"
    );
    assert!(
        !stack_is_empty(&engine),
        "dealing damage is no mana ability, so the ability is on the stack"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "one damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the damage went to the creature that was named, not to the seat whose \
         board it stood on"
    );

    // The other half of "any target": a player is a legal target too, off the
    // second Sorcerer, which nothing has tapped yet.
    assert_eq!(
        wizards
            .iter()
            .copied()
            .filter(|id| !is_tapped(&engine, *id))
            .count(),
        1,
        "the other Sorcerer is still standing"
    );
    activate(&mut engine, p0, prodigal_sorcerer(), 0);
    let Pending::ChooseTargets { player_options, .. } = engine.pending().clone() else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert!(
        player_options.contains(&p1),
        "the opponent is a legal target as well: {player_options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![],
                players: vec![p1],
            },
        )
        .expect("a face was one of the options it enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        wizards.iter().all(|id| is_tapped(&engine, *id)),
        "the second Sorcerer paid its own {{T}} as well"
    );
    assert_eq!(
        engine.state().players[1].life,
        19,
        "\"deals 1 damage\" — one, and not two"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and the damage landed on the seat it was aimed at, not on the one that \
         aimed it"
    );
}

fn quagmire_druid() -> CardIndex {
    card_index("560e1e81-6675-4d08-8e82-cdf1abd4b3d0")
}

/// Quagmire Druid prints one line — "{G}, {T}, Sacrifice a creature: Destroy
/// target enchantment" — and every part of it is the engine's answer rather
/// than the card's. An enchantment on either side of the table is what says
/// the target is any enchantment and not one this seat controls, while the one
/// that is not named stays behind afterwards. The two creatures are the ends of
/// CR 701.21a: the Elf beside the Druid pays, the Elf across the table is never
/// on the menu, and the Druid's own body is offered to itself because the card
/// says "a creature" and not "another". The single Forest is the whole of the
/// {G}, tapped before anything is claimed about the offer, because
/// `can_afford` reads the pool and not the untapped lands.
#[test]
#[allow(clippy::too_many_lines)] // one activation, every gate it passes asserted
fn quagmire_druid_trades_a_creature_and_a_forest_for_an_enchantment_across_the_table() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[quagmire_druid(), forest(), llanowar_elves(), fastbond()],
        )
        .battlefield(1, &[llanowar_elves(), fastbond()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let druid = on_battlefield(&engine, p0, quagmire_druid()).expect("the Druid stands");
    let fodder = on_battlefield(&engine, p0, llanowar_elves()).expect("a creature to sacrifice");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their creature");
    let mine = on_battlefield(&engine, p0, fastbond()).expect("my enchantment");
    let target = on_battlefield(&engine, p1, fastbond()).expect("their enchantment");

    // The price that is not the {G} is the Druid's own {T} plus a creature, so
    // the Elf is named as the one source kept back: it is the creature the cost
    // is about, and a Forest tapped for the fixer is a pool of exactly one.
    let taken = tap_mana_except(&mut engine, p0, fodder);
    assert_eq!(
        taken, 1,
        "the Forest, and nothing else on this board taps for mana"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "one green floating for the {{G}}"
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(druid, 0)),
        "with the {{G}} in the pool the whole price is payable, so the one line \
         the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, quagmire_druid(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target enchantment\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert_eq!((min, max), (1, 1), "one enchantment, no more and no fewer");
    assert!(
        options.contains(&target) && options.contains(&mine),
        "\"target enchantment\" reaches either side of the table, so both are \
         offered: {options:?}"
    );
    assert!(
        !options.contains(&theirs) && !options.contains(&fodder) && !options.contains(&druid),
        "a creature is no enchantment: {options:?}"
    );
    assert_eq!(
        options.len(),
        2,
        "and those two are the whole menu: {options:?}"
    );
    // CR 601.2c before CR 601.2h: the target is named while the {G} is still
    // floating and the Druid is still standing, so both halves of the price are
    // read after the answer.
    assert!(
        !is_tapped(&engine, druid) && engine.state().players[0].mana_pool.total() == 1,
        "nothing is paid while the target question stands"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![target],
            },
        )
        .expect("the enchantment the question offered was chosen");

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which creature, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostSacrifice,
        "a cost and not a search, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one creature, and the cost asks once");
    assert!(
        options.contains(&fodder),
        "the Elf beside the Druid is a creature you control: {options:?}"
    );
    assert!(
        options.contains(&druid),
        "\"a creature\" is not \"another creature\": the Druid is on its own \
         menu: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "CR 701.21a: an opponent's creature is not yours to sacrifice: {options:?}"
    );
    assert_eq!(
        options.len(),
        2,
        "and those two are the whole menu: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the creature the question offered pays the cost");
    assert!(
        !stack_is_empty(&engine),
        "destroying is no mana ability, so the ability is on the stack"
    );
    assert!(
        is_tapped(&engine, druid),
        "{{T}} was the other half of the price"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, fastbond()).is_some(),
        "\"destroy target enchantment\" — the card that was named is in its \
         owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, fastbond()).is_none(),
        "and off the battlefield"
    );
    assert!(
        on_battlefield(&engine, p0, fastbond()).is_some(),
        "the enchantment the ability never named never moved"
    );
    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "a sacrificed creature goes to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "and the opponent's creature was never fodder"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{G}} came out of the pool"
    );
}

fn raging_cougar() -> CardIndex {
    card_index("695ebb35-55fd-4ed1-8cbe-e3fc1223115b")
}

/// Raging Cougar is `{2}{R}` for a 2/2 Cat whose whole printed text is haste,
/// so the only play that proves anything is the one summoning sickness would
/// otherwise forbid: cast it in a main phase and offer it as an attacker in
/// the same turn. The Llanowar Elves cast beside it is what makes the offer
/// mean something — it is an untapped 1/1 that entered on the same turn, and
/// it is missing from `ChooseAttackers` for exactly the reason the Cougar is
/// present, so the list is not simply everything on the board.
#[test]
fn raging_cougar_attacks_the_turn_it_arrives_while_a_sick_elf_cannot() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), mountain(), mountain(), mountain()])
        .hand(0, &[raging_cougar(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Mana before the cast: `can_afford` reads the pool and not the untapped
    // lands. The Forest is named as the printing kept back because it is what
    // pays for the Elf afterwards.
    tap_all_mana_but(&mut engine, p0, Some(forest()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Mountains in the pool and the Forest still standing"
    );
    cast_with_floating(&mut engine, p0, raging_cougar());
    pass_until(&mut engine, stack_is_empty);

    let cougar = on_battlefield(&engine, p0, raging_cougar()).expect("the Cougar resolved");
    assert_eq!(pt(&engine, cougar), (2, 2), "the body the card prints");
    assert!(
        keywords(&engine, cougar).contains(KeywordSet::HASTE),
        "the one line the card prints reaches the permanent"
    );

    // The control, cast on the very same turn: an untapped creature with no
    // summoning-sickness exemption of its own.
    tap_all_mana(&mut engine, p0);
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, stack_is_empty);
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf resolved");
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::HASTE),
        "the control prints no haste of its own"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&cougar),
        "a 2/2 cast this turn is offered as an attacker, which is haste (CR 702.10b): {attackers:?}"
    );
    assert!(
        !attackers.contains(&elves),
        "and the untapped Elf cast the same turn is not — summoning sickness \
         (CR 302.6) is the only thing keeping it out: {attackers:?}"
    );
}

fn raging_kavu() -> CardIndex {
    card_index("d126bb08-be60-4046-91f1-65672ef42c63")
}

/// Raging Kavu is {1}{R}{G} for a 3/1 Kavu with flash and haste, and each
/// keyword is read in the window the other one does not open. Haste is the
/// attack declaration of the turn the 3/1 arrived, where an untapped Llanowar
/// Elves that entered the very same main phase is *not* offered — the two
/// creatures differ in nothing but the printed word. Flash is the end step's
/// own priority round, where the same sources still standing and the same
/// empty stack leave the Elves held in hand uncastable and the second Kavu
/// castable.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn raging_kavu_flashes_in_on_an_end_step_and_attacks_the_turn_it_arrives() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(41, forest())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                forest(),
                forest(),
                forest(),
                forest(),
            ],
        )
        .hand(
            0,
            &[
                raging_kavu(),
                raging_kavu(),
                quiet_creature(),
                quiet_creature(),
            ],
        )
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Four of the eight lands, and only those: the four left standing are the
    // mana the end step's cast is measured against, and a land tapped here is
    // a land that cannot pay there.
    let mountains = all_on_battlefield(&engine, p0, mountain());
    let forests = all_on_battlefield(&engine, p0, forest());
    assert_eq!(
        (mountains.len(), forests.len()),
        (4, 4),
        "four Mountains and four Forests, which is one {{G}} and two casts of \
         {{1}}{{R}}{{G}}"
    );
    let spent = [mountains[0], mountains[1], forests[0], forests[1]];
    tap_mana_where(&mut engine, p0, |id| spent.contains(&id));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "two Mountains and two Forests tapped, and the rest of the board still \
         standing"
    );

    // A main phase takes any creature, so both of these are in the offer with
    // the very same mana in the pool. Everything below turns on that.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    let kavu_in_hand = in_hand(&engine, p0, raging_kavu()).expect("a Kavu is in hand");
    let elves_in_hand = in_hand(&engine, p0, quiet_creature()).expect("an Elves is in hand");
    assert!(
        legal.castable.contains(&kavu_in_hand) && legal.castable.contains(&elves_in_hand),
        "{{1}}{{R}}{{G}} and {{G}} are both payable here: {:?}",
        legal.castable
    );
    cast_with_floating(&mut engine, p0, quiet_creature());
    pass_until(&mut engine, stack_is_empty);
    let sick = on_battlefield(&engine, p0, quiet_creature()).expect("the Elves resolved");
    cast_with_floating(&mut engine, p0, raging_kavu());

    // Haste, and the control that makes it a reading rather than an
    // assumption: both creatures entered this main phase and both are
    // untapped, so the printed word is the only difference between them.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let kavu = on_battlefield(&engine, p0, raging_kavu()).expect("the first Kavu resolved");
    assert_eq!(pt(&engine, kavu), (3, 1), "the body the card prints");
    assert!(!is_tapped(&engine, sick), "the control is untapped");
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stopped on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&kavu),
        "haste: a 3/1 that arrived a moment ago may attack: {attackers:?}"
    );
    assert!(
        !attackers.contains(&sick),
        "and the Elves that arrived in the same main phase may not — summoning \
         sickness (CR 508.1a) is what the printed haste buys off: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(kavu, Defender::Player(p1))],
            },
        )
        .expect("the offer it was just read out of");

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
            && e.state().turn.active == p0
            && matches!(e.pending(), Pending::Priority { player, .. } if *player == p0)
    });
    assert_eq!(
        engine.state().players[1].life,
        17,
        "the 3/1 connected: three damage to a seat that has nothing to block with"
    );

    // Flash: an end step is a priority round where a spell with the keyword
    // may be cast, and the sources the first main phase left standing are
    // still standing to pay with — the four lands, and **not** the Elves
    // beside them. The Elves arrived this turn and has no haste, so CR 302.6
    // keeps its {{T}} out of this pool exactly as it kept the creature out of
    // the attack above: one card, the same rule, read twice.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "the two Mountains and two Forests held back, and the Elves that \
         arrived this turn cannot tap for its own {{G}}"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!(
            "the end step hands priority back, got {:?}",
            engine.pending()
        )
    };
    let second_kavu =
        in_hand(&engine, p0, raging_kavu()).expect("the second Kavu is still in hand");
    let held_elves = in_hand(&engine, p0, quiet_creature()).expect("an Elves is still in hand");
    assert!(
        legal.castable.contains(&second_kavu),
        "flash: a creature costing {{1}}{{R}}{{G}} is castable in an end step: {:?}",
        legal.castable
    );
    assert!(
        !legal.castable.contains(&held_elves),
        "control: the Elves is in the same hand, is payable out of the same \
         pool and has the same empty stack, and is not castable here — an end \
         step is no main phase: {:?}",
        legal.castable
    );

    cast_with_floating(&mut engine, p0, raging_kavu());
    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        all_on_battlefield(&engine, p0, raging_kavu()).len(),
        2,
        "and it resolved: both copies are on the battlefield"
    );
}

// oracle_id = "b8ae71b3-8ee7-49a0-87ea-7e938166ccb3"
fn ravenous_skirge() -> CardIndex {
    card_index("b8ae71b3-8ee7-49a0-87ea-7e938166ccb3")
}

/// Ravenous Skirge — {2}{B} Creature — Phyrexian Imp 1/1: "Flying" and
/// "Whenever this creature attacks, it gets +2/+0 until end of turn."
///
/// The pump is aimed at `Filter::This`, so the board carries a second creature
/// under the same seat and one across the table: both must still read their
/// printed 1/1 once the attack trigger has resolved, which a static that had
/// widened to "creatures you control" would not. `(3, 1)` is the only body on
/// the attacker that reads the printed +2/+0 — `(3, 3)` would be a toughness
/// nobody granted — and the life total the turn ends on is where the two
/// granted power has to have counted in combat, on a 1/1 that would otherwise
/// deal one.
#[test]
fn ravenous_skirge_flies_and_pumps_itself_only_when_it_attacks() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), llanowar_elves()])
        .hand(0, &[ravenous_skirge()])
        // A creature across the table, so "it gets" has something it must not
        // reach, and so the attacker's flying has a board to fly over.
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The {2}{B} comes out of the three Swamps, and the Elf is named as the
    // printing kept back: `tap_all_mana` would have spent its own {T} and
    // taken it out of the board every assertion below reads.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Swamps, and the Elf paid nothing"
    );
    cast_with_floating(&mut engine, p0, ravenous_skirge());
    pass_until(&mut engine, |e| {
        stack_is_empty(e) && matches!(e.pending(), Pending::Priority { .. })
    });

    let skirge = on_battlefield(&engine, p0, ravenous_skirge()).expect("the Skirge resolved");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert_eq!(
        pt(&engine, skirge),
        (1, 1),
        "a printed 1/1 before it attacks"
    );
    assert!(
        keywords(&engine, skirge).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );

    // The Skirge arrived this turn, so CR 302.6 keeps it out of this
    // combat: the attack trigger is read one turn cycle later.
    reach_their_main_phase(&mut engine, p1);
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. }) && e.state().turn.active == p0
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&skirge),
        "an untapped 1/1 may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(skirge, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The pump is a trigger and not the declaration itself, so the walk passes
    // priority until it has actually resolved.
    pass_until(&mut engine, |e| pt(e, skirge) == (3, 1));
    assert_eq!(
        pt(&engine, skirge),
        (3, 1),
        "\"Whenever this creature attacks, it gets +2/+0 until end of turn\""
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the trigger is aimed at the attacking creature and no other"
    );
    assert_eq!(pt(&engine, theirs), (1, 1), "nor across the table");

    // And the pump has to be worth something: nothing across the table can
    // block a flier, so three damage is where the +2/+0 is read off a life
    // total rather than off the projection alone.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        17,
        "three combat damage — one printed power plus the two the trigger granted"
    );
}

fn reliquary_monk() -> CardIndex {
    card_index("a149ac31-b792-4fbe-903a-788bbdfd5e97")
}

/// Reliquary Monk is a {2}{W} 2/2 whose entire text is one dies trigger:
/// "When this creature dies, destroy target artifact or enchantment." The
/// filter names no controller, so the board carries an artifact *and* an
/// enchantment under each seat, plus a creature and a land to be declined —
/// the offer is then exactly those four permanents and nothing else. The Monk
/// dies to Vindicate aimed at itself, so one resolution both kills it and puts
/// the trigger on the stack (CR 603.3b), and the card the trigger names is the
/// one the graveyard finds afterwards.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn reliquary_monk_dies_and_destroys_a_target_artifact_or_enchantment() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                reliquary_monk(),
                quiet_artifact(),
                exploration(),
                plains(),
                swamp(),
            ],
        )
        // An artifact, an enchantment, a creature and a land across the table:
        // "target artifact or enchantment" is not "a permanent you don't
        // control" and the two declinations are the proof.
        .battlefield(
            1,
            &[quiet_artifact(), exploration(), llanowar_elves(), forest()],
        )
        .hand(0, &[vindicate()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let monk = on_battlefield(&engine, p0, reliquary_monk()).expect("the Monk is out");
    let my_rock = on_battlefield(&engine, p0, quiet_artifact()).expect("my Sol Ring is out");
    let my_glide = on_battlefield(&engine, p0, exploration()).expect("my enchantment is out");
    let their_rock = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    let their_glide = on_battlefield(&engine, p1, exploration()).expect("their enchantment is out");
    let their_elf = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    let their_land = on_battlefield(&engine, p1, forest()).expect("their Forest is out");

    cast_from_hand(&mut engine, p0, vindicate());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets { options, .. } = engine.pending().clone() else {
        unreachable!("the predicate just matched")
    };
    assert!(
        options.contains(&monk),
        "the first target question is Vindicate's own, and the Monk is a \
         permanent it may name: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![monk],
            },
        )
        .expect("the Monk was one of the options it enumerated");

    // Vindicate resolves, the Monk dies, and the death trigger is put on the
    // stack with its own target question (CR 603.3b).
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the Monk's controller answers its own trigger");
    assert!(
        in_graveyard(&engine, p0, reliquary_monk()).is_some(),
        "the Monk died before the trigger was put on the stack"
    );
    assert_eq!((min, max), (1, 1));
    assert!(
        options.contains(&my_rock) && options.contains(&their_rock),
        "\"target artifact\" is either seat's artifact: {options:?}"
    );
    assert!(
        options.contains(&my_glide) && options.contains(&their_glide),
        "and \"or enchantment\" is either seat's enchantment: {options:?}"
    );
    assert!(
        !options.contains(&their_elf),
        "a creature that is not an artifact is no legal target: {options:?}"
    );
    assert!(
        !options.contains(&their_land),
        "a land is neither an artifact nor an enchantment: {options:?}"
    );
    assert_eq!(options.len(), 4, "and those four are the whole menu");

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![their_rock],
            },
        )
        .expect("the artifact the question offered was chosen");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_none(),
        "the targeted artifact left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p1, quiet_artifact()).is_some(),
        "and it is in its owner's graveyard, not merely gone"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_some()
            && on_battlefield(&engine, p0, exploration()).is_some()
            && on_battlefield(&engine, p1, exploration()).is_some(),
        "one target, one destruction: the other three permanents never moved"
    );
    assert!(
        on_battlefield(&engine, p0, reliquary_monk()).is_none(),
        "and the Monk itself is still dead, so the trigger fired once for one death"
    );
}

fn rib_cage_spider() -> CardIndex {
    card_index("906cba93-3dac-4720-a482-987cf1b4e786")
}

/// Rib Cage Spider is `{2}{G}` for a 1/4 whose whole text is reach — "This
/// creature can block creatures with flying". Reach is not readable off a card
/// file at all: it lives in the block declaration, so the scenario seats a
/// flier across the table and reads the pairing the engine is willing to
/// offer. The Llanowar Elves beside it is the control — a creature with
/// neither reach nor flying must not be offered against that same attacker,
/// or the offer says "any creature" instead of "reach". Declaring the block
/// and following the attacker into its graveyard is what makes the offer the
/// block that happened rather than a menu entry.
#[test]
fn rib_cage_spider_uses_its_reach_to_block_a_flier_that_ground_creatures_cannot() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), rib_cage_spider(), llanowar_elves()])
        // A 1/1 flier, seated rather than cast so its own enters-trigger never
        // fires: the question here is the block, not the draw.
        .battlefield(1, &[baleful_strix()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let spider = on_battlefield(&engine, p0, rib_cage_spider()).expect("the Spider is deployed");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are deployed");
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("the Strix is deployed");
    assert_eq!(
        pt(&engine, spider),
        (1, 4),
        "the printed body and nothing added"
    );
    assert!(
        keywords(&engine, spider).contains(KeywordSet::REACH),
        "reach is the whole of what the card prints"
    );

    // Across p0's turn and into p1's, where the flier can attack.
    reach_their_main_phase(&mut engine, p1);
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&strix),
        "an untapped 1/1 flier may attack: {attackers:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareAttackers {
                attackers: vec![(strix, Defender::Player(p0))],
            },
        )
        .unwrap();

    // CR 508.2: priority is handed round once attackers are declared, so
    // the block is the next question and not this one.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        panic!(
            "the defending seat declares blockers, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "and it is the seat being attacked");
    let allowed = blockers
        .iter()
        .find(|option| option.blocker == spider)
        .expect("reach is why the Spider is offered against a flier at all");
    assert!(
        allowed.attackers.contains(&strix),
        "the Spider may be paired with the flier: {:?}",
        allowed.attackers
    );
    assert!(
        !blockers
            .iter()
            .any(|option| option.blocker == elves && option.attackers.contains(&strix)),
        "the Elves have neither reach nor flying, so the same attacker must \
         not be offered to them"
    );

    engine
        .apply(
            p0,
            PlayerAction::DeclareBlockers {
                blockers: vec![(spider, strix)],
            },
        )
        .expect("the pairing the engine offered is legal to declare");
    pass_until(&mut engine, |e| {
        in_graveyard(e, p1, baleful_strix()).is_some()
    });

    assert!(
        in_graveyard(&engine, p1, baleful_strix()).is_some(),
        "the blocked flier took the Spider's damage and died: the offer was a \
         block and not a menu entry"
    );
}

fn rootwalla() -> CardIndex {
    card_index("4dda5f21-11d6-40ce-be24-7c9529272c25")
}

/// Rootwalla — {2}{G} 2/2 Lizard: "{1}{G}: This creature gets +2/+2 until end
/// of turn. Activate only once each turn."
///
/// Four Forests are tapped so that the {1}{G} is a real payment and — the half
/// that makes the limit mean anything — two green are still floating once the
/// pump has resolved, which is exactly what a second activation would cost.
/// The ability's absence from `LegalActions::abilities` is therefore the printed
/// once-a-turn clause and not `can_afford` reading an empty pool. The following
/// turn is the control: the Lizard is a printed 2/2 again once the pump's
/// until-end-of-turn has expired, and the same line is offered a second time —
/// "once each turn" is a limit and not a lost ability.
#[test]
fn rootwalla_pumps_itself_once_a_turn_and_the_pump_expires_with_the_turn() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), forest(), rootwalla()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let lizard = on_battlefield(&engine, p0, rootwalla()).expect("the Lizard is on the table");
    assert_eq!(
        pt(&engine, lizard),
        (2, 2),
        "the printed body, before anything asks"
    );

    // Mana first: the offer is read off the pool, and {1}{G} is two mana.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Forests tapped, and the Lizard itself taps for nothing"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(lizard, 0)),
        "four green pays {{1}}{{G}}: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, rootwalla(), 0);
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, lizard),
        (4, 4),
        "+2/+2, and the pump is the whole of it"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the {{1}}{{G}} came out of the pool and two green are left"
    );

    // The limit with the price still covered: two mana is exactly a second
    // activation's cost, so a missing entry here cannot be an unaffordable
    // ability being withheld.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(lizard, 0)),
        "\"Activate only once each turn\": {:?}",
        legal.abilities
    );

    // And a limit is not a lost ability: the next turn hands the Lizard back
    // its printed body and its {1}{G}.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert_eq!(
        pt(&engine, lizard),
        (2, 2),
        "\"until end of turn\" is exactly one turn long"
    );
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "the Forests untapped and were tapped again"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(lizard, 0)),
        "once *each* turn, so the new turn offers the line again: {:?}",
        legal.abilities
    );
}

fn rootwater_hunter() -> CardIndex {
    card_index("8e42ed82-8b56-46ad-a1ca-e29689a9d030")
}

/// Rootwater Hunter — {2}{U} 1/1 Merfolk: "{T}: This creature deals 1 damage
/// to any target."
///
/// "Any target" (CR 115.4) is the whole card: one damage that may be aimed at
/// a creature *or* at a player, and only playing both of them names it. So two
/// Hunters are cast — one kills a 1/1 Elf across the table, the other is aimed
/// at the opponent's face — and each activation is read where the rules put its
/// price: the target at CR 601.2c while the Hunter is still untapped, the tap
/// symbol at CR 601.2h after the answer. The turn in between is what the {T}
/// costs a creature that has just arrived (CR 302.6).
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn rootwater_hunter_pings_a_creature_or_a_player_and_taps_for_it() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(29, island())
        .battlefield(
            0,
            &[island(), island(), island(), island(), island(), island()],
        )
        .hand(0, &[rootwater_hunter(), rootwater_hunter()])
        .battlefield(1, &[llanowar_elves()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Two {2}{U} spells out of six Islands, both inside the one main phase, so
    // the pool CR 500.5 empties never has to carry anything across a step.
    assert_eq!(tap_all_mana(&mut engine, p0), 6, "six Islands, six mana");
    cast_with_floating(&mut engine, p0, rootwater_hunter());
    pass_until(&mut engine, |e| {
        all_on_battlefield(e, p0, rootwater_hunter()).len() == 1
    });
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "the first Hunter took {{2}}{{U}} out of the pool"
    );
    cast_with_floating(&mut engine, p0, rootwater_hunter());
    pass_until(&mut engine, |e| {
        all_on_battlefield(e, p0, rootwater_hunter()).len() == 2
    });
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the second took the rest of it"
    );

    let hunters = all_on_battlefield(&engine, p0, rootwater_hunter());
    assert_eq!(hunters.len(), 2, "both Hunters resolved");
    let (first, second) = (hunters[0], hunters[1]);
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("the Elf is standing");
    assert_eq!(pt(&engine, first), (1, 1), "a printed 1/1 either way");

    // A creature that entered this turn cannot pay a {T} (CR 302.6), so the
    // whole card is unofferable until its controller's next turn — which is
    // why the two activations below wait for one.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == first),
        "summoning sick: its {{T}} is not a price it may pay yet: {:?}",
        legal.abilities
    );

    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    // ---- the first Hunter: 1 damage to a creature ------------------------
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    let (source, ability_index) = legal
        .abilities
        .iter()
        .copied()
        .find(|(src, _)| *src == first)
        .expect("untapped and past summoning sickness, the line is offered");
    engine
        .apply(
            p0,
            PlayerAction::ActivateAbility {
                source,
                ability_index,
            },
        )
        .unwrap();

    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(
        (player, min, max),
        (p0, 1, 1),
        "the activating seat, and exactly one target"
    );
    assert!(
        options.contains(&elf),
        "the creature across the table is one of the object options: {options:?}"
    );
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "CR 115.4: \"any target\" counts players in the same choice: {player_options:?}"
    );
    assert!(
        !is_tapped(&engine, first),
        "CR 601.2c before CR 601.2h: the target is named while the tap is \
         still unpaid"
    );
    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options it enumerated");
    assert!(
        is_tapped(&engine, first),
        "{{T}} is the whole price, and it is paid after the target"
    );
    assert!(
        !stack_is_empty(&engine),
        "dealing damage is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "one damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the damage went to the creature that was named, not to its controller"
    );

    // ---- the second Hunter: 1 damage to a player -------------------------
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    let (source, ability_index) = legal
        .abilities
        .iter()
        .copied()
        .find(|(src, _)| *src == second)
        .expect("the other Hunter is the one still untapped");
    engine
        .apply(
            p0,
            PlayerAction::ActivateAbility {
                source,
                ability_index,
            },
        )
        .unwrap();
    let Pending::ChooseTargets { player_options, .. } = engine.pending().clone() else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert!(
        player_options.contains(&p1),
        "a player is a target of its own kind here (CR 115.4): {player_options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![],
                players: vec![p1],
            },
        )
        .expect("the opponent was one of the players it enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[1].life,
        19,
        "\"1 damage to any target\" is a player's life total too"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and the damage belongs to the seat that was aimed at"
    );
    assert!(
        is_tapped(&engine, first) && is_tapped(&engine, second),
        "both Hunters paid their {{T}}, and neither came back untapped"
    );
}

// oracle_id = "de7f1725-833c-4784-94b1-7a33e36aec94"
fn rotlung_reanimator() -> CardIndex {
    card_index("de7f1725-833c-4784-94b1-7a33e36aec94")
}

/// Rotlung Reanimator — {2}{B} — Creature — Zombie Cleric, 2/2, printing
/// "Whenever this creature or another Cleric dies, create a 2/2 black Zombie
/// creature token."
///
/// The trigger is a subtype filter with an `or` in it, so the board has to
/// carry both sides of that word: an Ondu Cleric (Kor Cleric Ally) is the
/// Cleric, and a Llanowar Elves (Elf Druid) is the body that must not count.
/// Three Vindicates kill the Elf, the Cleric and finally the Reanimator
/// itself, and the token ledger is read off the battlefield after each one —
/// so neither the subtype nor the second arm of the printed `or` can be
/// missing without a count going wrong.
#[test]
#[allow(clippy::too_many_lines)] // three deaths, one printed trigger, and every arm of it read off the board
fn rotlung_reanimator_makes_a_zombie_for_a_cleric_and_not_for_a_body() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[swamp(), swamp(), swamp(), ondu_cleric(), llanowar_elves()],
        )
        .hand(0, &[rotlung_reanimator()])
        // Six Swamps and six Plains: three Vindicates are three white and
        // three black pips plus three generic, so the pool has to leave room
        // for the auto-payer to spend a colour on the generic half.
        .battlefield(
            1,
            &[
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                plains(),
                plains(),
                plains(),
                plains(),
                plains(),
                plains(),
            ],
        )
        .hand(1, &[vindicate(), vindicate(), vindicate()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The card arrives the way it arrives: cast for three mana off the Swamps.
    cast_from_hand(&mut engine, p0, rotlung_reanimator());
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, rotlung_reanimator()).is_some()
    });
    let reanimator =
        on_battlefield(&engine, p0, rotlung_reanimator()).expect("the Reanimator resolved");
    let cleric = on_battlefield(&engine, p0, ondu_cleric()).expect("the Cleric is out");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is out");
    assert_eq!(pt(&engine, reanimator), (2, 2), "a printed 2/2 body");
    assert!(
        tokens_of(&engine, p0).is_empty(),
        "nothing has died yet, so the trigger has had nothing to look at"
    );

    reach_their_main_phase(&mut engine, p1);

    // The control: a death that is not a Cleric. The Elf really does die,
    // which is what makes the token count a claim about the subtype filter
    // rather than about a destroy that never resolved.
    cast_from_hand(&mut engine, p1, vindicate());
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"destroy target permanent\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p1, "the seat that cast it does the choosing");
    assert!(
        options.contains(&elf),
        "a creature is a permanent, on either side of the table: {options:?}"
    );
    engine
        .apply(p1, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "the Elf died, so the count below is read after a real death"
    );
    assert!(
        tokens_of(&engine, p0).is_empty(),
        "an Elf Druid is no Cleric, so its death creates nothing at all"
    );

    // The card's own word: another Cleric dies.
    cast_from_hand(&mut engine, p1, vindicate());
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"destroy target permanent\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p1, "the seat that cast it does the choosing");
    assert!(
        options.contains(&cleric),
        "the Ondu Cleric is a permanent and a Cleric: {options:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::ChooseObjects {
                objects: vec![cleric],
            },
        )
        .expect("the Cleric was one of the options");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, ondu_cleric()).is_some(),
        "the Cleric died"
    );
    let zombies = tokens_of(&engine, p0);
    assert_eq!(
        zombies.len(),
        1,
        "another Cleric died, so exactly one Zombie: {zombies:?}"
    );
    let zombie = engine
        .state()
        .object(zombies[0])
        .expect("the token is on the battlefield")
        .token
        .expect("and it knows which token it is");
    assert_eq!(zombie.name, "Zombie");
    assert_eq!((zombie.power, zombie.toughness), (Some(2), Some(2)));
    assert!(
        zombie.colors.contains(baylee_core::color::Color::Black),
        "a black Zombie, not a colourless one"
    );
    assert_eq!(
        pt(&engine, zombies[0]),
        (2, 2),
        "and the body the battlefield projects is the body the token prints"
    );

    // The other arm of the printed `or`: "whenever this creature ... dies".
    // The first arm cannot answer for it — it carries `Another`, which is
    // exactly what the source is not — so a card missing `Filter::This`
    // would leave this death silent.
    cast_from_hand(&mut engine, p1, vindicate());
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"destroy target permanent\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p1, "the seat that cast it does the choosing");
    assert!(
        options.contains(&reanimator),
        "the Reanimator is itself a Zombie Cleric and a permanent: {options:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::ChooseObjects {
                objects: vec![reanimator],
            },
        )
        .expect("the Reanimator was one of the options");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, rotlung_reanimator()).is_some(),
        "the Reanimator died"
    );
    assert_eq!(
        tokens_of(&engine, p0).len(),
        2,
        "\"this creature or another Cleric\": its own death is the second arm, \
         and the ability looks back to the game before it left (CR 603.10a)"
    );
}

fn royal_assassin() -> CardIndex {
    card_index("9ed6f28f-a3db-48c5-9ab0-b90a7fba5f57")
}

/// Royal Assassin — {1}{B}{B}, a 1/1 Human Assassin whose entire text is
/// "{T}: Destroy target tapped creature."
///
/// Two words carry the card and each needs its own witness, so four creatures
/// stand: a tapped one and an untapped one on each side of the table, none of
/// them bought with a combat step. Only the two tapped creatures may appear in
/// the offer — a list carrying an untapped one would mean "tapped" was never
/// read, and a list holding nothing but this seat's own creature would mean a
/// "you control" the card does not print. Killing the Elf across the table
/// with a price that is nothing but the tap symbol is then the whole card: the
/// named creature leaves for its owner's graveyard while the untapped Elf
/// beside it, the tapped Elf behind it and the Assassin itself all stay put.
#[test]
#[allow(clippy::too_many_lines)] // two taps, one activation, every clause of the card read off it
fn royal_assassin_destroys_the_tapped_creature_it_names_and_reaches_across_the_table() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[royal_assassin(), llanowar_elves()])
        .battlefield(1, &[llanowar_elves(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let assassin = on_battlefield(&engine, p0, royal_assassin()).expect("the Assassin is out");
    let my_elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");
    let theirs = all_on_battlefield(&engine, p1, llanowar_elves());
    assert_eq!(theirs.len(), 2, "two Elves across the table");
    let (standing_elf, doomed) = (theirs[0], theirs[1]);

    // Two creatures tapped and two not, so the offer below has something to be
    // wrong about in either direction. Tapping them for their own mana is the
    // shortest way to say "tapped" without a combat step, and `tap_mana_where`
    // will not return while a printed mana ability is still standing untapped
    // (#159) — a creature's is one of them.
    tap_mana_where(&mut engine, p0, |id| id == my_elf);
    assert!(is_tapped(&engine, my_elf), "my own Elf is tapped for mana");
    // The Elf across the table has to be tapped by its own controller, so
    // priority is handed over and then straight back: a mana ability is an
    // action, and the round starts over after one.
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::Priority { player, .. } if *player == p1),
    );
    tap_mana_where(&mut engine, p1, |id| id == doomed);
    assert!(
        is_tapped(&engine, doomed),
        "and one across the table is too"
    );
    assert!(
        !is_tapped(&engine, standing_elf),
        "the other Elf never moved"
    );
    pass_until(
        &mut engine,
        |e| matches!(e.pending(), Pending::Priority { player, .. } if *player == p0),
    );

    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds a quiet priority: {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(assassin, 0)),
        "an untapped Assassin is a paid {{T}}, so the one line the card prints \
         is offered: {:?}",
        legal.abilities
    );
    let pool_before = engine.state().players[0].mana_pool.total();

    activate(&mut engine, p0, royal_assassin(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target tapped creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert_eq!((min, max), (1, 1), "one creature, no more and no fewer");
    assert_eq!(
        options.len(),
        2,
        "exactly the two tapped creatures on the battlefield: {options:?}"
    );
    assert!(
        options.contains(&doomed),
        "\"tapped creature\" is not \"a creature you control\": the Elf across \
         the table is on the menu: {options:?}"
    );
    assert!(
        options.contains(&my_elf),
        "and so is the tapped creature this seat controls: {options:?}"
    );
    assert!(
        !options.contains(&standing_elf),
        "the Elf that is still untapped is the whole of what \"tapped\" \
         excludes: {options:?}"
    );
    assert!(
        !options.contains(&assassin),
        "an untapped creature may not be aimed at, its own ability \
         notwithstanding: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![doomed],
            },
        )
        .expect("the Elf the question offered was one of its answers");

    assert!(
        is_tapped(&engine, assassin),
        "{{T}} is the whole price and is paid as the ability is activated"
    );
    assert!(
        !stack_is_empty(&engine),
        "destroying a creature is no mana ability, so it is on the stack"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        pool_before,
        "and nothing about the price is mana"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "the targeted creature died, and it is in its *owner's* graveyard"
    );
    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_some(),
        "the Elf the ability did not name is still across the table"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "and so is the tapped creature this seat controls: one target, one \
         casualty"
    );
    assert!(
        on_battlefield(&engine, p0, royal_assassin()).is_some(),
        "the Assassin outlives what it killed"
    );
}

fn sabretooth_tiger() -> CardIndex {
    card_index("8ea35158-1c1a-46da-b466-0eafb376e464")
}

/// Sabretooth Tiger is {2}{R} for a 2/1 Cat with first strike. Reading the
/// keyword off the card file would say nothing about *when* the damage
/// happens, so the scenario is the one the step structure decides: the Tiger
/// attacks and a 1/1 Elf blocks it — without first strike that Elf would deal
/// its one damage in the same step and kill a 2/1, while with it the Elf dies
/// before it deals anything. The Elf is the control of both claims: the
/// pool's known 1/1, carrying no first strike of its own, and the attacker is
/// blocked (CR 509.1h), so the life totals must not move either.
#[test]
fn sabretooth_tiger_kills_its_blocker_in_the_first_strike_step_and_survives() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(0, &[mountain(), mountain(), mountain()])
        .hand(0, &[sabretooth_tiger()])
        .battlefield(1, &[quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {2}{R} off the three Mountains, and the Tiger arrives as a printed 2/1.
    cast_from_hand(&mut engine, p0, sabretooth_tiger());
    pass_until(&mut engine, stack_is_empty);
    let tiger = on_battlefield(&engine, p0, sabretooth_tiger()).expect("the Tiger resolved");
    let elf = on_battlefield(&engine, p1, quiet_creature()).expect("an Elf across the table");
    assert_eq!(pt(&engine, tiger), (2, 1), "the body the card prints");
    assert!(
        keywords(&engine, tiger).contains(KeywordSet::FIRST_STRIKE),
        "first strike reaches the permanent through the layers"
    );
    assert!(
        !keywords(&engine, elf).contains(KeywordSet::FIRST_STRIKE),
        "and nothing on this board hands the keyword out: the Elf is the control"
    );

    // A creature cast this turn has summoning sickness (CR 302.6), so the
    // attack waits for its controller's next turn — walked rather than
    // skipped, with `pass_until` declaring no attackers on the way.
    let cast_turn = engine.state().turn.number;
    pass_until(&mut engine, |e| {
        e.state().turn.number > cast_turn
            && e.state().turn.active == p0
            && matches!(e.state().turn.phase, Phase::FirstMain)
    });

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until only stops on the attack declaration")
    };
    assert!(
        attackers.contains(&tiger),
        "the Tiger is untapped and no longer sick: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(tiger, Defender::Player(p1))],
            },
        )
        .unwrap();

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("pass_until only stops on the block declaration")
    };
    assert!(
        blockers
            .iter()
            .any(|option| option.blocker == elf && option.attackers.contains(&tiger)),
        "a 1/1 may block a 2/1: {blockers:?}"
    );
    engine
        .apply(
            p1,
            PlayerAction::DeclareBlockers {
                blockers: vec![(elf, tiger)],
            },
        )
        .unwrap();

    // Past the damage steps: `stack_is_empty` would stop before them, since
    // the stack is already empty the moment attackers are declared.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });

    assert!(
        in_graveyard(&engine, p1, quiet_creature()).is_some(),
        "two first-strike damage on a 1/1 is lethal (CR 704.5f)"
    );
    assert!(
        on_battlefield(&engine, p0, sabretooth_tiger()).is_some(),
        "and the Tiger is still standing: the Elf died in the first-strike \
         damage step, where its one damage would have killed a 2/1"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the attacker was blocked (CR 509.1h), so no damage reached the player"
    );
}

// oracle_id = "dd520d83-297a-487f-b8f3-4997bbc056e0"
fn serendib_efreet() -> CardIndex {
    card_index("dd520d83-297a-487f-b8f3-4997bbc056e0")
}

/// Serendib Efreet — {2}{U} for a 3/4 flier with one drawback printed under
/// it: "At the beginning of your upkeep, this creature deals 1 damage to
/// you."
///
/// Both halves are played, because neither can be read off the other. The
/// three Islands pay for the cast and are spent doing it, so the pool is
/// empty and the only thing left on the board that can move a life total is
/// the trigger; the body and the keyword are read off the permanent the cast
/// left behind. The opponent is the control that fixes the word "you": p1 is
/// at 20 before the bite and still at 20 on their next main phase, which is
/// also where the walk on shows the bite belongs to the *controller's*
/// upkeep rather than to every upkeep at the table.
#[test]
fn serendib_efreet_flies_and_bites_its_controller_on_its_own_upkeep() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(2024, island())
        .battlefield(0, &[island(), island(), island()])
        .hand(0, &[serendib_efreet()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, serendib_efreet());
    pass_until(&mut engine, stack_is_empty);
    let efreet = on_battlefield(&engine, p0, serendib_efreet()).expect("the Efreet resolved");
    assert_eq!(pt(&engine, efreet), (3, 4), "the printed 3/4 body");
    assert!(
        keywords(&engine, efreet).contains(KeywordSet::FLYING),
        "the printed flying reaches the permanent"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "the upkeep this Efreet arrived after has already passed"
    );

    // The trigger fires on p0's own next upkeep, and it is read on the life
    // total rather than on the question, because a `DealDamage` aimed at a
    // fixed player may arrive as a target choice or as nothing at all. The
    // walk answers whatever comes and stops the moment a life point moves.
    let mut bitten = false;
    for _ in 0..300 {
        if engine.state().players[0].life < 20 {
            bitten = true;
            break;
        }
        match engine.pending().clone() {
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            Pending::ChooseBlockers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .unwrap();
            }
            Pending::ChooseTargets {
                player,
                options,
                player_options,
                ..
            } => {
                // "deals 1 damage to you" names a player, so the answer is the
                // Efreet's controller whichever of the two lists carries them.
                let players: Vec<PlayerId> = if player_options.contains(&p0) {
                    vec![p0]
                } else {
                    player_options.iter().copied().take(1).collect()
                };
                let objects = if players.is_empty() {
                    options.iter().copied().take(1).collect()
                } else {
                    Vec::new()
                };
                engine
                    .apply(player, PlayerAction::ChooseTargets { objects, players })
                    .unwrap();
            }
            other => panic!("unexpected on the way to the Efreet's upkeep: {other:?}"),
        }
    }
    assert!(
        bitten,
        "the printed upkeep trigger never took a life point off its controller"
    );
    assert_eq!(
        engine.state().turn.active,
        p0,
        "the bite is on the controller's own upkeep, got turn for {:?}",
        engine.state().turn.active
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the trigger says \"you\": the Efreet bites nobody but its controller"
    );

    // The control: a whole turn later, off p0's upkeep entirely, the life
    // totals have not moved again. That is what tells "at the beginning of
    // *your* upkeep" from a trigger that sweeps the table every turn.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        engine.state().players[0].life,
        19,
        "one bite, and no more, on the way through a turn that is not its controller's"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "the seat that never controlled the Efreet is never damaged by it"
    );
    assert!(
        on_battlefield(&engine, p0, serendib_efreet()).is_some(),
        "the Efreet outlives the life it takes"
    );
}

fn serpent_warrior() -> CardIndex {
    card_index("fe249f27-db6c-4826-836e-a04efb1a3eaa")
}

/// Serpent Warrior — {2}{B} — 3/3 Snake Warrior: "When this creature enters,
/// you lose 3 life."
///
/// Two claims meet in one cast and each is the other's witness: the 3/3 body
/// is what proves a permanent really entered (a life loss read off a card
/// still on the stack would be a different card), and the life total is what
/// proves the loss is the *controller's* and not the table's. The life is
/// read both before and after the trigger resolves, because the price is a
/// triggered ability (CR 603.6a) and not an additional cost: the Warrior is
/// already standing at 20 while the question is still on the stack, and only
/// the resolution behind it takes the three.
#[test]
fn serpent_warrior_makes_its_controller_lose_three_life_as_it_enters() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(23, forest())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp()])
        .hand(0, &[serpent_warrior()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, serpent_warrior());
    // The spell resolves and its entry trigger goes on the stack behind it,
    // so this stops with the Warrior on the battlefield and the trigger
    // unanswered.
    pass_until(&mut engine, |e| {
        on_battlefield(e, p0, serpent_warrior()).is_some() && !stack_is_empty(e)
    });
    assert_eq!(
        engine.state().players[0].life,
        20,
        "the loss is a triggered ability (CR 603.6a): the Warrior has already \
         entered and nothing has been paid for it yet"
    );

    pass_until(&mut engine, stack_is_empty);
    let warrior = on_battlefield(&engine, p0, serpent_warrior()).expect("the Warrior resolved");
    assert_eq!(pt(&engine, warrior), (3, 3), "the body the card prints");
    assert_eq!(
        engine.state().players[0].life,
        17,
        "\"you lose 3 life\" — three off the seat that cast it"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "\"you\" is the controller: the loss never crosses the table"
    );
}

fn seton_krosan_protector() -> CardIndex {
    card_index("48d9747f-f9eb-4f71-93c9-e5151a7ff3ea")
}

/// Seton, Krosan Protector prints one line: "Tap an untapped Druid you
/// control: Add {G}." The whole price is the tap of a permanent the filter
/// names, so the board carries one of each answer and the menu has to tell
/// them apart: a Druid under this seat (Llanowar Elves), a creature that is
/// no Druid (Festering Goblin), and a Druid across the table, which is not
/// this seat's to tap. Nothing on the board is tapped before the mana is
/// read, so the single green in the pool can only be the ability's own — no
/// land and no ability of the tapped Elf's was pressed to get it.
#[test]
fn seton_krosan_protector_taps_a_druid_you_control_for_one_green() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                seton_krosan_protector(),
                llanowar_elves(),
                festering_goblin(),
            ],
        )
        .battlefield(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches its own main phase"
    );

    let seton = on_battlefield(&engine, p0, seton_krosan_protector()).expect("Seton is out");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let goblin = on_battlefield(&engine, p0, festering_goblin()).expect("the Goblin is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats before the ability is pressed"
    );
    assert!(
        !is_tapped(&engine, elf),
        "and the Druid the price is about is untapped"
    );

    activate(&mut engine, p0, seton_krosan_protector(), 0);
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the cost asks which Druid is tapped, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostTap,
        "a tap being paid for, and not a search"
    );
    assert_eq!((min, max), (1, 1), "one Druid, no more and no fewer");
    assert!(
        options.contains(&elf),
        "the untapped Druid you control is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&goblin),
        "a Goblin is no Druid: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "a seat taps only what it controls, so the Druid across the table is \
         not on the menu: {options:?}"
    );

    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Druid the question offered pays the cost");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        1,
        "\"Add {{G}}\" — one green, and the empty pool before it is what says \
         the ability is where it came from"
    );
    assert_eq!(pool.total(), 1, "and nothing else came with it");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack"
    );
    assert!(
        is_tapped(&engine, elf),
        "the Druid that paid the cost is tapped"
    );
    assert!(
        !is_tapped(&engine, seton),
        "the price was a Druid and not the source: Seton is still standing"
    );
    assert!(
        !is_tapped(&engine, goblin),
        "the permanent the filter declined never moved"
    );
    assert!(
        !is_tapped(&engine, theirs),
        "and neither did the Druid across the table"
    );
}

fn shu_grain_caravan() -> CardIndex {
    card_index("587e9f15-1d79-458f-a073-229b828b2393")
}

/// Shu Grain Caravan — `{2}{W}` — Creature — Human Soldier 2/2: "When this
/// creature enters, you gain 2 life."
///
/// A life total read only at the end of the cast proves nothing on its own, so
/// the scenario reads both ends of it: while the Caravan is a *spell* on the
/// stack the controller is still at the twenty they started with (CR 603.6a
/// puts the trigger on entering and not on casting), and the three Plains are
/// empty of mana because `{2}{W}` is paid on announcement (CR 601.2h). The
/// opponent's life is the control for the pronoun — "you" is the controller,
/// not the table — and exactly two says the entry was counted once.
#[test]
fn shu_grain_caravan_gains_two_life_when_it_enters() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains()])
        .hand(0, &[shu_grain_caravan()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, shu_grain_caravan());
    assert!(
        on_stack(&engine, shu_grain_caravan()).is_some(),
        "the Caravan is a creature *spell* until it resolves, so the trigger \
         that gains the life has not fired yet"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "nothing has entered, so nothing has been gained (CR 603.6a)"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the three Plains paid the {{2}}{{W}} when the spell was announced"
    );

    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[0].life,
        22,
        "\"you gain 2 life\" — two, once, off one entry"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "\"you\" is the controller of the Caravan: the opponent's life never \
         moved"
    );
    let caravan = on_battlefield(&engine, p0, shu_grain_caravan()).expect("the Caravan resolved");
    assert_eq!(
        pt(&engine, caravan),
        (2, 2),
        "and the 2/2 body the card prints is standing on the battlefield"
    );
    assert!(
        all_on_battlefield(&engine, p0, plains())
            .iter()
            .all(|id| is_tapped(&engine, *id)),
        "the mana came out of the three Plains: every one of them is tapped"
    );
}

fn silent_attendant() -> CardIndex {
    card_index("4fa30e29-94c1-4537-bebd-dc7124e4ef71")
}

/// Silent Attendant is a {2}{W} 0/2 Human Cleric whose whole printed text is
/// "{T}: You gain 1 life." The board holds nothing else that can move a life
/// total — no mana, no spell, no permanent of the opponent's — so the single
/// life p0 gains can only have come off the tap the card prints. It is seated
/// rather than cast because the price is its own {T}: a creature that arrived
/// this turn could not pay it (CR 302.6) and the test would be asserting an
/// ability the engine never had reason to offer.
#[test]
fn silent_attendant_taps_for_one_life_and_leaves_the_other_seat_alone() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[silent_attendant()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let attendant = on_battlefield(&engine, p0, silent_attendant()).expect("the Attendant is out");
    assert_eq!(pt(&engine, attendant), (0, 2), "a printed 0/2 body");
    assert!(!is_tapped(&engine, attendant), "and it starts untapped");

    // The whole price is the tap symbol, so nothing has to be floating and no
    // source is tapped: the offer below is read off an empty pool.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the board holds no mana at all"
    );
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Attendant holds it");
    assert!(
        legal.abilities.contains(&(attendant, 0)),
        "the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, silent_attendant(), 0);
    assert!(
        is_tapped(&engine, attendant),
        "{{T}} is the cost and is paid as the ability is activated"
    );
    assert!(
        !stack_is_empty(&engine),
        "gaining life is no mana ability, so the ability waits on the stack"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and nothing has happened yet — the effect resolves off the stack"
    );

    pass_until(&mut engine, |e| at_rest(e, p0));
    assert_eq!(
        engine.state().players[0].life,
        21,
        "\"You gain 1 life\" — one, on one activation"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the life belongs to the seat that paid the price"
    );

    // The tap is spent, so the line is no longer one this seat may take.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(attendant, 0)),
        "a tapped Attendant has no {{T}} left to pay with: {:?}",
        legal.abilities
    );
}

fn sisters_of_the_flame() -> CardIndex {
    card_index("389a9d46-d3fb-47f0-91cd-f6d487636916")
}

/// Sisters of the Flame — {1}{R}{R} — a 2/2 Human Shaman whose entire printed
/// text is "{T}: Add {R}".
///
/// The card is played out of the hand for its three mana and arrives as the
/// body it prints, and the mana line is then read on a board where the one red
/// has nowhere else to come from: three Mountains are the only other
/// permanents, they are all still standing untapped, and the pool is empty on
/// both sides of the activation. The tap symbol is the whole price, which is
/// why the ability is offered with nothing floating, why it lands without a
/// stack (CR 605.3b) and why nothing is asked on the way — the card names its
/// colour, where a "one mana of any color" rock would have to ask.
#[test]
fn sisters_of_the_flame_is_a_two_two_that_taps_for_one_red() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), mountain(), mountain()])
        .hand(0, &[sisters_of_the_flame()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {1}{R}{R} off the three Mountains, and the pool is read after the cast,
    // so the three mana have really gone somewhere.
    cast_from_hand(&mut engine, p0, sisters_of_the_flame());
    pass_until(&mut engine, stack_is_empty);
    let sister = on_battlefield(&engine, p0, sisters_of_the_flame()).expect("the Sisters resolved");
    assert!(
        types(&engine, sister).contains(TypeSet::CREATURE),
        "a creature, and not some other permanent the board happened to hold"
    );
    assert_eq!(pt(&engine, sister), (2, 2), "the body the card prints");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Mountains paid {{1}}{{R}}{{R}} and nothing is left floating"
    );

    // The untap step is what puts the Mountains back, and that board is the
    // one the mana line is read on: nothing floating, three untapped Mountains
    // beside the Sister, and a creature that entered on the previous turn.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "the Sisters' controller takes another turn"
    );
    let mountains = all_on_battlefield(&engine, p0, mountain());
    assert_eq!(mountains.len(), 3, "the three Mountains came back");
    assert!(
        mountains.iter().all(|id| !is_tapped(&engine, *id)),
        "every Mountain is standing untapped, so none of them paid for the \
         mana read below"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and nothing floats, which is what makes `one red` an exact claim"
    );

    // The whole price is the tap symbol, so an untapped Sister is a paid
    // ability even on an empty pool: `can_afford` reads the permanent and not
    // the lands.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(sister, 0)),
        "the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, sisters_of_the_flame(), 0);
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "{{R}} is named and not chosen, so nothing was asked on the way: {:?}",
        engine.pending()
    );
    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(pool.available(ManaColor::Red), 1, "{{T}}: Add {{R}}");
    assert_eq!(
        pool.total(),
        1,
        "one mana, off one tap, and nothing beside it"
    );
    assert_eq!(
        pool.available(ManaColor::Green),
        0,
        "the red is the Sister's: the only land types on this board make green"
    );
    assert!(is_tapped(&engine, sister), "the Sister paid her own {{T}}");
    assert!(
        mountains.iter().all(|id| !is_tapped(&engine, *id)),
        "and the Mountains never moved, so the red mana has no other source \
         on this board"
    );
}

fn skittering_horror() -> CardIndex {
    card_index("4344abeb-47ab-4638-b50f-dd502f14c1af")
}

/// Skittering Horror is a {2}{B} 4/3 with one printed sentence: "When you
/// cast a creature spell, sacrifice this creature." Every word of it is read
/// on one board, because each one is a chance for the trigger to be the wrong
/// trigger: its own cast leaves it standing (a permanent's ability does
/// nothing from a stack), Dark Ritual leaves it standing (an instant is no
/// creature spell), the opponent's Goblin leaves it standing ("you" is the
/// Horror's controller), and the controller's own Goblin takes it away a step
/// *before* that Goblin resolves — which is the difference between a trigger
/// on the casting and one on the entry.
#[test]
fn skittering_horror_sacrifices_itself_for_its_controllers_creature_spell_and_no_other() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp(), swamp()])
        .hand(0, &[skittering_horror(), dark_ritual(), festering_goblin()])
        .battlefield(1, &[swamp()])
        .hand(1, &[festering_goblin()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Its own cast: the trigger belongs to a permanent, so the spell that is
    // still a card on the stack raises nothing and the Horror arrives.
    cast_from_hand(&mut engine, p0, skittering_horror());
    pass_until(&mut engine, stack_is_empty);
    let horror = on_battlefield(&engine, p0, skittering_horror())
        .expect("the Horror resolved, and its own cast did not sacrifice it");
    assert_eq!(
        pt(&engine, horror),
        (4, 3),
        "the printed body, on the table"
    );

    // A spell that is no creature: `YOUR_CREATURE` reads the card type, and
    // Dark Ritual costs the one black the Horror left in the pool.
    cast_from_hand(&mut engine, p0, dark_ritual());
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, skittering_horror()).is_some(),
        "an instant is no creature spell, so the Horror stays where it is"
    );

    // And a creature spell across the table: "you" is whoever controls the
    // Horror, never whoever happens to be casting.
    reach_their_main_phase(&mut engine, p1);
    cast_from_hand(&mut engine, p1, festering_goblin());
    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p1, festering_goblin()).is_some(),
        "the Goblin resolved for the seat that cast it"
    );
    assert!(
        on_battlefield(&engine, p0, skittering_horror()).is_some(),
        "another seat's creature spell is not this Horror's to answer"
    );

    // The real thing, back on p0's turn with the Swamps untapped.
    reach_their_main_phase(&mut engine, p0);
    cast_from_hand(&mut engine, p0, festering_goblin());
    pass_until(&mut engine, |e| {
        in_graveyard(e, p0, skittering_horror()).is_some()
    });
    assert!(
        on_battlefield(&engine, p0, festering_goblin()).is_none() && !stack_is_empty(&engine),
        "the trigger resolves above the spell that raised it, so the Goblin \
         is still on the stack while the Horror is already gone — a trigger \
         on the creature *entering* would have it the other way round"
    );

    pass_until(&mut engine, stack_is_empty);
    assert!(
        on_battlefield(&engine, p0, festering_goblin()).is_some(),
        "and then the creature spell the trigger was about resolves"
    );
}

fn sky_spirit() -> CardIndex {
    card_index("fc7e288f-ade2-4997-b3fe-f873c26990b0")
}

/// Sky Spirit is `{1}{W}{U}` for a 2/2 Spirit whose whole text is "Flying,
/// first strike", so the card is only itself if that line reaches the
/// permanent the layers project *and* flying actually decides a block. The
/// board carries an untapped ground Elf on each side, which is what makes the
/// block offer readable in both directions: the defending Elf is paired with
/// this seat's own ground attacker, and never with the Spirit — whose two
/// damage then lands on the player that Elf stands beside rather than being
/// soaked up. The keywords come off `characteristics()` because that is the
/// only reading that sees a granted one, and the combat is a turn later
/// because a creature cast this turn is sick (CR 302.6).
#[test]
#[allow(clippy::too_many_lines)] // one play, and both halves of the keyword line read off it
fn sky_spirit_flies_over_a_ground_creature_for_two_damage() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[plains(), island(), island(), quiet_creature()])
        .hand(0, &[sky_spirit()])
        .battlefield(1, &[quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The Elf is the ground creature the flight is measured against, so it is
    // named as the thing kept back: `tap_all_mana` presses every mana ability
    // whose whole price is its own `{T}` (#159), and a creature tapped for
    // mana may not attack afterwards.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "the three lands pay {{1}}{{W}}{{U}} and the Elf stays standing"
    );
    cast_with_floating(&mut engine, p0, sky_spirit());
    pass_until(&mut engine, stack_is_empty);

    let spirit = on_battlefield(&engine, p0, sky_spirit()).expect("the Spirit resolved");
    let my_elf = on_battlefield(&engine, p0, quiet_creature()).expect("my Elf is out");
    let their_elf = on_battlefield(&engine, p1, quiet_creature()).expect("their Elf is out");
    assert_eq!(pt(&engine, spirit), (2, 2), "the body the card prints");
    let granted = keywords(&engine, spirit);
    assert!(granted.contains(KeywordSet::FLYING), "Flying");
    assert!(granted.contains(KeywordSet::FIRST_STRIKE), "first strike");

    // CR 302.6: a creature cast this turn may not attack, so the combat the
    // keyword line is about is the next turn this seat takes.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&spirit) && attackers.contains(&my_elf),
        "both untapped creatures may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (spirit, Defender::Player(p1)),
                    (my_elf, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    // The rest of combat, one pending at a time. The defending seat's block
    // offer is where the flight lives, so it is asserted where it is asked
    // rather than inferred from a life total afterwards.
    for _ in 0..80 {
        if matches!(engine.state().turn.phase, Phase::Ending) {
            break;
        }
        match engine.pending().clone() {
            Pending::ChooseBlockers {
                player, blockers, ..
            } => {
                let ground = blockers
                    .iter()
                    .find(|option| option.blocker == their_elf)
                    .unwrap_or_else(|| panic!("the ground Elf may block something: {blockers:?}"));
                assert!(
                    ground.attackers.contains(&my_elf),
                    "the control: two ground 1/1s are a legal pairing: {ground:?}"
                );
                assert!(
                    !ground.attackers.contains(&spirit),
                    "\"Flying\" keeps the ground Elf off the flier: {ground:?}"
                );
                assert!(
                    blockers
                        .iter()
                        .all(|option| !option.attackers.contains(&spirit)),
                    "and no other blocker is paired with it either: {blockers:?}"
                );
                engine
                    .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
                    .expect("declaring no blockers is always legal");
            }
            Pending::Priority { player, .. } => {
                engine.apply(player, PlayerAction::PassPriority).unwrap();
            }
            Pending::ChooseAttackers { player, .. } => {
                engine
                    .apply(player, PlayerAction::DeclareAttackers { attackers: vec![] })
                    .unwrap();
            }
            other => panic!("unexpected while the flier's damage resolves: {other:?}"),
        }
    }

    assert_eq!(
        engine.state().players[1].life,
        17,
        "two from the Spirit and one from the ground Elf, and none of it blocked"
    );
    assert!(
        on_battlefield(&engine, p0, sky_spirit()).is_some(),
        "nothing could block the flier, so nothing dealt damage back to it"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_creature()).is_some(),
        "the Elf that was never paired with the flier is still standing"
    );
}

fn skyhunter_prowler() -> CardIndex {
    card_index("5e0d13b0-d5d0-4c5f-945e-5cda7d980670")
}

/// Skyhunter Prowler prints a 1/3 Cat Knight for {2}{W} whose whole text is
/// flying and vigilance. A body alone cannot show vigilance — "attacking
/// doesn't cause this creature to tap" is only readable by attacking with it
/// and finding it still standing afterwards — and flying needs a witness that
/// is not itself printed on the card, which is the ground Elf across the
/// table: a 1/1 with no flying and no reach is never offered as its blocker.
/// The one point of life p1 loses says the attack really connected, so the
/// untapped Prowler afterwards is vigilance and not a declaration that was
/// rolled back.
#[test]
fn skyhunter_prowler_attacks_without_tapping_and_flies_over_the_ground() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, plains())
        .battlefield(0, &[plains(), plains(), plains()])
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[skyhunter_prowler()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Three Plains pay {2}{W}, and the mana is tapped before the spell is
    // claimed as castable because `can_afford` reads the pool.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "nothing floats before the spell is paid for"
    );
    cast_from_hand(&mut engine, p0, skyhunter_prowler());
    pass_until(&mut engine, stack_is_empty);
    let prowler = on_battlefield(&engine, p0, skyhunter_prowler()).expect("the Prowler resolved");
    assert_eq!(pt(&engine, prowler), (1, 3), "a printed 1/3");
    let granted = keywords(&engine, prowler);
    assert!(
        granted.contains(KeywordSet::FLYING),
        "flying is printed on it"
    );
    assert!(
        granted.contains(KeywordSet::VIGILANCE),
        "and so is vigilance"
    );

    // Summoning sickness (CR 302.6) keeps it out of this turn's combat, so the
    // attack that reads the vigilance is a full turn cycle later — and by then
    // the Plains that paid for it have untapped with it.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(!is_tapped(&engine, prowler), "untapped and ready to attack");

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&prowler),
        "an untapped 1/3 flier may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(prowler, Defender::Player(p1))],
            },
        )
        .expect("the Prowler was one of the offered attackers");

    assert!(
        !is_tapped(&engine, prowler),
        "\"attacking doesn't cause this creature to tap\" — vigilance leaves it \
         standing the moment it is declared"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        unreachable!("the predicate just matched")
    };
    assert!(
        blockers
            .iter()
            .all(|option| !option.attackers.contains(&prowler)),
        "the Elf across the table has neither flying nor reach, so it is no \
         legal blocker for the Prowler: {blockers:?}"
    );
    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .expect("declaring no blockers is always legal");

    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        19,
        "the one point of combat damage got through, so the attack was real"
    );
    assert!(
        !is_tapped(&engine, prowler),
        "and it is still untapped after damage (CR 510.2), which is vigilance \
         and not an untap step that has come round"
    );
}

/// Skyhunter Skirmisher — {1}{W}{W}, a 1/1 Cat Knight printing flying and
/// double strike. Neither keyword is a number a card file can be checked
/// against: flying and double strike only mean anything once the layer
/// system has projected them onto a permanent that is actually in a game,
/// and double strike is only itself in a combat where a printed 1/1 takes
/// **two** life rather than one. So the Skirmisher is cast for its printed
/// cost, read off its projected characteristics, and then walked around a
/// whole turn — it is summoning sick the turn it arrives (CR 302.6) — to
/// attack past a ground 1/1 that could block any other 1/1 and may not block
/// this one.
fn skyhunter_skirmisher() -> CardIndex {
    card_index("0c07d09e-e127-4573-b827-6c50246f7a31")
}

#[test]
fn skyhunter_skirmisher_flies_and_strikes_twice_for_two_damage() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, plains())
        // {1}{W}{W}: three Plains, and nothing else on the board could pay a
        // white pip.
        .battlefield(0, &[plains(), plains(), plains()])
        .hand(0, &[skyhunter_skirmisher()])
        // A ground 1/1 across the table: it is what "flying" is about, since
        // it is a legal blocker for anything that is not a flier.
        .battlefield(1, &[quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");
    cast_from_hand(&mut engine, p0, skyhunter_skirmisher());
    pass_until(&mut engine, stack_is_empty);

    let knight = on_battlefield(&engine, p0, skyhunter_skirmisher())
        .expect("the Skirmisher resolved onto the battlefield");
    assert_eq!(pt(&engine, knight), (1, 1), "the printed 1/1 body");
    let projected = keywords(&engine, knight);
    assert!(
        projected.contains(KeywordSet::FLYING),
        "the printed flying reached the permanent through the layers"
    );
    assert!(
        projected.contains(KeywordSet::DOUBLE_STRIKE),
        "and so did double strike: {projected:?}"
    );

    // CR 302.6: a creature that entered this turn cannot attack, and this one
    // did. A whole turn cycle is what makes the attack below legal.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, knight),
        "nothing tapped it on the way round"
    );

    let life_before = engine.state().players[1].life;
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&knight),
        "an untapped, unsick Skirmisher may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(knight, Defender::Player(p1))],
            },
        )
        .unwrap();

    // The walk answers the blocker question with nobody blocking, and the
    // ground 1/1 across the table is not a pairing the engine could have
    // offered for a flier anyway. The end step is past both damage steps
    // (CR 510.2, CR 510.4).
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        life_before - 2,
        "a printed 1/1 with double strike deals its damage in the first-strike \
         step and again in the regular one: two life, where a single strike \
         would have taken one"
    );
    assert!(
        on_battlefield(&engine, p0, skyhunter_skirmisher()).is_some(),
        "the attacker took no damage back, because nothing blocked it"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_creature()).is_some(),
        "and the creature that could not block is untouched"
    );
}

fn skyknight_legionnaire() -> CardIndex {
    card_index("61178a6c-70b7-447d-87ee-a8d9369c3d15")
}

/// Skyknight Legionnaire prints one body and two words: `{1}{R}{W}` for a 2/2
/// Human Knight with flying and haste. Haste is the half a card file cannot
/// show, so it is read where the engine reads it — the attack declaration of
/// the very turn the creature arrived, which CR 302.6 would otherwise bar it
/// from — and flying is read in the blocking pairing, where the flyer across
/// the table is offered as a blocker and the ground creature beside it is not.
/// Mountain, Plains and Forest pay the `{R}`, the `{W}` and the generic, so
/// both coloured symbols are real payments, and the two damage that reach the
/// opponent are the printed 2/2.
#[test]
fn skyknight_legionnaire_flies_and_attacks_the_turn_it_lands() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), plains(), forest()])
        .hand(0, &[skyknight_legionnaire()])
        // The block question only exists if somebody may block, so the other
        // seat gets a flyer — the card under test, the one flying creature
        // these tests already name — beside a ground creature, which is the
        // half that flying is supposed to decline.
        .battlefield(1, &[skyknight_legionnaire(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    // Tolerant of the opponent's turn: it declares empty attackers, so no
    // creature across the table is tapped when the blocking step below asks.
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    cast_from_hand(&mut engine, p0, skyknight_legionnaire());
    pass_until(&mut engine, stack_is_empty);
    let knight = on_battlefield(&engine, p0, skyknight_legionnaire())
        .expect("the Legionnaire resolved onto the battlefield");
    assert_eq!(pt(&engine, knight), (2, 2), "the body the card prints");
    let printed = keywords(&engine, knight);
    assert!(printed.contains(KeywordSet::FLYING), "flying");
    assert!(printed.contains(KeywordSet::HASTE), "and haste");

    // CR 302.6: a creature that arrived this turn may not attack unless
    // something gives it haste, so a Legionnaire missing from this offer is
    // the keyword never having reached the permanent.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert!(
        attackers.contains(&knight),
        "haste: it arrived this turn and the combat step still offers it: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(knight, Defender::Player(p1))],
            },
        )
        .unwrap();

    // Flying, read in the pairing rather than in the keyword alone.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers {
        player, blockers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the block declaration")
    };
    assert_eq!(player, p1, "the seat being attacked declares the blockers");
    let their_flyer = on_battlefield(&engine, p1, skyknight_legionnaire())
        .expect("their Legionnaire is on the battlefield");
    let their_ground =
        on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are on the battlefield");
    assert!(
        blockers
            .iter()
            .any(|option| option.blocker == their_flyer && option.attackers.contains(&knight)),
        "a creature that flies may block one: {blockers:?}"
    );
    assert!(
        !blockers
            .iter()
            .any(|option| option.blocker == their_ground && option.attackers.contains(&knight)),
        "CR 702.9b: neither flying nor reach, so it may not block a flying \
         attacker: {blockers:?}"
    );
    engine
        .apply(player, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();

    // Past the damage step (CR 510.2). `stack_is_empty` is already true the
    // moment attackers are declared, so the ending phase is what the life
    // total below needs.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        18,
        "two unblocked damage, which is the power the card prints"
    );
}

fn smokespew_invoker() -> CardIndex {
    card_index("a6df9679-1e4c-4791-855b-28bc2fa35b49")
}

/// Smokespew Invoker is a {2}{B} 3/1 Zombie Mutant whose entire rules text is
/// "{7}{B}: Target creature gets -3/-3 until end of turn."
///
/// Both numbers are the engine's answers rather than the card's, so the board
/// is built to make each one legible in a different place. Eleven Swamps tapped
/// in one go pay the {2}{B} and leave exactly the eight the ability charges,
/// read off the pool before the claim — `legal.abilities` is filtered through
/// `can_afford`, and that reads the pool and not the untapped lands. The pump
/// is then measured as a three-point drop on a creature that survives it, with
/// the Elf under the same seat as the control that says the -3/-3 landed only
/// where it was aimed.
#[test]
fn smokespew_invoker_pays_eight_for_minus_three_on_the_creature_it_names() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    // Eleven Swamps: enough to cast the Invoker for {2}{B} and still hold the
    // whole {7}{B} the ability asks for, since a pool survives the step it was
    // filled in (CR 500.5) and this scenario never leaves the main phase.
    let mut board = vec![swamp(); 11];
    board.push(quiet_creature());
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &board)
        // The creature "target creature" has to reach, and reaching it must not
        // be a creature of yours by accident.
        .battlefield(1, &[rootbreaker_wurm()])
        .hand(0, &[smokespew_invoker()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let elf = on_battlefield(&engine, p0, quiet_creature()).expect("the Elf is out");
    let wurm = on_battlefield(&engine, p1, rootbreaker_wurm()).expect("the Wurm is out");

    // The Elf is named as the one source kept back: it prints its own
    // `{T}: Add {G}`, so `tap_all_mana` would have spent it and left a green
    // mana in a pool every assertion below reads as black and nothing else.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        11,
        "eleven Swamps tapped, and the Elf left standing"
    );

    cast_with_floating(&mut engine, p0, smokespew_invoker());
    pass_until(&mut engine, stack_is_empty);
    let invoker = on_battlefield(&engine, p0, smokespew_invoker()).expect("the Invoker resolved");
    assert_eq!(pt(&engine, invoker), (3, 1), "the printed 3/1 body arrived");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        8,
        "{{2}}{{B}} is spent and exactly the {{7}}{{B}} the ability charges is still floating"
    );

    let before = pt(&engine, wurm);
    assert!(
        before.1 > 3,
        "the target has to survive the pump for its body to be read back: {before:?}"
    );

    // Ability 0 is the only line the card prints, and it is pressed with the
    // mana already floating: the offer is read off the pool.
    activate(&mut engine, p0, smokespew_invoker(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&wurm) && options.contains(&elf),
        "\"target creature\" reaches across the table and does not stop at your own: {options:?}"
    );
    // CR 601.2c names the target first and CR 601.2h pays last, so the mana is
    // still in the pool and the ability nowhere near the stack.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        8,
        "the cost is the last step of the activation"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![wurm],
            },
        )
        .expect("the Wurm was one of the options the question enumerated");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "{{7}}{{B}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "and the pump is waiting on the stack"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, wurm),
        (before.0 - 3, before.1 - 3),
        "-3/-3 until end of turn on the creature the ability named"
    );
    assert_eq!(
        pt(&engine, elf),
        (1, 1),
        "the creature it did not name is untouched"
    );
}

fn soratami_rainshaper() -> CardIndex {
    card_index("63c5f42b-13d0-4391-b033-4ab2f4e3152b")
}

/// Soratami Rainshaper — {2}{U}, a 2/1 Moonfolk Wizard with flying — prints
/// "{3}, Return a land you control to its owner's hand: Target creature you
/// control gains shroud until end of turn."
///
/// The price lands in two different places, so both halves are read off the
/// state after the target question has been answered (CR 601.2c before
/// CR 601.2h): the {3} leaves the pool the four Islands filled, and one of
/// those Islands — **tapped**, because four tapped Islands are still "a land
/// you control" and the card prints no "untapped" — goes back to hand while
/// the land count falls by one.
///
/// The targeting half is read against an Elf across the table, which a bare
/// "target creature" would have offered and "you control" refuses, and the
/// grant is read off the layers: the chosen Elf has shroud, the Shaper that
/// granted it does not, and the Elf nobody named never gets it.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn soratami_rainshaper_returns_a_tapped_land_to_give_a_creature_shroud() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                island(),
                island(),
                island(),
                island(),
                soratami_rainshaper(),
                quiet_creature(),
            ],
        )
        .battlefield(1, &[quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let shaper =
        on_battlefield(&engine, p0, soratami_rainshaper()).expect("the Rainshaper is on the table");
    let mine =
        on_battlefield(&engine, p0, quiet_creature()).expect("a creature this seat controls");
    let theirs =
        on_battlefield(&engine, p1, quiet_creature()).expect("a creature across the table");
    assert_eq!(pt(&engine, shaper), (2, 1), "the body the card prints");
    assert!(
        keywords(&engine, shaper).contains(KeywordSet::FLYING),
        "and the flying it prints"
    );
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::SHROUD),
        "nothing has been granted yet"
    );
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();
    assert_eq!(lands_of(&engine, p0).len(), 4, "four Islands to give up");

    // Four Islands, and the Elf named as the one source kept back: its own
    // `{T}: Add {G}` is a mana ability whose whole price is its tap (#159),
    // and it is the creature this ability is about to aim at.
    tap_all_mana_but(&mut engine, p0, Some(quiet_creature()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Islands and nothing off the Elf"
    );
    assert!(!is_tapped(&engine, mine), "which the mana never touched");

    activate(&mut engine, p0, soratami_rainshaper(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature you control\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "one creature, no more and no fewer");
    assert!(
        options.contains(&mine),
        "the creature this seat controls is on the menu: {options:?}"
    );
    assert!(
        !options.contains(&theirs),
        "\"creature *you* control\" declines the Elf across the table: {options:?}"
    );
    // CR 601.2c names the target before CR 601.2h pays anything: while this
    // question stands, the mana is still floating and every Island is still
    // on the battlefield.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "the price is paid after the target, not before it"
    );
    assert_eq!(
        lands_of(&engine, p0).len(),
        4,
        "and no land has left the battlefield yet"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("the creature the question offered was chosen");

    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!("the cost asks which land, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        crate::choice::ChoicePrompt::CostReturn,
        "a land given up to pay, and not a search and not a tap"
    );
    assert_eq!((min, max), (1, 1), "one land, no more and no fewer");
    let my_lands = lands_of(&engine, p0);
    for land in &my_lands {
        assert!(
            options.contains(land),
            "a *tapped* land you control is still a land you control — the \
             card prints no \"untapped\", so {land:?} belongs on this menu: \
             {options:?}"
        );
    }
    for offered in &options {
        assert!(
            my_lands.contains(offered),
            "\"a land you control\" is a land and not a creature or an \
             artifact: {offered:?} is none of the {my_lands:?}"
        );
    }

    let given_up = options[0];
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![given_up],
            },
        )
        .expect("the land the question offered pays the cost");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{3}} came out of the pool the four Islands filled"
    );
    assert_eq!(
        lands_of(&engine, p0).len(),
        3,
        "exactly one land was given up: the other three are still standing"
    );
    assert!(
        in_hand(&engine, p0, island()).is_some(),
        "\"to its owner's hand\": the land is a card in the hand of the seat \
         that controlled it"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before + 1,
        "one card up, so a land that merely vanished would not satisfy the \
         claim above"
    );

    assert!(
        keywords(&engine, mine).contains(KeywordSet::SHROUD),
        "the creature the question offered gained shroud"
    );
    assert!(
        !keywords(&engine, shaper).contains(KeywordSet::SHROUD),
        "the Shaper grants the keyword and does not keep it"
    );
    assert!(
        !keywords(&engine, theirs).contains(KeywordSet::SHROUD),
        "and the Elf the ability declined to target never got it"
    );

    // "until end of turn": one turn cycle is enough for the grant to lapse,
    // which is what tells the printed duration from a permanent one.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !keywords(&engine, mine).contains(KeywordSet::SHROUD),
        "the shroud is gone by the caster's next main phase"
    );
}

fn soulsworn_jury() -> CardIndex {
    card_index("06424141-2c26-4ee8-83c2-dac62e3d3540")
}

/// Soulsworn Jury — {2}{W} — a 1/4 Spirit with defender whose second line is
/// "{1}{U}, Sacrifice this creature: Counter target creature spell."
///
/// A creature spell exists only between the announcement and its resolution,
/// so the board has to hold one mid-flight: p1 casts a Llanowar Elves and
/// passes, which is the only window in which the Jury's ability has a legal
/// target at all. Two Islands pay the {1}{U} and the printed sacrifice is read
/// where it lands — the Jury is still standing while the target question is
/// open (CR 601.2c before 601.2h) and in its owner's graveyard once the answer
/// is given — while the Elves go from the stack to a graveyard without ever
/// becoming a creature.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn soulsworn_jury_sacrifices_itself_to_counter_a_creature_spell() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[soulsworn_jury(), island(), island()])
        .battlefield(1, &[forest()])
        .hand(1, &[llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);

    let jury = on_battlefield(&engine, p0, soulsworn_jury()).expect("the Jury is deployed");
    assert_eq!(pt(&engine, jury), (1, 4), "the body the card prints");
    assert!(
        keywords(&engine, jury).contains(KeywordSet::DEFENDER),
        "and the defender that keeps it out of combat"
    );

    // p1's own main phase: a creature spell needs a sorcery-speed window, and
    // the seat that is not casting it is the one that has to answer.
    reach_their_main_phase(&mut engine, p1);
    cast_from_hand(&mut engine, p1, llanowar_elves());
    assert!(
        on_stack(&engine, llanowar_elves()).is_some(),
        "the Elves are a spell on the stack, not yet a creature: {:?}",
        engine.pending()
    );
    // The caster holds priority after casting, so the walk passes until the
    // response window belongs to p0 and the spell is still in flight.
    pass_until(&mut engine, |e| {
        on_stack(e, llanowar_elves()).is_some()
            && matches!(e.pending(), Pending::Priority { player, .. } if *player == p0)
    });

    // Mana before the claim: `can_afford` reads the pool and not the untapped
    // Islands.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        2,
        "two Islands, two blue"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(jury, 0)),
        "{{1}}{{U}} and the sacrifice are payable, so the one line the card \
         prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, soulsworn_jury(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"counter target creature spell\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    let elves = on_stack(&engine, llanowar_elves()).expect("the spell is still on the stack");
    assert!(
        options.contains(&elves),
        "the creature spell mid-flight is the whole of the offer: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p0, soulsworn_jury()).is_some(),
        "targets are chosen before costs are paid (CR 601.2c, then CR 601.2h)"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "and the {{1}}{{U}} is still in the pool for the same reason"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .expect("the spell the question named was one of the options");

    assert!(
        on_battlefield(&engine, p0, soulsworn_jury()).is_none(),
        "\"Sacrifice this creature\" is paid as the ability is announced"
    );
    assert!(
        in_graveyard(&engine, p0, soulsworn_jury()).is_some(),
        "and the Jury is in its owner's graveyard"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "the {{1}}{{U}} came out of the pool"
    );
    assert!(
        on_stack(&engine, llanowar_elves()).is_some(),
        "the counter has not resolved yet: the spell is still on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, llanowar_elves()).is_none(),
        "a countered creature spell never becomes a creature"
    );
    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "it goes to the graveyard of the seat that cast it"
    );
}

fn stalking_assassin() -> CardIndex {
    card_index("12117089-67f7-4d0e-88db-82b27a4c7cdc")
}

/// Stalking Assassin — {1}{U}{B} for a 1/1 Human Assassin whose whole card is
/// two activated abilities: "{3}{U}, {T}: Tap target creature" and
/// "{3}{B}, {T}: Destroy target tapped creature."
///
/// One Assassin can pay its own tap symbol only once a turn, so the board
/// carries two of them — and that is what makes the printed word "tapped"
/// readable from both sides at once: the black half offers the Elf the blue
/// half has just tapped *and* the spent Assassin standing beside it, while
/// declining the Elf left untapped across the table and the Assassin that has
/// not paid its {T} yet. None of that is in the card file; the filter and the
/// four-mana prices are the engine's answers, and the empty-pool read before
/// the mana says those prices are real rather than labels.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn stalking_assassin_taps_a_creature_and_then_destroys_it_with_the_other_half() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                island(),
                island(),
                island(),
                island(),
                swamp(),
                swamp(),
                swamp(),
                swamp(),
                stalking_assassin(),
                stalking_assassin(),
            ],
        )
        .battlefield(1, &[quiet_creature(), quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let assassins = all_on_battlefield(&engine, p0, stalking_assassin());
    assert_eq!(assassins.len(), 2, "one Assassin per printed line");
    let (tap_half, kill_half) = (assassins[0], assassins[1]);
    let elves = all_on_battlefield(&engine, p1, quiet_creature());
    assert_eq!(elves.len(), 2, "one Elf to be tapped, one to be left alone");
    let (doomed, bystander) = (elves[0], elves[1]);

    // CR 601.2h read from the other side: `legal.abilities` is filtered
    // through `can_afford`, and that reads the mana pool rather than the
    // untapped lands — so on an empty pool neither price is offered at all.
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the seat with the Assassins holds it");
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == tap_half),
        "eight lands stand untapped and not one mana floats, so nothing is \
         offered: {:?}",
        legal.abilities
    );

    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        8,
        "four Islands and four Swamps, and no creature on this board makes mana"
    );

    // The blue half: {3}{U}, {T}: Tap target creature.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    let (source, ability_index) = legal
        .abilities
        .iter()
        .copied()
        .find(|(src, index)| *src == tap_half && *index == 0)
        .expect("{3}{U} is four of the eight floating, so ability 0 is offered");
    engine
        .apply(
            p0,
            PlayerAction::ActivateAbility {
                source,
                ability_index,
            },
        )
        .expect("the cost is payable out of the pool");

    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert_eq!((min, max), (1, 1), "exactly one creature");
    assert!(
        player_options.is_empty(),
        "\"target creature\" names no player: {player_options:?}"
    );
    for creature in [doomed, bystander, tap_half, kill_half] {
        assert!(
            options.contains(&creature),
            "\"target creature\" is any creature, tapped or not and on either \
             side of the table: {options:?}"
        );
    }

    // CR 601.2c picks the target and CR 601.2h pays afterwards, so while this
    // question stands the mana is still floating and the Assassin is untapped.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        8,
        "the cost is the last step of the activation"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![doomed],
            },
        )
        .expect("the Elf was one of the options it enumerated");
    assert!(is_tapped(&engine, tap_half), "{{T}} is half the price");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "and the {{3}}{{U}} came out of the pool"
    );

    pass_until(&mut engine, |e| at_rest(e, p0));
    assert!(
        is_tapped(&engine, doomed),
        "the targeted creature is tapped"
    );
    assert!(
        !is_tapped(&engine, bystander),
        "and the creature nobody named never moved"
    );

    // The black half: {3}{B}, {T}: Destroy target tapped creature.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "the {{3}}{{B}} is still floating in this same main phase (CR 500.5)"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.iter().any(|(src, _)| *src == tap_half),
        "the Assassin that already spent its {{T}} has none left to pay with: {:?}",
        legal.abilities
    );
    let (source, ability_index) = legal
        .abilities
        .iter()
        .copied()
        .find(|(src, index)| *src == kill_half && *index == 1)
        .expect("{3}{B} is four of the four left, so ability 1 is offered");
    engine
        .apply(
            p0,
            PlayerAction::ActivateAbility {
                source,
                ability_index,
            },
        )
        .expect("the cost is payable out of the pool");

    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target tapped creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&doomed),
        "the Elf the blue half just tapped is the card's own play: {options:?}"
    );
    assert!(
        options.contains(&tap_half),
        "\"target tapped creature\" is not \"a creature an opponent controls\": \
         the spent Assassin is tapped too: {options:?}"
    );
    assert!(
        !options.contains(&bystander),
        "the Elf standing untapped beside it is no legal target: {options:?}"
    );
    assert!(
        !options.contains(&kill_half),
        "and neither is the Assassin about to pay the {{3}}{{B}}, which is \
         still untapped: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![doomed],
            },
        )
        .expect("the tapped Elf was one of the options it enumerated");
    assert!(
        is_tapped(&engine, kill_half),
        "{{T}} is paid by the Assassin that activated the ability"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{3}}{{B}} came out of the pool"
    );

    pass_until(&mut engine, |e| at_rest(e, p0));
    assert!(
        in_graveyard(&engine, p1, quiet_creature()).is_some(),
        "\"Destroy target tapped creature\": the Elf is in its owner's graveyard"
    );
    assert_eq!(
        all_on_battlefield(&engine, p1, quiet_creature()).len(),
        1,
        "and only the creature that was named: the bystander still stands"
    );
    assert_eq!(
        all_on_battlefield(&engine, p0, stalking_assassin()).len(),
        2,
        "neither Assassin was its own target"
    );
}

fn standing_troops() -> CardIndex {
    card_index("9e9d5242-424d-4f61-b625-806295dbb0c7")
}

/// Standing Troops is a {2}{W} 1/4 Human Soldier whose whole printed text is
/// "Vigilance", so the one thing a board can hold it to is what the keyword
/// does: attacking does not tap it (CR 702.20b).
///
/// A lone attacker proves nothing — "the Troops is still untapped" is
/// satisfied just as well by a combat step that taps nobody — so the seat
/// attacks with a Llanowar Elves beside it, a creature with no keyword to keep
/// it standing. One declaration, two answers: the Elves is tapped by attacking
/// (CR 508.1f) and the Troops is not, and both are read a second time after the
/// damage step has been and gone so that neither reading is taken mid-step.
#[test]
fn standing_troops_attacks_without_tapping_because_of_vigilance() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[standing_troops(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches its own first main phase"
    );

    let troops = on_battlefield(&engine, p0, standing_troops()).expect("the Troops are seated");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are seated");
    assert_eq!(pt(&engine, troops), (1, 4), "the body the card prints");
    assert!(
        keywords(&engine, troops).contains(KeywordSet::VIGILANCE),
        "the printed keyword reaches the permanent through the layers"
    );
    assert!(
        !keywords(&engine, elves).contains(KeywordSet::VIGILANCE),
        "and it is the Troops' own word: nothing on this board grants it"
    );
    assert!(
        !is_tapped(&engine, troops) && !is_tapped(&engine, elves),
        "both stand untapped before anything is declared"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player,
        attackers,
        defenders,
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert_eq!(player, p0, "the active seat declares its own attackers");
    assert!(
        attackers.contains(&troops) && attackers.contains(&elves),
        "two untapped, unsick creatures with no demand on them are offered: {attackers:?}"
    );
    assert!(
        defenders.contains(&Defender::Player(p1)),
        "and the opponent is what may be attacked: {defenders:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![
                    (troops, Defender::Player(p1)),
                    (elves, Defender::Player(p1)),
                ],
            },
        )
        .unwrap();

    assert!(
        !is_tapped(&engine, troops),
        "CR 702.20b: the declaration tapped everything it attacked with except \
         the creature that has vigilance"
    );
    assert!(
        is_tapped(&engine, elves),
        "and CR 508.1f is what tapped that one: the very same declaration"
    );

    // Past the damage step, so the attack really happened rather than being
    // rolled back, and the standing Troops is still standing.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        18,
        "two unblocked attackers dealt 1 + 1 combat damage (CR 510.2)"
    );
    assert!(
        !is_tapped(&engine, troops) && is_tapped(&engine, elves),
        "and the tap states outlive the combat they were set in"
    );
}

fn storm_shaman() -> CardIndex {
    card_index("65e07c0f-4eff-4b38-9785-63684d67c0d8")
}

/// Storm Shaman — {2}{R}, a printed 0/4 whose whole text is one line:
/// "{R}: This creature gets +1/+0 until end of turn."
///
/// Two Mountains are the entire cost of both activations and the pool is read
/// *after* they are tapped, because `legal.abilities` is filtered through
/// `can_afford`, which reads the pool and not the untapped lands — the pool
/// is empty once the second activation resolves, so `(2, 4)` can only have
/// been bought rather than assumed. The Raptor beside it is the control for
/// the word "This": a pump whose filter had widened would read the same in the
/// card file and a different number on this board, where the bystander stays a
/// printed 1/1. The walk into the opponent's turn is the "until end of turn",
/// read where it cannot be mistaken for a pump that never landed.
#[test]
fn storm_shaman_pays_one_red_to_pump_only_itself_until_end_of_turn() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[mountain(), mountain(), storm_shaman(), umara_raptor()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let shaman = on_battlefield(&engine, p0, storm_shaman()).expect("the Shaman is on the table");
    let bystander =
        on_battlefield(&engine, p0, umara_raptor()).expect("the Raptor is on the table");
    assert_eq!(pt(&engine, shaman), (0, 4), "the body the card prints");
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "and a creature the pump must not reach"
    );

    // Mana before the claim. Two Mountains are the only mana sources on this
    // board, so a pool of two is also the exact number of activations the
    // card's {R} can be paid for today.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "two Mountains, two red, and nothing else that could have made mana"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(shaman, 0)),
        "with {{R}} floating, the only line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, storm_shaman(), 0);
    assert!(
        matches!(drive_to_rest(&mut engine, p0), Rest::Reached),
        "one activation resolves and the activating seat is back at a quiet priority"
    );
    assert_eq!(
        pt(&engine, shaman),
        (1, 4),
        "+1/+0 until end of turn: the power moves and the toughness does not"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{R}} came out of the pool the Mountains filled"
    );

    activate(&mut engine, p0, storm_shaman(), 0);
    assert!(
        matches!(drive_to_rest(&mut engine, p0), Rest::Reached),
        "a second activation is paid out of the same pool"
    );
    assert_eq!(
        pt(&engine, shaman),
        (2, 4),
        "two activations are two +1/+0s: the pump stacks instead of replacing itself"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and both Mountains were spent on it"
    );
    assert_eq!(
        pt(&engine, bystander),
        (1, 1),
        "\"This creature\" — the pump lands on the Shaman and on no creature beside it"
    );

    // The other side of the same price: with the pool empty and both
    // Mountains tapped there is nothing left to pay it with, and the ability
    // is absent from the offer rather than listed and then refused.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        !legal.abilities.contains(&(shaman, 0)),
        "an unpayable {{R}} is not an option to take: {:?}",
        legal.abilities
    );

    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, shaman),
        (0, 4),
        "\"until end of turn\": the pump was gone by the time the next turn began"
    );
}

fn stronghold_machinist() -> CardIndex {
    card_index("50bbbb39-4709-478f-bb51-716c7e4f8323")
}

/// Stronghold Machinist — {2}{U}, 1/1 Human Spellshaper: "{U}{U}, {T},
/// Discard a card: Counter target noncreature spell."
///
/// The scenario pays all three parts of that price, each of which leaves a
/// mark somewhere else: the {U}{U} out of a pool two Islands actually filled,
/// the tap symbol off the creature itself, and the discarded card in its
/// owner's graveyard. The spell being countered is a Dark Ritual that is
/// really on the stack — cast for real, so the counter has something to aim
/// at — and the proof it died there is that its controller's pool never
/// grows by the three black it would have made.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn stronghold_machinist_discards_a_card_to_counter_a_noncreature_spell() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[island(), island(), stronghold_machinist()])
        // The price the Spellshaper pays in cards: a printing that stands
        // nowhere else on the board, so the graveyard entry below can only be
        // this discard.
        .hand(0, &[llanowar_elves()])
        .battlefield(1, &[swamp()])
        .hand(1, &[dark_ritual()])
        .start();
    keep_mulligans(&mut engine);
    reach_their_main_phase(&mut engine, p1);

    // The spell that is about to be countered, cast for real: an instant with
    // no target of its own (CR 601.2c asks nothing), paid by the one Swamp.
    tap_all_mana(&mut engine, p1);
    cast_with_floating(&mut engine, p1, dark_ritual());

    // p1's own priority passes to p0 with the Ritual still on the stack, which
    // is the window a counterspell exists for.
    pass_until(&mut engine, |e| {
        on_stack(e, dark_ritual()).is_some()
            && matches!(e.pending(), Pending::Priority { player, .. } if *player == p0)
    });
    let ritual = on_stack(&engine, dark_ritual()).expect("the Ritual is on the stack");
    let machinist =
        on_battlefield(&engine, p0, stronghold_machinist()).expect("the Machinist is out");

    // Mana before the claim: `legal.abilities` is filtered through
    // `can_afford`, which reads the pool and not the untapped Islands.
    tap_all_mana_but(&mut engine, p0, Some(stronghold_machinist()));
    assert_eq!(
        engine.state().players[0]
            .mana_pool
            .available(ManaColor::Blue),
        2,
        "two Islands tapped, and the Machinist makes no mana of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(machinist, 0)),
        "the one line the card prints, now that {{U}}{{U}} is in the pool: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, stronghold_machinist(), 0);

    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target noncreature spell\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&ritual),
        "the Ritual is the noncreature spell on the stack: {options:?}"
    );
    // CR 601.2c picks the target and CR 601.2h pays afterwards, so while this
    // question stands nothing at all has been given up.
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        2,
        "the {{U}}{{U}} is still floating"
    );
    assert!(
        !is_tapped(&engine, machinist),
        "and the Machinist is still standing"
    );
    assert!(
        in_hand(&engine, p0, llanowar_elves()).is_some(),
        "and the card to discard is still in hand"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![ritual],
            },
        )
        .expect("the spell the question offered is a legal target");

    // The card is the last part of the price, and it is asked off the hand.
    let Pending::ChooseCards {
        player,
        options,
        min,
        max,
        prompt,
    } = engine.pending().clone()
    else {
        panic!(
            "the discard is a cost and is asked before it is paid: {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat answers its own cost");
    assert_eq!(
        prompt,
        ChoicePrompt::CostDiscard,
        "a cost and not a cleanup, which is all a client has to tell the two apart"
    );
    assert_eq!((min, max), (1, 1), "one card, no more and no fewer");
    let fodder = in_hand(&engine, p0, llanowar_elves()).expect("the card to discard is in hand");
    assert!(
        options.contains(&fodder),
        "any card in hand pays a `Discard a card` price: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![fodder],
            },
        )
        .expect("the card the question offered pays the cost");

    assert!(
        is_tapped(&engine, machinist),
        "{{T}} was the second half of the price"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{U}}{{U}} the third"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_stack(&engine, dark_ritual()).is_none(),
        "the Ritual left the stack"
    );
    assert!(
        in_graveyard(&engine, p1, dark_ritual()).is_some(),
        "a countered spell goes to its owner's graveyard (CR 701.5a)"
    );
    assert_eq!(
        engine.state().players[1].mana_pool.total(),
        0,
        "and it never resolved: the three black it would have made are not there"
    );
    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "the discarded card is in its owner's graveyard"
    );
}

fn taoist_hermit() -> CardIndex {
    card_index("960b1251-12af-4766-8df1-bb98e7e967f5")
}

/// Taoist Hermit — {2}{G} 2/2 Human Mystic with hexproof (CR 702.11b):
/// "This creature can't be the target of spells or abilities your
/// opponents control."
///
/// Hexproof is half a rule and the board plays both halves in one game. The
/// Hermit has to be a legal target for its *own* controller's Giant Growth —
/// the +3/+3 is read straight off the projected body afterwards — while the
/// opponent's Vindicate, cast in their own main phase, has to offer the
/// Llanowar Elves standing beside it and refuse the Hermit. The Elves is the
/// control that keeps the refusal from being an empty menu: same controller,
/// same card type, no hexproof, so a menu that reached it and not the Hermit
/// is the keyword's doing and not a broken offer.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn taoist_hermit_is_its_own_controllers_target_and_never_the_opponents() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[forest(), forest(), forest(), forest(), llanowar_elves()],
        )
        .hand(0, &[taoist_hermit(), giant_growth()])
        // Exactly the {1}{W}{B} the Vindicate charges: two Plains and a Swamp.
        .battlefield(1, &[plains(), plains(), swamp()])
        .hand(1, &[vindicate()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Four Forests pay the Hermit's {2}{G} and leave the {G} the Giant Growth
    // is about to charge. The Elves is named as the printing kept back: it is
    // the creature the opponent's removal is read against, and a mana creature
    // tapped for the Hermit would be a target that had already moved for a
    // reason of its own.
    tap_all_mana_but(&mut engine, p0, Some(llanowar_elves()));
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        4,
        "four Forests, and the Elves' own {{T}} left alone"
    );
    cast_with_floating(&mut engine, p0, taoist_hermit());
    pass_until(&mut engine, |e| at_rest(e, p0));

    let hermit = on_battlefield(&engine, p0, taoist_hermit()).expect("the Hermit resolved");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");
    assert_eq!(pt(&engine, hermit), (2, 2), "the body the card prints");
    assert!(
        keywords(&engine, hermit).contains(KeywordSet::HEXPROOF),
        "the printed keyword reaches the permanent through the layers"
    );

    // The half that is the controller's: hexproof is the *opponents'* word,
    // so p0's own spell may still name it (CR 702.11b).
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        1,
        "the {{2}}{{G}} is spent and the Giant Growth's {{G}} is still floating"
    );
    cast_with_floating(&mut engine, p0, giant_growth());
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the seat that cast it aims it");
    assert!(
        options.contains(&hermit),
        "its own controller's spell is still allowed to name it: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![hermit],
            },
        )
        .expect("the Hermit was one of the options the spell enumerated");
    pass_until(&mut engine, |e| at_rest(e, p0));
    assert_eq!(
        pt(&engine, hermit),
        (5, 5),
        "the pump resolved, so the offer was a real target and not a filtered one"
    );

    // The other side of the table, and the same spell pointed at a creature
    // with no keyword on it at all.
    reach_their_main_phase(&mut engine, p1);
    cast_from_hand(&mut engine, p1, vindicate());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p1, "the opponent aims their own removal");
    assert!(
        options.contains(&elves),
        "the creature beside it is the control — same controller, same card \
         type, no hexproof — so the offer does reach this seat's board: {options:?}"
    );
    assert!(
        !options.contains(&hermit),
        "\"target permanent\" is every permanent on the table except the one \
         hexproof refuses an opponent: {options:?}"
    );

    engine
        .apply(
            p1,
            PlayerAction::ChooseObjects {
                objects: vec![elves],
            },
        )
        .expect("an option the offer enumerated");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p0, llanowar_elves()).is_some(),
        "the removal resolved against the target it was allowed"
    );
    assert!(
        on_battlefield(&engine, p0, taoist_hermit()).is_some(),
        "and the hexproof creature is exactly where it was"
    );
}

fn tempest_drake() -> CardIndex {
    card_index("ff0086e0-706f-4474-9b5e-a1591235bf9b")
}

/// Tempest Drake — `{1}{W}{U}` — a 2/2 Drake with flying and vigilance, and
/// both keywords are claims about combat rather than about the card file. So
/// the drake is cast and walked into an attack on its controller's *next*
/// turn, beside a grounded Elf, against a board holding a grounded Elf and a
/// flier: the defending Elf is offered as a blocker for the grounded attacker
/// and never for the drake (CR 702.9b), and the drake alone is still untapped
/// after the declaration that tapped its companion (CR 702.14b). Flying is
/// read as a *pairing* and vigilance against a creature that lacks it,
/// because either assertion on its own is satisfied by a board that never
/// asked the question.
#[test]
fn tempest_drake_flies_over_a_ground_creature_and_attacks_without_tapping() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), island(), llanowar_elves()])
        .hand(0, &[tempest_drake()])
        // Their grounded Elf is what keeps the flying claim from being empty;
        // their Strix is the one creature that may legally block a flier.
        .battlefield(1, &[llanowar_elves(), baleful_strix()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, tempest_drake());
    pass_until(&mut engine, stack_is_empty);
    let drake = on_battlefield(&engine, p0, tempest_drake()).expect("the Drake resolved");
    assert_eq!(pt(&engine, drake), (2, 2), "the printed 2/2 body");
    let kw = keywords(&engine, drake);
    assert!(
        kw.contains(KeywordSet::FLYING),
        "Flying reaches the permanent"
    );
    assert!(kw.contains(KeywordSet::VIGILANCE), "and so does vigilance");

    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elf is out");

    // A creature cast this turn is summoning sick (CR 302.6), so the attack
    // waits for its controller's next turn.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(drake, Defender::Player(p1)), (elf, Defender::Player(p1))],
            },
        )
        .expect("both untapped creatures may attack");

    // Vigilance is read against a creature that lacks it: the Elf beside the
    // drake is tapped by the very declaration that left the drake standing.
    assert!(
        !is_tapped(&engine, drake),
        "\"vigilance\": attacking does not tap the drake (CR 702.14b)"
    );
    assert!(
        is_tapped(&engine, elf),
        "while the grounded attacker beside it paid the usual price"
    );

    // Flying is legible in the pairing the defender is offered (CR 702.9b)
    // — after the priority round CR 508.2 hands out, which is why the block
    // is not the pending the declaration left behind.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseBlockers { .. })
    });
    let Pending::ChooseBlockers { blockers, .. } = engine.pending().clone() else {
        panic!(
            "a flier may block, so the declaration happens: {:?}",
            engine.pending()
        )
    };
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("their Strix is out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    assert!(
        blockers
            .iter()
            .any(|o| o.blocker == strix && o.attackers.contains(&drake)),
        "a creature with flying may block the drake: {blockers:?}"
    );
    assert!(
        !blockers
            .iter()
            .any(|o| o.blocker == theirs && o.attackers.contains(&drake)),
        "and the grounded Elf may not: {blockers:?}"
    );
    assert!(
        blockers
            .iter()
            .any(|o| o.blocker == theirs && o.attackers.contains(&elf)),
        "the same Elf is offered against the grounded attacker, so the \
         exclusion above is about flying and not about a creature that can \
         block nothing at all: {blockers:?}"
    );

    engine
        .apply(p1, PlayerAction::DeclareBlockers { blockers: vec![] })
        .unwrap();
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending)
    });
    assert_eq!(
        engine.state().players[1].life,
        17,
        "2 + 1 went through unblocked: nothing turned the flying half aside"
    );
    assert_eq!(pt(&engine, drake), (2, 2), "and the body is untouched");
}

fn temporal_adept() -> CardIndex {
    card_index("fd9b5462-6578-4bf6-8026-23eaf5af3eee")
}

/// Temporal Adept — {1}{U}{U} 1/1 Human Wizard: "{U}{U}{U}, {T}: Return
/// target permanent to its owner's hand."
///
/// "Target permanent" is the widest target any card prints, and the only way
/// to read it is to offer it a board with a permanent on each side and of
/// each kind: the opponent's Sol Ring and Forest are on the menu and so is
/// this seat's own Island, which is what tells `Filter::Any` from a filter
/// quietly narrowed to one side. The Sol Ring is the target, because the
/// destination is half the sentence — it has to reach the hand of the seat
/// that *owns* it and not the seat that aimed the bounce — and the Adept's
/// own {T} plus the three blue out of the pool are read after the answer,
/// since CR 601.2c names the target before CR 601.2h pays.
#[test]
fn temporal_adept_bounces_any_permanent_to_its_owners_hand() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[temporal_adept(), island(), island(), island()])
        .battlefield(1, &[quiet_artifact(), forest()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    let adept = on_battlefield(&engine, p0, temporal_adept()).expect("the Adept is out");
    let ring = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    let their_land = on_battlefield(&engine, p1, forest()).expect("their Forest is out");
    let mine = on_battlefield(&engine, p0, island()).expect("my Island is out");
    assert!(!is_tapped(&engine, adept), "it starts untapped");

    // {U}{U}{U} is read off the pool and not off the untapped lands, so the
    // mana comes first: three Islands, three blue, and the Adept untouched.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "three Islands, and the Adept prints no mana of its own"
    );
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(adept, 0)),
        "with {{U}}{{U}}{{U}} floating the one line the card prints is offered: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, temporal_adept(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        min,
        max,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target permanent\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat chooses");
    assert_eq!((min, max), (1, 1), "exactly one permanent");
    assert!(
        options.contains(&ring) && options.contains(&their_land),
        "a permanent across the table is a permanent: {options:?}"
    );
    assert!(
        options.contains(&mine),
        "and so is one this seat controls — \"target permanent\" reads neither \
         side off the board: {options:?}"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_some(),
        "the target is named before the cost is paid (CR 601.2c, then CR 601.2h)"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![ring],
            },
        )
        .expect("the artifact across the table was one of the options");

    assert!(
        is_tapped(&engine, adept),
        "{{T}} is half the cost, paid by the Adept itself"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and the {{U}}{{U}}{{U}} came out of the pool"
    );
    assert!(
        !stack_is_empty(&engine),
        "bouncing is no mana ability, so the ability is on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_none(),
        "the targeted permanent left the battlefield"
    );
    assert!(
        in_hand(&engine, p1, quiet_artifact()).is_some(),
        "\"to its owner's hand\": the Sol Ring goes back to the seat that owns \
         it, and not to the seat that aimed the bounce"
    );
    assert!(
        in_hand(&engine, p0, quiet_artifact()).is_none(),
        "the bouncing player's hand is where it did not go"
    );
    assert!(
        on_battlefield(&engine, p1, forest()).is_some(),
        "and only the permanent that was named: the Forest never moved"
    );
    assert!(
        on_battlefield(&engine, p0, island()).is_some(),
        "nor the Island under the Adept's own controller"
    );
}

fn thornwind_faeries() -> CardIndex {
    card_index("941a0e8d-c407-476b-9d0e-cffc1f8c6003")
}

/// Thornwind Faeries is a {1}{U}{U} 1/1 Faerie with flying, and its whole
/// printed text is "{T}: This creature deals 1 damage to any target."
/// The scenario casts it off three Islands, walks a full turn cycle so the
/// tap symbol it prints is actually payable (CR 302.6), and then aims the
/// ping at the opponent: the life total moves by one, the Faerie is tapped
/// as the last step of the activation (CR 601.2h), and the Elf standing
/// across the table is untouched — so "any target" reached the player that
/// was named and not a permanent.
#[test]
fn thornwind_faeries_taps_to_deal_one_damage_to_the_player_it_names() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island()])
        .hand(0, &[thornwind_faeries()])
        .battlefield(1, &[llanowar_elves()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, thornwind_faeries());
    pass_until(&mut engine, stack_is_empty);
    let faerie = on_battlefield(&engine, p0, thornwind_faeries()).expect("the Faerie resolved");
    assert_eq!(pt(&engine, faerie), (1, 1), "the body the card prints");
    assert!(
        keywords(&engine, faerie).contains(KeywordSet::FLYING),
        "the printed flying line reaches the permanent"
    );
    assert!(
        !is_tapped(&engine, faerie),
        "it enters untapped, so the {{T}} it prints is still its to spend"
    );

    // A creature that arrived this turn cannot pay a {T} cost (CR 302.6), so
    // the ping is only offered after a whole turn cycle — in which the three
    // Islands and the Faerie alike come back in the untap step.
    reach_their_main_phase(&mut engine, p1);
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");
    assert!(
        !is_tapped(&engine, faerie),
        "the untap step stood it back up"
    );

    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elf is out");
    activate(&mut engine, p0, thornwind_faeries(), 0);
    let Pending::ChooseTargets {
        player,
        options,
        player_options,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat aims it");
    assert!(
        options.contains(&theirs),
        "CR 115.4: the creature across the table is one of the object options: {options:?}"
    );
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "and players are counted in the same choice: {player_options:?}"
    );
    assert!(
        !is_tapped(&engine, faerie),
        "targets are chosen before costs are paid (CR 601.2c, then CR 601.2h), \
         so the tap symbol has not been spent while the question stands"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![],
                players: vec![p1],
            },
        )
        .expect("a player is a legal target for `any target`");

    assert!(is_tapped(&engine, faerie), "the {{T}} was the price");
    assert!(
        !stack_is_empty(&engine),
        "and dealing damage is no mana ability"
    );
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[1].life,
        19,
        "\"deals 1 damage to any target\" — one, to the player that was named"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and the damage belongs to the seat that was aimed at"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "the Elf nobody aimed at is untouched: the damage went to the player \
         and not to a permanent on the board"
    );
    assert!(
        on_battlefield(&engine, p0, thornwind_faeries()).is_some(),
        "an activated ability costs the creature nothing but its tap"
    );
}

fn thundering_wurm() -> CardIndex {
    card_index("cdab50a8-1e02-4ba5-8c09-e2837e7652f7")
}

/// Thundering Wurm — {2}{G}, a printed 4/4 — "When this creature enters,
/// sacrifice it unless you discard a land card."
///
/// The trigger is played rather than read: three Forests pay for the Wurm,
/// the engine asks its controller for the price when the trigger resolves,
/// and the Wurm is a 4/4 on the battlefield afterwards while a land card has
/// moved from the hand to the graveyard. The two failure modes are separated
/// by the counts below — a trigger that never asked leaves the hand one card
/// fuller, one that sacrificed unconditionally leaves no Wurm — and the land
/// in the graveyard is what says the price read "a land card" rather than
/// "a card".
#[test]
fn thundering_wurm_buys_itself_with_a_land_card_from_the_hand() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest()])
        .hand(0, &[thundering_wurm(), forest()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // The price has to be payable on this board or the engine never asks its
    // question at all: a land card is named into the hand so that the trigger
    // really asks, instead of resolving straight to the sacrifice.
    assert!(
        in_hand(&engine, p0, thundering_wurm()).is_some(),
        "the Wurm is in hand to be cast"
    );
    assert!(
        in_hand(&engine, p0, forest()).is_some(),
        "and a land card is in hand to be given up for it"
    );
    let hand_before = engine.state().zones.list(ZoneLocation::Hand(p0)).len();
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        0,
        "nothing has been given up yet"
    );

    // {2}{G} off the three Forests, and the entry trigger is what the driver
    // then meets — the question is answered with the price.
    cast_from_hand(&mut engine, p0, thundering_wurm());
    assert!(
        matches!(drive_to_rest(&mut engine, p0), Rest::Reached),
        "the entry trigger's question is answerable and the game comes back \
         to a quiet priority"
    );

    let wurm = on_battlefield(&engine, p0, thundering_wurm())
        .expect("the Wurm kept itself by paying the price");
    assert_eq!(pt(&engine, wurm), (4, 4), "the body the card prints");
    assert!(
        in_graveyard(&engine, p0, thundering_wurm()).is_none(),
        "and it was not sacrificed"
    );
    assert!(
        in_graveyard(&engine, p0, forest()).is_some(),
        "\"unless you discard a land card\" — the price was a land card, and \
         it is in its owner's graveyard"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Graveyard(p0)).len(),
        1,
        "exactly one card was given up: one discard and no more"
    );
    assert_eq!(
        engine.state().zones.list(ZoneLocation::Hand(p0)).len(),
        hand_before - 2,
        "the Wurm left the hand to be cast and one land card left it as the \
         price; a trigger that never asked would stop at one"
    );
}

fn timberwatch_elf() -> CardIndex {
    card_index("50cee3ac-cba0-4abb-babf-de1928b1590e")
}

/// Timberwatch Elf is a 1/2 Elf whose whole text is one line: "{T}: Target
/// creature gets +X/+X until end of turn, where X is the number of Elves on
/// the battlefield." The board makes four readings disagree, because the Elf
/// itself, one Llanowar Elves on each side of the table and a Bird beside them
/// are all on the battlefield at once: `(4, 4)` on a targeted printed 1/1 is
/// "every Elf on the battlefield, the source included", where "Elves you
/// control" would be `(3, 3)`, "creatures" `(5, 5)` and a source excluded
/// `(2, 2)`. The {T} and nothing else is the price, so the Forests that cast
/// the Elf are read only as the board the count happens on.
#[test]
fn timberwatch_elf_pumps_by_every_elf_on_the_battlefield_itself_included() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), llanowar_elves()])
        // An Elf on the other side of the table, and a Bird that is a
        // creature and no Elf: one of them has to count and the other must not.
        .battlefield(1, &[llanowar_elves(), baleful_strix()])
        .hand(0, &[timberwatch_elf()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // The Elf arrives for real: {2}{G} out of the three Forests. The ability
    // costs no mana at all, so what the cast leaves in the pool says nothing
    // about the activation below.
    cast_from_hand(&mut engine, p0, timberwatch_elf());
    pass_until(&mut engine, stack_is_empty);
    let timberwatch =
        on_battlefield(&engine, p0, timberwatch_elf()).expect("the Elf resolved onto the table");
    let mine = on_battlefield(&engine, p0, llanowar_elves()).expect("my Elves are out");
    let theirs = on_battlefield(&engine, p1, llanowar_elves()).expect("their Elves are out");
    let strix = on_battlefield(&engine, p1, baleful_strix()).expect("their Bird is out");
    assert_eq!(pt(&engine, mine), (1, 1), "a printed 1/1 before the pump");
    assert!(
        !is_tapped(&engine, timberwatch),
        "and the source is untapped"
    );

    // A creature cast this turn cannot pay a {T} (CR 302.6), so the ability
    // is read one turn cycle later — the same rule that keeps it out of a
    // combat, asked of a cost instead of an attack.
    reach_their_main_phase(&mut engine, PlayerId::new(1));
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");

    // Ability 0 is the one line the card prints, and its whole price is the
    // tap symbol: nothing has to be floating for it to be offered.
    activate(&mut engine, p0, timberwatch_elf(), 0);
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"target creature\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert_eq!(player, p0, "the activating seat is the one that aims it");
    assert!(
        options.contains(&mine) && options.contains(&theirs) && options.contains(&strix),
        "\"target creature\" is any creature on either side of the table: {options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![mine],
            },
        )
        .expect("my own Elves were one of the options it enumerated");

    // CR 601.2c names the target and CR 601.2h pays afterwards, so the tap is
    // read here rather than before the answer.
    assert!(is_tapped(&engine, timberwatch), "{{T}} is the whole price");
    assert!(!stack_is_empty(&engine), "and it is no mana ability");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        pt(&engine, mine),
        (4, 4),
        "three Elves on the battlefield — the source itself, my Llanowar Elves \
         and the one across the table — and neither the Bird beside them nor a \
         land is one"
    );
    assert_eq!(
        pt(&engine, theirs),
        (1, 1),
        "the pump reaches the creature it targeted and no other"
    );
    assert_eq!(
        pt(&engine, strix),
        (1, 1),
        "and a creature that is no Elf is neither counted nor pumped"
    );
}

fn uktabi_orangutan() -> CardIndex {
    card_index("6cc07a7e-e70c-45c5-83c5-a2704e57dbc5")
}

/// Uktabi Orangutan is a {2}{G} 2/2 Ape with "When this creature enters,
/// destroy target artifact." The scenario proves the trigger is asked *after*
/// the creature has resolved rather than as part of casting it, and that the
/// filter is read as "artifact" and neither "permanent" nor "yours": both Sol
/// Rings are offered while the Llanowar Elves beside them are not, and only
/// the one that was named leaves the battlefield. The second Sol Ring and the
/// Elves are the controls — a widened filter would have killed one of them,
/// and nothing about the Ape itself would have looked wrong.
#[test]
fn uktabi_orangutan_destroys_the_artifact_it_was_pointed_at_and_no_other_permanent() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[
                forest(),
                forest(),
                forest(),
                forest(),
                llanowar_elves(),
                quiet_artifact(),
            ],
        )
        .hand(0, &[uktabi_orangutan()])
        .battlefield(1, &[quiet_artifact(), llanowar_elves()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let mine = on_battlefield(&engine, p0, quiet_artifact()).expect("my Sol Ring is out");
    let theirs = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    let elf = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elves are out");

    cast_from_hand(&mut engine, p0, uktabi_orangutan());
    // The Ape resolves first; its enters-trigger is what asks for the target.
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(player, p0, "the Ape's controller aims the trigger");
    assert!(
        options.contains(&mine) && options.contains(&theirs),
        "\"target artifact\" reaches either side of the table: {options:?}"
    );
    assert!(
        !options.contains(&elf),
        "a creature is no artifact, so the Elves are not on the menu: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![theirs],
            },
        )
        .expect("the artifact across the table was one of the options");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p0, uktabi_orangutan()).is_some(),
        "the Ape itself is on the battlefield, which is where its trigger came from"
    );
    assert!(
        in_graveyard(&engine, p1, quiet_artifact()).is_some(),
        "the targeted artifact was destroyed and went to its owner's graveyard"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_some(),
        "the artifact the trigger did not name is untouched: one target, one destruction"
    );
    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "and nothing that is not an artifact ever moved"
    );
}

fn venerable_monk() -> CardIndex {
    card_index("5c5cfa6d-857f-44a9-80f7-46f016ef71e4")
}

/// Venerable Monk is a `{2}{W}` 2/2 whose whole rules text is "When this
/// creature enters, you gain 2 life." The scenario is built so that the two
/// halves cannot be confused: three Plains pay the spell, and the life total
/// is read *while the card is still on the stack* — twenty, because the gain
/// belongs to the enters trigger and not to the cast — and again once the
/// stack has emptied, where it is twenty-two. The body is asserted with it,
/// so the card is a permanent that arrived rather than a life total that
/// moved on its own, and the seat across the table is read to say that
/// "you" is the controller and not the table.
#[test]
fn venerable_monk_gains_two_life_as_it_enters_and_leaves_the_other_seat_alone() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[plains(), plains(), plains()])
        .hand(0, &[venerable_monk()])
        .life(0, 20)
        .life(1, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, venerable_monk());
    assert!(
        on_stack(&engine, venerable_monk()).is_some(),
        "three Plains pay {{2}}{{W}}, so the creature is a spell before it is a permanent"
    );
    assert_eq!(
        engine.state().players[0].life,
        20,
        "the gain is the enters trigger's, so nothing is gained while the spell is still on the stack"
    );

    pass_until(&mut engine, stack_is_empty);

    let monk = on_battlefield(&engine, p0, venerable_monk()).expect("the Monk resolved");
    assert_eq!(pt(&engine, monk), (2, 2), "the printed 2/2 body arrived");
    assert_eq!(
        engine.state().players[0].life,
        22,
        "\"When this creature enters, you gain 2 life\" — two, and not a life per permanent or per turn"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "\"you\" is the controller, and the seat across the table gains nothing"
    );
}

fn verduran_enchantress() -> CardIndex {
    card_index("cd98a31b-cc7e-43f9-982e-109ad9850908")
}

/// Verduran Enchantress — `{1}{G}{G}`, a 0/2 — prints one line: "Whenever
/// you cast an enchantment spell, you may draw a card."
///
/// Three spells are cast off one tapping of six Forests, and each of them is
/// a different half of that sentence. The first Fastbond is an enchantment of
/// the Enchantress' own controller, so the trigger asks and the accepted draw
/// costs exactly one card off the top of the library — the library and not the
/// hand, because the spell leaving the hand and the card arriving cancel out
/// there. The second Fastbond is answered "no", which is the whole of the word
/// "may". And the Llanowar Elves is a spell of the same seat that is no
/// enchantment at all, so the type half of the trigger's filter is read
/// against a cast that really happened rather than assumed.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn verduran_enchantress_draws_for_an_enchantment_of_its_controller_and_declines_the_rest() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(
            0,
            &[forest(), forest(), forest(), forest(), forest(), forest()],
        )
        .hand(
            0,
            &[
                verduran_enchantress(),
                fastbond(),
                fastbond(),
                llanowar_elves(),
            ],
        )
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // Mana before the claim: `can_afford` reads the pool and never the
    // untapped lands, and the whole scenario plays inside this one main
    // phase, so CR 500.5 does not empty what the six Forests fill.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        6,
        "six Forests, six green — and nothing else on the board makes mana"
    );

    cast_with_floating(&mut engine, p0, verduran_enchantress());
    pass_until(&mut engine, |e| at_rest(e, p0));
    assert!(
        on_battlefield(&engine, p0, verduran_enchantress()).is_some(),
        "the Enchantress resolved onto the table"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "and her {{1}}{{G}}{{G}} came out of the pool"
    );

    // The trigger's own enchantment, answered "yes". The library is read
    // before the cast and after the question, so the number that moves is the
    // card the ability offered and nothing else.
    let library = library_size(&engine, p0);
    cast_with_floating(&mut engine, p0, fastbond());
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::YesNo {
                prompt: YesNoPrompt::MayDo,
                ..
            }
        )
    });
    let Pending::YesNo { player, .. } = engine.pending().clone() else {
        unreachable!("the predicate just matched")
    };
    assert_eq!(
        player, p0,
        "\"whenever you cast\": the seat that cast the spell is the seat asked"
    );
    engine.apply(p0, PlayerAction::YesNo(true)).unwrap();
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert!(
        on_battlefield(&engine, p0, fastbond()).is_some(),
        "the enchantment itself resolved once its trigger was through"
    );
    assert_eq!(
        library_size(&engine, p0),
        library - 1,
        "\"you may draw a card\", accepted: exactly one card off the top"
    );

    // The same cast again, answered the other way. "May" is the whole of what
    // separates the two readings, and a trigger that drew on a refusal would
    // have satisfied every count above it.
    let library = library_size(&engine, p0);
    cast_with_floating(&mut engine, p0, fastbond());
    pass_until(&mut engine, |e| {
        matches!(
            e.pending(),
            Pending::YesNo {
                prompt: YesNoPrompt::MayDo,
                ..
            }
        )
    });
    engine.apply(p0, PlayerAction::YesNo(false)).unwrap();
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert_eq!(
        all_on_battlefield(&engine, p0, fastbond()).len(),
        2,
        "two enchantments cast and two resolved, so the question really was asked twice"
    );
    assert_eq!(
        library_size(&engine, p0),
        library,
        "\"you may\" declined: the library is untouched"
    );

    // And a spell of the same seat that is no enchantment at all: the filter's
    // type half, read against a cast that really happened.
    let library = library_size(&engine, p0);
    cast_with_floating(&mut engine, p0, llanowar_elves());
    pass_until(&mut engine, |e| at_rest(e, p0));

    assert!(
        on_battlefield(&engine, p0, llanowar_elves()).is_some(),
        "the creature spell resolved, so the silence around it is not a cast \
         that never happened"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "and its {{G}} came out of the pool the Forests filled"
    );
    assert_eq!(
        library_size(&engine, p0),
        library,
        "no question and no draw for a creature spell: the trigger reads \
         \"enchantment\""
    );
}

fn vesper_ghoul() -> CardIndex {
    card_index("c45562ce-5d1a-4ad4-82f8-92199520ae87")
}

/// Vesper Ghoul prints one line: "{T}, Pay 1 life: Add one mana of any
/// color." Neither half of that price is readable out of the card file, so
/// the board is built so each one is visible somewhere a test can look:
/// three Swamps pay the {2}{B} and leave the pool empty, so the single mana
/// that appears afterwards can only have come off the Ghoul's own tap, and
/// the life total falls only because the payment is a cost and not a rider.
/// Naming green is the control — every land on this table makes black, so
/// green in the pool has no other source on it — and the question is five
/// colors wide with no colorless among them (CR 105.4).
#[test]
fn vesper_ghoul_taps_and_pays_a_life_for_one_mana_of_any_color() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(1177, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[vesper_ghoul()])
        .life(0, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    cast_from_hand(&mut engine, p0, vesper_ghoul());
    pass_until(&mut engine, stack_is_empty);
    let ghoul = on_battlefield(&engine, p0, vesper_ghoul()).expect("the Ghoul resolved");
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Swamps paid the {{2}}{{B}} and nothing is left floating"
    );
    assert!(!is_tapped(&engine, ghoul), "the Ghoul enters untapped");
    assert_eq!(
        engine.state().players[0].life,
        20,
        "and its price has not been paid yet"
    );

    // A creature cast this turn cannot pay a {T} (CR 302.6), so the ability
    // is read one turn cycle later — the same rule that keeps it out of a
    // combat, asked of a cost instead of an attack.
    reach_their_main_phase(&mut engine, PlayerId::new(1));
    assert!(walk_to_own_main(&mut engine, p0), "p0 takes another turn");

    // The three Swamps are tapped already, so whatever the ability makes is
    // the whole of the pool: no other source on this board is standing.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending());
    };
    assert!(
        legal.abilities.contains(&(ghoul, 0)),
        "the one line the card prints costs no mana, so an empty pool still \
         offers it: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, vesper_ghoul(), 0);
    let Pending::ChooseColor { player, options } = engine.pending().clone() else {
        panic!("`any color` is a question, got {:?}", engine.pending());
    };
    assert_eq!(player, p0, "the activating seat is the one that names it");
    assert_eq!(
        options.len(),
        5,
        "the five colors of the game, and colorless is no color at all \
         (CR 105.4): {options:?}"
    );
    for color in [
        ManaColor::White,
        ManaColor::Blue,
        ManaColor::Black,
        ManaColor::Red,
        ManaColor::Green,
    ] {
        assert!(
            options.contains(&color),
            "\"any color\" includes {color:?}: {options:?}"
        );
    }

    engine
        .apply(p0, PlayerAction::ChooseColor(ManaColor::Green))
        .expect("green was one of the colors it offered");

    let pool = &engine.state().players[0].mana_pool;
    assert_eq!(
        pool.available(ManaColor::Green),
        1,
        "the color that was named, and not a default"
    );
    assert_eq!(
        pool.available(ManaColor::Black),
        0,
        "every land here makes black and all of them are tapped, so the green \
         has no other source on this board"
    );
    assert_eq!(pool.total(), 1, "one mana, off one activation");
    assert!(
        stack_is_empty(&engine),
        "CR 605.3b: a mana ability uses no stack, so nothing is waiting to resolve"
    );
    assert!(
        matches!(engine.pending(), Pending::Priority { player, .. } if *player == p0),
        "the seat holds priority again, got {:?}",
        engine.pending()
    );
    assert!(
        is_tapped(&engine, ghoul),
        "the tap symbol is half the price the card prints"
    );
    assert_eq!(
        engine.state().players[0].life,
        19,
        "\"Pay 1 life\" is the other half, and a cost is paid as the ability \
         is activated"
    );
}

// oracle_id = "236fbf12-f908-4918-babb-1558e767cbe3"
fn vicious_kavu() -> CardIndex {
    card_index("236fbf12-f908-4918-babb-1558e767cbe3")
}

/// Vicious Kavu — {1}{B}{R}, a printed 2/2 — "Whenever this creature
/// attacks, it gets +2/+0 until end of turn."
///
/// The body is read at four moments because no single one of them tells the
/// card from its neighbours: a 2/2 the turn it lands rules out anything that
/// fires on arrival or stands permanently, a 2/2 *while its attack trigger
/// waits on the stack* rules out a static reading "while attacking", a 4/2
/// once that trigger resolves is the printed +2/+0 and not a toughness pump,
/// and a 2/2 on the following turn is the "until end of turn". The opponent's
/// life total keeps the projection honest, since a body nothing ever swings
/// with would satisfy every other reading here.
#[test]
fn vicious_kavu_pumps_itself_for_the_turn_it_attacks_and_no_longer() {
    let (p0, p1) = (PlayerId::new(0), PlayerId::new(1));
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[swamp(), mountain(), mountain()])
        .hand(0, &[vicious_kavu()])
        .start();
    keep_mulligans(&mut engine);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "p0 reaches its own main phase"
    );

    // {1}{B}{R} out of a Swamp and two Mountains, so the Kavu arrives the way
    // the card arrives rather than being seated by the harness.
    cast_from_hand(&mut engine, p0, vicious_kavu());
    pass_until(&mut engine, stack_is_empty);
    let kavu = on_battlefield(&engine, p0, vicious_kavu()).expect("the Kavu resolved");
    assert_eq!(
        pt(&engine, kavu),
        (2, 2),
        "the printed body: nothing has happened for the trigger to have done"
    );

    // Summoning sickness (CR 302.6) puts the attack a turn away, so the walk
    // goes across p1's turn and back to p0's own main phase.
    reach_their_main_phase(&mut engine, p1);
    reach_their_main_phase(&mut engine, p0);
    assert!(
        !is_tapped(&engine, kavu),
        "the untap step gave it back, so it may be declared below"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers { attackers, .. } = engine.pending().clone() else {
        unreachable!("pass_until stops on the attack declaration");
    };
    assert!(
        attackers.contains(&kavu),
        "an untapped 2/2 past summoning sickness may attack: {attackers:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::DeclareAttackers {
                attackers: vec![(kavu, Defender::Player(p1))],
            },
        )
        .unwrap();

    // CR 603.2: attacking *triggers*, so the pump goes on the stack. A static
    // reading "as long as this creature is attacking" would already be a 4/2
    // in this very read.
    assert!(
        !stack_is_empty(&engine),
        "the attack trigger is waiting on the stack"
    );
    assert_eq!(
        pt(&engine, kavu),
        (2, 2),
        "and it changes nothing until it resolves"
    );

    pass_until(&mut engine, stack_is_empty);
    assert_eq!(
        pt(&engine, kavu),
        (4, 2),
        "+2/+0 — the bonus the card prints, and no toughness with it"
    );

    // Past the combat damage step (CR 510.2), where the extra power stops
    // being a projection: an unblocked 4/2 takes four, not two.
    pass_until(&mut engine, |e| {
        matches!(e.state().turn.phase, Phase::Ending) && e.state().turn.active == p0
    });
    assert_eq!(
        engine.state().players[1].life,
        16,
        "the pumped Kavu dealt four combat damage to the defending player"
    );

    // CR 514.2: the cleanup step is where "until end of turn" ends, so the
    // next turn's reading is the printed body again.
    reach_their_main_phase(&mut engine, p1);
    assert_eq!(
        pt(&engine, kavu),
        (2, 2),
        "\"until end of turn\" expired with the turn it attacked in"
    );
    assert_eq!(
        engine.state().players[1].life,
        16,
        "and the damage it dealt is not undone with the effect"
    );
}

fn viridian_shaman() -> CardIndex {
    card_index("5aa6d553-a144-4c5b-83fa-65e931903899")
}

/// Viridian Shaman is a `{2}{G}` 2/2 Elf Shaman whose entire text is "When
/// this creature enters, destroy target artifact." The board carries an
/// artifact under each seat — so "target artifact" is read as the whole table
/// and not as "you control", which is the filter this card is easiest to
/// narrow by accident — plus a creature across it, so the offer proves the
/// type was read rather than skipped. Cast from three Forests and aimed at the
/// opponent's Sol Ring, it shows the destroy resolved: the card is in its
/// *owner's* graveyard, my own artifact is still standing and the Elf beside
/// it never moved.
#[test]
fn viridian_shaman_destroys_an_artifact_across_the_table_and_nothing_else() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, forest())
        .battlefield(0, &[forest(), forest(), forest(), quiet_artifact()])
        .hand(0, &[viridian_shaman()])
        .battlefield(1, &[quiet_artifact(), quiet_creature()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    let my_ring = on_battlefield(&engine, p0, quiet_artifact()).expect("my Sol Ring is out");
    let their_ring = on_battlefield(&engine, p1, quiet_artifact()).expect("their Sol Ring is out");
    let their_elf = on_battlefield(&engine, p1, quiet_creature()).expect("their Elf is out");

    cast_from_hand(&mut engine, p0, viridian_shaman());
    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseTargets { .. })
    });
    assert!(
        on_battlefield(&engine, p0, viridian_shaman()).is_some(),
        "the creature is on the battlefield before its enters-trigger is put on the stack"
    );
    let Pending::ChooseTargets {
        player, options, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the trigger's own target")
    };
    assert_eq!(player, p0, "the Shaman's controller aims its own trigger");
    assert!(
        options.contains(&my_ring) && options.contains(&their_ring),
        "\"target artifact\" reaches either side of the table: {options:?}"
    );
    assert!(
        !options.contains(&their_elf),
        "a creature is not an artifact, so the Elf across the table is no target: {options:?}"
    );

    engine
        .apply(
            p0,
            PlayerAction::ChooseObjects {
                objects: vec![their_ring],
            },
        )
        .expect("the artifact the question offered was chosen");
    pass_until(&mut engine, stack_is_empty);

    assert!(
        on_battlefield(&engine, p1, quiet_artifact()).is_none(),
        "the targeted artifact left the battlefield"
    );
    assert!(
        in_graveyard(&engine, p1, quiet_artifact()).is_some(),
        "and it is in its owner's graveyard — destroyed, not exiled"
    );
    assert!(
        on_battlefield(&engine, p0, quiet_artifact()).is_some(),
        "the artifact the trigger did not name never moved"
    );
    assert!(
        on_battlefield(&engine, p1, quiet_creature()).is_some(),
        "and neither did the creature beside it"
    );
    assert!(
        on_battlefield(&engine, p0, viridian_shaman()).is_some(),
        "the Shaman survives its own trigger"
    );
}

fn vulshok_sorcerer() -> CardIndex {
    card_index("6f858405-dfe4-4ca2-b2e3-80ce8cda5522")
}

/// Vulshok Sorcerer is a 1/1 for {1}{R}{R} with haste and "{T}: This
/// creature deals 1 damage to any target". Both halves are played in one
/// first main phase: the Sorcerer pings on the turn it arrives, which is the
/// whole of what the haste line buys (CR 302.6), and a second copy aims the
/// same line at a player instead of at a creature. The printed 1/1 across
/// the table and the 20 life beside it make the damage exact — one point
/// kills a 1/1 and leaves its controller untouched, and one point off a life
/// total is a number no other source on this board could have produced.
#[allow(clippy::too_many_lines)] // One printed card, played end to end: the length is the card's.
#[test]
fn vulshok_sorcerer_pings_on_the_turn_it_arrives_and_reaches_creatures_and_players_alike() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, mountain())
        .battlefield(
            0,
            &[
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                mountain(),
                mountain(),
            ],
        )
        .battlefield(1, &[llanowar_elves()])
        .hand(0, &[vulshok_sorcerer(), vulshok_sorcerer()])
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // Six Mountains are exactly what two {1}{R}{R} casts cost, and they are
    // tapped before anything is claimed about the offer: `legal` is filtered
    // by `can_afford`, which reads the pool and not the untapped lands.
    tap_all_mana(&mut engine, p0);
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        6,
        "six Mountains, six red"
    );

    cast_with_floating(&mut engine, p0, vulshok_sorcerer());
    pass_until(&mut engine, stack_is_empty);
    let first = on_battlefield(&engine, p0, vulshok_sorcerer()).expect("the Sorcerer resolved");
    let elf = on_battlefield(&engine, p1, llanowar_elves()).expect("an Elf across the table");
    assert!(
        keywords(&engine, first).contains(KeywordSet::HASTE),
        "the printed haste line reaches the permanent"
    );

    // Ability 0 is the only activated line the card prints, and it is offered
    // on the turn the creature arrived — which is what haste is for (CR 302.6).
    let Pending::Priority { player, legal } = engine.pending().clone() else {
        panic!("expected priority, got {:?}", engine.pending())
    };
    assert_eq!(player, p0, "the Sorcerer's controller holds it");
    assert!(
        legal.abilities.contains(&(first, 0)),
        "{{T}}: 1 damage to any target, on a creature cast this turn: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, vulshok_sorcerer(), 0);
    let Pending::ChooseTargets {
        options,
        player_options,
        ..
    } = engine.pending().clone()
    else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert!(
        options.contains(&elf),
        "the creature across the table is one of the object options: {options:?}"
    );
    assert!(
        player_options.contains(&p0) && player_options.contains(&p1),
        "CR 115.4: \"any target\" counts players in the same choice: {player_options:?}"
    );
    assert!(
        !is_tapped(&engine, first),
        "CR 601.2c before CR 601.2h: the {{T}} is the last step of the activation"
    );

    engine
        .apply(p0, PlayerAction::ChooseObjects { objects: vec![elf] })
        .expect("the Elf was one of the options the question enumerated");
    assert!(
        is_tapped(&engine, first),
        "the tap symbol is the whole price the ability charges"
    );
    pass_until(&mut engine, stack_is_empty);

    assert!(
        in_graveyard(&engine, p1, llanowar_elves()).is_some(),
        "one damage to a printed 1/1 is lethal (CR 704.5f)"
    );
    assert_eq!(
        engine.state().players[1].life,
        20,
        "and the damage went to the creature that was named, not to its controller"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        3,
        "the ping cost no mana: the pool is exactly where the {{1}}{{R}}{{R}} left it"
    );

    // The other half of "any target": the same line aimed at a player. The
    // second copy is the one still untapped, so nothing about the first
    // Sorcerer's tap is being read a second time below.
    cast_with_floating(&mut engine, p0, vulshok_sorcerer());
    pass_until(&mut engine, stack_is_empty);
    let shooters = all_on_battlefield(&engine, p0, vulshok_sorcerer());
    assert_eq!(shooters.len(), 2, "both Sorcerers are on the table");
    let second = *shooters
        .iter()
        .find(|id| !is_tapped(&engine, **id))
        .expect("one of the two is still untapped");

    activate(&mut engine, p0, vulshok_sorcerer(), 0);
    let Pending::ChooseTargets { player_options, .. } = engine.pending().clone() else {
        panic!(
            "\"any target\" is a target choice, got {:?}",
            engine.pending()
        )
    };
    assert!(
        player_options.contains(&p1),
        "the opponent is a target the question offers: {player_options:?}"
    );
    engine
        .apply(
            p0,
            PlayerAction::ChooseTargets {
                objects: vec![],
                players: vec![p1],
            },
        )
        .expect("a player the question enumerated is a legal answer");
    pass_until(&mut engine, stack_is_empty);

    assert_eq!(
        engine.state().players[1].life,
        19,
        "\"deals 1 damage to any target\": one point, to the seat that was named"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "both casts paid and neither ping did: the pool is empty"
    );
    assert!(
        is_tapped(&engine, second),
        "and the second Sorcerer paid its own {{T}}"
    );
}

fn wall_of_air() -> CardIndex {
    card_index("b2d3da40-e2f7-4480-9da9-33019d6f4071")
}

/// Wall of Air prints two keywords on a 1/5 body — Defender and flying — and
/// each is read off a different part of the engine: flying from the keyword
/// projection the layers produce, Defender from the combat step's own offer.
/// The Wall is really cast for {1}{U}{U} off three Islands, and a whole turn
/// cycle is walked before the attack declaration, because a creature that
/// arrived this turn is refused as an attacker by summoning sickness
/// (CR 302.6) whatever it prints — it is asserted untapped and past its
/// controller's untap step first, so its absence from `attackers` can only be
/// the word Defender. The Llanowar Elves standing beside it is the control
/// that says the offer was there to be missed.
#[test]
fn wall_of_air_arrives_as_a_flying_wall_the_combat_step_never_offers() {
    let p0 = PlayerId::new(0);
    let p1 = PlayerId::new(1);
    let mut engine = Duel::new(SEED, island())
        .battlefield(0, &[island(), island(), island(), llanowar_elves()])
        .hand(0, &[wall_of_air()])
        .start();
    keep_mulligans(&mut engine);
    assert!(walk_to_own_main(&mut engine, p0), "p0 reaches its own main");

    // {1}{U}{U} off the three Islands, with the Elf's own {G} beside them in
    // the pool: the Wall arrives by being cast, not by being placed.
    cast_from_hand(&mut engine, p0, wall_of_air());
    pass_until(&mut engine, stack_is_empty);
    let wall = on_battlefield(&engine, p0, wall_of_air()).expect("the Wall resolved");
    assert_eq!(pt(&engine, wall), (1, 5), "the body the card prints");

    let printed = keywords(&engine, wall);
    assert!(
        printed.contains(KeywordSet::FLYING),
        "flying reaches the permanent"
    );
    assert!(
        printed.contains(KeywordSet::DEFENDER),
        "and so does Defender"
    );

    // A full turn cycle, so the Wall is no longer summoning sick. Without this
    // the next claim would be satisfied by CR 302.6 rather than by the card's
    // own word.
    reach_their_main_phase(&mut engine, p1);
    assert!(
        walk_to_own_main(&mut engine, p0),
        "back to the Wall's controller"
    );
    assert!(
        on_battlefield(&engine, p0, wall_of_air()).is_some(),
        "the Wall survives the turn it arrived in"
    );
    assert!(
        !is_tapped(&engine, wall),
        "the untap step stood it back up, so nothing but the printed word can keep it out of combat"
    );

    pass_until(&mut engine, |e| {
        matches!(e.pending(), Pending::ChooseAttackers { .. })
    });
    let Pending::ChooseAttackers {
        player, attackers, ..
    } = engine.pending().clone()
    else {
        unreachable!("pass_until stops on nothing but the attack declaration")
    };
    assert_eq!(player, p0, "the Wall's controller declares this combat");
    let elves = on_battlefield(&engine, p0, llanowar_elves()).expect("the Elf is still out");
    assert!(
        attackers.contains(&elves),
        "an untapped 1/1 past its untap step is offered, so the combat step \
         really asked: {attackers:?}"
    );
    assert!(
        !attackers.contains(&wall),
        "\"This creature can't attack\" — Defender on an untapped creature that \
         has been under its controller's control since the turn began: {attackers:?}"
    );
}

fn wall_of_blood() -> CardIndex {
    card_index("b26c3563-d289-4ca3-8736-9d89e191a840")
}

/// Wall of Blood — {2}{B} 0/2 Wall with defender and one line: "Pay 1 life:
/// This creature gets +1/+1 until end of turn."
///
/// The price names no mana at all, so the board is three Swamps the cast has
/// already spent: with the pool empty and nothing else able to make mana, the
/// only thing the ability is allowed to take is the life the two activations
/// below cost, and `(2, 4)` on a printed 0/2 is what says each payment bought
/// its own +1/+1 rather than the first one buying both. Defender is read
/// beside the numbers because it is the half of the card that must not move —
/// a pump that had quietly turned the Wall into a creature that can attack
/// would leave the P/T exactly as they are.
#[test]
fn wall_of_blood_pays_life_for_power_and_keeps_its_defender() {
    let p0 = PlayerId::new(0);
    let mut engine = Duel::new(SEED, swamp())
        .battlefield(0, &[swamp(), swamp(), swamp()])
        .hand(0, &[wall_of_blood()])
        .life(0, 20)
        .start();
    keep_mulligans(&mut engine);
    reach_main_phase(&mut engine, p0);

    // {2}{B} off the three Swamps, and nothing is held back: the whole price
    // read below is life, so an empty pool is what makes each claim exact.
    cast_from_hand(&mut engine, p0, wall_of_blood());
    pass_until(&mut engine, |e| at_rest(e, p0));
    let wall = on_battlefield(&engine, p0, wall_of_blood()).expect("the Wall resolved");
    assert_eq!(pt(&engine, wall), (0, 2), "the body the card prints");
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "the printed defender, before anything is paid into it"
    );
    assert_eq!(
        engine.state().players[0].mana_pool.total(),
        0,
        "three Swamps paid for the Wall, so no mana is left for the pump to cost"
    );

    // Ability 0 is the card's only line, and `can_afford` has nothing but the
    // life total to read here — an empty pool does not withhold it.
    let Pending::Priority { legal, .. } = engine.pending().clone() else {
        panic!("the seat holds a quiet main phase: {:?}", engine.pending())
    };
    assert!(
        legal.abilities.contains(&(wall, 0)),
        "with an empty pool the pump is still offered, because its price is \
         life and not mana: {:?}",
        legal.abilities
    );

    activate(&mut engine, p0, wall_of_blood(), 0);
    assert_eq!(
        engine.state().players[0].life,
        19,
        "the life is the last step of the activation (CR 601.2h)"
    );
    assert!(
        !stack_is_empty(&engine),
        "paying life is no mana ability, so the pump is on the stack"
    );
    assert_eq!(
        pt(&engine, wall),
        (0, 2),
        "and nothing has happened to the body yet"
    );
    pass_until(&mut engine, |e| at_rest(e, p0));
    assert_eq!(pt(&engine, wall), (1, 3), "+1/+1 until end of turn, once");

    // A second activation is a second life: the pump is priced per point and
    // not a bonus the Wall gets for having been asked once.
    activate(&mut engine, p0, wall_of_blood(), 0);
    pass_until(&mut engine, |e| at_rest(e, p0));
    assert_eq!(pt(&engine, wall), (2, 4), "a second +1/+1");
    assert_eq!(
        engine.state().players[0].life,
        18,
        "and a second life paid for it"
    );
    assert!(
        keywords(&engine, wall).contains(KeywordSet::DEFENDER),
        "still a Wall: nothing about the pump touches the keyword"
    );
}

